(window.DEEP=window.DEEP||{})['myth']={"T":{"myth-m1":"الدرس M1: يعني إيه أسطورة؟ وإزاي الشاعر الإنجليزي بيستخدمها؟","myth-m10":"الدرس M10: أبولو، إله النور والنبوءة والقيثارة","myth-m11":"الدرس M11: أرتميس وديانا — إلهة القمر والصيد <span class=\"em\">🏹🌙</span>","myth-m12":"الدرس M12: أثينا ومينيرفا — الإلهة اللي اتولدت من راس أبوها","myth-m13":"الدرس M13: أفروديت وفينوس — إلهة الحب والجمال","myth-m14":"الدرس M14: هيرميس وعطارد: الرسول، واللص، وإله الحدود","myth-m15":"الدرس M15: آريس وهيفايستوس: مارس وفولكان: الحرب والصنعة","myth-m16":"الدرس M16: هاديس وبلوتو: الإله اللي مش بيتسمى","myth-m17":"الدرس M17: ديميتر وسيريس: الأم اللي وقفت الدنيا","myth-m18":"الدرس M18: ديونيسوس وباخوس: الإله اللي بيكسر الحدود","myth-m19":"الدرس M19: بان والحوريات: الإله اللي مابيسألش عنك","myth-m2":"الدرس M2: خلق الكون — من الفوضى (Chaos) لأوليمبوس","myth-m20":"الدرس M20: الاستدعاء: الشاعر بيطلب من الميوز تحكي بدله","myth-m21":"الدرس M21: بيرسيفوني وديميتر: البنت اللي اختفت من المرج","myth-m22":"الدرس M22: أبولو وداڤني: الحب اللي بيجري","myth-m23":"الدرس M23: بان وسيرينكس: ناي القصب","myth-m24":"الدرس M24: هياكينثوس: الزهرة اللي مكتوب عليها الحزن","myth-m25":"الدرس M25: نرسيس وإيكو: الصدى والانعكاس","myth-m26":"الدرس M26: بيراموس وثيسبي: الحب من ورا الحيطة","myth-m27":"الدرس M27: هيرو وليندر: السباحة اللي بتنتهي بنور مطفي","myth-m28":"الدرس M28: فيليمون وباوكيس: الضيافة اللي بتتكافأ","myth-m3":"الدرس M3: أعمار البشر الخمسة (Hesiod)","myth-m4":"الدرس M4: الطوفان الإغريقي — Deucalion وPyrrha","myth-m5":"الدرس M5: باندورا وبروميثيوس — النار المسروقة والجرة الملعونة","myth-m6":"الدرس M6: خريطة العالم السفلي — الأنهار الخمسة وCharon والقضاة","myth-m7":"الدرس M7: Sisyphus — أشهر عقوبة في التاريخ","myth-m8":"الدرس M8: طنطالوس وإكسيون وبنات داناوس","myth-m9":"الدرس M9: زيوس / جوبيتر، ملك الآلهة والشعر"},"P":[{"i":"myth-m1","s":0,"h":"","t":"learn","x":"📌 1) يعني إيه أسطورة ( myth )؟ حكاية قديمة عن آلهة وأبطال وكائنات خارقة، اتوارثتها الشعوب عشان تشرح العالم: الخلق، الموت، الحب، الفصول، العقاب. مش مجرد حدوتة: الأسطورة كانت الدين والعلم والأدب بتاع الإغريق والرومان. 📌 2) ليه الشعراء الإنجليز مهووسين بيها؟"},{"i":"myth-m1","s":1,"h":"","t":"mc","x":"الأسطورة ( myth ) هي... ؟ خبر علمي عن أصل الكون بيتنشر في الجرائد / حكاية قديمة عن آلهة وأبطال، بتشرح العالم زي الخلق والموت والحب / قصيدة بقافية AABB عن حدث حقيقي / حكاية خيالية حديثة للأطفال قبل النوم . حكاية قديمة عن آلهة وأبطال، بتشرح العالم زي الخلق والموت والحب"},{"i":"myth-m1","s":2,"h":"","t":"learn","x":"الشاعر الإنجليزي من العصور الوسطى للقرن العشرين اتربى على اللاتيني واليوناني، فالأساطير دي كانت \"القاموس المشترك\" بينه وبين قارئه — زي ما انت وصحابك عندكم أفلام وأغان مشتركة، كلمة منها بتفهمهم قصيدة كاملة. لما يقول \" Hector \" فهو مختصر صفحة كاملة من المعنى في كلمة: البطولة والشرف والموت."},{"i":"myth-m1","s":3,"h":"","t":"learn","x":"الأسطورة بتديه صور جاهزة للحب ( Cupid )، والجمال ( Venus )، والطموح ( Icarus )، والعقاب ( Tantalus ). 📌 3) ال allusion (الإشارة): أهم مهارة في الكورس ده الشاعر مش هيحكيلك الأسطورة، هيلمح ليها بس. إشارة = اسم أو كلمة بتستدعي الحكاية كلها."},{"i":"myth-m1","s":4,"h":"","t":"learn","x":"مثال من حياتنا: لما حد يقول \"ده فيلم تيتانيك\" وانت فاهم فورا: غرق، حب، نهاية حزينة — من غير ما يحكي الفيلم. أو لما تقول \"عمل زي فيلم الأفلام دي\" وصاحبك يضحك لأنه شاف نفس المشهد. الشاعر الإنجليزي بيعمل كده بالأساطير بالظبط: يقول \" wax wings \" فيفهم قارئه قصة Icarus كلها في كلمتين."},{"i":"myth-m1","s":5,"h":"","t":"mc","x":"ال allusion (الإشارة) هي... ؟ شرح طويل ومفصل لحكاية أسطورية / سطر بيتكرر في آخر كل مقطع / اسم أو كلمة بتستدعي حكاية كاملة من غير ما الشاعر يحكيها / ترجمة حرفية لقصيدة قديمة . اسم أو كلمة بتستدعي حكاية كاملة من غير ما الشاعر يحكيها"},{"i":"myth-m1","s":6,"h":"","t":"learn","x":"إزاي تمسكها في الامتحان: ١) اسم علم غريب (شخصية/مكان) = غالبا إشارة. ٢) اسأل: مين ده؟ وحصله إيه؟ ٣) اسأل: ليه الشاعر اختار الحكاية دي هنا بالظبط؟ الفكرة اللي بيقولها من خلالها هي الإجابة. 📌 4) خريطة الأسماء: يوناني ← روماني (الشعر الإنجليزي بيستخدم الاتنين)"},{"i":"myth-m1","s":7,"h":"","t":"learn","x":"Zeus ← Jupiter/Jove | Hera ← Juno | Poseidon ← Neptune | Athena ← Minerva | Apollo ← Apollo (نفسه) | Artemis ← Diana | Aphrodite ← Venus | Ares ← Mars | Hermes ← Mercury | Hephaestus ← Vulcan | Dionysus ← Bacchus | Hades ← Pluto | Heracles ← Hercules | Odysseus ← Ulysses"},{"i":"myth-m1","s":8,"h":"","t":"mc","x":"إيه الاسم الروماني ل Zeus ؟ ؟ Jupiter / Neptune / Mars / Saturn . Jupiter"},{"i":"myth-m1","s":9,"h":"","t":"mc","x":"إيه الاسم الروماني ل Aphrodite ؟ ؟ Venus / Juno / Diana / Minerva . Venus"},{"i":"myth-m1","s":10,"h":"","t":"learn","x":"ملحوظة امتحان: ميلتون بيحب \" Jove \"، وشكسبير بيحب \" Jupiter \"، والرومانتيكيين بيرجعوا للأسماء اليونانية."},{"i":"myth-m1","s":11,"h":"","t":"learn","x":"📌 5) الشخصيات اللي هتقابلك في كل قصيدة: ال Muses التسعة: بنات Zeus و Mnemosyne (الذاكرة)، ساكنين جبل Helicon و Parnassus ، وبيلهموا الشعراء. أهمهم للشعر: Calliope (شعر الملاحم)، Erato (شعر الحب)، Melpomene (التراجيديا)، Thalia (الكوميديا)، Urania (الفلك، ميلتون بيسميها في Paradise Lost ). ال \" sacred well \" (عين Aganippe المقدسة) بتاعتهم تحت عرش Jove."},{"i":"myth-m1","s":12,"h":"","t":"mc","x":"ال Muses التسعة هم بنات... ؟ Poseidon و Athena / Hades و Hera / Cronos و Rhea / Zeus و Mnemosyne (الذاكرة) . Zeus و Mnemosyne (الذاكرة)"},{"i":"myth-m1","s":13,"h":"","t":"learn","x":"ال Fates التلاتة ( Moirai/Parkae ): Clotho بتغزل خيط العمر، Lachesis بتقيسه، Atropos بتقطعه. ولا Zeus نفسه يقدر يرجعهم. ال Furies ( Erinyes ): تلات كيانات عقاب ( Alecto و Megaera و Tisiphone ) بيطاردوا قاتل الدم حتى الجنون، وبعدين اتحولوا ل Eumenides \"المهدونات\" في مسرحية Aeschylus. 📌 6) الأسطورة في الشعر الإنجليزي (قسم ثابت في كل درس):"},{"i":"myth-m1","s":14,"h":"","t":"mc","x":"مين من ال Fates بتقطع خيط العمر؟ ؟ Atropos / Clotho / Lachesis / Moirai . Atropos"},{"i":"myth-m1","s":15,"h":"","t":"learn","x":"أ) الاستدعاء ( invocation ): الشاعر بيفتح قصيدته بطلب الإلهام من ال Muse ، تقليد من Homer لفيرجيل لميلتون: Milton, Paradise Lost 1.6-9 : \" Sing Heav'nly Muse, that on the secret top Of Oreb, or of Sinai, didst inspire That Shepherd, who first taught the chosen Seed, \""},{"i":"myth-m1","s":16,"h":"","t":"mc","x":"ال invocation في بداية القصيدة هو... ؟ الشاعر بيطلب الإلهام من ال Muse / الشاعر بيشكر القارئ على صبره / الشاعر بيختم القصيدة بدعاء / الشاعر بيعتذر عن أخطاء القصيدة . الشاعر بيطلب الإلهام من ال Muse"},{"i":"myth-m1","s":17,"h":"","t":"mc","x":"كمل الجملة اللي لسه شايفها: that on the _____ top ؟ learning / loudly / secret / rapid . that on the secret top"},{"i":"myth-m1","s":18,"h":"","t":"learn","x":"ميلتون بيخلط: Muse إغريقية + جبل Oreb/Sinai توراتي = \"ميوز مسيحية\". ده أشهر سطر استدعاء في الإنجليزي. Milton, Lycidas 15-17 : \" Begin then, Sisters of the sacred well, That from beneath the seat of Jove doth spring, Begin, and somwhat loudly sweep the string. \" ال \" Sisters \" هما ال Muses ، وال \" sacred well \" هي عينهم. قصيدة رثاء بتستدعي إلهام الشعر نفسه."},{"i":"myth-m1","s":19,"h":"","t":"learn","x":"ب) Pieria (موطن ال Muses عند جبل Olympus ): Pope, An Essay on Criticism 215-218 : \" A little learning is a dangerous thing ;"},{"i":"myth-m1","s":20,"h":"","t":"learn","x":"Drink deep, or taste not the Pierian spring : There shallow draughts intoxicate the brain, And drinking largely sobers us again. \" \"العين البييرية\" = منبع المعرفة بتاع ال Muses. الشربة الصغيرة بتسكر، الغوص بيعقل: تعلم للآخر أو بلاش."},{"i":"myth-m1","s":21,"h":"","t":"mc","x":"في An Essay on Criticism ل Pope ، ال Pierian spring معناها... ؟ منبع المعرفة بتاع ال Muses / نهر في مصر بيرمز للخصب / جبل عالي بيسكنه الآلهة / مدينة يونانية قديمة مشهورة بالنقد . منبع المعرفة بتاع ال Muses"},{"i":"myth-m1","s":22,"h":"","t":"learn","x":"📌 7) كلمات إنجليزي طلعت من درس النهارده: muse (يتأمل) / museum (معبد ال Muses ) / music • fatal / fate • fury / furious • invoke / invocation • Parnassian (صفت شعرية)."},{"i":"myth-m1","s":24,"h":"تذكر واكتب","t":"recall","x":"إيه الفرق بين الحكاية والإشارة ( allusion ) في الشعر؟ . الحكاية بتتحكى كاملة، والإشارة تذكير سريع باسم أو صورة القارئ بيفهمها من غير شرح. زي ما ميلتون يكتب \" Heav'nly Muse \" فيفهم القارئ إنه بيستدعي إلهام الشعر، مش بيحكي حكاية الميوز."},{"i":"myth-m1","s":25,"h":"تذكر واكتب","t":"recall","x":"مين ال Fates التلاتة، ووظيفة كل واحدة فيهم؟ . Clotho بتغزل خيط العمر، Lachesis بتقيسه، و Atropos بتقطعه. ومحدش يقدر يرجع الخيط، ولا Zeus نفسه."},{"i":"myth-m1","s":26,"h":"تذكر واكتب","t":"write","x":"قارن في ٣-٤ جمل بين صورة الإلهام عند Pope في Essay on Criticism 215-218 وصورة ميلتون في Paradise Lost 1.6-9. . عند Pope الصورة مادية وحسابية: \" Drink deep, or taste not the Pierian spring \" (٢١٥)، فالمعرفة شراب، والقليل منه بيسكر صاحبه بدل ما يعقله، والشراب الكتير هو اللي بيرجع الاتزان. وعند ميلتون الصورة صوتية وطقسية: نداء لميوز بتنزل من جبل مقدس عشان تعلمه، والطلب مش معرفة عامة، هو عون على كتابة قصيدة. يبدو أن Pope بيحذر من التعلم السطحي، بينما ميلتون بيطلب عونا على العمل نفسه. الاتنين بيرجعوا لنفس المنبع، لكن واحد بيحذر من الشربة الصغيرة والتاني بيطلب الشربة كلها."},{"i":"myth-m1","s":27,"h":"تذكر واكتب","t":"write","x":"قارن في ٣-٤ جمل بين صورة الإلهام عند Pope في Essay on Criticism 215-218 وصورة ميلتون في Paradise Lost 1.6-9. . عند Pope الصورة مادية: \" Drink deep, or taste not the Pierian spring \" (٢١٥)، فالمعرفة شراب، والقليل منه بيسكر صاحبه. وعند ميلتون الصورة صوتية: نداء لميوز بتنزل من جبل مقدس عشان تعلمه. يبدو أن Pope بيحذر من التعلم السطحي، بينما ميلتون بيطلب عونا على الكتابة نفسها. الاتنين بيرجعوا لنفس المنبع، لكن واحد بيحذر من الشربة الصغيرة والتاني بيطلب الشربة كلها. والنتيجة إن الصورة نفسها بتتغير وظيفتها: من منبع للشعر إلى امتحان للعقل."},{"i":"myth-m10","s":0,"h":"","t":"learn","x":"🎣 أول حاجة: أول طاعون في تاريخ الأدب الأدب الغربي كله بيبدأ بملحمة الإلياذة، والإلياذة بتبدأ بمصيبة: طاعون بيضرب معسكر الإغريق قدام طروادة. ومين اللي باعث الطاعون؟ مش شرير، مش وحش، ده إله النور نفسه: أبولو."},{"i":"myth-m10","s":1,"h":"","t":"learn","x":"هوميروس بيوصف نزوله من أوليمبوس غضبان: \" The arrows rattled on the shoulders of the angry god as he moved, and his coming was like the night. \" (السهام كانت بترعش على كتف الإله الغضبان وهو ماشي، وقدومه كان زي الليل.) ( Iliad 1.43-52 ، ترجمة Murray )"},{"i":"myth-m10","s":2,"h":"","t":"learn","x":"إله الضوء بييجي زي الضلمة؟ دي أول مفارقة هتتعلمها النهارده عن أبولو: الإله اللي بيشفي هو نفسه اللي بيمرض، ونوره بيحرق. 🏝️ أولا: الميلاد على الجزيرة المنبوذة 1 ️ ⃣ أم هاربة أم أبولو هي ليتو ( Leto )، من التييتنز، وأبوه زيوس. هيرا مرات زيوس غارت منها غيرة قاتلة، فممنوع أي أرض \"تشوفها الشمس\" تستقبلها للولادة."},{"i":"myth-m10","s":3,"h":"","t":"learn","x":"فليتو وهي تعبانة في الوضع لفت على عشرات الجزر والمدن، \"بس الكل كان بيرتعب ويخاف، ومحدش، ولا أغنى أرض، جرؤ يستقبل فيبوس\". (ترنيمة هوميروس لأبولو، رقم 3، ترجمة Evelyn-White ) 🔄 من الحياة: زي واحدة في التاسع بتدور على مستشفى تقبلها وكل الأبواب بتتقفل. الحامل في الأسطورة مش بتدور على سرير، بتدور على أرض كاملة. 2 ️ ⃣ ديلوس تقول نعم 🤝"},{"i":"myth-m10","s":4,"h":"","t":"learn","x":"أخيرا وافقت جزيرة صغيرة فقيرة اسمها ديلوس ( Delos ): صخرية، مابتزرعش، \"سمعتها وحشة بين الناس\". بس ديلوس كانت خايفة برضه: قالت لليتو \"بيقولوا ابنك هيبقى متكبر جدا، خايفة أول ما يشوف نور الشمس يحتقرني ويدفعني برجليه في البحر\". فليتو حلفت أعظم قسم عند الآلهة، القسم بستيكس (نهر العالم السفلي): أبولو هيبني هنا أول معبد وأوراكل عظيم. ديلوس وافقت."},{"i":"myth-m10","s":5,"h":"","t":"mc","x":"أنهي جزيرة قبلت تستقبل ليتو لتلد؟ ؟ كريت، الجزيرة الكبيرة / جزيرة كبيرة وغنية بالمعابد / رودس، جزيرة الشمس / ديلوس، جزيرة صغيرة وفقيرة . ديلوس، جزيرة صغيرة وفقيرة"},{"i":"myth-m10","s":6,"h":"","t":"learn","x":"3 ️ ⃣ الولادة المعجزة ✨ ليتو فضلت في آلام الوضع تسع أيام وتسع ليالي، لأن هيرا خبت إيليثيا (إلهة الولادة) عشان متجيش تساعدها. الآلهات بعتوا آيريس تستدعيها سرا بوعد عقد من الذهب طوله تسع أذرع. أول ما إيليثيا دست الجزيرة، ليتو حضنت شجرة نخلة وركعت على المرج، \"والأرض ضحكت من الفرحة من تحتها\"، والطفل قفز للنور."},{"i":"myth-m10","s":7,"h":"","t":"learn","x":"ثيمس سقته النكتار والأمبروزيا، وأول ما ذاق الأكل الإلهي، قال أول كلام في حياته: \" The lyre and the curved bow shall ever be dear to me, and I will declare to men the unfailing will of Zeus. \" (القيثارة والقوس المعقوف هيفضلوا أعز حاجة عندي، وهبلغ الناس إرادة زيوس اللي مابتكذبش.) ثلاث كلمات تلخص شخصية أبولو كلها: موسيقى، وسهم، ونبوءة."},{"i":"myth-m10","s":8,"h":"","t":"mc","x":"كمل الجملة اللي لسه شايفها: The lyre and the _____ bow shall ever be dear to me, ؟ curved / broken / steeds / those . The lyre and the curved bow shall ever be dear to me,"},{"i":"myth-m10","s":9,"h":"","t":"learn","x":"وديلوس الفقيرة؟ \"اتحملت كلها دهب... وتفتحت زي قمة جبل بالزهور\"، وبقت من أقدس جزر اليونان كلها. ملحوظة توأم: أخت أبولو التوأم هي أرتميس ( Artemis )، الترنيمة بتقول أرتميس اتولدت في أورتيجيا وأبولو في ديلوس. هنتكلم عن أرتميس في الدرس الجاي. 🐍 ثانيا: أبولو والحية العملاقة"},{"i":"myth-m10","s":10,"h":"","t":"mc","x":"إيه اللي قاله أبولو في أول كلامه بعد الميلاد؟ ؟ هحارب أبويا وآخد عرشه / هبني مدينة عند منبع النهر / القيثارة والقوس أعز حاجة عنده، وهيبلغ الناس إرادة زيوس / الفضل كله لأمي اللي سابتني . القيثارة والقوس أعز حاجة عنده، وهيبلغ الناس إرادة زيوس"},{"i":"myth-m10","s":11,"h":"","t":"learn","x":"أول شغلانة لأبولو الشاب: نزل منطقة دلفي ( Delphi ) وقتل التنين، أو الحية العملاقة بيثون ( Python )، اللي كانت بترعب الناس عند عين المية. المكان اتسمى \"بيثو\" ( Pytho ) من الفعل اليوناني اللي معناه \"يتعفن\"، لأن جثة الحية تعفنت في الشمس. ومن هنا جه لقب أبولو \"البيثياني\" ( Pythian ). (المصدر: الترنيمة الهوميرية لأبولو، سطور 281-374)"},{"i":"myth-m10","s":12,"h":"","t":"learn","x":"أوفيد عنده نسخة تانية: الحية طلعت من الطينة اللي فضلت بعد الطوفان العظيم (أوفيد بيربطها بطوفان ديوكاليون، Metamorphoses 1.434-451 ). وعلى أنقاض المعركة أبولو أسس أهم مكان في اليونان كلها: معبد وأوراكل دلفي. 🔮 ثالثا: دلفي، سقطة اللسان اللي حكمت اليونان 1 ️ ⃣ الأوراكل"},{"i":"myth-m10","s":13,"h":"","t":"mc","x":"مين اللي قتل الحية بيثون عند دلفي؟ ؟ هرقل / أبولو / زيوس / بوسيدون . أبولو"},{"i":"myth-m10","s":14,"h":"","t":"learn","x":"الأوراكل ( oracle ) يعني \"الوحي\": مكان تسأل فيه الإله عن المستقبل. في دلفي، كانت كاهنة اسمها البيثيا ( Pythia ) تقعد فوق شق في الأرض، تدخل في حالة نشوة، وتتكلم بلسان أبولو. ملوك ومدن كاملة كانت بتسافر تسأل: نحارب ولا لأ؟ نبني مستعمرة فين؟ وإجابات البيثيا كانت مشهورة بغموضها. 2 ️ ⃣ التلات حكم على المعبد 📜"},{"i":"myth-m10","s":15,"h":"","t":"learn","x":"على معبد أبولو في دلفي اتكتبت تلات حكم (من القرن الخامس ق.م على الأقل، أفلاطون بيذكر الحكم دي في حواراته): أ) \"اعرف نفسك\" ( Know thyself / Gnothi seauton ) ب) \"لا شيء بزيادة\" ( Nothing in excess / Meden agan ) ج) \"الضمان يجيب الخراب\" (متتكفلش لحد بفلوس، هتخسر)"},{"i":"myth-m10","s":16,"h":"","t":"learn","x":"الحكم دي كانت بتتنسب لسبع حكماء اليونان أو لأبولو نفسه، وبلينيوس الأكبر بيقول إنها كانت مكتوبة بحروف من ذهب. (المصدر: مقال Delphic maxims ) 3 ️ ⃣ كلمة دخلت الإنجليزي: Delphic من غموض إجابات الأوراكل جت الصفة الإنجليزية delphic : معناها \"غامض، محتمل معنيين، زي كلام الوحي\"."},{"i":"myth-m10","s":17,"h":"","t":"mc","x":"أنهي جملة من الحكم المكتوبة على معبد دلفي؟ ؟ مفيش فايدة من التعب / اعرف نفسك / الصبر مفتاح الفرج / اللي يطلع الأول يكسب . اعرف نفسك"},{"i":"myth-m10","s":18,"h":"","t":"learn","x":"مثال: \" She was known for her Delphic pronouncements. \" 🏹 رابعا: وجه أبولو التاني، إله الطاعون والشفا نرجع لمشهد البداية: الإلياذة الكتاب الأول. أجاممنون أهان كاهن أبولو (كريسيس) ورفض يرجعله بنته، فالكاهن صلى: \"اسمعني يا إله القوس الفضي... خلي الدانايين يدفعوا ثمن دموعي بسهامك\"."},{"i":"myth-m10","s":19,"h":"","t":"mc","x":"كمل الجملة اللي لسه شايفها: She was known for her Delphic _____. ؟ pronouncements / verse / enormous / quietness . She was known for her Delphic pronouncements."},{"i":"myth-m10","s":20,"h":"","t":"learn","x":"فأبولو نزل، ضرب البغال والكلاب الأول، وبعدين البشر، \"وكانت محارق الموتى بتولع بلا توقف\". تسع أيام كاملة. ( Iliad 1.8-52 ) اللقب اللي اتنادى بيه هنا غريب: \" Sminthian \"، يعني إله الفئران! لأن الفئران كانت بتتربط بالطاعون."},{"i":"myth-m10","s":21,"h":"","t":"learn","x":"الدرس: أبولو عند الإغريق وجهين لعملة واحدة: إله الطب والشفا، وإله الوباء. نفس السهم اللي بيقتل بيشفي. عشان كده ابنه أسكليبيوس بقى إله الطب. 🌞 خامسا: فيبوس، الاسم اللي معناه \"المشرق\" اللقب الأشهر لأبولو: فيبوس ( Phoebus )، من اليوناني Phoibos ، ومعناه حرفيا \"المشرق، اللامع، المتوهج\"."},{"i":"myth-m10","s":22,"h":"","t":"mc","x":"ليه أبولو إله الطب وإله الوباء مع بعض؟ ؟ لأن فيه إلهين بنفس الاسم واتدمجوا / لأنه كان طبيب فعلا في جيش طروادة / لأن نفس السهم اللي بيقتل بيشفي / لأن الوباء كان من حظ الإله اللي غضب . لأن نفس السهم اللي بيقتل بيشفي"},{"i":"myth-m10","s":23,"h":"","t":"learn","x":"من اللقب ده، الشعراء بعدين عاملوا أبولو على إنه إله الشمس نفسها (اليونان القدام كانوا بيفرقوا بين أبولو وهيليوس، بس الشعراء اللاتيني والإنجليز دمجوهم). لما شكسبير يقول \"فيبوس بيطلع\"، فهو قاصد الشمس. ومن شجرة أبولو المقدسة، الغار ( laurel )، جت عادة تتويج الشعراء بالغار: \" poet laureate \"، شاعر البلاط. قصة الغار نفسها (أبولو ودافني) هنقابلها في درس لاحق."},{"i":"myth-m10","s":24,"h":"","t":"mc","x":"إيه معنى Phoebus ؟ ؟ الغاضب الحزين / الحكيم الصبور / الصامت الغامض / المشرق اللامع . المشرق اللامع"},{"i":"myth-m10","s":25,"h":"","t":"mc","x":"تتويج الشعراء بتاج poet laureate جاي من أنهي شجرة؟ ؟ الغار / البلوط / الزيتون / النخيل . الغار"},{"i":"myth-m10","s":26,"h":"","t":"learn","x":"📜 الأسطورة في الشعر الإنجليزي 1 ️ ⃣ برسي شيلي، \"نشيد أبولو\" ( Hymn of Apollo ، كتبها حوالي 1820 ونشرت بعد وفاته): شيلي بيخلي أبولو يغني عن نفسه، والقصيدة كلها أنا الشمس/النور. من القصيدة: \" The sunbeams are my shafts, with which I kill Deceit, that loves the night and fears the day. \" (أشعة الشمس هي سهامي، بيها أقتل الخداع اللي بيحب الليل ويخاف النهار.)"},{"i":"myth-m10","s":27,"h":"","t":"learn","x":"ومن مقطع تاني في القصيدة، التلخيص العبقري لكل وظايف أبولو: \" I am the eye with which the Universe Beholds itself and knows itself divine ; All harmony of instrument or verse, All prophecy, all medicine is mine, All light of art or nature. \""},{"i":"myth-m10","s":28,"h":"","t":"learn","x":"(أنا العين اللي الكون بيبص بيها على نفسه ويعرف إنه إلهي؛ كل انسجام آلة أو شعر، وكل نبوءة، وكل طب، ملكي؛ كل نور فن أو طبيعة.)"},{"i":"myth-m10","s":29,"h":"","t":"learn","x":"2 ️ ⃣ جون كيتس، Hyperion الكتاب التالت (1820): كيتس بيكمل قصة صعود الأوليمبيين، وبيخلي الكتاب التالت كله لأبولو الشاب على جزيرة ديلوس: \" Chief isle of the embowered Cyclades, Rejoice, O Delos. .. Apollo is once more the golden theme !\" وأبولو في القصيدة بيتحول لإله لحظة ما العلم يدخل دماغه، فيقول الجملة المشهورة: \" Knowledge enormous makes a God of me. \""},{"i":"myth-m10","s":30,"h":"","t":"mc","x":"كمل الجملة اللي لسه شايفها: Chief isle of the _____ Cyclades, ؟ embowered / sunbeams / instrument / rotten . Chief isle of the embowered Cyclades,"},{"i":"myth-m10","s":31,"h":"","t":"learn","x":"(المعرفة الهائلة هي اللي بتخليني إله.) ( Hyperion 3.113 ) لاحظ فكرة كيتس: أبولو مابقتش إله بالولادة، بقى إله بالمعرفة، ومعرفة مؤلمة. دي نفس فكرة \"الحكمة تجي بالألم\" اللي شفناها عند إسخيلوس."},{"i":"myth-m10","s":32,"h":"","t":"learn","x":"القصيدة بتفتح بشجرة أبولو نفسها: \" Yet once more, O ye laurels, and once more Ye myrtles brown, with ivy never sere. ..\" (مرة تاني يا أغصان الغار...) ولما الشاعر بيشكي إن الشعر مالوش قيمة، بيرد عليه أبولو نفسه في السطر 77: \" Phoebus replied, and touch'd my trembling ears. \" (فيبوس رد، ولمس وداني المرتعشة.)"},{"i":"myth-m10","s":33,"h":"","t":"learn","x":"أبولو هنا هو حارس قيمة الشعر نفسه: بيصحح للشاعر حساباته. 4 ️ ⃣ شكسبير، أغنية الصباح في \" Cymbeline \" (الفصل التاني، المشهد التالت): \" Hark, hark ! the lark at heaven's gate sings, And Phoebus 'gins arise, His steeds to water at those springs On chaliced flowers that lies. ..\""},{"i":"myth-m10","s":34,"h":"","t":"learn","x":"(اسمعوا! القبرة بتغني عند بوابة السما، وفيبوس بدأ يطلع، خيوله بتشرب من الينابيع اللي على الأزهار كأسية الشكل...) هنا فيبوس = شروق الشمس بعينه، بعربته وخيوله. 5 ️ ⃣ المرجع الكلاسيكي: الترنيمة الهوميرية لأبولو (ترجمة Evelyn-White ) والإلياذة الكتاب الأول (ترجمة Murray )، الاتنين فوق. 🧠 سادسا: الفكرة العامة"},{"i":"myth-m10","s":35,"h":"","t":"learn","x":"أبولو هو \"إله النور\" بكل معاني الكلمة: نور الشمس: فيبوس، عربة الشمس، السهام المضيئة. نور المعرفة: النبوءة، \"اعرف نفسك\". نور الفن: القيثارة، الشعر، الغار. بس افتكر المفارقة: النور القوي بيحرق. إله النور هو نفسه إله الطاعون. الإغريق فاهمين إن الحقيقة، زي الشمس، تنفع ومتوصلهاش مباشرة."},{"i":"myth-m10","s":36,"h":"","t":"learn","x":"ولما تيجي تذاكر النقد الأدبي قدام، هتلاقي نيتشه سمى الروح دي \"الأبولونية\" (النظام والضوء والعقل)، في مقابل \"الديونيسية\" (الفوضى والنشوة). 🔤 كلمات إنجليزي من الفصل Phoebus : فيبوس، لقب أبولو، معناه المشرق/اللامع. oracle : أوراكل، الوحي أو مكانه. prophecy : نبوءة. prophetess / priestess : كاهنة. laurel : الغار (شجرة أبولو، وتاج الشعراء). lyre : القيثارة."},{"i":"myth-m10","s":37,"h":"","t":"mc","x":"إيه اللي سماه نيتشه الأبولونية؟ ؟ الفوضى والنشوة والانفلات / الحرب والعنف / الحزن والرثاء / النظام والضوء والعقل . النظام والضوء والعقل"},{"i":"myth-m10","s":38,"h":"","t":"learn","x":"bow and arrows : قوس وسهام. plague : طاعون / وباء. hymn : ترنيمة / نشيد ديني. Delphic : غامض زي كلام الوحي. \" Know thyself \": اعرف نفسك. \" Nothing in excess \": لا شيء بزيادة."},{"i":"myth-m10","s":40,"h":"تذكر واكتب","t":"recall","x":"إيه الحكمتين المكتوبتين على معبد أبولو في دلفي؟ . اعرف نفسك، ولا شيء بزيادة. والاتنين حكمة عملية، مش نبوءة."},{"i":"myth-m10","s":41,"h":"تذكر واكتب","t":"recall","x":"ليه أبولو بقى إلها في Hyperion بتاع كيتس؟ . لأن المعرفة الهائلة هي اللي خلته إلها: \" Knowledge enormous makes a God of me \"، فالألوهية عنده مكتسبة، مش موروثة."},{"i":"myth-m10","s":42,"h":"تذكر واكتب","t":"write","x":"قارن في ٣-٤ جمل بين أبولو عند شيلي في نشيد أبولو وأبولو عند كيتس في Hyperion الكتاب التالت. . شيلي بيخلي أبولو يعرف نفسه بالنور: \" The sunbeams are my shafts, with which I kill / Deceit \"، والهوية عنده بتتقال من خلال الشغل اللي بيعمله في العالم. كيتس بيخلي أبولو يتغير: بيبدأ شابا على ديلوس، وينتهي إلها بالمعرفة، وبيقول \" Knowledge enormous makes a God of me \". يبدو أن شيلي بيوصف إلها كامل من الأول، وكيتس بيوصف لحظة التحول. الاتنين بيستعملوا نفس الإله، لكن واحد بيغني عن سلطته والتاني بيحكي عن تمنها."},{"i":"myth-m10","s":43,"h":"تذكر واكتب","t":"write","x":"قارن في ٣-٤ جمل بين استدعاء أبولو في مطلع Lycidas لميلتون وبين أبولو في نشيد شيلي. . ميلتون بيبدأ من رموز أبولو نفسها: \" Yet once more, O ye laurels, and once more / Ye myrtles brown, with ivy never sere \"، فهو بيدخل القصيدة من باب النبات المقدس عند الإله، والنداء موجه لنفسه كشاعر. شيلي بيعمل العكس: بيسيب أبولو يتكلم، فالإله بقى صوتا، مش رمزا. يمكن القول إن ميلتون بيطلب الإلهام، وشيلي بيخلي الإلهام يتكلم لوحده. والفرق ده بيدينا مقياس على ثقة الشاعر في موقعه من التقليد."},{"i":"myth-m11","s":0,"h":"","t":"learn","x":"🎣 أول حاجة: تخيل الإحساس ده فيه بنت عندها 17 سنة، أبوها رئيس دولة. جات له في يوم وقالت له: \"يا بابا، أنا عايزة حاجة واحدة بس: عايزة أفضل حرة، ماحدش يتجوزني، وماحدش يقولي أعمل إيه. هاتلي قوس وسهام، وهاتلي كلاب، وهاتلي جبل أعيش فيه.\" وأبوها ضحك، وقال: \"خدي اللي عايزاه، وزودك كمان.\""},{"i":"myth-m11","s":1,"h":"","t":"learn","x":"دي مش قصة عصرية عن بنت مستقلة. دي حكاية إغريقية عمرها أكتر من 2200 سنة، عن إلهة اسمها أرتميس ( Artemis )، الرومان سموها ديانا ( Diana ). وكل حاجة في الفصل ده هترجع للحظة الطفولة دي: البنت اللي اختارت حدودها بنفسها."},{"i":"myth-m11","s":2,"h":"","t":"learn","x":"وفي حاجة كمان: أرتميس هي أخت أبولو التوأم، اللي خدناه الفصل اللي فات. وبالرغم إنهم توأم، هم نقيضين تماما. وهو الشمس والنور والكلام والشعر. وهي الليل والغابة والسكوت والقوس. وهنشوف النهارده إن الشعر الإنجليزي استخدم الاتنين، بس كل واحد في مكان مختلف. 📍 إحنا فين في الحكاية؟"},{"i":"myth-m11","s":3,"h":"","t":"learn","x":"في أول الكورس عرفنا يعني إيه أسطورة، وإن الإشارة للأسطورة من غير ذكر اسمها اسمها allusion. بعدها خدنا زيوس، أبو الآلهة. وفي الدرس اللي فات خدنا أبولو: الشمس، النبوة، الشعر، دلفي. النهارده: أخته التوأم أرتميس، إلهة الصيد والقمر والبرية والولادة."},{"i":"myth-m11","s":4,"h":"","t":"learn","x":"وليه الفصل ده مهم للكورس كله؟ لأن أرتميس هي أول إلهة \"الحدود\" في الكورس. هي اللي بتحدد إيه مسموح وإيه ممنوع، وإيه اللي بيحصل لما حد يعدي الخط. والفكرة دي هتيجي معانا في قصص كتير جاية: نيوبي ، أكتايون ، كاليستو ، أنديميون ، إيفيجينيا ، هيبوليتوس . 1 ️ ⃣ مين أرتميس؟ البطاقة الأساسية 🪪 1.1 الاسم."},{"i":"myth-m11","s":5,"h":"","t":"learn","x":"أرتميس ( Artemis ) هو الاسم اليوناني. الرومان سموها ديانا ( Diana ). والرومان ما اخترعوش إلهة جديدة. هم خدوا الإلهة اليونانية وحطوا عليها الاسم الروماني. العادة دي اسمها في التاريخ interpretatio romana ، يعني \"الترجمة الرومانية\" للآلهة الأجنبية. فلو قريت \" Diana \" في قصيدة إنجليزية، اعرف إنها أرتميس."},{"i":"myth-m11","s":6,"h":"","t":"learn","x":"وأصل الاسم اليوناني نفسه مش معروف. ده مش رأيي، ده كلام قاموس أصول الكلمات بالحرف: اسمها \" of unknown origin \". وعالم اللغة بهيكس ( Beekes ) بيرجح إنه اسم من لغة أقدم من اليونانية ( Pre-Greek ). يعني الإغريق نفسهم أخدوا الإلهة دي من حضارة أقدم منهم، وحطوا لها اسم. 1.2 العيلة. أبوها زيوس، وأمها ليتو ( Leto ، والرومان سموها Latona )."},{"i":"myth-m11","s":7,"h":"","t":"mc","x":"إيه الاسم الروماني لأرتميس؟ ؟ ديانا / سيرس / سيليني / أفروديت . ديانا"},{"i":"myth-m11","s":8,"h":"","t":"learn","x":"أخوها التوأم: أبولو. ودي حاجة قالها هسيود في \"نسب الآلهة\" ( Theogony ) في سطر 918: ليتو حملت من زيوس وولدت \"أبولو وأرتميس المحبة للسهام\" (الترجمة الإنجليزية: \" Artemis delighting in arrows \"). يعني الصفة الأولى اللي اتقالت عنها في أقدم نص: السهام. 1.3 الولادة، وأغرب تفصيلة في الحكاية."},{"i":"myth-m11","s":9,"h":"","t":"mc","x":"كمل الجملة اللي لسه شايفها: Artemis delighting in _____ ؟ slumber / archer / chair / arrows . Artemis delighting in arrows"},{"i":"myth-m11","s":10,"h":"","t":"learn","x":"ليتو كانت هربانة من هيرا (مرات زيوس) اللي كانت بتطاردها في كل الأرض، لحد ما وصلت لجزيرة صغيرة اسمها ديلوس ( Delos ). وفي \"الترنيمة الهوميرية لأبولو\" ( Hymn 3, سطر 14-16) بنقرا: \"ابتهجي يا ليتو المباركة، لأنك ولدت أولادا مجيدين: السيد أبولو وأرتميس المحبة للسهام؛ هي في أورتيجيا، وهو في ديلوس الصخرية.\""},{"i":"myth-m11","s":11,"h":"","t":"learn","x":"يعني الاتنين ما اتولدوش في نفس المكان بالظبط. أرتميس اتولدت الأول، في أورتيجيا. وهنا الجزء الغريب: أبولودوروس ( Library 1.4.1 ) بيقول إن ليتو \"ولدت أرتميس أولا، وبمساعدة قابليتها ( midwifery ) ولدت أبولو بعدها\"."},{"i":"myth-m11","s":12,"h":"","t":"learn","x":"تخيل المشهد: بنت مولودة لسه، بتساعد أمها تولد أخوها. والحكاية دي معمولة لسبب: عشان تفسر ليه الستات في اليونان كانوا بينادوا أرتميس وقت الولادة. ونفس الحكاية عند كاليماكوس (شاعر إسكندري من القرن الثالث قبل الميلاد)، وفيها إن الآلام ما جاتش على ليتو وهي بتولد أرتميس، فبقيت أرتميس هي اللي بتخفف آلام غيرها. ( Callimachus, Hymn 3, سطر 1-40)"},{"i":"myth-m11","s":13,"h":"","t":"mc","x":"إيه اللي حصل في الولادة حسب الرواية اللي حكاها أبولودوروس؟ ؟ أبولو اتولد الأول وساعد أخته / أرتميس اتولدت الأول وساعدت أمها تولد أبولو / اتولدوا في نفس اللحظة بالظبط / ماتولدوش، اتخلقوا من نور . أرتميس اتولدت الأول وساعدت أمها تولد أبولو"},{"i":"myth-m11","s":14,"h":"","t":"learn","x":"1.4 ألقابها، وكل لقب وراه حكاية. Cynthia (كينثيا): من جبل كينثوس ( Cynthus ) في جزيرة ديلوس، مكان ولادتها. (من اللاتينية Cynthia dea ، \"الإلهة الكينثية\") Delia : نفس الفكرة، من ديلوس. Phoebe (فيبي): يعني \"المشرقة\"، وده لقب بيستخدم للقمر كمان. Diana Nemorensis : \"ديانا الغابة\"، وهنحكي عنها تحت."},{"i":"myth-m11","s":15,"h":"","t":"learn","x":"potnia theron : يعني \"سيدة الوحوش\". ده لقبها عند هوميروس، في الإلياذة 21.470. 2 ️ ⃣ القصة الكبيرة: البنت اللي طلبت حاجاتها من أبوها 👧 2.1 المشهد. كاليماكوس، في ترنيمته لأرتميس، بيبدأ من مشهد واحد بس: طفلة صغيرة قاعدة على ركب أبوها (زيوس)، وبتتكلم معاه بجدية تامة. 2.2 الطلبات، واحدة واحدة."},{"i":"myth-m11","s":16,"h":"","t":"learn","x":"العذرية الأبدية: \" Give me to keep my maidenhood, Father, forever \" — \"اديني أحفظ عذريتي للأبد يا بابا\". أسماء كتير: \" give me to be of many names \" — عشان أبولو ما يبقاش هو الأشهر. القوس والسهام: بس بذكاء، ما طلبتش قوس كبير: قالت للسيклопات هيعملوا لها واحد. النور: \" Bringer of Light \" — إنها تبقى جايبة النور."},{"i":"myth-m11","s":17,"h":"","t":"mc","x":"كمل الجملة اللي لسه شايفها: Give me to keep my _____, ؟ granted / maidenhood / against / exhausted . Give me to keep my maidenhood,"},{"i":"myth-m11","s":18,"h":"","t":"learn","x":"هدوم عملية: تونيك قصير لحد الركبة، مطرز، عشان تقدر تجري وتصطاد. 60 بنت من بنات أوقيانوس، كلهم 9 سنين، كورس بيغنوا معاها. 20 حورية من أمنيسوس يخدموا كلابها وأحذيتها. كل الجبال. ومدينة واحدة بس. وقالت: \"قليل لما أرتميس بتنزل المدينة.\" 2.3 رد الأب."},{"i":"myth-m11","s":19,"h":"","t":"learn","x":"زيوس ضحك، ووافق، وزادها: 30 مدينة، وقال لها إنها هتبقى \"حارسة الشوارع والمواني\". ( Callimachus, Hymn 3, سطر 28-39) 2.4 ليه المشهد ده عبقرية؟ لأنه بيشرح كل صفات الإلهة في مشهد واحد، من غير ما يعددها. ولأنه بيقول حاجة مهمة: أرتميس هي الإلهة الوحيدة اللي \"اختارت\" هويتها بنفسها. ماحدش فرضها عليها."},{"i":"myth-m11","s":20,"h":"","t":"mc","x":"إيه اللي طلبته أرتميس من أبوها وهي صغيرة؟ ؟ قصر وعرش وسلطة على الآلهة / جواز من أفضل الآلهة / تفضل حرة، وقوس وسهام وأسماء كتير / مدينة تتسمى باسمها . تفضل حرة، وقوس وسهام وأسماء كتير"},{"i":"myth-m11","s":21,"h":"","t":"learn","x":"وده أول مفتاح للفصل: أرتميس إلهة الحدود. هي اللي بترسم الخط، ومش بتحب اللي يعديه. 2.5 ملحوظة أمانة علمية. كاليماكوس متأخر: القرن الثالث قبل الميلاد. يعني النسخة دي مصقولة ومكتوبة، مش أقدم نص. أقدم الإشارات لأرتميس عندنا في هوميروس وهسيود، وأرتميس عندهم إلهة صيد، مش \"بنت طلبت حاجات من أبوها\". الأسطورة بتكبر وتتظبط مع الزمن."},{"i":"myth-m11","s":22,"h":"","t":"learn","x":"3 ️ ⃣ الميادين الأربعة بتاعتها 🗺️ 3.1 الصيد والبرية 🏹 هي إلهة الصيد الأول. بتصطاد بالليل، وبتخرج مع حورياتها. وفي هوميروس، لقبها \"سيدة الوحوش\" ( potnia theron ). يعني مش بس بتصطاد الحيوانات، هي مسؤولة عنهم. والبرية عند الإغريق مش \"مكان وحش\". البرية هي المكان اللي بره المدينة، بره القانون، بره البيوت. وأرتميس هي ملكة المكان ده."},{"i":"myth-m11","s":23,"h":"","t":"learn","x":"مثال من الحياة: الفرق بين الشارع المنظم اللي فيه إشارات ومرور، وبين الصحرا اللي بره البلد. الاتنين موجودين، بس لكل واحد قواعده. 3.2 القمر 🌙 أرتميس اتربطت بالقمر. بس خلينا نكون دقيقين: الربط ده جه متأخر."},{"i":"myth-m11","s":24,"h":"","t":"learn","x":"فيه مرجع متخصص في الأساطير بيقول بالحرف: \" The identification of Selene with Artemis was a late invention \" — توحيد سيليني (إلهة القمر اليونانية) مع أرتميس كان اختراعا متأخرا، ويمكن جه مع دخول إلهة تراقية اسمها بنديس ( Bendis ) لليونان. ومع الوقت، التلاتة (سيليني + هيكاتي + أرتميس) اندمجوا في فكرة واحدة: الإلهة التلاتية."},{"i":"myth-m11","s":25,"h":"","t":"mc","x":"كمل الجملة اللي لسه شايفها: The identification of Selene with Artemis was a late _____ ؟ bethought / albeit / surrender / invention . The identification of Selene with Artemis was a late invention"},{"i":"myth-m11","s":26,"h":"","t":"learn","x":"وشاهد حلو من شيشرون ( De Natura Deorum 2.27 ): \"ديانا بيعرفوها بالقمر... واسم لونا جاي من lucere يعني 'يلمع'... وهي بتتنادى عشان تساعد في ولادة الأطفال، لأن مدة الحمل سبع أو تسع دورات قمرية.\" يعني الربط بين القمر والولادة مش شعر: هو محاولة بدائية لتفسير إن الشهور مرتبطة بالقمر. وفي الشعر الإنجليزي، القمر = ديانا = كينثيا. تلات أسماء لحاجة واحدة."},{"i":"myth-m11","s":27,"h":"","t":"mc","x":"إمتى اتربطت أرتميس بالقمر؟ ؟ من أول الأسطورة وكانت هي القمر / متأخر، واتوحدت مع سيليني بعدين / عمرها ما اتربطت بيه خالص / اتربطت بيه في العصر الروماني بس . متأخر، واتوحدت مع سيليني بعدين"},{"i":"myth-m11","s":28,"h":"","t":"learn","x":"3.3 الولادة والموت المفاجئ ⚖️ دي أغرب نقطة في أرتميس، ومحتاجة تركيز. هي بتحمي الأطفال والحيوانات الصغيرة. وبنفس الوقت، هي اللي بتموت الستات موتا مفاجئا من غير مرض."},{"i":"myth-m11","s":29,"h":"","t":"learn","x":"الدليل الأول، الإلياذة 21: هيرا بتعير أرتميس وتقول لها بالحرف (ترجمة Murray ): \" Zeus made thee a lion against women, and granted thee to slay whomsoever of them thou wilt \" — \"زيوس خلاك لبؤة على الستات، وأدالك تقتلي أي واحدة فيهم تحبيها.\""},{"i":"myth-m11","s":30,"h":"","t":"learn","x":"الدليل التاني، الأوديسة 11: أوديسيوس بيسأل أمه الميتة عن سبب موتها (ترجمة Kline ): \" Was it a wasting disease, or did Artemis of the Bow attack you with her gentle arrows, and kill you? \" — \"كان مرض بياكلك، ولا أرتميس صاحبة القوس ضربتك بسهامها اللطيفة وقتلتك؟\""},{"i":"myth-m11","s":31,"h":"","t":"learn","x":"خد بالك من الكلمة: \" gentle arrows \"، سهام لطيفة. الموت اللي بييجي من غير وجع، من غير حرب، من غير مرض طويل: ده سهم أرتميس. يعني أرتميس مش \"إلهة الموت\". هي الإلهة اللي بتقف على الحد بين الحياة والموت. الست بتولد بمساعدة أرتميس، وبتموت فجأة بسهم أرتميس. نفس الإلهة على الطرفين."},{"i":"myth-m11","s":32,"h":"","t":"learn","x":"وده مثال كويس على حاجة اسمها في الدراسات الدينية \"تفسير بدائي للظاهرة\": الإغريق شافوا إن الستات بتموت فجأة أكتر من الرجالة في سن معينة، فحطوا تفسير: فيه إلهة بتصطادهم. التفسير غلط طبيا، بس الأسطورة شغالة عشان بتدي معنى. 3.4 الطهارة والعذرية 🕊️ أرتميس عذراء للأبد، وحورياتها كلهم عذارى."},{"i":"myth-m11","s":33,"h":"","t":"mc","x":"الموت المفاجئ من غير مرض للستات اتنسب في هوميروس لمين؟ ؟ أثينا بسيفها / ديميتر بسنابل القمح / هيرا بغضبها / أرتميس بسهامها . أرتميس بسهامها"},{"i":"myth-m11","s":34,"h":"","t":"learn","x":"والقاعدة دي هي اللي بتفجر معظم قصصها: أول ما حد يكسر القاعدة، العقاب بييجي فورا. أكتايون شافها، كاليستو حملت، هيبوليتوس اختارها على أفروديت. مثال من الحياة: مدربة فريق صارمة عندها قواعد واضحة، وماحدش بيتناقش فيها. أول واحد يكسر قاعدة بيتطرد من الفريق، مش بسبب كره، بسبب إن القاعدة هي اللي بتحمي الفريق كله. 4 ️ ⃣ 🔄 من الحياة: فين أرتميس في يومك؟"},{"i":"myth-m11","s":35,"h":"","t":"learn","x":"4.1 البنت اللي بتحب \"البرية\". فيه ناس مابيرتاحوش غير بره المدينة: يمشوا في الصحرا، يناموا في خيمة، يصحوا على صوت طيور. المدينة بتخنقهم. أرتميس هي القديسة الراعية للنوع ده من البشر. ولاحظ إنها في الحكاية ما اختارتش قصر، اختارت جبل. 4.2 الطبيبة أو القابلة."},{"i":"myth-m11","s":36,"h":"","t":"learn","x":"اللي بتدخل أوضة الولادة وتقف مع ست في أخطر لحظة في حياتها. ده بالظبط الشغل التاني لأرتميس، والدليل إنها في الحكاية ساعدت أمها تولد وهي لسه مولودة. مفيش إله يوناني تاني عنده الشغلانة دي. 4.3 الخط الأحمر. فيه ناس بتعرف تقول \"لأ\" بوضوح، وعندها خط ما بيتعداش. أرتميس هي أسطورة الخط الأحمر. وكل مشاكلها بتيجي من ناس عدوا الخط."},{"i":"myth-m11","s":37,"h":"","t":"learn","x":"4.4 اللي بيحصل لما حد يعدي الحد. أرتميس ما بتعملش محاكمة. ما بتسمعش دفاع. بتعاقب على طول. وده فرق مهم بين الأسطورة والقانون: القانون بيسأل، الأسطورة بتحكم. خد بالك من النقطة دي لما تقرا قصصها. 5 ️ ⃣ ديانا الرومانية وملك الغابة 🌲🗡️ 5.1 الاسم."},{"i":"myth-m11","s":38,"h":"","t":"learn","x":"ديانا اسم إيطالي قديم، مش ترجمة لأرتميس. وأصله غالبا من جذر هندو-أوروبي * dyeu- يعني \"يلمع\"، ومنه كمان كلمات زي divine و deity و Zeus نفسه. يعني الاسم معناه تقريبا \"اللامعة\"، وده مناسب للقمر. 5.2 غابة نيمي."},{"i":"myth-m11","s":39,"h":"","t":"learn","x":"قرب روما، في منطقة اسمها جبال ألبان، فيه بحيرة اسمها نيمي ( Lake Nemi ). الرومان سموها \"مراية ديانا\" ( Speculum Dianae ) لأنها كانت بتعكس القمر. وحواليها غابة مقدسة لديانا نيمورينسيس. وفي الغابة دي كان فيه كاهن اسمه \"ملك الغابة\" ( rex Nemorensis )."},{"i":"myth-m11","s":40,"h":"","t":"learn","x":"والقاعدة: عبد هارب ( runaway slave ) لو كسر غصن من شجرة بلوط مقدسة، بياخد حق إنه يحارب الكاهن الحالي. لو قتله، بيبقى هو الكاهن الجديد. والكاهن الجديد بيفضل شايل سيفه، قاعد مستني اللي جاي يقتله. (المصادر: سترابو، الجغرافيا 5.3.12؛ باوسانياس 2.27.4؛ سويتونيوس، كاليجولا 35.3) وده مش تخيل: ده وصف من نصوص قديمة. 5.3 ليه ده مهم؟"},{"i":"myth-m11","s":41,"h":"","t":"learn","x":"لأن جيمس فريزر بدأ كتابه الشهير \"الغصن الذهبي\" ( The Golden Bough ) من السؤال ده بالظبط: ليه كاهن ديانا لازم يقتل اللي قبله؟ وده بداية علم الأنثروبولوجيا الحديثة في دراسة الأسطورة. ملحوظة مهمة: مفيش دليل إن أرتميس اليونانية كان عندها طقس زي ده. ده طقس إيطالي محلي لديانا. يعني نفس الإلهة، لكن كل شعب حط لها طقوسه."},{"i":"myth-m11","s":42,"h":"","t":"mc","x":"إيه القاعدة في غابة نيمي لديانا؟ ؟ الكاهن بيتنتخب بالتصويت / اللي يقتل الكاهن الحالي يبقى هو الكاهن الجديد / الكاهن بيورث لابنه / الكاهن بيتعين من الإمبراطور . اللي يقتل الكاهن الحالي يبقى هو الكاهن الجديد"},{"i":"myth-m11","s":43,"h":"","t":"learn","x":"6 ️ ⃣ أفسس: المعبد اللي اتحرق في يوم ميلاد الإسكندر 🏛️🔥 6.1 المدينة. أفسس مدينة على ساحل آسيا الصغرى (تركيا النهاردة). وكان فيها معبد أرتميس، واحد من عجائب الدنيا السبع. 6.2 البناء. بدأ حوالي سنة 550 قبل الميلاد، واتمول جزئيا من كروسوس ( Croesus )، ملك ليديا الغني. (المصدر: Biblical Archaeology Society ، مقال مارك ويلسون عن حريق المعبد) 6.3 الحريق."},{"i":"myth-m11","s":44,"h":"","t":"learn","x":"في سنة 356 قبل الميلاد، واحد اسمه هيروستراتوس ( Herostratus ) دخل المعبد بالليل وحط نار في الأماكن الحساسة، وحرقه بالكامل. وسلم نفسه بنفسه، واعترف، والسبب؟ عايز اسمه يفضل في التاريخ. والأفسسيون عملوا إيه؟ قتلوه، ومنعوا ذكر اسمه تحت تهديد الموت. بس مؤرخ اسمه ثيوبومبوس كتب عنه، فالاسم وصل لنا. الخطة نجحت. 😅 6.4 الحكاية الحلوة."},{"i":"myth-m11","s":45,"h":"","t":"learn","x":"في نفس الليلة، اتولد الإسكندر الأكبر في مقدونيا. بلوتارخ في \"حياة الإسكندر\" (فصل 3) بيقول إن هيجيسياس قال جملة لطيفة: مش عجيب إن معبد أرتميس اتحرق، لأن الإلهة كانت مشغولة تولد الإسكندر. وفيه تفصيلة سياسية حلوة: الإسكندر بعدين عرض يدفع تمن إعادة البناء، فالأفسسيون رفضوا، وقالوا: \"مش صح إن إله يبني معبد لإله تاني.\" (نفس المصدر)"},{"i":"myth-m11","s":46,"h":"","t":"learn","x":"6.5 الاسم في العهد الجديد. المعبد اتبنى تاني بعد كده. والرومان سموها ديانا أفسس. وفي سفر أعمال الرسل، الفصل 19، فيه مشهد كامل عن هيصة في المدينة بسببها: واحد اسمه ديميتروس، صايغ فضة، كان بيصنع \"مقامات فضة لديانا\" وبيتعيش من الشغلانة دي. (أعمال 19:24) لما بولس بقى يوعظ، ديميتروس خاف على تجارته، وجمع الصناع، وقال لهم إن \"صناعتنا في خطر\". (19:27)"},{"i":"myth-m11","s":47,"h":"","t":"learn","x":"والنتيجة: المدينة اتقسمت، والناس اتجمعت في المسرح، وفضلوا يصوتوا لمدة ساعتين: \" Great is Diana of the Ephesians \" — \"عظيمة هي ديانا الأفسسيين\". (أعمال 19:34، ترجمة King James ) 6.6 التمثال الشهير، والحقيقة اللي ماحدش بيقولها. تمثال ديانا أفسس مش زي أي تمثال يوناني أو روماني. فيه \"زخرفة صدر متعدد\" — كتل كتير على الصدر أو على الوسط."},{"i":"myth-m11","s":48,"h":"","t":"mc","x":"مين حرق معبد أرتميس في أفسس سنة 356 ق.م؟ ؟ زلزال دمره / الرومان في حرب مع اليونان / عباد أبولو الغاضبين / هيروستراتوس عشان اسمه يفضل في التاريخ . هيروستراتوس عشان اسمه يفضل في التاريخ"},{"i":"myth-m11","s":49,"h":"","t":"learn","x":"والكتب الشعبية بتقول \"إلهة بأثداء كتير\". الحقيقة: العلماء مش متفقين خالص. فيه دراسات بتقول أثداء، ودراسات بتقول بلح أو فواكه (لأن النخلة رمز أفسس)، وفيه اللي بيقول بيض، وفيه اللي بيقول خصي تيران. (بحث أنيتا رادي، \" The Polymastic Nature of the Diana Ephesia Cult Statue \")"},{"i":"myth-m11","s":50,"h":"","t":"learn","x":"الخلاصة الأمينة: إحنا مش عارفين. وأي حد يقول لك \"دي إلهة الخصوبة بألف بز\" بيبقى بيبالغ. 6.7 تنبيه مهم. ديانا أفسس مش ديانا الرومانية الكلاسيكية. التمثال شكله شرقي قديم جدا، واليونانيين والرومان نفسهم كانوا مستغربين منه. نفس الاسم، حاجات مختلفة. وده درس في الميثولوجيا: الاسم الواحد ممكن يغطي تلات ديانات. 7 ️ ⃣ القصص المرتبطة، وهنقابلها لاحقا 🧵"},{"i":"myth-m11","s":51,"h":"","t":"learn","x":"7.1 نيوبي — ست تحدت أم الإلهة. نيوبي ست من طيبة، عندها ولاد كتير. قالت لليتو: \"أنا ولدت كتير، وإنت ولدت اتنين بس.\" النتيجة: أبولو قتل الولاد بسهامه، وأرتميس قتلت البنات بسهامها. وهوميروس حكاها في الإلياذة 24، سطر 602-617، وهي أقدم ذكر للقصة."},{"i":"myth-m11","s":52,"h":"","t":"learn","x":"والاقتباس (ترجمة Murray ): \" For even the fair-haired Niobe bethought her of meat, albeit twelve children perished in her halls, six daughters and six lusty sons. The sons Apollo slew with shafts from his silver bow. .. and the daughters the archer Artemis. \""},{"i":"myth-m11","s":53,"h":"","t":"mc","x":"كمل الجملة اللي لسه شايفها: For even the fair-_____ Niobe bethought her of meat, ؟ sleep / sailed / wandring / haired . For even the fair-haired Niobe bethought her of meat,"},{"i":"myth-m11","s":54,"h":"","t":"learn","x":"يعني: \"حتى نيوبي الجميلة شعرها افتكرت الأكل، مع إن 12 ولد ماتوا في بيتها، ست بنات وست ولاد. الولاد قتلهم أبولو بسهام قوسه الفضي، والبنات قتلتهم أرتميس صاحبة السهام.\" وبعدها نيوبي بكت لحد ما بقت حجر على جبل سيبيلوس، والدموع لسه بتنزل منه."},{"i":"myth-m11","s":55,"h":"","t":"learn","x":"ملحوظة: عدد الولاد بيختلف بين النسخ. هوميروس بيقول 12 (6+6)، أوفيد بيقول 14 (7+7)، وفيه نسخ بأرقام تانية. ( Oxford Classical Dictionary ، مادة Niobe ) 7.2 أكتايون — الصياد اللي شافها. أكتايون صياد شاف أرتميس وهي بتستحمى في الغابة. العقاب: حولته لغزال، وكلابه هي اللي قتلته."},{"i":"myth-m11","s":56,"h":"","t":"learn","x":"أوفيد حكى القصة في \"التحولات\" الكتاب 3 ولاحظ الحكمة القاسية: الصياد اللي عاش على الصيد، مات بسبب كلابه. 7.3 كاليستو — الحورية اللي بقت دبة. كاليستو كانت من حوريات أرتميس. زيوس حبها، وجالها في شكل أرتميس نفسها (يعني استغل شكل الإلهة عشان يخدعها). لما الحمل بان وهي بتستحمى، أرتميس طردتها. وبعدين هيرا (مرات زيوس) حولتها لدبة."},{"i":"myth-m11","s":57,"h":"","t":"learn","x":"وابنها أركاس كبر وصياد، وجا يقتلها وهو مش عارف إنها أمه، فزيوس أنقذ الموقف وحول الاتنين لكواكب: الدب الأكبر والدب الأصغر. ( Ovid, Metamorphoses 2.409-531 ) الحكاية دي فيها كل حاجة: الخداع، والطرد، والتحول، والنجاة في السما. 7.4 أوريون — الصياد العملاق."},{"i":"myth-m11","s":58,"h":"","t":"mc","x":"كاليستو حورية أرتميس اتحولت لإيه؟ ؟ ذئبة / دبة / غزالة / شجرة . دبة"},{"i":"myth-m11","s":59,"h":"","t":"learn","x":"أوريون صياد عملاق. فيه نسخة قديمة عند هوميروس إن إيوس (الفجر) حبته، فأرتميس قتلته في أورتيجيا. (الأوديسة 5.121-124) وفي الأوديسة 11.572-575، أوديسيوس شافه في العالم السفلي وهو بيجمع الوحوش اللي كان قتلهم في حياته. وفي الإلياذة 18.487-489، أوريون مرسوم على درع أخيل، والدب في السما بيراقبه. (المصدر: Oxford Classical Dictionary ، مادة Orion )"},{"i":"myth-m11","s":60,"h":"","t":"learn","x":"يعني أوريون موجود في السما كنجم، وقصته فيها أكتر من نسخة، وده طبيعي في الميثولوجيا. 7.5 إيفيجينيا — البنت اللي اتطلبت قربان. أرتميس هي اللي طلبت من أجاممنون يقدم بنته إيفيجينيا قربان، عشان الرياح ترجع للسفن اللي رايحة طروادة. والحكاية دي من أهم حكايات حرب طروادة 7.6 هيبوليتوس — الشاب اللي اختارها."},{"i":"myth-m11","s":61,"h":"","t":"learn","x":"هيبوليتوس شاب مخصص حياته لأرتميس، ورفض أفروديت (إلهة الحب). النتيجة: مات موتة فظيعة بسبب حصنه. 7.7 أنديميون — الراعي النايم. أبولودوروس ( Library 1.7.5 ) بيقول: أنديميون كان جميل جدا، \"فالقمر حبه، وزيوس خلاه يختار، فاختار إنه ينام للأبد، بلا موت وبلا شيخوخة\"."},{"i":"myth-m11","s":62,"h":"","t":"learn","x":"يعني إلهة القمر حبت واحد، وهو اختار النوم. أغرب قصة حب في الميثولوجيا، وكيتس كتب عنها قصيدة كاملة. 8 ️ ⃣ 📜 الأسطورة في الشعر الإنجليزي 8.1 شكسبير، \"حلم ليلة صيف\" ( A Midsummer Night's Dream )، الفصل الأول، المشهد الأول، سطر 9-11. هيبوليتا بتتكلم: \" And then the moon, like to a silver bow New-bent in heaven, shall behold the night Of our solemnities. \""},{"i":"myth-m11","s":63,"h":"","t":"mc","x":"كمل الجملة اللي لسه شايفها: like to a _____ bow ؟ shafts / slain / silver / paper . like to a silver bow"},{"i":"myth-m11","s":64,"h":"","t":"learn","x":"الترجمة: \"وبعدين القمر، زي قوس فضي متوتر جديد في السما، هيشهد ليلة أفراحنا.\" الشرح: هيبوليتا بتتكلم عن الهلال اللي هيطلع بعد أربع ليالي. وشبهته بقوس \"متوتر جديد\" ( new-bent ). وليه التشبيه ده ذكي؟ لأن القوس هو سلاح أرتميس بالظبط. يعني شكسبير حط الإلهة في المشهد من غير ما ينطق اسمها. ده ال allusion اللي اتكلمنا عنه، إشارة من غير اسم."},{"i":"myth-m11","s":65,"h":"","t":"learn","x":"وكمان: المسرحية كلها مشغولة بالقمر. القمر هو اللي بيحدد مواعيد العرس، والقمر هو اللي بيخبط على كل حاجة في الغابة. فالتشبيه مش زينة، هو موضوع المسرحية. 8.2 بن جونسون، \" Queen and huntress, chaste and fair \" — من مسرحية Cynthia's Revels (اتعملت بين سبتمبر 1600 ومايو 1601):"},{"i":"myth-m11","s":66,"h":"","t":"learn","x":"\" Queen and huntress, chaste and fair, Now the sun is laid to sleep, Seated in thy silver chair"},{"i":"myth-m11","s":67,"h":"","t":"learn","x":"State in wonted manner keep : Hesperus entreats thy light, Goddess excellently bright. \" الترجمة: \"يا ملكة ويا صيادة، عفيفة وجميلة، / الشمس دلوقتي راحت تنام، / قاعدة على كرسيك الفضي / حافظة مكانك زي عادتك: / نجمة المساء بتستأذن نورك، / يا إلهة شديدة الإشراق.\""},{"i":"myth-m11","s":68,"h":"","t":"learn","x":"الشرح: أول سطر فيه تلات صفات في ست كلمات: queen (ملكة)، huntress (صيادة)، chaste (عفيفة). ده تلخيص كامل لأرتميس. \" silver chair \" = القمر، عرش فضي في السما. و Hesperus هو نجم المساء (كوكب الزهرة)، وبيتوسل للإلهة إنها تطلع. يعني جونسون بيصور لحظة غروب الشمس وظهور القمر كأنها تغيير حراسة."},{"i":"myth-m11","s":69,"h":"","t":"learn","x":"و\" Cynthia \" في عنوان المسرحية مش القمر بس: هي الملكة إليزابيث الأولى. الملكة كانت بتتسمى كينثيا في البلاط، وجونسون استغل ده. وليه ده مهم؟ لأنه بيورينا الاستخدام التاني للأسطورة: مش بس تشبيه شعري، ده مدح سياسي. الشاعر بيقول للملكة: إنت الإلهة. والمدح ده كان شغلانة الشاعر في القرن السبعتاشر."},{"i":"myth-m11","s":70,"h":"","t":"learn","x":"8.3 ميلتون، \" Il Penseroso \" (نشرت في مجموعة Poems سنة 1645)، سطر 59-60: \" While Cynthia checks her Dragon yoke, Gently o're th' accustom'd Oke \" الترجمة: \"بينما كينثيا تكبح نير تنينها، / بهدوء فوق البلوطة المعتادة.\""},{"i":"myth-m11","s":71,"h":"","t":"mc","x":"كمل الجملة اللي لسه شايفها: While Cynthia _____ her Dragon yoke, ؟ wasting / checks / sleep / breaks . While Cynthia checks her Dragon yoke,"},{"i":"myth-m11","s":72,"h":"","t":"learn","x":"الشرح: كينثيا = القمر. والتنين هو التنين اللي بيجر عربة القمر في التقليد القديم. ميلتون بيصور مشهد الليل الهادي: القمر بيعدي على الشجرة اللي هو معتاد يعدي عليها كل ليلة. وفي نفس القصيدة، سطر 67-68، بيكمل: \" To behold the wandring Moon, / Riding neer her highest noon \" — \"عشان أشوف القمر التايه، راكب قريب من أعلى نقطة ليه.\""},{"i":"myth-m11","s":73,"h":"","t":"learn","x":"وملحوظة إملاء مهمة: النص الأصلي فيه \" wandring \" و\" neer \" و\" o're \". دي إملاء القرن السبعتاشر. لما تنقل اقتباس من ميلتون، انقله بإملائه الأصلي، وماتصلحهوش. (دي نفس الملحوظة اللي عملناها في فصل أبولو.) والمصدر: نص مشروع ميلتون في جامعة دارتموث. 8.4 ماكولي، \" The Battle of the Lake Regillus \" (من مجموعة Lays of Ancient Rome ): \" The priest who slew the slayer,"},{"i":"myth-m11","s":74,"h":"","t":"learn","x":"And shall himself be slain. \" الترجمة: \"الكاهن اللي قتل القاتل، / وهو نفسه هيقتل.\" الشرح: سطرين بس، وفيهم كل حكاية ملك الغابة اللي حكيناها فوق. ماكولي بيلخص الدايرة: العنف بيدور، واللي بيقتل بيبقى هو اللي مستني دوره. ودي حاجة حلوة تتعلمها عن الشعر: مش لازم تقول كل حاجة. سطرين كفاية لو اختارتهم صح."},{"i":"myth-m11","s":75,"h":"","t":"learn","x":"8.5 كيتس، \" Endymion \" (1818): \" A thing of beauty is a joy for ever. \" الترجمة: \"الحاجة الجميلة فرحة للأبد.\" الشرح: القصيدة كلها عن الراعي أنديميون، وإلهة القمر — كيتس بيسميها Cynthia في القصيدة — بتحبه. وأول سطر في القصيدة بقى واحد من أشهر سطور الشعر الإنجليزي كله."},{"i":"myth-m11","s":76,"h":"","t":"learn","x":"ولاحظ: كيتس كتب 4000 سطر عشان يحكي قصة حب إلهة القمر لراعي نايم. الأسطورة دي عندها طاقة شعرية غريبة. 8.6 والتر رالي، \" The Ocean to Cynthia \" — الإلهة بقت ملكة. رالي كتب قصيدة طويلة عن الملكة إليزابيث الأولى، وسماها Cynthia."},{"i":"myth-m11","s":77,"h":"","t":"learn","x":"ما اتنشرتش في حياته، ومفيش نسخة كاملة. اتلاقى جزء منها في مخطوطات هاتفيلد، مكتوب عليه \"الكتاب الحادي والعشرين والأخير من المحيط، إلى كينثيا\". وطبعها ج. هانا أول مرة سنة 1870. وحتى سبنسر، صاحب \"ملكة الجن\"، بيسموها كينثيا في قصيدته Colin Clout."},{"i":"myth-m11","s":78,"h":"","t":"learn","x":"الخلاصة: من القرن الستاشر، \"كينثيا\" في الشعر الإنجليزي بقت تعني الملكة إليزابيث. الإلهة خرجت من الأسطورة ودخلت السياسة. 9 ️ ⃣ أخطاء شائعة، خد بالك منها ⚠️ 9.1 \"ديانا إلهة الشر\". لأ. هي إلهة حدود. العقاب عندها مش شر، هو نتيجة حتمية لتعدي الحد. والفرق ده هو اللي بيخلي القصص مفهومة، مش مجرد حكايات عن إلهة عصبية."},{"i":"myth-m11","s":79,"h":"","t":"mc","x":"من القرن ال16، كينثيا ( Cynthia ) في الشعر الإنجليزي بقت تعني مين؟ ؟ الملكة إليزابيث / القمر بس / أبولو / ديانا الصيادة . الملكة إليزابيث"},{"i":"myth-m11","s":80,"h":"","t":"learn","x":"9.2 \"أرتميس = القمر من الأول\". لأ. الربط بالقمر جه متأخر، واتوحدت مع سيليني بعدين. في هوميروس هي بالأساس إلهة الصيد والوحوش. 9.3 \"ديانا أفسس = ديانا الرومانية\". لأ. التمثال مختلف تماما وأقدم بكتير، واليونانيين والرومان نفسهم كانوا مستغربين منه."},{"i":"myth-m11","s":81,"h":"","t":"learn","x":"9.4 \"الأسطورة نسخة واحدة\". لأ. عدد ولاد نيوبي 12 عند هوميروس و14 عند أوفيد. ومكان ولادة التوأم مختلف عليه (ديلوس وأورتيجيا). وده مش عيب في الأسطورة، ده طبيعتها. 9.5 \"أرتميس وأبولو توأم يعني شبه بعض\". لأ، هما نقيضين: نهار/ليل، كلام/سكوت، مدينة/غابة، شمس/قمر. والاتنين بيتقابلوا في حاجة واحدة: ديلوس، أمهم، وليتو. 🔟 كلمات هتقع لك في الشعر 📖"},{"i":"myth-m11","s":82,"h":"","t":"learn","x":"huntress = صيادة (مؤنث hunter ) chaste = عفيفة / عذراء quiver = جعبة السهام bow = قوس hind = غزالة stag = غزال ذكر yoke = نير (اللي بيربط الحيوانات بالعربة) orb = جسم سماوي / كرة (بيتقال على القمر والشمس) maidenhood = العذرية wilderness = البرية nymph = حورية the chase = الصيد / المطاردة silver = فضي (صفة أساسية لأرتميس: قوس فضي، كرسي فضي، سهام فضية)"},{"i":"myth-m11","s":83,"h":"","t":"mc","x":"إيه معنى the chase ؟ ؟ نير (اللي بيربط الحيوانات بالعربة) / الصيد / المطاردة / الحرية / العذرية . the chase = الصيد / المطاردة"},{"i":"myth-m11","s":84,"h":"","t":"mc","x":"إيه معنى maidenhood ؟ ؟ الصيد / المطاردة / العذرية / نير (اللي بيربط الحيوانات بالعربة) / صيادة (مؤنث hunter) . maidenhood = العذرية"},{"i":"myth-m11","s":85,"h":"","t":"mc","x":"إيه معنى huntress ؟ ؟ جسم سماوي / كرة (بيتقال على القمر والشمس) / صيادة (مؤنث hunter) / البرية / فضي (صفة أساسية لأرتميس: قوس فضي، كرسي فضي، سهام فضية) . huntress = صيادة (مؤنث hunter)"},{"i":"myth-m11","s":86,"h":"","t":"mc","x":"إيه معنى orb ؟ ؟ فضي (صفة أساسية لأرتميس: قوس فضي، كرسي فضي، سهام فضية) / عذراء (مؤنث maiden) / نير (اللي بيربط الحيوانات بالعربة) / جسم سماوي / كرة (بيتقال على القمر والشمس) . orb = جسم سماوي / كرة (بيتقال على القمر والشمس)"},{"i":"myth-m11","s":87,"h":"","t":"write","x":"مقارنة: قارن بين أرتميس وأبولو: العلاقة بينهم، والمجالات، وإيه اللي بيرمز له كل واحد في الشعر. . أرتميس وأبولو توأم، أولاد زيوس وليتو. أبولو: الشمس والنور والنبوءة والموسيقى والشعر (وفي معبد دلفي). أرتميس: القمر والبرية والصيد وحماية البنات الصغيرات والولادة، وهي عذراء. في الشعر أبولو غالبا بيمثل الإلهام والنظام والنور، وأرتميس (أو ديانا) بتمثل العفة والقمر والحدود والعالم البري. الخلاصة: الاتنين نقيضين: هو نهار وكلام وفن، وهي ليل وغابة وسكوت."},{"i":"myth-m12","s":1,"h":"مقدمة","t":"learn","x":"🎣 فيه بنت اتولدت بطريقة محدش يتخيلها: ما اتولدتش من بطن أم. اتولدت من راس أبوها. وطلعت من راسه كاملة، لابسة درع دهبي، وبتلوح برمح حاد. والدنيا كلها ارتعشت من صرختها."},{"i":"myth-m12","s":2,"h":"مقدمة","t":"learn","x":"دي مش قصة خيال علمي. دي أول حاجة بيقولها الإغريق عن أثينا ( Athena )، واسمها عند الرومان مينيرفا ( Minerva ). الفصل ده هو التوأم المعنوي للفصل اللي فات. في M11 خدنا أرتميس: إلهة الغابة والصيد والحدود. النهارده أثينا: إلهة المدينة والحكمة والحرف والقانون."},{"i":"myth-m12","s":3,"h":"مقدمة","t":"learn","x":"الاتنين عذارى، والاتنين إلهات قويات. بس واحدة ملكة البرية، والتانية ملكة المدينة. وده الفرق اللي هيمشي معانا طول الفصل."},{"i":"myth-m12","s":5,"h":"إحنا فين في الحكاية؟","t":"learn","x":"في الأول عرفنا يعني إيه أسطورة، وإيه ال allusion (الإشارة لأسطورة من غير ذكر اسمها)، وإيه البطل. بعدها خدنا زيوس، وأبولو، وأرتميس. النهارده أثينا، وهي إلهة هنقابلها بعد كده في قصص كتير: النساجة أراخني، ومحاكمة أوريستيس، وميدوسا، وحرب طروادة."},{"i":"myth-m12","s":6,"h":"إحنا فين في الحكاية؟","t":"learn","x":"وليه أثينا مهمة لكورس الشعر الإنجليزي؟ لأن الشاعر بيستدعيها لما يتكلم عن العقل والحكمة والقانون والفن. ولما تشوف في قصيدة إنجليزية كلمة Pallas أو Minerva ، اعرف إن الشاعر بيستدعي العقل نفسه."},{"i":"myth-m12","s":8,"h":"1) مين أثينا؟ البطاقة الأساسية 🪪","t":"learn","x":"الاسم: أثينا ( Athena ) هو الاسم اليوناني. والرومان سموها مينيرفا ( Minerva ). أصل اسم أثينا مش معروف بشكل مؤكد. فيه علماء، زي Beekes ، بيرجحوا إنه من لغة أقدم من اليونانية، اللي بيسموها pre-Greek ."},{"i":"myth-m12","s":9,"h":"1) مين أثينا؟ البطاقة الأساسية 🪪","t":"learn","x":"أما مينيرفا فاسم روماني قديم، وأصله من كلمة معناها \"ذكي، فاهم\"، من جذر هندو-أوروبي معناه \"يفكر\". ومن نفس الجذر جت كلمة mind الإنجليزية. يعني اسم مينيرفا قريب جدا من معنى \"العقل\". وده مش صدفة: الإلهة الرومانية كانت إلهة العقل والحرف."},{"i":"myth-m12","s":10,"h":"1) مين أثينا؟ البطاقة الأساسية 🪪","t":"learn","x":"العيلة: أبوها زيوس. أمها ميتيس ( Metis )، واسمها معناه \"الحكمة\" أو \"الفكرة الذكية\". وميتيس مش أم عادية، لأن زيوس بلعها وهي حامل. هنحكي الحكاية بعد شوية."},{"i":"myth-m12","s":11,"h":"1) مين أثينا؟ البطاقة الأساسية 🪪","t":"learn","x":"ألقابها، وكل لقب بيقول حاجة: Pallas : أشهر ألقابها، وبيتستخدم في الشعر الإنجليزي كتير. Parthenos : يعني \"العذراء\". ومنها اسم البارثينون. Promachos : \"اللي بتقاتل في المقدمة\". Polias : \"حامية المدينة\"."},{"i":"myth-m12","s":12,"h":"1) مين أثينا؟ البطاقة الأساسية 🪪","t":"learn","x":"glaukopis : صفة بتتكرر عند هوميروس. معناها غالبا \"اللي عينيها لامعة\"، وفيه تفسير تاني إنها \"بعين البومة\". Tritogeneia : لقب معناه مختلف عليه، ومحدش متأكد منه. وإحنا مش هنخترع له معنى."},{"i":"myth-m12","s":13,"h":"1) مين أثينا؟ البطاقة الأساسية 🪪","t":"learn","x":"مجالاتها: الحكمة والمشورة. الحرب العاقلة والدفاعية، مش الحرب الهمجية. الحرف: النسيج والفخار وبناء السفن. القانون والمدينة. وهي حامية الأبطال الأذكياء، زي أوديسيوس."},{"i":"myth-m12","s":15,"h":"2) القصة الكبيرة: الولادة من الراس 🧠⚡","t":"learn","x":"زيوس وميتيس: بعد ما الآلهة كسبوا حرب التيتان، زيوس اتجوز ميتيس، وهي كانت \"أحكم من الآلهة والبشر\". في \"نسب الآلهة\" ( Theogony ) لهسيود، تقريبا في الأسطر 886 ل 900، فيه نبوة: ميتيس هتولد بنت تساوي أبوها في القوة والحكمة، وبعدها ولد هيبقى ملك الآلهة وهيزيح زيوس."},{"i":"myth-m12","s":16,"h":"2) القصة الكبيرة: الولادة من الراس 🧠⚡","t":"learn","x":"وزيوس، اللي هو نفسه خدع أبوه كرونوس، عرف يعني إيه نبوة زي دي. فعمل إيه؟ خدع ميتيس بكلام ناعم، وبلعها وهي حامل."},{"i":"myth-m12","s":17,"h":"2) القصة الكبيرة: الولادة من الراس 🧠⚡","t":"mc","x":"ليه زيوس بلع ميتيس؟ ؟ عشان كانت بتحارب الآلهة / عشان ماكانتش حكيمة كفاية / عشان عاقبها على سرقة النار / عشان النبوة قالت إن ابنها هيزيحه عن الحكم . عشان النبوة قالت إن ابنها هيزيحه عن الحكم"},{"i":"myth-m12","s":18,"h":"2) القصة الكبيرة: الولادة من الراس 🧠⚡","t":"learn","x":"النتيجة: أثينا اتولدت من راس زيوس. هسيود، في حوالي السطر 924، بيقول إن زيوس ولد من راسه أثينا \"اللامعة العينين\" ( glaukopis ). وفي الترنيمة الهوميرية 28، المشهد بيتحكي بالتفصيل. ده وصف جميل: \" From his awful head wise Zeus himself bare her arrayed in warlike arms of flashing gold, and awe seized all the gods as they gazed .\""},{"i":"myth-m12","s":19,"h":"2) القصة الكبيرة: الولادة من الراس 🧠⚡","t":"learn","x":"يعني: \"من راسه المهيب، زيوس الحكيم نفسه ولدها، لابسة سلاح حرب من دهب لامع، والرهبة أخدت الآلهة كلهم وهما بيبصوا\"."},{"i":"myth-m12","s":20,"h":"2) القصة الكبيرة: الولادة من الراس 🧠⚡","t":"learn","x":"وبعدها: \" But Athena sprang quickly from the immortal head and stood before Zeus who holds the aegis, shaking a sharp spear : great Olympus began to reel horribly at the might of the bright-eyed goddess .\" يعني أثينا نطت من الراس ووقفت قدام زيوس بتلوح برمح حاد، وجبل أوليمبوس العظيم بدأ يترنح من قوتها."},{"i":"myth-m12","s":21,"h":"2) القصة الكبيرة: الولادة من الراس 🧠⚡","t":"learn","x":"وأجمل تفصيلة: الشمس نفسها وقفت. الترنيمة بتقول إن ابن هيبيريون (يعني الشمس) وقف حصانه السريع فترة طويلة. يعني الكون كله اتجمد لحظة الميلاد."},{"i":"myth-m12","s":22,"h":"2) القصة الكبيرة: الولادة من الراس 🧠⚡","t":"learn","x":"ملحوظة أمانة علمية: هسيود هو أقدم مصدر عندنا، وهو ما ذكرش هيفايستوس ولا الفأس ولا إنها طلعت لابسة سلاح. أول واحد ذكر السلاح هو الشاعر Stesichorus ، وقصيدته ضاعت. وبعده Pindar ( Olympian 7) حكى إن هيفايستوس شق راس زيوس بفأس، والدنيا ارتعبت من الصرخة."},{"i":"myth-m12","s":23,"h":"2) القصة الكبيرة: الولادة من الراس 🧠⚡","t":"learn","x":"يعني التفصيلة الشهيرة \"هيفايستوس شق الراس بفأس\" جت متأخرة عن هسيود. والنسخة الشعبية النهارده خليط من مصادر كتير."},{"i":"myth-m12","s":24,"h":"2) القصة الكبيرة: الولادة من الراس 🧠⚡","t":"tf","x":"هسيود، أقدم مصدر، ذكر إن هيفايستوس شق راس زيوس بفأس. . غلط"},{"i":"myth-m12","s":25,"h":"2) القصة الكبيرة: الولادة من الراس 🧠⚡","t":"learn","x":"ليه من الراس؟ لأنها إلهة العقل. الحكاية رمز: الحكمة بتتولد من العقل نفسه، من غير أم ومن غير جسد. وفيها حاجة تانية أعمق: الإلهة الراعية لأثينا، المدينة اللي اخترعت الديمقراطية، بتتولد من الأب بس. وده بيفسر موقفها في محاكمة أوريستيس، وهنشوفها بعد شوية."},{"i":"myth-m12","s":26,"h":"2) القصة الكبيرة: الولادة من الراس 🧠⚡","t":"learn","x":"مثال من حياتنا: تخيل شركة كل الناس فيها بيقولوا \"الفكرة دي جت من دماغ المدير\". الفكرة مالهاش أم، ليها مصدر واحد بس: العقل. الأسطورة بتقول نفس الحكاية عن الحكمة."},{"i":"myth-m12","s":28,"h":"3) الميادين الأربعة 🗺️","t":"learn","x":"المدينة 🏙️ أثينا حامية المدينة اللي اسمها عليها. والعلاقة بينهم قوية لدرجة إن ناس بتقول إن اسم المدينة جاي من اسم الإلهة، وناس بتقول العكس، ويمكن الاتنين من أصل أقدم. معبدها الكبير هو البارثينون على الأكروبوليس. ومهرجانها الكبير اسمه Panathenaia ، وفيه موكب ضخم."},{"i":"myth-m12","s":29,"h":"3) الميادين الأربعة 🗺️","t":"learn","x":"الحرب العاقلة ⚔️ أثينا إلهة الحرب، بس مش أي حرب. هي حرب التخطيط والدفاع عن المدينة والاستراتيجية. الحرب الهمجية والعنف من غير سبب شغل آريس ( Ares )، إله الحرب العنيف. ولما شاعر عايز يقول \"حرب شريفة\" بيستدعي أثينا. ولما عايز يقول \"حرب وحشية\" بيستدعي آريس."},{"i":"myth-m12","s":30,"h":"3) الميادين الأربعة 🗺️","t":"learn","x":"الحرف والنسيج 🧵 أثينا إلهة الصنعة: النسيج والفخار وبناء السفن. النسيج كان شغل الستات الأساسي في اليونان، وفيه مهارة وفن. وده اللي بيخلي حكاية أراخني خطيرة: ست بتتحدى إلهة الحرفة في حرفتها."},{"i":"myth-m12","s":31,"h":"3) الميادين الأربعة 🗺️","t":"learn","x":"العقل والحيلة 🦉 أثينا إلهة metis ، يعني الحكمة العملية، الذكاء اللي بيلاقي طريق. وده اللي بيخليها تحب أوديسيوس، الراجل اللي بيكسب بالعقل مش بالعضلات. والبومة رمزها، لأن البومة بتشوف في الضلمة. الحكمة إنك تشوف اللي غيرك مش شايفه."},{"i":"myth-m12","s":32,"h":"3) الميادين الأربعة 🗺️","t":"mc","x":"مين اللي بيمثل الحرب العاقلة، ومين اللي بيمثل الحرب الهمجية؟ ؟ أثينا للعاقلة، وآريس للهمجية / آريس للعاقلة، وأثينا للهمجية / زيوس للعاقلة، وهيرا للهمجية / أرتميس للعاقلة، وأبولو للهمجية . أثينا للعاقلة، وآريس للهمجية"},{"i":"myth-m12","s":34,"h":"4) أثينا وأوديسيوس: المدينة بتحب الذكي 🧠🌊","t":"learn","x":"في الأوديسة، أثينا هي اللي بتقود الحكاية. في الكتاب الأول بتنزل في شكل Mentes عشان تحرك تليماخوس، ابن أوديسيوس. وفي الكتاب التاني بتاخد شكل Mentor ، صاحب قديم لأوديسيوس. ومن هنا جت كلمة mentor الإنجليزية، يعني \"مرشد\". اسم شخصية في الأوديسة بقى كلمة عادية بنستخدمها كل يوم."},{"i":"myth-m12","s":35,"h":"4) أثينا وأوديسيوس: المدينة بتحب الذكي 🧠🌊","t":"learn","x":"وفي الكتاب 13، أحلى مشهد بينهم. أوديسيوس رجع إيثاكا، وأثينا جات له في شكل راعي شاب. هو حكى لها قصة كدب كاملة عشان يخبي نفسه. أثينا ضحكت، ومسحت على وشه، وتحولت لست طويلة جميلة."},{"i":"myth-m12","s":36,"h":"4) أثينا وأوديسيوس: المدينة بتحب الذكي 🧠🌊","t":"learn","x":"وقالت له جملة تستاهل تتحفظ (ترجمة Murray ): \" Cunning must he be and knavish, who would go beyond thee in all manner of guile, aye, though it were a god that met thee .\" يعني: لازم يكون ماكر وخبيث جدا اللي عايز يغلبك في الحيلة، حتى لو كان إله قابلك."},{"i":"myth-m12","s":37,"h":"4) أثينا وأوديسيوس: المدينة بتحب الذكي 🧠🌊","t":"learn","x":"وبعدها: \" thou art far the best of all men in counsel and in speech, and I among all the gods am famed for wisdom and craft .\" يعني: إنت الأفضل بين كل البشر في المشورة والكلام، وأنا بين كل الآلهة مشهورة بالحكمة والحيلة. الإلهة بتقول للبطل: إحنا شبه بعض."},{"i":"myth-m12","s":38,"h":"4) أثينا وأوديسيوس: المدينة بتحب الذكي 🧠🌊","t":"learn","x":"ليه المشهد ده مهم للفصل؟ لأن أرتميس بتحب الصياد المنفرد اللي في الغابة، وأثينا بتحب الراجل اللي بيكسب بالعقل وسط الناس. واحدة بتحمي الحدود، والتانية بتحمي النظام. وده الفرق اللي بدأنا بيه الفصل."},{"i":"myth-m12","s":39,"h":"4) أثينا وأوديسيوس: المدينة بتحب الذكي 🧠🌊","t":"mc","x":"إيه أصل كلمة mentor الإنجليزية؟ ؟ اسم إله روماني للحرب / اسم مدينة يونانية قديمة / اسم قصيدة هوميرية / اسم Mentor ، شخصية في الأوديسة أثينا اتخفت في شكلها . اسم Mentor ، شخصية في الأوديسة أثينا اتخفت في شكلها"},{"i":"myth-m12","s":41,"h":"5) البارثينون: البيت الحجري للإلهة 🏛️","t":"learn","x":"الأرقام: البارثينون اتبنى بين 447 و438 قبل الميلاد، والمهندسين Iktinos و Kallikrates . النحت اتعمل بإشراف النحات Pheidias ، وخلص سنة 432 قبل الميلاد. والمعبد كان في قلب برنامج البناء بتاع Pericles في أثينا."},{"i":"myth-m12","s":42,"h":"5) البارثينون: البيت الحجري للإلهة 🏛️","t":"learn","x":"الاسم: كلمة parthenos في اليونانية معناها \"بنت، عذراء\". فالبارثينون معناه تقريبا \"بيت العذراء\". وجوه المعبد كان فيه تمثال أثينا بارثينوس من الدهب والعاج، عمله Pheidias ، وطوله حوالي 12 متر، واتدشن حوالي 438 قبل الميلاد."},{"i":"myth-m12","s":43,"h":"5) البارثينون: البيت الحجري للإلهة 🏛️","t":"learn","x":"النحت هو أهم حاجة: البروز الشرقي (فوق الباب الرئيسي): ميلاد أثينا من راس زيوس. البروز الغربي: المنافسة بين أثينا وبوسيدون على المدينة. والفريز: موكب Panathenaia ، يعني ناس حقيقيين في موكب ديني. يعني المعبد نفسه بيحكي الأسطورة اللي في الفصل ده. الحجر بقى كتاب."},{"i":"myth-m12","s":44,"h":"5) البارثينون: البيت الحجري للإلهة 🏛️","t":"learn","x":"المنافسة مع بوسيدون: الآلهة قررت إن المدينة تتسمى على اسم اللي يديها أحسن هدية. في بعض الروايات بوسيدون ضرب الصخر بالرمح الثلاثي، فطلع حصان. وفي روايات تانية طلعت عين مية مالحة. وأثينا ضربت الأرض فطلعت شجرة زيتون. وأثينا هي اللي كسبت."},{"i":"myth-m12","s":45,"h":"5) البارثينون: البيت الحجري للإلهة 🏛️","t":"learn","x":"أوفيد ( Metamorphoses 6) بيوصف المشهد منسوج على نسيج مينيرفا. وهيرودوت ( Histories 8.55) بيقول إن على الأكروبوليس، في معبد Erechtheus ، فيه شجرة زيتون وعين مية مالحة، والأثينيين بيقولوا إن بوسيدون وأثينا حطوهم شهود على خلافهم."},{"i":"myth-m12","s":46,"h":"5) البارثينون: البيت الحجري للإلهة 🏛️","t":"learn","x":"الدرس: المدينة اختارت الزيتون، يعني الغذاء والسلام والتجارة، مش الحرب. وده اختيار بيقول إيه شخصية المدينة. وفي حاجة كمان: الغرفة الغربية من المعبد غالبا كانت بتحفظ فيها أموال المدينة وهداياها. يعني المعبد كان زي بنك كمان."},{"i":"myth-m12","s":47,"h":"5) البارثينون: البيت الحجري للإلهة 🏛️","t":"mc","x":"إيه اللي بيظهر في البروز الشرقي من البارثينون؟ ؟ موت أوديسيوس / حرب طروادة / ميلاد أثينا من راس زيوس / خلق الإنسان . ميلاد أثينا من راس زيوس"},{"i":"myth-m12","s":48,"h":"5) البارثينون: البيت الحجري للإلهة 🏛️","t":"tf","x":"كلمة parthenos معناها \"عذراء\"، ومنها اسم البارثينون. . صح"},{"i":"myth-m12","s":49,"h":"5) البارثينون: البيت الحجري للإلهة 🏛️","t":"mc","x":"إيه هدية أثينا للمدينة في المنافسة مع بوسيدون؟ ؟ شجرة زيتون / حصان / سيف / درع . شجرة زيتون"},{"i":"myth-m12","s":51,"h":"6) قصص مرتبطة، وهنقابلها لاحقا 🧵","t":"learn","x":"أراخني، النساجة اللي تحدت الإلهة. (أوفيد، Metamorphoses 6) أراخني بنت من ليديا، مشهورة بالنسيج لدرجة إن الحوريات كانوا بيسيبوا كرومهم عشان يتفرجوا عليها. قالت إن مهارتها من نفسها، مش من مينيرفا. فمينيرفا جات لها في شكل عجوزة تنصحها، وأراخني رفضت. فالإلهة كشفت نفسها، واتفقوا على مسابقة نسيج."},{"i":"myth-m12","s":52,"h":"6) قصص مرتبطة، وهنقابلها لاحقا 🧵","t":"learn","x":"مينيرفا نسجت منافستها مع بوسيدون على المدينة. وأراخني نسجت فضايح الآلهة وحبهم للبشر. شغل أراخني كان بلا عيب. فمينيرفا مزقته وضربتها. وأراخني شنقت نفسها، فحولتها مينيرفا لعنكبوت. وفيها سؤال حلو: ليه الإلهة بتعاقب أحسن واحدة بعدها؟ هنرجع له في فصل جاي."},{"i":"myth-m12","s":53,"h":"6) قصص مرتبطة، وهنقابلها لاحقا 🧵","t":"learn","x":"أوريستيس والمحكمة: أثينا بتأسس القانون. في مسرحية Aeschylus اللي اسمها Eumenides ، أوريستيس متحاكم لأنه قتل أمه. وأثينا هي اللي بترأس المحكمة، وبتصوت معاه. وقالت جملة هي مفتاح شخصيتها (ترجمة Smyth ، الأسطر 734 ل 738): \" For there was no mother who gave me birth ; and in all things, except for marriage, whole-heartedly I am for the male and entirely on the father's side .\""},{"i":"myth-m12","s":54,"h":"6) قصص مرتبطة، وهنقابلها لاحقا 🧵","t":"learn","x":"يعني: مفيش أم ولدتني، وفي كل حاجة ما عدا الجواز أنا بكل قلبي مع الذكر، ومع الأب تماما. ده مش رأي شخصي منها، ده نتيجة أسطورتها: اللي اتولد من راس أبوه بيقف مع الأب. والمحكمة اللي أسستها هي الأريوباغوس. وفي آخر المسرحية الإلهات القديمة (الإيرينيس) بتبقى جزء من المدينة بدل ما تفضل بره، يعني أثينا بتحول الغضب القديم لقانون."},{"i":"myth-m12","s":55,"h":"6) قصص مرتبطة، وهنقابلها لاحقا 🧵","t":"learn","x":"ميدوسا: الدرع اللي بيجمد. على درع أثينا (الأيجيس، aegis ) كان فيه راس ميدوسا، اللي بتحول اللي يبص لها لحجر. وحكاية ميدوسا لها نسخ كتير، وأوفيد عنده نسخة قاسية جدا. هنشوفها بالتفصيل بعدين."},{"i":"myth-m12","s":56,"h":"6) قصص مرتبطة، وهنقابلها لاحقا 🧵","t":"learn","x":"طروادة: الإلهة اللي اختارت جانب. أثينا كانت مع اليونانيين في حرب طروادة. وفي الإلياذة، الكتاب 6، الأسطر 297 ل 311، فيه مشهد قاسي: الستات الطرواديات راحوا معبد أثينا، وحطوا أفخم روب عندهم على ركبتي التمثال. وصلوا: \" Lady Athene, that dost guard our city, fairest among goddesses, break now the spear of Diomedes .\""},{"i":"myth-m12","s":57,"h":"6) قصص مرتبطة، وهنقابلها لاحقا 🧵","t":"learn","x":"يعني: \"يا سيدة أثينا، حامية مدينتنا، أجمل الإلهات، اكسري رمح ديوميديس.\" والجواب: \" So spake she praying, but Pallas Athene denied the prayer .\" يعني كده صلت، لكن بالاس أثينا رفضت الدعاء. ده مش موقف أخلاقي، ده موقف سياسي: الإلهة بتحمي مدينتها هي مش أي مدينة."},{"i":"myth-m12","s":58,"h":"6) قصص مرتبطة، وهنقابلها لاحقا 🧵","t":"mc","x":"مين اللي حولته مينيرفا لعنكبوت؟ ؟ ميدوسا / أراخني / ميتيس / أريادني . أراخني"},{"i":"myth-m12","s":59,"h":"6) قصص مرتبطة، وهنقابلها لاحقا 🧵","t":"mc","x":"في Eumenides ، أثينا قالت إنها مع الأب. ليه؟ ؟ لأنها كانت بتكره الستات / لأن أبوها أمرها / لأنها اتجوزت قبل كده / لأن مفيش أم ولدتها، هي اتولدت من راس أبوها . لأن مفيش أم ولدتها، هي اتولدت من راس أبوها"},{"i":"myth-m12","s":60,"h":"6) قصص مرتبطة، وهنقابلها لاحقا 🧵","t":"tf","x":"في الإلياذة 6، أثينا وافقت على دعاء الستات الطرواديات. . غلط"},{"i":"myth-m12","s":62,"h":"7) الأسطورة في الشعر الإنجليزي 📜","t":"learn","x":"شكسبير: اسم الإلهة كاستدعاء للإلهام ✨ في Titus Andronicus ، الفصل الرابع، المشهد الأول، تقريبا سطر 66-67، ماركوس بيقول: \" Apollo, Pallas, Jove, or Mercury / Inspire me, that I may this treason find .\" يعني: أبولو أو بالاس أو جوف أو عطارد، ألهموني عشان أقدر أكتشف الخيانة دي."},{"i":"myth-m12","s":63,"h":"7) الأسطورة في الشعر الإنجليزي 📜","t":"learn","x":"وفي The Taming of the Shrew ، الفصل الأول، المشهد الأول، تقريبا سطر 85، لوسينتيو بيقول عن بيانكا: \" Hark, Tranio, thou mayst hear Minerva speak !\" يعني: اسمع يا ترانيو، إنت بتسمع مينيرفا وهي بتتكلم! شكسبير بيستخدم أسماء الإلهة كإشارات سريعة: بالاس للإلهام، ومينيرفا لواحدة بتتكلم بحكمة. وده allusion صريح بالاسم."},{"i":"myth-m12","s":64,"h":"7) الأسطورة في الشعر الإنجليزي 📜","t":"learn","x":"ميلتون، Comus : بيسأل عن درع الجورجون اللي لبسته مينيرفا: \" What was that snaky-headed Gorgon shield / That wise Minerva wore, unconquer'd Virgin , / Wherewith she freez'd her foes to congeal'd stone , / But rigid looks of Chaste austerity \" يعني: إيه الدرع ده اللي راسه تعابين، اللي لبسته مينيرفا الحكيمة، العذراء اللي ما اتغلبتش، وجمدت بيه أعداءها حجر؟ كان نظرات صارمة من العفة الشديدة."},{"i":"myth-m12","s":65,"h":"7) الأسطورة في الشعر الإنجليزي 📜","t":"learn","x":"ميلتون بيسأل سؤال وبعدين بيجاوب: اللي بيجمد الأعداء مش سحر، ده نظرة العفة الصارمة. يعني أسطورة بقت فكرة أخلاقية. وقبلها بكام سطر ذكر أرتميس: \" Hence had the huntress Dian her dread bow , / Fair silver-shafted Queen for ever chaste \". يعني الفصل اللي فات والفصل ده بيتقابلوا في نفس القصيدة: العفة سلاح. أرتميس بالقوس، وأثينا بالدرع."},{"i":"myth-m12","s":66,"h":"7) الأسطورة في الشعر الإنجليزي 📜","t":"learn","x":"بوب، The Dunciad ، الكتاب الأول، السطرين 9 و10: \" In eldest time, e'er mortals writ or read , / E'er Pallas issu'd from the Thund'rer's head \" يعني: في أقدم زمن، قبل ما البشر يكتبوا ويقروا، قبل ما بالاس تطلع من راس الراعد (زيوس). بوب بيستخدم ميلاد أثينا كعلامة على \"أول الزمن\". والسخرية حلوة: القصيدة كلها عن الغباء، وبتبدأ من ولادة الحكمة."},{"i":"myth-m12","s":67,"h":"7) الأسطورة في الشعر الإنجليزي 📜","t":"learn","x":"كيتس، سونيتة \" On Seeing the Elgin Marbles \": \" My spirit is too weak — mortality / Weighs heavily on me like unwilling sleep \" يعني: روحي ضعيفة جدا، والفناء بيتقل علي زي نوم مش عايزه. كيتس كتبها بعد ما شاف رخام البارثينون في المتحف البريطاني. والقصيدة ما بتذكرش أثينا بالاسم، بس كلها عن أثر فنها عليه: حس إنه صغير وضعيف قدام حاجة عمرها ألفين سنة."},{"i":"myth-m12","s":68,"h":"7) الأسطورة في الشعر الإنجليزي 📜","t":"mc","x":"إيه اللي بيقوله ميلتون عن درع مينيرفا في Comus ؟ ؟ اللي بيجمد الأعداء هو نظرة العفة الصارمة / الدرع كان من دهب / الدرع كان لأرتميس / الدرع كان بيحمي من النار . اللي بيجمد الأعداء هو نظرة العفة الصارمة"},{"i":"myth-m12","s":69,"h":"7) الأسطورة في الشعر الإنجليزي 📜","t":"tf","x":"بوب في The Dunciad استخدم ميلاد أثينا كعلامة على أول الزمن. . صح"},{"i":"myth-m12","s":70,"h":"7) الأسطورة في الشعر الإنجليزي 📜","t":"mc","x":"مين قال: Hark, Tranio, thou mayst hear Minerva speak ؟ ؟ ماركوس في Titus Andronicus / لوسينتيو في The Taming of the Shrew / ميلتون في Comus / بيتروشيو في The Taming of the Shrew . لوسينتيو في The Taming of the Shrew"},{"i":"myth-m12","s":72,"h":"8) أخطاء شائعة ⚠️","t":"learn","x":"\"أثينا إلهة الحرب\". نص صح. هي إلهة الحرب العاقلة والدفاعية. الحرب الهمجية إلهها آريس. \"أثينا اتولدت وهيفايستوس شق الراس بفأس في كل النسخ\". لأ. هسيود ما ذكرش لا هيفايستوس ولا الفأس ولا السلاح. والنسخة الشعبية خليط متأخر."},{"i":"myth-m12","s":73,"h":"8) أخطاء شائعة ⚠️","t":"learn","x":"\"مينيرفا مجرد ترجمة لأثينا\". لأ. مينيرفا اسم روماني قديم، وأصله من كلمة معناها \"ذكي، فاهم\"، من جذر معناه \"يفكر\". \"أثينا وأرتميس نفس الحاجة\". لأ. الاتنين عذارى، بس واحدة للمدينة (النظام والقانون والحرف)، وواحدة للغابة (الحدود والصيد والوحدة). وبيظهروا في نفس القصيدة عند ميلتون، وكل واحدة بشغلها."},{"i":"myth-m12","s":75,"h":"9) كلمات هتقع لك في الشعر 📖","t":"learn","x":"wisdom = حكمة counsel = مشورة cunning = حيلة / ذكاء ماكر craft = حرفة (وكمان: مكر) loom = نول النسيج weave = ينسج shield = درع aegis = درع زيوس اللي بتحمله أثينا، ومنها التعبير under the aegis of يعني \"تحت حماية\" helmet = خوذة spear = رمح"},{"i":"myth-m12","s":76,"h":"9) كلمات هتقع لك في الشعر 📖","t":"learn","x":"owl = بومة olive = زيتون virgin / maiden = عذراء / بنت mentor = مرشد (من اسم Mentor في الأوديسة) strategy = استراتيجية"},{"i":"myth-m12","s":77,"h":"9) كلمات هتقع لك في الشعر 📖","t":"mc","x":"إيه معنى التعبير under the aegis of ؟ ؟ ضد / بعيد عن / تحت حماية / فوق . تحت حماية"},{"i":"myth-m12","s":78,"h":"9) كلمات هتقع لك في الشعر 📖","t":"mc","x":"إيه معنى craft في الشعر؟ ؟ حرفة، وأحيانا مكر / سفينة / درع / ريشة . حرفة، وأحيانا مكر"},{"i":"myth-m12","s":80,"h":"10) كويز سريع 🧠","t":"learn","x":"راجع معانا: مين أم أثينا؟ ميتيس، ومعناها الحكمة. اتولدت من فين؟ من راس زيوس، بعد ما بلع ميتيس. اسمها عند الرومان إيه؟ مينيرفا. في الإلياذة 6، الستات الطرواديات حطوا إيه على ركبتي تمثال أثينا؟ أفخم روب عندهم. وفي Eumenides ، قالت إيه عن أمها؟ إن مفيش أم ولدتها."},{"i":"myth-m12","s":81,"h":"10) كويز سريع 🧠","t":"mc","x":"مين أم أثينا؟ ؟ هيرا / ميتيس / ليتو / ديميتر . ميتيس"},{"i":"myth-m12","s":82,"h":"10) كويز سريع 🧠","t":"mc","x":"اسم أثينا عند الرومان إيه؟ ؟ ديانا / فينوس / مينيرفا / يونو . مينيرفا"},{"i":"myth-m12","s":84,"h":"الخلاصة","t":"learn","x":"الخلاصة: أثينا (مينيرفا) إلهة الحكمة والمدينة والحرف والحرب العاقلة، واتولدت من راس زيوس بعد ما بلع أمها ميتيس. هسيود ما ذكرش الفأس ولا السلاح. دول جم من مصادر أحدث. البارثينون بيحكي أسطورتها بالحجر، والمدينة اختارت الزيتون. والشعراء، من شكسبير لكيتس، استدعوا اسمها أو أثرها."},{"i":"myth-m12","s":85,"h":"الخلاصة","t":"learn","x":"مهمة صغيرة ✍️ اقرا جملة أثينا في Eumenides بصوت عالي: \" there was no mother who gave me birth \". حس بالقسوة اللي فيها. فكر: مين في حياتك \"مرشد\" بالمعنى اللي شفناه في الأوديسة؟ وفكر: لو مدينتك كانت هتختار هدية من إله، هتختار الزيتون ولا الحصان؟ وليه؟"},{"i":"myth-m12","s":87,"h":"تذكر واكتب","t":"recall","x":"مين أم أثينا، وإيه اللي حصل لها؟ . ميتيس، إلهة الحكمة. زيوس بلعها وهي حامل، وأثينا اتولدت من راسه."},{"i":"myth-m12","s":88,"h":"تذكر واكتب","t":"recall","x":"إيه اللي حطته ستات طروادة على ركبتي تمثال أثينا في الإلياذة 6؟ . ثوبا مطرزا، قدموه هدية للإلهة عشان ترحم المدينة."},{"i":"myth-m12","s":89,"h":"تذكر واكتب","t":"write","x":"قارن في ٣-٤ جمل بين مينيرفا في كوموس لميلتون وبالاس في الدونسياد لبوب. . ميلتون بيسأل عن الدرع اللي \" That wise Minerva wore, unconquer'd Virgin \" (٤٤٦-٤٤٩)، وبعدها بيجاوب إن اللي بيجمد الأعداء مش سحر، هو نظرة العفة، فالإلهة بقت فكرة أخلاقية. بوب بيستعمل ميلادها كعلامة على أول الزمن: \" E'er Pallas issu'd from the Thund'rer's head \" (١.٩-١٠)، والولادة نفسها بقت تاريخا. يبدو أن الاتنين بيسحبوا من الإلهة حاجة مختلفة: ميلتون بياخد الدرع، وبوب بياخد اللحظة. والنتيجة إن نفس الأسطورة بتخدم أخلاقا في نص، وسخرية في نص تاني."},{"i":"myth-m12","s":90,"h":"تذكر واكتب","t":"write","x":"قارن في ٣-٤ جمل بين إشارة شكسبير الصريحة لأثينا في مسرحياته وبين إشارة كيتس لها في سونيتة رخام إلجين. . شكسبير بيسمي الإلهة ويناديها: \" Pallas, inspire me !\"، فالاسم صريح والطلب مباشر، والقارئ بيعرف على طول مين بيتكلم. كيتس مابيسميهاش خالص، وبيبدأ من إحساسه هو: \" My spirit is too weak — mortality / Weighs heavily on me like unwilling sleep \". يمكن القول إن شكسبير بيستدعي الإلهة، وكيتس بيستدعي أثرها. والإشارة غير المباشرة هنا أقوى، لأن القارئ بيحس بالنقص قبل ما يعرف مصدره. وده يوضح إن الأسماء القديمة لما تختفي من القصيدة، أثرها مابيختفيش."},{"i":"myth-m13","s":1,"h":"مقدمة","t":"learn","x":"فيه إلهة في اليونان اتولدت من البحر. مش من بطن أم، ولا من راس أب. من الزبد الأبيض اللي طلع على سطح المية. والحكاية اللي قبلها بشعة: حد قطع أعضاء أبوه ورماهم في البحر. ومن الجرح ده، ومن الزبد، طلعت أجمل إلهة في الأسطورة كلها. يعني أول درس في الفصل ده: الحب في الميثولوجيا اليونانية مش ناعم. الحب بيطلع من جرح، وبيبدأ من عنف، وبيبقى قوة ماحدش يقدر يقاومها. حتى الآلهة نفسها."},{"i":"myth-m13","s":2,"h":"مقدمة","t":"learn","x":"دي أفروديت ( Aphrodite )، اللي الرومان سموها فينوس ( Venus ). والنهارده هنقابل معاها ابنها المشهور: إيروس ( Eros )، أو كيوبيد ( Cupid ) عند الرومان. وفيه حاجة تحفة هنكتشفها في الفصل ده: الترنيمة الهوميرية لأفروديت بتقول بالنص إن فيه تلات إلهات أفروديت مابتعرفش تتحكم فيهم: أثينا، وأرتميس، وهيستيا. يعني الفصل ده بيربط الفصلين اللي فاتوا بالخيط الرسمي: الحب نفسه بيعترف إن فيه حاجات بره سلطته."},{"i":"myth-m13","s":3,"h":"مقدمة","t":"learn","x":"📍 إحنا فين في الحكاية؟ في M11 خدنا أرتميس: البرية، والحدود، والصيد. في M12 خدنا أثينا: المدينة، والعقل، والقانون. والنهارده أفروديت: الرغبة، والجمال، والقوة اللي بتحرك كل حاجة حية. والتلاتة مع بعض بيمثلوا تلات قوى في الإنسان: الغريزة (أرتميس)، والعقل (أثينا)، والرغبة (أفروديت). وهي هتفتح لنا أبواب كتير: فينوس وأدونيس ( M31 )، كيوبيد وسايكي ( M30 )، هيلين وطروادة ( M66 )، إينياس والإنيد ( M76 )، وأفروديت في تاريخ الشعر الإنجليزي ( M109 و M110 )."},{"i":"myth-m13","s":5,"h":"النقطة 1: مين أفروديت؟ البطاقة الأساسية","t":"learn","x":"الاسم. أفروديت يوناني، وفينوس روماني. والإغريق نفسهم فسروا اسم أفروديت من كلمة aphros ، يعني \"زبد البحر\"، لأنها اتولدت من الزبد. بس فيه حاجة مهمة: الاسم على الأرجح مش يوناني أصلا. عالم اللغة بهيكس ( Beekes ) بيقول إن الإلهة نفسها أصلها شرقي، والاسم غالبا جاي من الشرق، ويمكن دخل اليونانية عن طريق لغة تانية، وأقرب احتمال إنه جاي من الفينيقيين في قبرص."},{"i":"myth-m13","s":6,"h":"النقطة 1: مين أفروديت؟ البطاقة الأساسية","t":"mc","x":"الإغريق فسروا اسم أفروديت من كلمة aphros ، معناها إيه؟ ؟ نار / زبد البحر / ضحك / جمال . زبد البحر"},{"i":"myth-m13","s":7,"h":"النقطة 1: مين أفروديت؟ البطاقة الأساسية","t":"learn","x":"يعني الإغريق عملوا نفس اللي عملناه في الفصل اللي فات: خدوا إلهة من حضارة أقدم، وحطوا لها حكاية تشرح اسمها. وفينوس اسمها من كلمة لاتينية معناها \"حب، رغبة، جمال\"، من جذر هندو-أوروبي * wen- يعني \"يرغب، يسعى\"."},{"i":"myth-m13","s":8,"h":"النقطة 1: مين أفروديت؟ البطاقة الأساسية","t":"learn","x":"وملحوظة لطيفة: فينوس الرومانية كانت في الأصل إلهة أقل شأنا، يعني الرومان ما كانوش بيعتبروها من كبار الآلهة، وبعد ما اتوحدت مع أفروديت اليونانية كبرت. الآلهة كمان بتكبر بالشغل."},{"i":"myth-m13","s":9,"h":"النقطة 1: مين أفروديت؟ البطاقة الأساسية","t":"learn","x":"العيلة، وهنا مشكلة. في نسخة هسيود: أفروديت مالهاش أم ولا أب بالمعنى العادي. هي بنت قطع من جسد أورانوس (السماء). (هنحكيها كاملة.) في نسخة هوميروس: هي بنت زيوس وديوني ( Dione ). (الإلياذة 5.312 و5.370-371، وده مذكور في حواشي ترجمة Symposium ) والنسختين مش متفقين، وده طبيعي. الأسطورة ليها نسخ، زي ما اتعلمنا من أول فصل."},{"i":"myth-m13","s":10,"h":"النقطة 1: مين أفروديت؟ البطاقة الأساسية","t":"mc","x":"مين أبو أفروديت عند هوميروس؟ ؟ أورانوس / كرونوس / زيوس (مع ديوني) / بوسيدون . زيوس (مع ديوني)"},{"i":"myth-m13","s":11,"h":"النقطة 1: مين أفروديت؟ البطاقة الأساسية","t":"learn","x":"ألقابها. Cytherea : من جزيرة سيثيرا ( Cythera ). Cypris / Cyprogenes : من قبرص ( Cyprus )، لأنها طلعت على شطها. Aphrogeneia : \"المولودة من الزبد\". philommeides : \"محبة الضحك\". ودي صفة بتتكرر معاها كتير في هوميروس."},{"i":"myth-m13","s":12,"h":"النقطة 1: مين أفروديت؟ البطاقة الأساسية","t":"learn","x":"وملحوظة أمانة علمية حلوة: في مخطوطات هسيود، اللقب مكتوب philommedes ، يعني \"محبة الأعضاء\"، وده مقصود بيه إنها طلعت من أعضاء أورانوس. والمحققين بيقولوا إن دي غالبا تحريف لكلمة philommeides ، \"محبة الضحك\". يعني عندنا لقبين: واحد وقح ومقصود، وواحد لطيف، والنسخ مختلفة. وده بيوريك إن النقل النصي نفسه فيه حكاية."},{"i":"myth-m13","s":14,"h":"النقطة 2: قصة الميلاد: من الجرح للجمال","t":"learn","x":"المشهد الأول، وهو بشع. جيا (الأرض) كانت زعلانة من أورانوس (السماء) لأنه كان بيخبي ولادها جواها. فعملت مؤامرة مع ابنها كرونوس. وفي \"نسب الآلهة\"، سطر 176-182، المشهد بيتحكي: أورانوس جه بالليل، ونام على الأرض، وكرونوس من الكمين مد إيده الشمال، ومسك في إيده اليمين المنجل الكبير المسنن، وقطع أعضاء أبوه، ورماهم ورا ظهره."},{"i":"myth-m13","s":15,"h":"النقطة 2: قصة الميلاد: من الجرح للجمال","t":"learn","x":"والدم اللي نزل على الأرض، الأرض خدته، وولدت منه الإيرينيس (إلهات الانتقام)، والعمالقة ( Giants )، وحوريات الرماد ( Meliae )."},{"i":"myth-m13","s":16,"h":"النقطة 2: قصة الميلاد: من الجرح للجمال","t":"learn","x":"المشهد التاني، وهو اللي يخصنا. الأعضاء نفسها وقعت في البحر. والنص بيقول: \" and a white foam spread around them from the immortal flesh, and in it there grew a maiden .\"، \"وزبد أبيض انتشر حواليهم من اللحم الخالد، وجواه كبرت بنت.\""},{"i":"myth-m13","s":17,"h":"النقطة 2: قصة الميلاد: من الجرح للجمال","t":"mc","x":"من فين طلعت أفروديت حسب هسيود؟ ؟ من راس زيوس / من زبد البحر حوالين أعضاء أورانوس / من الغابة / من بيضة سحرية . من زبد البحر حوالين أعضاء أورانوس"},{"i":"myth-m13","s":18,"h":"النقطة 2: قصة الميلاد: من الجرح للجمال","t":"learn","x":"وبعدها: \" First she drew near holy Cythera, and from there, afterwards, she came to sea-girt Cyprus, and came forth an awful and lovely goddess, and grass grew up about her beneath her shapely feet .\"، \"قربت الأول من سيثيرا المقدسة، وبعدها جات لقبرص المحاطة بالبحر، وطلعت إلهة مهيبة وجميلة، والعشب نبت حواليها تحت رجليها الجميلة.\""},{"i":"myth-m13","s":19,"h":"النقطة 2: قصة الميلاد: من الجرح للجمال","t":"learn","x":"يعني البحر حملها من سيثيرا لقبرص، والشط هو أول أرض لمستها. تخيل الصورة: زبد في البحر، وبنت طالعة منه، والعشب بينبت تحت رجليها."},{"i":"myth-m13","s":20,"h":"النقطة 2: قصة الميلاد: من الجرح للجمال","t":"learn","x":"الأسماء، والنص نفسه بيشرحها. النص بيقول: \" Her gods and men call Aphrodite, and the foam-born goddess and rich-crowned Cytherea, because she grew amid the foam, and Cytherea because she reached Cythera, and Cyprogenes because she was born in billowy Cyprus, and Philommedes because she sprang from the members .\""},{"i":"myth-m13","s":21,"h":"النقطة 2: قصة الميلاد: من الجرح للجمال","t":"learn","x":"يعني: الآلهة والناس بيسموها أفروديت، والمولودة من الزبد، وسيثيريا المتوجة، لأنها كبرت في الزبد، وسيثيريا لأنها وصلت سيثيرا، وكيبروجينيس لأنها اتولدت في قبرص المتلاطمة، وفيلوميديس لأنها طلعت من الأعضاء. يعني الاسم مش مجرد لافتة: كل لقب بيحكي مرحلة من الرحلة."},{"i":"myth-m13","s":22,"h":"النقطة 2: قصة الميلاد: من الجرح للجمال","t":"learn","x":"ومين كان معاها؟ النص بيقول: \" And with her went Eros, and comely Desire followed her at her birth .\"، \"ومعاها مشى إيروس (الحب)، والرغبة الجميلة ( Himeros ) تبعتها من أول لحظة في ميلادها.\" يعني الحب والرغبة اتولدوا معاها، مش بعدها. ومن أول لحظة، الحب هو رفيقها."},{"i":"myth-m13","s":23,"h":"النقطة 2: قصة الميلاد: من الجرح للجمال","t":"tf","x":"إيروس اتولد مع أفروديت ومشي معاها من أول لحظة في رواية هسيود عن ميلادها. . صح"},{"i":"myth-m13","s":24,"h":"النقطة 2: قصة الميلاد: من الجرح للجمال","t":"learn","x":"وليه الحكاية دي مهمة؟ لأنها بتقول حاجة عن الحب نفسه: الحب في الميثولوجيا اليونانية مش حاجة ناعمة ولطيفة. هو قوة بتطلع من جرح، ومن عنف، ومن قطع. وده مش تشاؤم، ده وصف دقيق لتجربة إنسانية: أقوى حالات الحب بتيجي مع أضعف لحظاتنا."},{"i":"myth-m13","s":25,"h":"النقطة 2: قصة الميلاد: من الجرح للجمال","t":"learn","x":"ومثال من الحياة: زي اللؤلؤة. بيقولوا إنها بتتكون من حاجة دخلت المحارة وجرحتها، فالمحارة بتحولها لحاجة جميلة. الحب كده: بيبدأ من جرح، وبيطلع منه حاجة جميلة. (ودي مقارنة، مش حقيقة علمية.) ومثال تاني أقرب: أول مرة تحب فيها، بتبقى مرتبك ومكسور شوية في نفس الوقت. الحب مش بيدخل حد وهو مرتاح."},{"i":"myth-m13","s":27,"h":"النقطة 3: إيروس/كيوبيد: إلهين في اسم واحد","t":"learn","x":"إيروس الأول: قوة كونية. في \"نسب الآلهة\"، سطر 116-120، إيروس مش ابن أفروديت ولا ابن حد. هو من أقدم الآلهة، قبل أوليمبوس، قبل زيوس. والنص بيقول: \" Eros ( Love ), fairest among the deathless gods, who unnerves the limbs and overcomes the mind and wise counsels of all gods and all men within them .\""},{"i":"myth-m13","s":28,"h":"النقطة 3: إيروس/كيوبيد: إلهين في اسم واحد","t":"mc","x":"إيه إيروس عند هسيود؟ ؟ ابن أفروديت الطفل / إله الحرب / إله الشمس / من أقدم الآلهة، قوة كونية . من أقدم الآلهة، قوة كونية"},{"i":"myth-m13","s":29,"h":"النقطة 3: إيروس/كيوبيد: إلهين في اسم واحد","t":"learn","x":"يعني: إيروس، أجمل الآلهة الخالدين، اللي بيرخي الأعصاب، وبيغلب العقل والمشورة الحكيمة جوه كل الآلهة وكل البشر. خد بالك من الجملة: بيغلب العقل والمشورة الحكيمة. يعني حتى العقل نفسه بيتغلب. وده بيرجعنا للفصل اللي فات. وفي النسخة دي، إيروس مالهوش أجنحة، ولا قوس، ولا سهام. هو مبدأ كوني: القوة اللي بتخلي الأشياء تتجاذب وتتوالد."},{"i":"myth-m13","s":30,"h":"النقطة 3: إيروس/كيوبيد: إلهين في اسم واحد","t":"learn","x":"إيروس التاني: الولد الصغير بسهام. بعد كده بقرون، إيروس بقى ابن أفروديت، وبقى شاب جميل، وبعدها بقى طفل صغير. ودارسين الفن بيقولوا: في الفن اليوناني القديم، إيروس كان بيتصور شاب مجنح، وأحيانا طفل. وفي العصر الهيلينستي (323-31 قبل الميلاد)، صورته اتغيرت: بقى طفل صغير ممتلئ الجسم، ملزوق بأفروديت. والطفل ده هو اللي أثر على كيوبيد الروماني، وبعدها على الملائكة الصغار ( cherubs ) في الفن الأوروبي."},{"i":"myth-m13","s":31,"h":"النقطة 3: إيروس/كيوبيد: إلهين في اسم واحد","t":"tf","x":"صورة كيوبيد الطفل السمين صورة يونانية قديمة. . غلط"},{"i":"myth-m13","s":32,"h":"النقطة 3: إيروس/كيوبيد: إلهين في اسم واحد","t":"learn","x":"وأدواته بقيت مشهورة: القوس والسهام، والمشعل، والشبكة اللي بيصطاد بيها القلوب. يعني الصورة اللي في دماغك، الطفل السمين اللي عنده قوس وسهم، دي مش يونانية قديمة. دي صورة متأخرة، وبعدها بقت صورة عصر النهضة."},{"i":"myth-m13","s":33,"h":"النقطة 3: إيروس/كيوبيد: إلهين في اسم واحد","t":"learn","x":"الدرس. نفس الاسم، إلهين مختلفين. واحد قوة كونية قديمة، وواحد طفل مدلل بيصطاد بالأسهم. وفي الشعر الإنجليزي، لما تقرا \" Cupid \"، غالبا المقصود هو التاني. ولما تقرا \" Love \" بحرف كبير، ممكن يكون الأول. وده فرق مهم في التحليل."},{"i":"myth-m13","s":35,"h":"النقطة 4: الميادين: فين بتشتغل أفروديت؟","t":"learn","x":"الحب والرغبة. ده مجالها الأساسي، وكل حاجة حية بتخضع له: الآلهة، والبشر، والطيور، ووحوش البر، وسمك البحر. (الترنيمة الهوميرية 5، سطر 1-6)"},{"i":"myth-m13","s":36,"h":"النقطة 4: الميادين: فين بتشتغل أفروديت؟","t":"learn","x":"الجمال. جمالها مش صفة شخصية، ده قوة. زي ما الشمس قوية، الجمال قوي. وبيخلي الناس تعمل حاجات مش معقولة."},{"i":"myth-m13","s":37,"h":"النقطة 4: الميادين: فين بتشتغل أفروديت؟","t":"learn","x":"البحر والتجارة. هي إلهة بحرية كمان: اتولدت من البحر، وطلعت على شط قبرص، ومراكز عبادتها كانت مواني (قبرص، سيثيرا). والمواني دي كانت مراكز تجارة. وده منطقي: الحب والبحر والتجارة كلهم بيربطوا الناس ببعض."},{"i":"myth-m13","s":38,"h":"النقطة 4: الميادين: فين بتشتغل أفروديت؟","t":"learn","x":"الزواج والعيلة. أفروديت متجوزة هيفايستوس (إله الحدادة). والجواز ده مش جواز حب، ده جواز بين الجمال والصنعة. وهنشوف نتيجته بعد شوية، في القصة الكبيرة."},{"i":"myth-m13","s":40,"h":"النقطة 5: القصة الكبيرة: أفروديت وأريس في الشبكة","t":"learn","x":"الخلفية. أفروديت متجوزة هيفايستوس، إله الحدادة، وهو أعرج وقبيح الشكل بس أشطر صانع في العالم. وهي بتحب أريس ( Mars )، إله الحرب. يعني الجمال بيحب القوة العنيفة، مش الصنعة الذكية."},{"i":"myth-m13","s":41,"h":"النقطة 5: القصة الكبيرة: أفروديت وأريس في الشبكة","t":"learn","x":"المؤامرة. في الأوديسة، الكتاب 8، سطر 266-366، الشاعر ديمودوكوس بيغني القصة في بلاط الفياشيين، وأوديسيوس بيسمعها. هيليوس (الشمس) شافهم وهما مع بعض، وراح بلغ هيفايستوس. وهيفايستوس عمل إيه؟ راح لحدادته، وحط السندان، وصنع قيود ماحدش يقدر يفكها، وفرشها حوالين السرير، ومن السقف كمان، \" fine as spiders' webs \"، رفيعة زي شباك العنكبوت، لدرجة إن ولا إله كان يقدر يشوفها."},{"i":"myth-m13","s":42,"h":"النقطة 5: القصة الكبيرة: أفروديت وأريس في الشبكة","t":"mc","x":"مين بلغ هيفايستوس عن أفروديت وأريس؟ ؟ هيرميس / هيليوس (الشمس) / أبولو / بوسيدون . هيليوس (الشمس)"},{"i":"myth-m13","s":43,"h":"النقطة 5: القصة الكبيرة: أفروديت وأريس في الشبكة","t":"learn","x":"الفخ. هيفايستوس عمل نفسه مسافر للينوس. وأريس، اللي مش أعمى، شاف فرصة، ودخل البيت، ومسك إيد أفروديت، وقال لها: \" Come, love, let us to bed and take our joy, couched together. For Hephaestus is no longer here in the land .\" وناموا. والشبكة وقعت عليهم. ومقدروش يتحركوا."},{"i":"myth-m13","s":44,"h":"النقطة 5: القصة الكبيرة: أفروديت وأريس في الشبكة","t":"learn","x":"الفضيحة. هيفايستوس رجع، ووقف على الباب، وزعق على كل الآلهة: تعالوا شوفوا حاجة مضحكة، أفروديت بنت زيوس بتحتقرني عشان أعرج، وبتحب أريس المدمر عشان حلو وشكله متناسق. والآلهة جات. والضحك ملأ المكان: \" unquenchable laughter flowed from the blessed gods \"."},{"i":"myth-m13","s":45,"h":"النقطة 5: القصة الكبيرة: أفروديت وأريس في الشبكة","t":"learn","x":"والآلهة قالت جملة بقت مثل: \" Ill deeds thrive not. The slow catches the swift ; even as now Hephaestus, slow though he is, has out-stripped Ares for all that he is the swiftest of the gods .\"، \"الأعمال الوحشة مابتنجحش. البطيء بيمسك السريع، زي ما هيفايستوس، بطيء زي ما هو، سبق أريس، مع إنه أسرع الآلهة.\""},{"i":"myth-m13","s":46,"h":"النقطة 5: القصة الكبيرة: أفروديت وأريس في الشبكة","t":"learn","x":"وأبولو سأل هيرميس: تبقى عايز تنام جنب أفروديت الدهبية ولو كنت مربوط بقيود؟ وهيرميس رد رد مضحك جدا: \" three times as many inescapable links could hold me, and you gods could be watching, and yes, all the goddesses too, if only I might sleep with golden Aphrodite .\"، \"حتى لو كانوا تلات أضعاف القيود اللي مالهاش فك، والآلهة كلهم بيتفرجوا، وأنا نايم جنب أفروديت الدهبية.\""},{"i":"myth-m13","s":47,"h":"النقطة 5: القصة الكبيرة: أفروديت وأريس في الشبكة","t":"learn","x":"والآلهة ضحكت أكتر. وبعدها أريس راح تراقيا، وأفروديت راحت قبرص، لغاية بافوس، حيث الحوريات غسلوها ودهنوها بزيت خالد. يعني حتى بعد الفضيحة، رجعت لمكانها واتصلحت."},{"i":"myth-m13","s":48,"h":"النقطة 5: القصة الكبيرة: أفروديت وأريس في الشبكة","t":"learn","x":"ليه القصة دي مهمة؟ لأنها بتحكي الحكاية من وجهة نظر هيفايستوس، مش من وجهة نظر أفروديت. الضحك كله على الاتنين، بس التعاطف مع الأعرج اللي اتنصب عليه. وفيها حكمة شعبية يونانية بقت مثل: البطيء بيمسك السريع. يعني الذكاء والصبر بيغلبوا القوة والسرعة. وفيها كمان سؤال أخلاقي: هل الفضيحة عقاب عادل؟ ولا مجرد تشهير؟ الآلهة ضحكت، ومحدش قال إن ده صح. والقصة محفوظة في الأوديسة كنكتة، مش كموعظة."},{"i":"myth-m13","s":49,"h":"النقطة 5: القصة الكبيرة: أفروديت وأريس في الشبكة","t":"mc","x":"القصة بتحكي من وجهة نظر مين؟ ؟ هيفايستوس / أفروديت / أريس / زيوس . هيفايستوس"},{"i":"myth-m13","s":50,"h":"النقطة 5: القصة الكبيرة: أفروديت وأريس في الشبكة","t":"learn","x":"وملاحظة مهمة للشعر الإنجليزي: المشهد ده اتستخدم بعدين في الكوميديا والهجاء، وأشهر تعبير جه منه هو \"شبكة فولكان\" ( Vulcan's net )، يعني فخ بيتحط للحبيبين. وهتقابل التعبير ده كتير."},{"i":"myth-m13","s":52,"h":"النقطة 6: التلاتة اللي الحب مش قادر عليهم","t":"learn","x":"الترنيمة الهوميرية 5 بتقول حاجة تحفة. بعد ما وصفت قوة أفروديت على كل الكائنات، بتقول: \" Yet there are three hearts that she cannot bend nor yet ensnare. First is the daughter of Zeus who holds the aegis, bright-eyed Athena .\" يعني: فيه تلات قلوب مش قادرة تلويهم ولا تصطادهم. الأول: بنت زيوس، أثينا اللامعة العينين."},{"i":"myth-m13","s":53,"h":"النقطة 6: التلاتة اللي الحب مش قادر عليهم","t":"mc","x":"مين التلات إلهات اللي أفروديت مش قادرة عليهم؟ ؟ هيرا وديميتر وهيستيا / أثينا وهيرا وأرتميس / هيرا وأرتميس وديميتر / أثينا وأرتميس وهيستيا . أثينا وأرتميس وهيستيا"},{"i":"myth-m13","s":54,"h":"النقطة 6: التلاتة اللي الحب مش قادر عليهم","t":"learn","x":"والتاني: \" Nor does laughter-loving Aphrodite ever tame in love Artemis, the huntress with shafts of gold .\"، \"ولا أفروديت محبة الضحك تقدر تروض أرتميس، الصيادة ذات السهام الدهبية.\" والتالت: هيستيا ( Hestia )، إلهة البيت والنار، \"العذراء الطاهرة\". يعني الفصل ده بيعترف بالفصلين اللي فاتوا بالنص. الإلهة اللي بتحكم الحب بتقول: فيه تلاتة بره سلطتي."},{"i":"myth-m13","s":55,"h":"النقطة 6: التلاتة اللي الحب مش قادر عليهم","t":"learn","x":"وليه؟ لأن التلاتة اختاروا العذرية، وكل واحدة اختارت لأسباب مختلفة: أثينا اختارت العقل والحرب، أرتميس اختارت البرية والحرية، وهيستيا اختارت البيت والنار. والفكرة دي بتوريك إن الميثولوجيا اليونانية مش نظام واحد. هي شبكة اتفاقات، وكل إله عنده حدود، وبيعرف حدوده."},{"i":"myth-m13","s":56,"h":"النقطة 6: التلاتة اللي الحب مش قادر عليهم","t":"learn","x":"وزيوس عمل إيه؟ زيوس، اللي بيحب يتسلط، قرر يكسر كبرياء أفروديت. فحط في قلبها رغبة في راجل بشري، أنخيسيس ( Anchises )، اللي كان بيرعى بقر في جبل إيدا. والسبب؟ عشان ما تفضلش تتشمت بالآلهة وتقول إنها قدرت تخلي الآلهة تحب بشر. (الترنيمة 5، سطر 45-55) يعني العقاب هنا مش عنف، ده إذلال: أجمل إلهة هتحب راجل، وهتعرف معنى الضعف اللي كانت بتضحك عليه."},{"i":"myth-m13","s":57,"h":"النقطة 6: التلاتة اللي الحب مش قادر عليهم","t":"mc","x":"ليه زيوس خلى أفروديت تحب أنخيسيس؟ ؟ عشان يكافئها / عشان يتجوزها / عشان يعاقب أنخيسيس / عشان يكسر كبرياءها . عشان يكسر كبرياءها"},{"i":"myth-m13","s":59,"h":"النقطة 7: أنخيسيس وإينياس: من قبرص لروما","t":"learn","x":"الحكاية. أفروديت جات لأنخيسيس في شكل أميرة بشرية، عشان ما يخافش. ولبست واتزينت، والحوريات غسلوها ودهنوها. وهو لما شافها، ظنها إلهة، وقال لها: \"هلا يا سيدة، أي واحدة من السعداء إنت، أرتميس، ولا ليتو، ولا أفروديت الدهبية، ولا ثيميس، ولا أثينا اللامعة العينين؟\" (الترنيمة 5، سطر 91-95)، يعني الراجل عدد كل الإلهات اللي يعرفهم، ما عدا اللي واقفة قدامه."},{"i":"myth-m13","s":60,"h":"النقطة 7: أنخيسيس وإينياس: من قبرص لروما","t":"learn","x":"ونام معاها، وهو مش فاهم إنها إلهة. والنص بيقول: \" a mortal man with an immortal goddess, not clearly knowing what he did \"، \"راجل فاني مع إلهة خالدة، وهو مش فاهم بالظبط بيعمل إيه.\""},{"i":"myth-m13","s":61,"h":"النقطة 7: أنخيسيس وإينياس: من قبرص لروما","t":"learn","x":"الصدمة. لما صحى، شاف وشها الحقيقي، وخاف، وغطى وشه بعبايته، وقال لها: أنا عارف إنك إلهة، بس إنت ما قلتليش الحقيقة. أرجوكي، متسيبنيش أعيش عاجز بعد كده، لأن اللي ينام مع إلهة ما بيبقاش سليم بعدها. وده خوف حقيقي في الميثولوجيا: القرب من الإله بيحرق."},{"i":"myth-m13","s":62,"h":"النقطة 7: أنخيسيس وإينياس: من قبرص لروما","t":"learn","x":"الوعد. أفروديت طمنته، وقالت له: \" you shall have a dear son who shall reign among the Trojans, and children's children after him, springing up continually. His name shall be Aeneas .\"، \"هيبقى عندك ابن غالي هيملك على الطرواديين، وأولاد أولاد بعده، يطلعوا باستمرار. اسمه إينياس.\" وإينياس ده هو بطل الإنيد لفيرجيل، يعني جد الرومان. وهنشوفه في M76 ."},{"i":"myth-m13","s":63,"h":"النقطة 7: أنخيسيس وإينياس: من قبرص لروما","t":"mc","x":"إيه اسم ابن أفروديت من أنخيسيس؟ ؟ أدونيس / إينياس / هيكتور / باريس . إينياس"},{"i":"myth-m13","s":64,"h":"النقطة 7: أنخيسيس وإينياس: من قبرص لروما","t":"learn","x":"التحذير. وقالت له حاجة أخيرة، وهي أهم حاجة في الحكاية: \" But if you tell all and foolishly boast that you lay with rich-crowned Aphrodite, Zeus will smite you in his anger with a smoking thunderbolt .\"، \"بس لو حكيت كل حاجة، وافتخرت بحماقة إنك نمت مع أفروديت المتوجة، زيوس هيضربك بغضبه بصاعقة مدخنة.\" يعني القاعدة: الحب مع الإله بيبقى سر. اللي بيتكلم، بيتحرق."},{"i":"myth-m13","s":65,"h":"النقطة 7: أنخيسيس وإينياس: من قبرص لروما","t":"tf","x":"أفروديت حذرت أنخيسيس إن الكلام عن علاقتهم بيعرضه لصاعقة زيوس. . صح"},{"i":"myth-m13","s":66,"h":"النقطة 7: أنخيسيس وإينياس: من قبرص لروما","t":"learn","x":"وده موضوع كبير في الميثولوجيا: العلاقة بين الإله والإنسان فيها سر، والكلام عنها كارثة. (زي ما هنشوف مع سيميلي وزيوس في M18 )"},{"i":"myth-m13","s":67,"h":"النقطة 7: أنخيسيس وإينياس: من قبرص لروما","t":"learn","x":"وأفروديت في روما. إينياس بقى جد الرومان، وفينوس بقت الجدة الإلهية لعيلة يوليوس. ويوليوس قيصر بنى معبد فينوس جينيتريكس ( Venus Genetrix )، يعني \"فينوس الأم/الوالدة\"، في منتداه، واتدشن في 26 سبتمبر سنة 46 قبل الميلاد، في آخر يوم من انتصاراته. وده استخدام سياسي كامل للأسطورة: عيلة حاكمة بتقول إنها من نسل إلهة. ونفس الحكاية اللي بدأت من زبد البحر، بقت شهادة ميلاد لإمبراطورية."},{"i":"myth-m13","s":68,"h":"النقطة 7: أنخيسيس وإينياس: من قبرص لروما","t":"mc","x":"إيه معبد Venus Genetrix اللي بناه يوليوس قيصر؟ ؟ معبد حرب / معبد فينوس الأم / معبد البحر / معبد النصر . معبد فينوس الأم"},{"i":"myth-m13","s":70,"h":"النقطة 8: فينوس: إلهة واحدة ولا اتنين؟","t":"learn","x":"أفلاطون في \"المأدبة\" ( Symposium 180 d-181 ). بيقول إن فيه أفروديتين: واحدة قديمة، مالهاش أم، بنت أورانوس (السماء)، ودي اسمها \"الأورانية\" ( Ourania )، يعني السماوية. والتانية أصغر، بنت زيوس وديوني، واسمها \"البانديموس\" ( Pandemos )، يعني \"بتاعة كل الشعب\". وكل واحدة ليها إيروس بتاعها: إيروس سماوي، وإيروس شعبي. والفكرة: الحب له درجتين. حب راقي بيحب الروح، وحب شعبي بيحب الجسد."},{"i":"myth-m13","s":71,"h":"النقطة 8: فينوس: إلهة واحدة ولا اتنين؟","t":"mc","x":"الأفروديتين عند أفلاطون اسمهم إيه؟ ؟ Cypris و Cytherea / Ourania و Pandemos / Eros و Himeros / Paphia و Cythera . Ourania و Pandemos"},{"i":"myth-m13","s":72,"h":"النقطة 8: فينوس: إلهة واحدة ولا اتنين؟","t":"learn","x":"وهل ده حقيقي في العبادة؟ أيوه. فيه إشارة عند باوسانياس (1.14.7 و1.22.3) إن أفروديت كان ليها معبدين في أثينا بالاسمين دول،. يعني التقسيم مش فلسفة بس، ده عبادة حقيقية: إلهة للحب الشعبي، وإلهة للحب الراقي."},{"i":"myth-m13","s":73,"h":"النقطة 8: فينوس: إلهة واحدة ولا اتنين؟","t":"learn","x":"وده بيوريك حاجة مهمة. نفس الإلهة بتتقسم على حسب الوظيفة. زي ما كان عندنا ديانا النيمورينسيس وديانا أفسس في M11 . الاسم واحد، والشغل مختلف."},{"i":"myth-m13","s":75,"h":"النقطة 9: الأسطورة في الشعر الإنجليزي","t":"learn","x":"شكسبير، السونيتة 153. وأول أربع سطور بيرجعونا للفصل اللي فات: \" Cupid laid by his brand and fell asleep . A maid of Dian's this advantage found , And his love-kindling fire did quickly steep In a cold valley-fountain of that ground \""},{"i":"myth-m13","s":76,"h":"النقطة 9: الأسطورة في الشعر الإنجليزي","t":"mc","x":"في سونيت 153، مين اللي أخد مشعل كيوبيد وهو نايم؟ ؟ أبولو / فينوس / هيرميس / خادمة من خدامات ديان . خادمة من خدامات ديان"},{"i":"myth-m13","s":77,"h":"النقطة 9: الأسطورة في الشعر الإنجليزي","t":"learn","x":"الترجمة: \"كيوبيد حط مشعله ونام. وخادمة من خدامات ديان (أرتميس) لقيت الفرصة دي، وغرقت ناره اللي بتشعل الحب بسرعة في نافورة باردة في الوادي ده.\""},{"i":"myth-m13","s":78,"h":"النقطة 9: الأسطورة في الشعر الإنجليزي","t":"learn","x":"الشرح: المشهد كله مبني على حاجة واحدة: إله الحب نام، وسلاحه (المشعل) وقع في إيد حد تاني. وخادمة أرتميس، يعني واحدة من عالم العفة، هي اللي خدت النار. وباقي السونيتة بتحكي إن النافورة بقت حمام سخن بيشفي الأمراض، والشاعر راح يستحمى عشان يتعالج من حب حبيبته، فما لقاش علاج. والعلاج الحقيقي في عينها هي."},{"i":"myth-m13","s":79,"h":"النقطة 9: الأسطورة في الشعر الإنجليزي","t":"learn","x":"ليه مهم؟ لأن شكسبير بيستخدم الأسطورة كأداة ساخرة: إله الحب نفسه بيتسرق سلاحه، والشاعر بيدور على علاج من الحب في حمام أسطوري. يعني الأسطورة بقت نكتة عن العجز."},{"i":"myth-m13","s":80,"h":"النقطة 9: الأسطورة في الشعر الإنجليزي","t":"learn","x":"شكسبير تاني: \"فينوس وأدونيس\" ( Venus and Adonis )، أول ست سطور: \" Even as the sun with purple-colored face Had ta'en his last leave of the weeping morn , Rose-cheeked Adonis hied him to the chase . Hunting he loved, but love he laughed to scorn . Sick-thought è d Venus makes amain unto him And, like a bold-faced suitor, gins to woo him .\""},{"i":"myth-m13","s":81,"h":"النقطة 9: الأسطورة في الشعر الإنجليزي","t":"learn","x":"الترجمة: \"لما كانت الشمس بوشها البنفسجي بتاخد آخر وداعها من الصبح الباكي، أدونيس الخدود وردية راح يجري ورا الصيد. كان بيحب الصيد، وبيسخر من الحب. وفينوس المتعبة الفكر جات له بسرعة، وزي خاطب وقح، بدأت تغازله.\""},{"i":"myth-m13","s":82,"h":"النقطة 9: الأسطورة في الشعر الإنجليزي","t":"learn","x":"الشرح: في ست سطور، شكسبير حط الموضوع كله: راجل بيحب الصيد وبيكره الحب، وإلهة الحب بتحاول تصطاده. والصراع ده هو القصيدة كلها. ولاحظ التشابه مع M11 : أرتميس بتحب الصيد. وأدونيس هنا بيشبهها في الاختيار. الحب بيحاول يغلب الصيد، والنتيجة مأساة. هنقرا القصيدة في M31 ."},{"i":"myth-m13","s":83,"h":"النقطة 9: الأسطورة في الشعر الإنجليزي","t":"learn","x":"كريستوفر مارلو، \"هيرو وليندر\"، أول ست سطور: \" On Hellespont, guilty of true love's blood , In view and opposite two cities stood , Sea-borderers, disjoin'd by Neptune's might ; The one Abydos, the other Sestos hight . At Sestos Hero dwelt ; Hero the fair , Whom young Apollo courted for her hair \""},{"i":"myth-m13","s":84,"h":"النقطة 9: الأسطورة في الشعر الإنجليزي","t":"learn","x":"الترجمة: \"على الهليسبونت، المتهم بدم حب حقيقي، وقفت مدينتين في النظر ومتقابلين، على حدود البحر، فصلهم قوة نبتون. واحدة أبيدوس، والتانية اسمها سيستوس. في سيستوس عاشت هيرو، هيرو الجميلة، اللي أبولو الشاب حاول يتودد لها بسبب شعرها.\""},{"i":"myth-m13","s":85,"h":"النقطة 9: الأسطورة في الشعر الإنجليزي","t":"learn","x":"الشرح: مارلو بيبدأ بمكان، مش بشخص. الهليسبونت مضيق مية بين أوروبا وآسيا، وهو \"متهم\" بالدم. يعني الحب عنده جريمة من أول سطر. والمدينتين على شطين متقابلين، والحب هيبقى بينهم. وده أنسب مشهد لقصة حب مأساوية: مسافة مية. هنقراها في M27 ."},{"i":"myth-m13","s":86,"h":"النقطة 9: الأسطورة في الشعر الإنجليزي","t":"learn","x":"لوكريتيوس، بداية قصيدته عن طبيعة الأشياء، في ترجمة إنجليزية قديمة: \" Delight of Human kind, and Gods above ; Parent of Rome ; Propitious Queen of Love ; Whose vital pow'r, Air, Earth, and Sea supplies ; And breeds what e'er is born beneath the rowling Skies \""},{"i":"myth-m13","s":87,"h":"النقطة 9: الأسطورة في الشعر الإنجليزي","t":"tf","x":"عند لوكريتيوس فينوس قوة طبيعية بتخلي الحياة شغالة. . صح"},{"i":"myth-m13","s":88,"h":"النقطة 9: الأسطورة في الشعر الإنجليزي","t":"learn","x":"الترجمة: \"فرحة البشر، والآلهة اللي فوق؛ أم روما؛ ملكة الحب الراضية؛ اللي قوتها الحيوية بتمد الهوا والأرض والبحر، وبتولد كل اللي بيتولد تحت السما الدايرة.\""},{"i":"myth-m13","s":89,"h":"النقطة 9: الأسطورة في الشعر الإنجليزي","t":"learn","x":"الشرح: لاحظ إن فينوس هنا مش إلهة غراميات، هي قوة طبيعية: هي اللي بتخلي الحياة تفضل شغالة. وده إيروس الأول، القوة الكونية، بس باسم فينوس. و\"أم روما\" جاية من إينياس: فينوس جدة الرومان. يعني السطر ده سياسي وديني وعلمي في نفس الوقت. ودي حاجة مهمة: الشعراء الإنجليز استخدموا فينوس في النسختين: إلهة الغرام (زي شكسبير)، وقوة الطبيعة (زي لوكريتيوس)."},{"i":"myth-m13","s":90,"h":"النقطة 9: الأسطورة في الشعر الإنجليزي","t":"learn","x":"سبنسر (تشويق ل M109 ): في \"ملكة الجن\"، الكتاب الثالث، فيه \"حديقة أدونيس\" ( Garden of Adonis )، وفيها فينوس وأدونيس، والحديقة رمز للخصوبة الأبدية. هنقراها بالتفصيل."},{"i":"myth-m13","s":92,"h":"النقطة 10: أخطاء شائعة","t":"learn","x":"\"أفروديت إلهة الجمال بس\". لأ. هي إلهة الحب والرغبة والقوة اللي بتحرك كل حاجة حية، وفي روما بقت قوة سياسية (أم روما)."},{"i":"myth-m13","s":93,"h":"النقطة 10: أخطاء شائعة","t":"learn","x":"\"أفروديت بنت زيوس وديوني دائما\". لأ. عند هسيود مالهاش أم ولا أب، طلعت من أعضاء أورانوس. عند هوميروس بنت زيوس وديوني. نسختين."},{"i":"myth-m13","s":94,"h":"النقطة 10: أخطاء شائعة","t":"learn","x":"\"إيروس ابن أفروديت من الأول\". لأ. عند هسيود إيروس من أقدم الآلهة، قوة كونية قبل أوليمبوس. الابن بيسهم في التقليد المتأخر."},{"i":"myth-m13","s":95,"h":"النقطة 10: أخطاء شائعة","t":"learn","x":"\"كيوبيد طفل سمين بأجنحة\". دي صورة هيلينستية (323-31 قبل الميلاد) اتطورت لكيوبيد الروماني، وبعدها للملائكة الصغار في الفن الأوروبي. مش الصورة اليونانية القديمة."},{"i":"myth-m13","s":96,"h":"النقطة 10: أخطاء شائعة","t":"mc","x":"\"فينوس = أفروديت بالظبط\". إيه الغلط؟ ؟ فينوس إله ذكر / مفيش فرق خالص بينهم / فينوس كانت إلهة الحرب / فينوس كانت في الأصل إلهة أقل شأنا وكبرت بعد التوحيد . فينوس كانت في الأصل إلهة أقل شأنا وكبرت بعد التوحيد"},{"i":"myth-m13","s":97,"h":"النقطة 10: أخطاء شائعة","t":"learn","x":"\"فينوس = أفروديت بالظبط\". قريبة، بس فينوس الرومانية كانت في الأصل إلهة أقل شأنا، وكبرت بعد ما اتوحدت مع أفروديت."},{"i":"myth-m13","s":98,"h":"النقطة 10: أخطاء شائعة","t":"write","x":"& lt ; b & gt ;مقارنة:& lt ;/ b & gt ; قارن بين أفروديت عند هسيود وأفروديت عند هوميروس: الأصل، والعيلة، وإيه اللي كل نسخة بتقوله عن الحب. . عند هسيود أفروديت مالهاش أم ولا أب بالمعنى العادي: هي بنت زبد طلع حوالين أعضاء أورانوس بعد ما كرونوس قطعها ورماها في البحر. يعني ميلادها من عنف وجرح، وإيروس والرغبة بيمشوا معاها من أول لحظة. عند هوميروس هي بنت زيوس وديوني، يعني داخلة في عيلة الآلهة عادي، ومن غير المشهد البشع. الفرق بيغير معنى الحب: نسخة هسيود بتقول إن الحب قوة كونية بتطلع من جرح وعنف، وما حدش يقدر يتحكم فيها. نسخة هوميروس بتخلي الحب جزء من نظام الأسرة الإلهية، وبتحكي عنه بأسلوب اجتماعي: جواز، وخيانة، وفضيحة، وضحك. والتشابه إن الاتنين بيسموها إلهة قوية، والاتنين بيربطوها بقبرص والبحر. والخلاصة: الأسطورة ليها نسخ، والنسخة اللي تختارها بتحدد هتقول إيه عن الحب."},{"i":"myth-m14","s":1,"h":"مقدمة","t":"learn","x":"في الفصل ١١ خدنا أرتميس: البرية، والحدود، والصيد. في الفصل ١٢ خدنا أثينا: المدينة، والعقل، والقانون. في الفصل ١٣ خدنا أفروديت: الرغبة، والجمال، والقوة اللي بتحرك كل حاجة حية. والنهارده هيرميس، اللي الرومان سموه عطارد. وهو مختلف عن كل اللي فات. مش إله بيحكم مجال، هو إله بيعدي بين المجالات. بيعدي بين الآلهة والبشر، لأنه رسول. بيعدي بين الأحياء والموتى، لأنه بيوصل أرواح الموتى."},{"i":"myth-m14","s":2,"h":"مقدمة","t":"learn","x":"بيعدي بين الحدود، لأنه إله الطرق والأبواب والعلامات اللي بتفصل بين مكان ومكان. وبيعدي بين المعلوم والمخفي، لأنه إله اللصوص والتجار في نفس الوقت. وهو أصغر إله اتكلمنا عنه لحد دلوقتي: في الحكاية الكبيرة بتاعته، هو طفل عنده يوم واحد. يوم واحد بس، وعمل فيه كل حاجة: اخترع آلة موسيقية، وسرق خمسين بقرة، وكدب على إله أكبر منه، وخرج من المحاكمة من غير عقاب. يعني الفصل ده مش فصل قوة، ده فصل ذكاء. 🧠"},{"i":"myth-m14","s":4,"h":"النقطة 1: البطاقة الأساسية","t":"learn","x":"الاسم هيرميس باليوناني، وعطارد ( Mercury ) باللاتيني. والاسم اليوناني مشروح عند المفسرين القدامى من كلمة herma ، يعني كومة حجر أو علامة على الطريق. ودي هترجع لنا في آخر الفصل، لأن الاسم ده هو أصل كلمة herm ، العلامة الحجرية اللي كانت بتتحط على الطرق. 🪨"},{"i":"myth-m14","s":5,"h":"النقطة 1: البطاقة الأساسية","t":"mc","x":"مين أبو هيرميس وأمه؟ ؟ زيوس ومايا / أبولو وليتو / هيرا وزيوس / بوسيدون وأمفيتريت . زيوس ومايا"},{"i":"myth-m14","s":6,"h":"النقطة 1: البطاقة الأساسية","t":"learn","x":"والاسم اللاتيني Mercury جاي من merx ، يعني بضاعة أو سلعة، ومنها كلمة merchant ، التاجر، وكلمة market ، السوق. وكان في الأصل غالبا إله التجار، وفيه رأي إن أصل الاسم ممكن يكون إتروسكي. يعني الاسم نفسه جاي من عالم البيع والشراء."},{"i":"myth-m14","s":7,"h":"النقطة 1: البطاقة الأساسية","t":"tf","x":"اسم Mercury جاي من merx ، يعني بضاعة. . صح"},{"i":"myth-m14","s":8,"h":"النقطة 1: البطاقة الأساسية","t":"learn","x":"العيلة أبوه زيوس، وأمه مايا، بنت أطلس، واحدة من البليادات، الحوريات اللي سكنوا جبل كيليني. والنسب بيقولها في سطر واحد، نسب الآلهة ٩٣٨: \" And Maia, the daughter of Atlas, bore to Zeus glorious Hermes, the herald of the deathless gods, for she went up into his holy bed .\" يعني: ومايا، بنت أطلس، خلفت لزيوس هيرميس المجيد، رسول الآلهة الخالدين."},{"i":"myth-m14","s":9,"h":"النقطة 1: البطاقة الأساسية","t":"learn","x":"خد بالك من اللقب اللي في السطر: رسول الآلهة الخالدين. اللقب ده هو وظيفته، وهو مكتوب في أول مرة يتذكر فيها اسمه."},{"i":"myth-m14","s":10,"h":"النقطة 1: البطاقة الأساسية","t":"learn","x":"مكان الميلاد كهف في جبل كيليني، في أركاديا، في وسط البيلوبونيز. وهوميروس في الأوديسة بيناديه \"الكيليني\" ( Cyllenian )، يعني المنسوب للجبل ده. يعني المكان بقة جزء من اسمه."},{"i":"myth-m14","s":11,"h":"النقطة 1: البطاقة الأساسية","t":"learn","x":"الألقاب أرجهيفونتيس ( Argeiphontes ): يعني قاتل أرغوس. وأرغوس ده الوحش اللي عنده عيون كتير، اللي هيرا حطته يراقب البنت إيو. وهيرميس قتله. واللقب ده مستعمل في الترنيمة نفسها: \" the sharp-eyed slayer of Argus \". سايكوبومبوس ( psychopompos ): دليل الأرواح، اللي بيوصل أرواح الموتى للعالم التاني. وده أهم دور ليه في الشعر، وهنشوفه في الأوديسة ٢٤. و\"رسول الآلهة\" و\"إله اللصوص\"، وكلها ألقاب بتوصف نفس الحاجة من زوايا مختلفة: الحركة."},{"i":"myth-m14","s":12,"h":"النقطة 1: البطاقة الأساسية","t":"mc","x":"لقب Argeiphontes معناه إيه؟ ؟ قاتل أرغوس / حارس القطيع / دليل الأرواح / رسول الآلهة . قاتل أرغوس"},{"i":"myth-m14","s":13,"h":"النقطة 1: البطاقة الأساسية","t":"learn","x":"الأدوات الكيريكيون ( kerykeion )، وباللاتيني caduceus : العصاية اللي بيلف حواليها تعبانين. ودي عصاية الرسول، علامة إن اللي ماسكها مش بيتلمس. الجناحات في الجزمة ( talaria )، والطاقية اللي ليها حرف ( petasos )، والعباية ( chlamys ). وده شكله المعتاد في الفن الكلاسيكي. ومن الحيوانات المرتبطة بيه الكبش والسلحفاة. والسلحفاة دي مش اختيار عشوائي، لأن أول آلة موسيقية عنده كانت من سلحفاة. وهنشوف الحكاية كمان سطر."},{"i":"myth-m14","s":14,"h":"النقطة 1: البطاقة الأساسية","t":"mc","x":"إيه العصاية اللي بيلف حواليها تعبانين وبيشيلها هيرميس؟ ؟ الصاعقة / الرمح / الكيريكيون ( caduceus ) / الصولجان . الكيريكيون ( caduceus )"},{"i":"myth-m14","s":15,"h":"النقطة 1: البطاقة الأساسية","t":"learn","x":"شكله في الفن في الفن القديم، كان بيتصور غالبا راجل ناضج بلحية، وبعدين بقى كمان شاب رياضي من غير لحية."},{"i":"myth-m14","s":17,"h":"النقطة 2: أول يوم في حياته","t":"learn","x":"الترنيمة الهوميرية الرابعة، المخصصة لهيرميس، بتحكي أول يوم في حياته. وهي من أطول الترانيم الهوميرية، حوالي ٥٨٠ سطر، وكلها عن يوم واحد."},{"i":"myth-m14","s":18,"h":"النقطة 2: أول يوم في حياته","t":"learn","x":"المشهد الأول: السلحفاة الطفل اتولد في الكهف، وأمه نامت. وهو قام من المهد، وخرج. وعلى باب الكهف لقى سلحفاة بترعى العشب. والنص بيقول: \" But as he stepped over the threshold of the high-roofed cave, he found a tortoise there and gained endless delight. For it was Hermes who first made the tortoise a singer .\""},{"i":"myth-m14","s":19,"h":"النقطة 2: أول يوم في حياته","t":"learn","x":"يعني: لما خطى على عتبة الكهف العالي السقف، لقى سلحفاة هناك، وفرح فرحة ملهاش آخر. لأن هيرميس هو أول واحد خلى السلحفاة مغنية. جملة \"خلى السلحفاة مغنية\" دي هي أذكى جملة في الترنيمة. السلحفاة مالهاش صوت. بس لما تموت ويبقى صدفها آلة، تبقى بتغني."},{"i":"myth-m14","s":20,"h":"النقطة 2: أول يوم في حياته","t":"learn","x":"المشهد التاني: اختراع القيثارة هيرميس قتل السلحفاة، ونضف الصدفة، وحط فيها أوتار. والأوتار كانت من مصارين الخروف اللي كان بيرعاه. يعني الآلة الأولى اتولدت من حيوانين: سلحفاة وخروف. وبقى عندها سبع أوتار، زي ما بتقول الترنيمة. وغنى عليها عن أبوه وأمه، وعن ميلاده هو. وده أول درس في الفصل: الفن مش رفاهية. أول حاجة عملها إله الذكاء إنه صنع آلة موسيقية من حاجة ميتة، وغنى."},{"i":"myth-m14","s":21,"h":"النقطة 2: أول يوم في حياته","t":"mc","x":"القيثارة الأولى اتصنعت من إيه؟ ؟ خشب وحرير / نحاس وفضة / عاج وحديد / صدفة سلحفاة وأوتار من مصارين الخروف . صدفة سلحفاة وأوتار من مصارين الخروف"},{"i":"myth-m14","s":22,"h":"النقطة 2: أول يوم في حياته","t":"learn","x":"مثال من الحياة: أول مرة حد ياخد حاجة مكسورة ويصلحها ويخليها تشتغل، بيحس بنفس الفرحة. الإصلاح نفسه إبداع. 🔧"},{"i":"myth-m14","s":23,"h":"النقطة 2: أول يوم في حياته","t":"learn","x":"المشهد التالت: سرقة البقر هيرميس طلع من الكهف، ومشي لسهل بييريا، اللي فيه بقر الآلهة. والنص بيقول:"},{"i":"myth-m14","s":24,"h":"النقطة 2: أول يوم في حياته","t":"learn","x":"\" Of these the Son of Maia, the sharp-eyed slayer of Argus then cut off from the herd fifty loud-lowing kine, and drove them straggling-wise across a sandy place, turning their hoof-prints aside. Also, he bethought him of a crafty ruse and reversed the marks of their hoofs, making the front behind and the hind before, while he himself walked the other way .\""},{"i":"myth-m14","s":25,"h":"النقطة 2: أول يوم في حياته","t":"learn","x":"يعني: ابن مايا، قاتل أرغوس الحاد البصر، فصل من القطيع خمسين بقرة بتخوار عالي، وساقهم متفرقين على أرض رملية، ولف آثار حوافرهم. وفكر في حيلة ماكرة، وقلب علامات حوافرهم، فخلى المقدمة ورا والمؤخرة قدام، وهو نفسه مشي في الاتجاه التاني. تخيل المشهد: خمسين بقرة ماشية لورا، وآثارهم بتقول إنهم مشيوا في الاتجاه العكسي، والطفل ماشي في الاتجاه التاني. أي واحد يتتبعهم هيوصل لمكان تاني خالص."},{"i":"myth-m14","s":26,"h":"النقطة 2: أول يوم في حياته","t":"tf","x":"هيرميس خلى آثار البقر تبان كأنها ماشية في الاتجاه العكسي. . صح"},{"i":"myth-m14","s":27,"h":"النقطة 2: أول يوم في حياته","t":"learn","x":"وبعدين عمل جزمة. والنص بيقول: \" Then he wove sandals with wicker-work by the sand of the sea, wonderful things, unthought of, unimagined .\" يعني: نسج جزمة من خيوط نباتية على رمل البحر، حاجات عجيبة، ماحدش فكر فيها ولا تخيلها. ليه؟ عشان أثر رجله ما يبانش. يعني هو اخترع الجزمة كأداة تمويه، مش كأداة لبس. 😄"},{"i":"myth-m14","s":28,"h":"النقطة 2: أول يوم في حياته","t":"learn","x":"ودي حاجة تستاهل وقفة. الجزمة اللي في رجلك النهارده، في الحكاية دي، أول سببها جريمة. والتكنولوجيا كده: كل اختراع بيطلع من حاجة، والحاجة مش دايما نبيلة."},{"i":"myth-m14","s":29,"h":"النقطة 2: أول يوم في حياته","t":"mc","x":"ليه هيرميس نسج جزمة من النبات؟ ؟ عشان يبيعها / عشان أثر رجله ما يبانش / عشان يهديها لأبولو / عشان يتدفى . عشان أثر رجله ما يبانش"},{"i":"myth-m14","s":30,"h":"النقطة 2: أول يوم في حياته","t":"learn","x":"المشهد الرابع: المحاكمة أبولو، صاحب البقر، اكتشف السرقة. وجه للكهف زعقان. وهيرميس عمل إيه؟ دخل في قماشه. والنص بيقول: \" he snuggled down in his fragrant swaddling-clothes... like a new born child seeking sweet sleep, though in truth he was wide awake, and he kept his lyre under his armpit .\" يعني: تمدد في قماشه الملفوف، زي طفل مولود بيدور على نوم حلو، مع إنه في الحقيقة صاحي خالص، وكان حاطط قيثارته تحت باطه."},{"i":"myth-m14","s":31,"h":"النقطة 2: أول يوم في حياته","t":"learn","x":"والتفصيلة الأخيرة دي هي الكوميديا كلها: الطفل بيدعي إنه رضيع، وقيثارته تحت باطه. وأبولو قال له: قول الحقيقة. وهيرميس رد بجملة بقت من أشهر مشاهد الدفاع الكوميدي: \" I care for sleep, and milk of my mother's breast, and wrappings round my shoulders, and warm baths .\" يعني: أنا بيهمني النوم، ولبن صدر أمي، ولفات على كتافي، وحمامات سخنة. يعني: أنا رضيع. مش عارف حاجة عن بقر ولا سرقة ولا كلام من ده. 😂"},{"i":"myth-m14","s":32,"h":"النقطة 2: أول يوم في حياته","t":"tf","x":"لما أبولو واجهه، هيرميس ادعى إنه رضيع. . صح"},{"i":"myth-m14","s":33,"h":"النقطة 2: أول يوم في حياته","t":"learn","x":"والنص نفسه بيقول إنه رد \"بحكمة ماكرة\" ( with crafty words ). الشاعر مش مخدوع، وهو عايزك تعرف إن الطفل بيكدب."},{"i":"myth-m14","s":34,"h":"النقطة 2: أول يوم في حياته","t":"learn","x":"المشهد الخامس: قدام زيوس راحوا لزيوس، والد الاتنين. وأبولو شكى، وهيرميس دافع عن نفسه تاني. وفي الدفاع ده بيصر الطفل إنه لسه مولود وملوش علاقة بالسرقة. وزيوس ضحك من حيلة الطفل، وطلب منهم يدوروا على البقر مع بعض."},{"i":"myth-m14","s":35,"h":"النقطة 2: أول يوم في حياته","t":"learn","x":"المشهد السادس: الهدية هيرميس إيه اللي عمل؟ إدى القيثارة لأبولو. هدية. والأسطورة بتقول إن أبولو خد الآلة ونسي البقر. والترنيمة بتحكي التسليم ده قرب آخرها. وده أهم تحول في الفصل: اللص بقى فنان، والخصم بقى صاحب. والآلة اللي اتولدت من سلحفاة ميتة بقت آلة أبولو الرسمية، وبعدها بقت آلة الشعر كله. ومن هنا ممكن نربط هيرميس ببداية الغنا والآلة الموسيقية."},{"i":"myth-m14","s":36,"h":"النقطة 2: أول يوم في حياته","t":"mc","x":"هيرميس عمل إيه بالقيثارة في الآخر؟ ؟ كسرها / خباها / إداها لأبولو هدية / رماها في البحر . إداها لأبولو هدية"},{"i":"myth-m14","s":37,"h":"النقطة 2: أول يوم في حياته","t":"learn","x":"وبعد كده بيبقى رسول الآلهة. يعني الطفل اللي سرق بقى صوت الكلام الرسمي بين الآلهة."},{"i":"myth-m14","s":39,"h":"النقطة 3: الميادين الخمسة","t":"learn","x":"الأول: الحركة والطرق والحدود هيرميس إله المسافرين، والطرق، والأبواب، والعلامات اللي على الطريق. والهيرم، العلامة الحجرية اللي بتتحط عند مفترق الطرق وباب البيت، كانت بتتحط باسمه. والهيرم عمود حجري مستطيل، فوقه راس، غالبا راس هيرميس، وفي النص أعضاء الرجل بارزة بالنحت. والناس في العصور القديمة كانت بتعتبر الهيرم مقدس، وليها طبيعة حامية، وكانوا بيحطوها على جوانب الطرق، وعند المفترقات، ومداخل الأماكن العامة."},{"i":"myth-m14","s":40,"h":"النقطة 3: الميادين الخمسة","t":"learn","x":"وده معنى مهم: العلامة اللي بتقول لك \"إنت هنا\" و\"إنت داخل\" كانت إله. الحدود نفسها كانت مقدسة، لأنها المكان اللي بيحصل فيه الانتقال."},{"i":"myth-m14","s":41,"h":"النقطة 3: الميادين الخمسة","t":"learn","x":"التاني: التجارة واللصوص نفس الإله بيحمي التاجر واللص. وده مش تناقض، ده منطق. الاتنين بيتحركوا، والاتنين بيعتمدوا على الذكاء، والاتنين بيعملوا صفقة فيها مخاطرة. والاسم اللاتيني نفسه من merx ، بضاعة. يعني في اللاتيني، الإله ده إله السوق من اسمه."},{"i":"myth-m14","s":42,"h":"النقطة 3: الميادين الخمسة","t":"learn","x":"ومثال من الحياة: في أي سوق، اللي بيبيع واللي بينصب على الناس بيلعبوا نفس اللعبة: إقناع وثقة وسرعة. الفرق إن واحد بيحترم العقد والتاني لأ. والميثولوجيا حطت الاتنين تحت نفس الإله، عشان تفكرك إن الخط بينهم رفيع. ⚖️"},{"i":"myth-m14","s":43,"h":"النقطة 3: الميادين الخمسة","t":"learn","x":"التالت: الكلام والرسالة والترجمة هيرميس رسول، وده معناه إنه بيتكلم باسم حد تاني. والرسول لازم يكون أمين وماهر في نفس الوقت. أمين في المعنى، ماهر في الصياغة. وكلمة hermeneia يعني تفسير، ومنها hermeneutics ، علم التفسير. والربط بينها وبين اسم هيرميس قديم ومعروف، مع إن أصل الكلمة مش محسوم. وده هو سبب أهمية هيرميس للشعر الإنجليزي: كل شاعر بيترجم أسطورة بيبقى هيرميس. بياخد معنى من لغة ويديه للغة تانية."},{"i":"myth-m14","s":44,"h":"النقطة 3: الميادين الخمسة","t":"learn","x":"الرابع: الرعي والقطيع هو كمان إله الرعاة والقطعان، وده واضح في الترنيمة اللي بيسرق فيها البقر وبيذبح منها. وده بيوريك إن الآلهة اليونانية مالهاش تخصص ضيق. الإله بيغطي مجال واسع، وكل مجال بيفسر جانب من شخصيته."},{"i":"myth-m14","s":45,"h":"النقطة 3: الميادين الخمسة","t":"learn","x":"الخامس: النوم والأحلام هيرميس بيجيب النوم، وبيفتح العيون اللي نايمة، وبيوصل رسايل في الأحلام. والعصاية بتاعته في الأوديسة ٢٤ بتعمل بالظبط كده: بتنيم اللي هو عايزه، وتصحي اللي هو عايزه. وده منطقي، لأن النوم هو الحد بين الوعي واللاشعور، وهيرميس إله الحدود."},{"i":"myth-m14","s":47,"h":"النقطة 4: هيرميس اللي بيوصل الأرواح","t":"learn","x":"ده أهم دور ليه في الشعر، ولازم تفتكره."},{"i":"myth-m14","s":48,"h":"النقطة 4: هيرميس اللي بيوصل الأرواح","t":"learn","x":"الأوديسة ٢٤ في آخر كتاب في الأوديسة، أرواح الخاطبين اللي اتقتلوا لسه بتطلع من العالم التاني. ومين اللي بياخدهم؟ هيرميس. والنص بيقول، بترجمة موراي: \" Meanwhile Cyllenian Hermes called forth the spirits of the wooers. He held in his hands his wand, a fair wand of gold, wherewith he lulls to sleep the eyes of whom he will, while others again he wakens even out of slumber .\""},{"i":"myth-m14","s":49,"h":"النقطة 4: هيرميس اللي بيوصل الأرواح","t":"learn","x":"يعني: في الوقت ده، هيرميس الكيليني نادى أرواح الخاطبين. كان ماسك في إيده عصايته، عصاية جميلة من دهب، بيها بينيم عيون اللي هو عايزه، وبيصحي تانيين من النوم. وبعدها بيقودهم، والنص بيقول: \" Hermes, the Helper, led them down the dank ways .\" يعني: هيرميس، المعين، قادهم في الطرق الندية المظلمة."},{"i":"myth-m14","s":50,"h":"النقطة 4: هيرميس اللي بيوصل الأرواح","t":"learn","x":"والصورة اللي بعده تحفة: الأرواح بتتحرك زي الخفافيش في كهف، بتصوت وتتعلق في بعض. يعني الموت هنا مش ملك فخم، هو قطيع خفافيش بتمشي ورا عصاية."},{"i":"myth-m14","s":51,"h":"النقطة 4: هيرميس اللي بيوصل الأرواح","t":"mc","x":"في الأوديسة ٢٤، هيرميس بيعمل إيه؟ ؟ بيحارب الخاطبين / بيحكم أيثاكا / بيقود أرواح الخاطبين للعالم التاني / بيحرس باب العالم التاني . بيقود أرواح الخاطبين للعالم التاني"},{"i":"myth-m14","s":52,"h":"النقطة 4: هيرميس اللي بيوصل الأرواح","t":"learn","x":"الإلياذة ٢٤ في آخر كتاب في الإلياذة، بريام بيجي يطلب جثة ابنه هيكتور من أخيل. ومين اللي بيوصله في نص الليل، ويحميه من الجيش كله؟ هيرميس. وزيوس بيقول له إن هيرميس أكتر واحد بيحب يرافق الناس في طريقهم، وإنه يوصل بريام لسفن الآخيين من غير ما حد يشوفه."},{"i":"myth-m14","s":53,"h":"النقطة 4: هيرميس اللي بيوصل الأرواح","t":"tf","x":"في الإلياذة ٢٤، هيرميس بيوصل بريام لسفن الآخيين من غير ما حد يشوفه. . صح"},{"i":"myth-m14","s":54,"h":"النقطة 4: هيرميس اللي بيوصل الأرواح","t":"learn","x":"الأوديسة ٥ و١٠ في الأوديسة ٥، زيوس بيبعته لكاليبسو، عشان يقول لها تسيب أوديسيوس يمشي. وفي الأوديسة ١٠، بيدي أوديسيوس العشبة اللي بتحميه من سحر سيرسي. والنص بيقول: \" So saying, Argeiphontes gave me the herb, drawing it from the ground, and showed me its nature. At the root it was black, but its flower was like milk. Moly the gods call it, and it is hard for mortal men to dig ; but with the gods all things are possible .\""},{"i":"myth-m14","s":55,"h":"النقطة 4: هيرميس اللي بيوصل الأرواح","t":"learn","x":"يعني: وقال ده، وأداني العشبة، قاتل أرغوس، وشالها من الأرض، ووراني طبيعتها. كانت سودا من تحت، وزهرتها زي اللبن. مولي بيسموها الآلهة، وصعب على البشر يقلعوها، بس مع الآلهة كل حاجة ممكنة. وده أقدم ظهور معروف للعشبة السحرية في الأدب الأوروبي، واسمها مولي."},{"i":"myth-m14","s":56,"h":"النقطة 4: هيرميس اللي بيوصل الأرواح","t":"mc","x":"إيه اسم العشبة اللي بتحمي أوديسيوس من سحر سيرسي؟ ؟ مولي ( moly ) / أمبروسيا / نكتار / لوتس . مولي ( moly )"},{"i":"myth-m14","s":58,"h":"النقطة 5: عطارد في روما","t":"learn","x":"الاسم والتجارة عطارد في الأصل إله التجار والبيع والكسب. واسمه من merx ، بضاعة. والرومان وحدوه مع هيرميس، فبقى بياخد وظايفه كلها: الرسول، والدليل، والحدود."},{"i":"myth-m14","s":59,"h":"النقطة 5: عطارد في روما","t":"learn","x":"المعبد معبده في روما كان في السيرك ماكسيموس، واتدشن سنة ٤٩٥ قبل الميلاد. والمعبد اتدشن على إيد قائد مئة، والشعب هو اللي إداه شرف التدشين. واختيار المكان نفسه معنى: السيرك ماكسيموس مكان السباق والتجمع والتجارة. إله الحركة في مكان الحركة. 🏇"},{"i":"myth-m14","s":60,"h":"النقطة 5: عطارد في روما","t":"learn","x":"يوم الأربع يوم الأربع في اللاتيني هو dies Mercurii ، يوم عطارد. والجرمان القدام ترجموا الاسم لإلههم Woden ، فبقت Wednesday في الإنجليزي. يعني كل مرة تقول Wednesday ، إنت بتقول اسم إله قديم، بس بواحد تاني. 😄"},{"i":"myth-m14","s":61,"h":"النقطة 5: عطارد في روما","t":"mc","x":"اسم Wednesday جاي من إلهه إيه؟ ؟ Zeus / Apollo / Woden (ترجمة جرمانية لعطارد) / Thor . Woden (ترجمة جرمانية لعطارد)"},{"i":"myth-m14","s":62,"h":"النقطة 5: عطارد في روما","t":"learn","x":"عطارد في الإنيد في الإنيد ٤، عطارد هو اللي بينزل من السما ويقول لإينياس: إنت بتعمل إيه في قرطاج؟ سيبك من الحب وسيبك من الملكة، إنت ليك مهمة في إيطاليا. والمشهد في الكتاب الرابع، لما جوبيتر يبعت عطارد لإينياس. وده استخدام سياسي للأسطورة: الرسول بييجي يفضح إينياس، وبكده قرطاج وديدو بيبقوا غلطة، وروما هي الوجهة الصح."},{"i":"myth-m14","s":63,"h":"النقطة 5: عطارد في روما","t":"learn","x":"ولاحظ الفرق: هيرميس في هوميروس بيحمي ضيف (بريام). وعطارد في فيرجيل بيقطع علاقة حب. نفس الوظيفة، ونتيجتين عكسيتين."},{"i":"myth-m14","s":64,"h":"النقطة 5: عطارد في روما","t":"tf","x":"في الإنيد ٤، عطارد بيقطع علاقة إينياس بقرطاج. . صح"},{"i":"myth-m14","s":66,"h":"النقطة 6: عطارد في أوفيد: المحتال اللي بياخد أجره","t":"learn","x":"قصة باتوس، الميتامورفوزيس ٢ عطارد سرق بقر، وشافه راجل اسمه باتوس. فعرض عليه صفقة: لو حد سألك، قول إنك ما شفتش حاجة، وخد بقرة أجر. وباتوس وعد. وبعدها عطارد رجع في شكل تاني، وسأله السؤال نفسه، ووعده بأجر أكبر. فباتوس فضح نفسه وقال له كل حاجة. والدرس: الإله ده بيختبر الناس بالطمع. واللي بيبيع نفسه مرة، بيبيعها تاني."},{"i":"myth-m14","s":67,"h":"النقطة 6: عطارد في أوفيد: المحتال اللي بياخد أجره","t":"mc","x":"عطارد عمل إيه في باتوس لما فضح نفسه؟ ؟ نيمه ورمى جثته في النهر / حوله لحجر / كافأه ببقرة / نيمه . حوله لحجر"},{"i":"myth-m14","s":68,"h":"النقطة 6: عطارد في أوفيد: المحتال اللي بياخد أجره","t":"learn","x":"قصة فيليمون وباوسيس، الميتامورفوزيس ٨ زيوس وعطارد نزلوا الأرض في شكل بشر، ولفوا على ألف بيت يطلبوا ضيافة، وكل الأبواب اتقفلت. وأوفيد بيوصف عطارد هناك بإنه ابن أطلس، حامل الكادوسيوس، وحاطط أجنحته على جنب. وفي الآخر بيت فقير واحد فتح لهم: فيليمون وباوسيس. والدرس: الإله اللي بيدخل بيتك على شكل غريب، ممكن يكون عطارد. والضيافة في الميثولوجيا اختبار، مش مجاملة."},{"i":"myth-m14","s":70,"h":"النقطة 7: الأسطورة في الشعر الإنجليزي","t":"learn","x":"وصلنا للجزء المهم. هيرميس/عطارد دخل الشعر الإنجليزي من بابين: باب اللص الشاب، وباب الترجمة."},{"i":"myth-m14","s":71,"h":"النقطة 7: الأسطورة في الشعر الإنجليزي","t":"learn","x":"الشاهد الأول: جون كيتس، لاميا، الجزء الأول في أول القصيدة، بعد افتتاحية قصيرة، هيرميس سايب عرشه ونازل يدور على حورية: \" The ever-smitten Hermes empty left His golden throne, bent warm on amorous theft : From high Olympus had he stolen light , On this side of Jove's clouds, to escape the sight Of his great summoner, and made retreat Into a forest on the shores of Crete .\""},{"i":"myth-m14","s":72,"h":"النقطة 7: الأسطورة في الشعر الإنجليزي","t":"mc","x":"إيه اللي بيعمله هيرميس في أول قصيدة لاميا؟ ؟ بيساب عرشه وينزل يدور على حورية / بيقتل أرغوس / بيغني لأبولو / بيسرق ماشية أبولو . بيساب عرشه وينزل يدور على حورية"},{"i":"myth-m14","s":73,"h":"النقطة 7: الأسطورة في الشعر الإنجليزي","t":"learn","x":"والترجمة: هيرميس، اللي دايما مصدوم بالحب، ساب عرشه الدهبي فاضي، وماشي بحرارة في سرقة عاطفية. من أوليمبوس العالي كان سارق نزلة، على الناحية دي من سحاب جوبيتر، عشان يهرب من نظر اللي استدعاه، وانسحب لجوة غابة على شط كريت. الشرح: كيتس بيستخدم هيرميس في أول قصيدة، وبيرجع للصورة الأصلية: الإله الشاب اللي بيسرق. بس السرقة هنا مش بقر، دي سرقة حب. وكلمة amorous theft بتفكرنا بروح الترنيمة: هو حرامي، والحب حرامي."},{"i":"myth-m14","s":74,"h":"النقطة 7: الأسطورة في الشعر الإنجليزي","t":"learn","x":"والتفصيلة الأهم: \" to escape the sight of his great summoner \". يعني هيرميس هرب من اللي بيبعته. الرسول بيتمرد على المرسل. وده اللي بيخلي القصيدة تبدأ. والقصة بعدين بتكمل: هيرميس بيقابل لاميا، وهي ثعبان، وبيساعدها مقابل إنها تديه الحورية اللي بيدور عليها. ولاميا قصيدة عن التحول."},{"i":"myth-m14","s":75,"h":"النقطة 7: الأسطورة في الشعر الإنجليزي","t":"learn","x":"الشاهد التاني: كريستوفر مارلو، هيرو وليندر مارلو بيوصف عطارد في الجزء الأول من القصيدة، لما شاف بنت جميلة: \" Heavens winged herrald, Jove-borne Mercury , The self-same day that he asleepe had layd Inchaunted Argus, spied a countrie mayd , Whose carelesse haire, in stead of pearle t'adorne it , Glist'red with deaw ...\""},{"i":"myth-m14","s":76,"h":"النقطة 7: الأسطورة في الشعر الإنجليزي","t":"learn","x":"والترجمة: رسول السما المجنح، عطارد المحمول من جوبيتر، في نفس اليوم اللي كان بينيم فيه أرغوس المسحور، شاف بنت ريفية، شعرها المهمل، بدل ما يتزين باللؤلؤ، كان بيلمع بالندى. الشرح: في سطرين، مارلو جمع كل حاجة في الفصل: الجناحات، والرسول، وقتل أرغوس، والمرأة. وكلمة \" Inchaunted Argus \" بتربط اللقب اليوناني بالحكاية: هيرميس نوم أرغوس بالحكي والموسيقى، وبعدها قتله. 🎵"},{"i":"myth-m14","s":77,"h":"النقطة 7: الأسطورة في الشعر الإنجليزي","t":"learn","x":"الشاهد التالت: بيرسي بيش شيلي، ترنيمة لعطارد شيلي ترجم الترنيمة الهوميرية الرابعة كاملة، ونشرها بعنوان \" Hymn to Mercury \"، وطبعت بعد وفاته سنة ١٨٢٤. وده مش اقتباس، ده النص نفسه بينتقل للإنجليزي. يعني الترنيمة اللي اتكتبت في العصر القديم، غالبا حوالي القرن السادس قبل الميلاد، بقت قصيدة إنجليزية في القرن التسعتاشر. وده مثال على إن الشعراء الإنجليز بيترجموا هيرميس كمان، فهو إله الترجمة بشكل ما."},{"i":"myth-m14","s":78,"h":"النقطة 7: الأسطورة في الشعر الإنجليزي","t":"learn","x":"وليه هيرميس مناسب للشعر الإنجليزي أكتر من أي إله؟ لأنه إله الكلام. والرسول واللص والمترجم والتاجر كلهم بيشتغلوا بالكلام. ولأنه إله الانتقال. والشعر الإنجليزي كله تقريبا بيتكلم عن لحظة انتقال: من حال لحال، من مكان لمكان، من حياة لموت. ولأنه إله الحدود. والشعر بيقف على الحدود: بين المعنى والتفسير، بين الأصل والترجمة، بين اللي اتقال واللي اتقصد."},{"i":"myth-m14","s":79,"h":"النقطة 7: الأسطورة في الشعر الإنجليزي","t":"write","x":"& lt ; b & gt ;مقارنة:& lt ;/ b & gt ; قارن بين هيرميس عند هوميروس في الإلياذة ٢٤ وعطارد عند فيرجيل في الإنيد ٤. الاتنين رسول بيبعته كبير الآلهة، لكن النتيجة مختلفة. إيه الفرق؟ . الوظيفة واحدة: رسول بيبعته كبير الآلهة. عند هوميروس في الإلياذة ٢٤، هيرميس بيوصل بريام لسفن الآخيين من غير ما حد يشوفه، فهو بيحمي راجل ضعيف وبيفتح له الطريق. وعند فيرجيل في الإنيد ٤، عطارد بينزل لإينياس بأمر جوبيتر ويقول له يسيب قرطاج وديدو ويروح إيطاليا، فهو بيقطع علاقة حب. يعني هيرميس هنا حامي، وعطارد هنا منفذ لقرار سياسي. والفرق ده بيوضح إن الأسطورة بتتغير مع الثقافة: عند اليونان الرسول مرافق وحامي، وعند الرومان الرسول بيخدم مصير روما. ومع كده الاتنين بيعدوا الحدود: بريام بيعدي معسكر العدو، وإينياس بيطلع من قرطاج. الخلاصة: نفس الرسول، لكن اتجاه الرسالة بيتغير حسب هدف الشاعر."},{"i":"myth-m14","s":81,"h":"النقطة 8: إزاي تعرف هيرميس في قصيدة","t":"learn","x":"خمس مجموعات كلمات: الأسماء: Hermes ، Mercury ، Cyllenian ، Maia ، Argeiphontes ، Atlantiades . الحركة: wing ، winged ، fly ، speed ، swift ، road ، path ، gate ، threshold ، cross . الرسالة: message ، herald ، embassy ، word ، news ، interpret ، translate . الخداع: theft ، thief ، trick ، craft ، cunning ، wile ، bargain ، trade ، market . الحد بين الحياة والموت: wand ، rod ، golden ، sleep ، wake ، shade ، ghost ، soul ، lead ، guide ."},{"i":"myth-m14","s":82,"h":"النقطة 8: إزاي تعرف هيرميس في قصيدة","t":"learn","x":"ولو لقيت تلاتة من دول، احتمال كبير إنك قدام هيرميس. والفرق عن الآلهة اللي فاتوا: كلمات زيوس فيها السلطة والصاعقة. كلمات أبولو فيها النور والنبوة والشعر. كلمات أرتميس فيها القمر والغابة. كلمات أثينا فيها الدرع والنول والقانون. كلمات أفروديت فيها النار والسهم والزبد. وكلمات هيرميس فيها الجناح والطريق والعصاية والصفقة."},{"i":"myth-m14","s":84,"h":"النقطة 9: سؤال مفتوح","t":"learn","x":"فيه سؤال في الفصل ده، ومش هجاوب عليه. هيرميس إله اللصوص، وفي نفس الوقت إله الرسول الأمين. وزيوس بيوصفه في الإلياذة بإنه أكتر إله بيحب مرافقة الناس. السؤال: إزاي إله واحد يبقى أمين وخاين في نفس الوقت؟ فيه قراءة بتقول: لأن الأمانة مش في نقل الكلام حرفيا، الأمانة في إنك تنقل اللي محتاج يتنقل، مش كل اللي اتقال. والرسول الحكيم بيفهم إيه اللي يتقال وإيه اللي يتخبى."},{"i":"myth-m14","s":85,"h":"النقطة 9: سؤال مفتوح","t":"learn","x":"وفيه قراءة تانية بتقول: لأن السلطة نفسها مبنية على الكتمان. اللي بيوصل الرسالة هو اللي بيعرف أسرارها، واللي بيعرف الأسرار بيقدر يبيعها. والاتنين بيقروا نفس النص، والسؤال يفضل مفتوح."},{"i":"myth-m14","s":87,"h":"النقطة 10: أخطاء شائعة","t":"learn","x":"هيرميس إله اللصوص بس. لأ. هو إله الحركة كلها: الطرق، والتجارة، والرسالة، والحدود، والنوم، والموت. هيرميس ابن أفروديت. لأ. هو ابن زيوس ومايا. اللي ابن أفروديت هو إيروس، وده اللي خدناه في الفصل اللي فات. القيثارة اختراع أبولو. لأ. اختراع هيرميس، وهو اللي إداها لأبولو كهدية. عطارد نسخة رومانية مطابقة. قريب، بس عطارد في الأصل إله تجارة وكسب، والاسم نفسه من merx ، بضاعة."},{"i":"myth-m14","s":88,"h":"النقطة 10: أخطاء شائعة","t":"tf","x":"القيثارة اختراع أبولو. . غلط"},{"i":"myth-m14","s":89,"h":"النقطة 10: أخطاء شائعة","t":"learn","x":"الهيرم مجرد تمثال. لأ. الهيرم علامة حدود ووقاية، وكانت بتتحط على الطرق والمفترقات ومداخل البيوت."},{"i":"myth-m14","s":91,"h":"ملخص في عشر جمل","t":"learn","x":"هيرميس ابن زيوس ومايا بنت أطلس، واتولد في كهف على جبل كيليني في أركاديا. في أول يوم في حياته اخترع القيثارة من صدفة سلحفاة، وسرق خمسين بقرة من أبولو. الحيلة كانت في آثار الحوافر المقلوبة، وفي جزمة منسوجة تخفي أثره. لما اتهمه أبولو، دافع عن نفسه بأنه رضيع بيحب اللبن والنوم والحمام الساخن. زيوس ضحك، والاتنين تصالحوا، وهيرميس إدى القيثارة لأبولو هدية."},{"i":"myth-m14","s":92,"h":"ملخص في عشر جمل","t":"learn","x":"وظايفه: الرسالة، والطرق، والحدود، والتجارة، واللصوص، والنوم، وقيادة الأرواح. لقبه أرجهيفونتيس يعني قاتل أرغوس، وسايكوبومبوس يعني دليل الأرواح. في الأوديسة ٢٤ بيقود أرواح الخاطبين بعصاية دهب، وفي الإلياذة ٢٤ بيحمي بريام. عطارد الروماني إله تجارة، واسمه من merx بضاعة، ومعبده في السيرك ماكسيموس اتدشن ٤٩٥ قبل الميلاد. في الشعر الإنجليزي، هيرميس هو إله الترجمة والانتقال، والشعراء بيستخدموه لما يتكلموا عن الكلام نفسه."},{"i":"myth-m14","s":94,"h":"الخلاصة","t":"learn","x":"هيرميس هو الإله اللي بيفتح الأبواب. مش لأنه قوي، لأنه بيعرف فين الباب. وهو الإله اللي بيعرف إن الكلام ممكن يكون رسالة، وممكن يكون صفقة، وممكن يكون سرقة. وفي الفصل الجاي، هنقابل إلهين متضادين: آريس، الحرب العنيفة، وهيفايستوس، الصنعة الهادية. والاتنين كانوا في قصة أفروديت اللي خدناها."},{"i":"myth-m15","s":1,"h":"إحنا فين في الحكاية","t":"learn","x":"الفصل ده مختلف، لأن فيه إلهين مش واحد. والاتنين أضداد، ومتصلين ببعض. آريس ( Ares )، مارس عند الرومان: إله الحرب. العنف، والصراخ، والدم. هيفايستوس ( Hephaestus )، فولكان عند الرومان: إله النار والصنعة. الحدادة، والآلات، والبناء. وإزاي الاتنين متصلين؟ الاتنين بيشتغلوا بالنار والحديد: واحد بيستخدمهم في الهدم، وواحد في البناء."},{"i":"myth-m15","s":2,"h":"إحنا فين في الحكاية","t":"learn","x":"والاتنين كانوا في قصة واحدة، وهي قصة أفروديت اللي خدناها في الفصل اللي فات: أفروديت مرات هيفايستوس، وحبيبة آريس. واليونان كانوا بيكرهوا آريس ويحبوا هيفايستوس. وده مش رأي شخصي، ده واضح في النصوص نفسها. والفصل ده فيه درس كبير عن الميثولوجيا اليونانية: مش كل الآلهة محبوبة. فيه إله بيخافوا منه ويكرهوه، وفيه إله بيحترموه ويشفقوا عليه."},{"i":"myth-m15","s":3,"h":"إحنا فين في الحكاية","t":"learn","x":"والاتنين أولاد زيوس وهيرا. يعني نفس البيت، ونتيجتين مختلفتين."},{"i":"myth-m15","s":4,"h":"إحنا فين في الحكاية","t":"mc","x":"إيه اللي بيجمع آريس وهيفايستوس في التقليد الأساسي؟ ؟ الاتنين إخوة زيوس / الاتنين أولاد أفروديت / الاتنين أولاد زيوس وهيرا / الاتنين أولاد بوسيدون . الاتنين أولاد زيوس وهيرا"},{"i":"myth-m15","s":6,"h":"البطاقة الأساسية: آريس","t":"learn","x":"الاسم آريس باليوناني، ومارس ( Mars ) باللاتيني. والاسم اللاتيني مارس هو أصل كلمة March ، شهر مارس. وقاموس أصل الكلمات بيقول: الكلمة جاية من اللاتيني Martius ( mensis )، يعني شهر مارس، من Mars ، والجمع Martis . يعني الشهر التالت في السنة، لحد النهارده، اسمه اسم إله حرب. العيلة أبوه زيوس، وأمه هيرا. وأخته من الأب أثينا، إلهة الحرب التانية."},{"i":"myth-m15","s":7,"h":"البطاقة الأساسية: آريس","t":"learn","x":"وهنا المقارنة المهمة: أثينا إلهة الحرب بالعقل والخطة، وآريس إله الحرب بالغضب والدم. الألقاب في الإلياذة، هوميروس بيناديه \"بلية البشر\" ( the bane of mortals ). والنص بيقول بالحرف : \" Now when Ares, the bane of mortals, was ware of goodly Diomedes ...\" يعني: لما آريس، بلية البشر، شاف ديوميديس الجميل. وده مش لقب فخر، ده لقب شتيمة."},{"i":"myth-m15","s":8,"h":"البطاقة الأساسية: آريس","t":"learn","x":"الشاعر بيقول لك رأيه من أول كلمة. وفي مجموعة الترنيمات الهوميرية، فيه ترنيمة قصيرة مخصصة لآريس (الترنيمة التامنة)، وفيها دعاء له. يعني حتى إله الحرب، ليه ترنيمة دعاء. ودي حاجة تستاهل وقفة: الناس بتدعي للحرب، وبعدها بتدعي إنها تخلص. الأدوات الرمح، والخوذة، والدرع. والعربة اللي بيقودها."},{"i":"myth-m15","s":9,"h":"البطاقة الأساسية: آريس","t":"learn","x":"الشخصية غضوب، وسريع الانفعال، وبيزعق. وفي الإلياذة، لما بيجرح، بيروح يشكي لأبوه زي طفل. وهنشوف المشهد ده حالا."},{"i":"myth-m15","s":10,"h":"البطاقة الأساسية: آريس","t":"tf","x":"هوميروس بينادي آريس \"بلية البشر\"، وده لقب فخر. . غلط"},{"i":"myth-m15","s":12,"h":"البطاقة الأساسية: هيفايستوس","t":"learn","x":"الاسم هيفايستوس باليوناني، وفولكان ( Vulcan ) باللاتيني. والاسم اللاتيني فولكان هو أصل كلمة volcano ، البركان. وده منطقي، لأن فولكان إله النار، ونار البركان أقرب حاجة لناره. العيلة أمه هيرا، وأبوه… هنا فيه نسختين."},{"i":"myth-m15","s":13,"h":"البطاقة الأساسية: هيفايستوس","t":"learn","x":"في نسب الآلهة، سطر ٩٢٤ وما بعده، بترجمة Evelyn-White : \" But Hera without union with Zeus--for she was very angry and quarrelled with her mate--bare famous Hephaistos, who is skilled in crafts more than all the sons of Heaven .\""},{"i":"myth-m15","s":14,"h":"البطاقة الأساسية: هيفايستوس","t":"learn","x":"يعني: لكن هيرا، من غير اتحاد مع زيوس، لأنها كانت غضبانة جدا واتخانقت مع شريكها، خلفت هيفايستوس الشهير، اللي أشطر في الصنعة من كل أولاد السماء. يعني هيفايستوس ابن هيرا لوحدها، من غير أب. وده رد على أثينا، اللي طلعت من راس زيوس لوحده في الفصل اللي فات. هيرا عملت نفس الحاجة، بس النتيجة كانت إله أعرج."},{"i":"myth-m15","s":15,"h":"البطاقة الأساسية: هيفايستوس","t":"learn","x":"وده من أقسى النكت في الميثولوجيا: لما الإله بيعمل حاجة لوحده، النتيجة بتكون ناقصة. الشكل هيفايستوس أعرج. ومشوه في رجليه. ودي حاجة مهمة جدا، وهنرجع لها في آخر الفصل. الإله الوحيد اللي شكله مش جميل، هو الإله اللي بيصنع أجمل الحاجات. الأدوات المطرقة، والسندان، والمنفاخ (اللي بينفخ فيه النار)."},{"i":"myth-m15","s":16,"h":"البطاقة الأساسية: هيفايستوس","t":"learn","x":"والورشة: بيت من برونز، في السماء، فيه منافيخ بتشتغل لوحدها. وفي الأرض، أشهر مكان ليه هو جزيرة ليمنوس."},{"i":"myth-m15","s":17,"h":"البطاقة الأساسية: هيفايستوس","t":"mc","x":"هيفايستوس ابن مين في رواية هسيود؟ ؟ ابن زيوس لوحده / ابن أفروديت وآريس / ابن أثينا / ابن هيرا لوحدها من غير زيوس . ابن هيرا لوحدها من غير زيوس"},{"i":"myth-m15","s":18,"h":"البطاقة الأساسية: هيفايستوس","t":"tf","x":"اسم فولكان هو أصل كلمة volcano . . صح"},{"i":"myth-m15","s":20,"h":"آريس: الإله اللي اتجرح في المعركة","t":"learn","x":"تعالى للحكاية اللي بتفضح آريس، وهي في الإلياذة، الكتاب الخامس. الخلفية ديوميديس، بطل يوناني، بيحارب في طروادة. وأثينا بتحبه، وبتقف جنبه. وآريس بيحارب في صف الطرواديين، وبيعمل مذبحة في اليونانيين. الخطة أثينا قررت توقف آريس. فعملت حاجة ذكية: لبست خوذة هاديس، خوذة الإخفاء، عشان آريس ما يشوفهاش."},{"i":"myth-m15","s":21,"h":"آريس: الإله اللي اتجرح في المعركة","t":"learn","x":"والنص بيقول : \" but Athene put on the cap of Hades, to the end that mighty Ares should not see her .\" يعني: أثينا لبست طاقية هاديس، عشان آريس الجبار ما يشوفهاش. وطلعت مع ديوميديس في العربية، وهي ماسكة اللجام. الضربة ديوميديس رشق الرمح في بطن آريس. والنص ملخص المشهد (الإلياذة ٥، من ٧٩٣ ل ٩٠٩) بيقول إن آريس زعق زعقة عالية جدا، وطلع لأوليمبوس."},{"i":"myth-m15","s":22,"h":"آريس: الإله اللي اتجرح في المعركة","t":"learn","x":"وهناك، زيوس، أبوه، قال له حاجة قاسية: إنت أكتر الآلهة كراهية عندي، لأنك بتحب الخناق والحرب. وبعدها طلب من بايون، طبيب الآلهة، إنه يداويه. يعني الإله اللي بيقتل البشر، لما اتجرح، راح لأبوه، وأبوه قال له: إنت السبب، وأنا مش طايقك. وده مش موقف بطولي، ده موقف مذل. وهوميروس عايزك تحس بالإذلال ده. وأفروديت كمان"},{"i":"myth-m15","s":23,"h":"آريس: الإله اللي اتجرح في المعركة","t":"learn","x":"في نفس الكتاب، ديوميديس جرح أفروديت في إيديها وهي بتحاول تنقذ ابنها إينياس. والمشهد في ترجمة كلاين عنوانه: \" Diomedes wounds Aphrodite \". وده معنى مهم: في الإلياذة، البشر بيجرحوا الآلهة. الحرب بتسوي الكل. وحتى إلهة الحب، بتسيل دم. الخلاصة عن آريس هو مش إله شرير بالمعنى الأخلاقي. هو إله الحرب، والحرب مش أخلاقية بطبيعتها. بس اليونان ما حبوهوش."},{"i":"myth-m15","s":24,"h":"آريس: الإله اللي اتجرح في المعركة","t":"learn","x":"وما بنوش له معابد كبيرة، وما عبدوهوش كتير. لأنهم كانوا بيعرفوا الحرب كويس، وكانوا بيكرهوها. وده فرق كبير بينه وبين أثينا. أثينا بتحمي المدينة، فالناس بتحبها. آريس بيخرب المدينة، فالناس بتخاف منه."},{"i":"myth-m15","s":25,"h":"آريس: الإله اللي اتجرح في المعركة","t":"mc","x":"إيه اللي لبسته أثينا عشان آريس ما يشوفهاش في الإلياذة ٥؟ ؟ طاقية هاديس / درع زيوس / خوذة آريس / عباية أرجوانية . طاقية هاديس"},{"i":"myth-m15","s":27,"h":"هيفايستوس: الإله اللي بيصنع","t":"learn","x":"المشهد الأول: السقوط في الإلياذة، الكتاب الأول، الآلهة متخانقين، وهيفايستوس بيحاول يهديهم. وبيقول لأمه هيرا كلام حكيم، وبعدها بيحكي حكاية عن نفسه، وهي من أقسى لحظات الإلياذة:"},{"i":"myth-m15","s":28,"h":"هيفايستوس: الإله اللي بيصنع","t":"learn","x":"\" On a time before this, when I was striving to save you, he caught me by the foot and hurled me from the heavenly threshold; the whole day long I was carried headlong and at sunset I fell in Lemnos, and but little life was in me. There the Sintian folk quickly tended me for my fall .\""},{"i":"myth-m15","s":29,"h":"هيفايستوس: الإله اللي بيصنع","t":"learn","x":"يعني: مرة قبل كده، وأنا بحاول أنقذك، مسكني من رجلي ورماني من عتبة السماء. طول النهار كنت متقذف، وعند الغروب وقعت في ليمنوس، وما كانش في غير شوية حياة. وهناك أهل سينتوس عالجوني بسرعة من وقوعتي. خد بالك من التفاصيل: مسكه من رجله. والرجل دي هي اللي بقيت عرجاء. ووقع في جزيرة ليمنوس، واللي عالجه ناس عاديين، مش آلهة. وده أول درس في شخصيته: هو اتعذب."},{"i":"myth-m15","s":30,"h":"هيفايستوس: الإله اللي بيصنع","t":"learn","x":"ومش من حد غريب، من أبوه. والتفصيلة الأهم: هو بيحكي الحكاية دي عشان يهدي خناقة. يعني الراجل اللي اتقذف من السما، بقى هو اللي بيقول للآلهة: اهدوا. اللي اتأذى هو اللي بيصنع السلام. المشهد التاني: الورشة في الإلياذة ١٨، ثيتيس، أم أخيل، بتروح لهيفايستوس تطلب منه سلاح لابنها. وبتلاقيه في ورشته، بيتعرق، وبيتحرك حوالين المنافيخ."},{"i":"myth-m15","s":31,"h":"هيفايستوس: الإله اللي بيصنع","t":"learn","x":"والنص بيقول : \" Him she found sweating with toil as he moved to and fro about his bellows in eager haste .\" يعني: لقيته بيتعرق من الشغل، وهو بيتحرك رايح جاي حوالين المنافيخ بلهفة. وبعدها التفصيلة اللي بتخلي المشهد خيال علمي: بيصنع عشرين حلة ( tripods ) ثلاثية القوايم، وكل واحدة ليها عجلات دهب، عشان تمشي لوحدها لمجلس الآلهة وترجع."},{"i":"myth-m15","s":32,"h":"هيفايستوس: الإله اللي بيصنع","t":"learn","x":"والنص بيقول : \" golden wheels had he set beneath the base of each that of themselves they might enter the gathering of the gods at his wish and again return to his house, a wonder to behold .\" يعني: حط عجلات دهب تحت قاعدة كل واحدة، عشان من نفسها تدخل مجلس الآلهة لما هو عايز، وترجع بيته تاني. حاجة تتشاف وتتعجب منها."},{"i":"myth-m15","s":33,"h":"هيفايستوس: الإله اللي بيصنع","t":"learn","x":"يعني أول روبوتات في الأدب الأوروبي مش في قصة خيال علمي حديثة، هي في الإلياذة. وهي مش سلاح، هي أثاث بيتمشى. المشهد التالت: الخدامات الدهب وأكتر من كده، عنده خدامات. مش بشر، تماثيل دهب. وبترجمة فاجلز : \" Handmaids ran to attend their master, all cast in gold but a match for living, breathing girls ."},{"i":"myth-m15","s":34,"h":"هيفايستوس: الإله اللي بيصنع","t":"learn","x":"Intelligence fills their hearts, voice and strength their frames .\" يعني: خدامات جريوا يخدموا سيدهم، كلهم مصبوبين من دهب، بس زيهم زي بنات حية بتتنفس. العقل ملي قلوبهم، والصوت والقوة ملي جسمهم. جملة \"العقل ملي قلوبهم\" دي هي المفتاح. مش مجرد آلات، دول كائنات ليها عقل. والصنعة هنا بقت خلق. وده الفرق بين هيفايستوس وأي حداد."},{"i":"myth-m15","s":35,"h":"هيفايستوس: الإله اللي بيصنع","t":"learn","x":"الحداد بيصنع حاجة، هيفايستوس بيصنع كائن. المشهد الرابع: الدرع وبعدها بيصنع درع أخيل. والدرع ده مش درع، ده عالم. عليه الأرض والسما والبحر، والنجوم، ومدينتين: واحدة في سلام، وواحدة في حرب، والحصاد، والرعي، والرقص، والنهر. والمشهد في الإلياذة ١٨، من ٤٦٨ ل ٦١٧، وعنوانه في ترجمة كلاين: \" Hephaestus forges Achilles' armour \"."},{"i":"myth-m15","s":36,"h":"هيفايستوس: الإله اللي بيصنع","t":"learn","x":"والفكرة: الإله اللي بيتقذف من السما، بيصنع درع عليه صورة العالم كله. يعني هو شاف العالم من فوق ومن تحت، فقدر يرسمه. المشهد الخامس: الشبكة في الأوديسة ٨، اللي خدناها في الفصل اللي فات، هيفايستوس عمل شبكة زي شباك العنكبوت، ومسك بيها مراته أفروديت وآريس. والفرق بين المشهدين: في الإلياذة هو بيصنع سلاح لحرب، وفي الأوديسة بيصنع فخ لخيانة."},{"i":"myth-m15","s":37,"h":"هيفايستوس: الإله اللي بيصنع","t":"learn","x":"نفس المهارة، ونيتين مختلفتين. وفي أوفيد، الميتامورفوزيس ٤، القصة موجودة كمان، وعنوانها في ترجمة كلاين: \" Leuconoë's story: Mars and Venus \"، من سطر ١٦٧ ل ١٨٩. يعني نفس الحكاية بتتنقل من اليوناني للاتيني، وبعدها للإنجليزي. وده بالظبط اللي اتكلمنا عنه في الفصل اللي فات: هيرميس بيوصل الحكاية."},{"i":"myth-m15","s":38,"h":"هيفايستوس: الإله اللي بيصنع","t":"mc","x":"إيه اللي صنعه هيفايستوس لأخيل في الإلياذة ١٨؟ ؟ رمح من دهب / شبكة من الحديد / خوذة بجناحين / درع عليه صورة العالم . درع عليه صورة العالم"},{"i":"myth-m15","s":39,"h":"هيفايستوس: الإله اللي بيصنع","t":"tf","x":"هيفايستوس رد على الخيانة بالقوة الجسدية. . غلط"},{"i":"myth-m15","s":41,"h":"الاتنين في قصة واحدة","t":"learn","x":"خلينا نربط الفصل ده بالفصل اللي فات. أفروديت مرات هيفايستوس، وحبيبة آريس. والجواز ده مش جواز حب، هو جواز بين الجمال والصنعة. واحد بيملك أجمل حاجة، والتاني بيصنع أجمل حاجة. وآريس هو عكس هيفايستوس تماما: وسيم، وقوي، وبيحب الحرب، ومش بيصنع حاجة. فأفروديت اختارت آريس. والاختيار ده مش حكم أخلاقي، هو اختيار شخصية: الرغبة بتحب القوة، مش المهارة."},{"i":"myth-m15","s":42,"h":"الاتنين في قصة واحدة","t":"learn","x":"وهيفايستوس رد مش بالعنف، بالصنعة. عمل شبكة. يعني رد على الخيانة بأداته، مش بأداة خصمه. وده أذكى رد في الميثولوجيا كلها. لو كان ضرب آريس، كان بقى زي آريس. بس هو عمل فخ، وخلى الآلهة كلها تتفرج وتضحك. الانتقام بالصنعة أقوى من الانتقام بالقوة."},{"i":"myth-m15","s":44,"h":"في روما: مارس وفولكان","t":"learn","x":"مارس مارس عند الرومان مش بس إله حرب. هو في الأصل إله زراعة كمان، وحامي الحقول. ومع الوقت بقى إله الحرب الرسمي، لأن روما كانت دولة حرب. وشهر مارس كان أول شهر في التقويم الروماني القديم، وهو بداية موسم الحرب والزراعة في نفس الوقت. وده مش مصادفة: نفس الشهر بيبدأ فيه الحرث والقتال."},{"i":"myth-m15","s":45,"h":"في روما: مارس وفولكان","t":"learn","x":"ومعبد مارس ألتر ( Mars Ultor )، يعني مارس المنتقم، اتدشن سنة ٢ قبل الميلاد، في منتدى أغسطس. والمصادر بتقول إن أغسطس نذر المعبد قبل معركة فيليبي سنة ٤٢ قبل الميلاد، اللي انتقم فيها لقتل قيصر، اللي كان أبوه بالتبني. يعني مارس بقى إله انتقام سياسي. والحرب بقت أداة دولة، مش مجرد غضب. فولكان"},{"i":"myth-m15","s":46,"h":"في روما: مارس وفولكان","t":"learn","x":"فولكان عند الرومان إله النار، وخصوصا النار المدمرة: البراكين والحرائق. والموسوعة البريطانية بتقول إن عبادته قديمة جدا، وكان ليه كاهن خاص اسمه flamen . وأهم عيد ليه هو الفولكاناليا ( Volcanalia )، وكان بيتحتفل بيه في ٢٣ أغسطس، وفيه كان رب البيت بيرمي سمك صغير في النار. والحكمة من الطقس مش معروفة بالظبط. وكانوا بيدعوا بيه عشان يمنعوا الحرائق."},{"i":"myth-m15","s":47,"h":"في روما: مارس وفولكان","t":"learn","x":"ومن ألقابه Quietus و Mulciber ، يعني \"الهادي\" و\"ملطف النار\". يعني الإله اللي بيحرق، بيدعوه إنه ما يحرقش. وحاجة مهمة: لأن فولكان إله نار مدمرة، معابده كانت بتتحط بره المدينة. الإله الخطير بيتحط على الحدود، مش في النص."},{"i":"myth-m15","s":48,"h":"في روما: مارس وفولكان","t":"mc","x":"إيه هي الفولكاناليا؟ ؟ عيد فولكان، وكان في ٢٣ أغسطس / عيد مارس في مارس / مهرجان للأموات / عيد الحصاد . عيد فولكان، وكان في ٢٣ أغسطس"},{"i":"myth-m15","s":49,"h":"في روما: مارس وفولكان","t":"tf","x":"معابد فولكان كانت بتتحط بره المدينة. . صح"},{"i":"myth-m15","s":51,"h":"الأسطورة في الشعر الإنجليزي","t":"learn","x":"الجزء ده فيه مفاجأة: آريس شبه غايب عن الشعر الإنجليزي، وهيفايستوس حاضر بقوة. والسبب في رأيي (وده تحليلي، مش حقيقة نصية) إن الشعراء الإنجليز بيفضلوا الصانع على المدمر. الحرب بتتكتب، بس الصنعة هي اللي بتلهم. الشاهد الأول: جون ميلتون، الفردوس المفقود، الكتاب الأول ميلتون بيحكي عن الآلهة الوثنية اللي بقت شياطين."},{"i":"myth-m15","s":52,"h":"الأسطورة في الشعر الإنجليزي","t":"learn","x":"ولما يوصل لهيفايستوس، بيسميه باسمه اللاتيني، ويحكي حكاية السقوط : \" Nor was his name unheard or unador'd In ancient Greece and in Ausonian land. Men call'd him Mulciber, and how he fell From Heav'n, they fabl'd, thrown by angry Jove Sheer o're the crystal battlements. From morn To noon he fell, from noon to dewy eve ,"},{"i":"myth-m15","s":53,"h":"الأسطورة في الشعر الإنجليزي","t":"learn","x":"A summer's day, and with the setting sun Dropp'd from the zenith like a falling star On Lemnos th' Aegaean isle: thus they relate, Erring .\" والترجمة: واسمه ما كانش مجهول ولا غير محبوب في اليونان القديمة وفي أرض أوسونيا. الناس سموه مولسيبر، وحكوا إنه وقع من السما، مطرود من جوبيتر الغضبان، من فوق الأسوار الكريستالية."},{"i":"myth-m15","s":54,"h":"الأسطورة في الشعر الإنجليزي","t":"learn","x":"من الصبح للضهر وقع، ومن الضهر لغروب الندى، يوم صيف كامل، ومع غروب الشمس سقط من القمة زي شهاب، على ليمنوس الجزيرة الإيجية. كده بيحكوا، وهم غلطانين. الشرح: خد بالك من التفاصيل. - أولا، ميلتون بياخد حكاية هيفايستوس من الإلياذة (اللي وقع يوم كامل في ليمنوس)، ويحولها لسقوط شيطان من السما."},{"i":"myth-m15","s":55,"h":"الأسطورة في الشعر الإنجليزي","t":"learn","x":"- ثانيا، الجملة الأخيرة هي الأهم: \" thus they relate, Erring \" يعني \"كده بيحكوا، وهم غلطانين\". ميلتون بيصحح الأسطورة: هو ما وقعش من أوليمبوس، هو وقع مع الشياطين المتمردين. الوثنية بقت خطأ، والمسيحية بقت الحقيقة. - وثالثا، \" Mulciber \" هو اللقب اللاتيني اللي معناه ملطف النار."},{"i":"myth-m15","s":56,"h":"الأسطورة في الشعر الإنجليزي","t":"learn","x":"يعني ميلتون بيستخدم اللقب اللي الرومان كانوا بيدعوا بيه عشان يمنعوا الحرائق، ويحطه على شيطان. وده مثال كامل على \"الأسطورة في الشعر الإنجليزي\": نفس الحكاية، بمعنى جديد، وبإدانة في آخرها. الشاهد التاني: هوميروس بالإنجليزي، ترجمة فاجلز الجزء بتاع الخدامات الدهب اللي قريته فوق، من ترجمة روبرت فاجلز للإلياذة."},{"i":"myth-m15","s":57,"h":"الأسطورة في الشعر الإنجليزي","t":"learn","x":"والترجمة دي مش نص إنجليزي أصلي، هي هوميروس بالإنجليزي. بس لازمة، لأنها بتوريك إزاي المترجم بيخلي الإله يتكلم إنجليزي حديث. وجملة \" Intelligence fills their hearts \" هي اختيار مترجم، مش في اليوناني بالحرف. واليوناني بيقول إن فيهم \"نوس\" (عقل) و\"صوت\" و\"قوة\". يعني المترجم اختار كلمة Intelligence ، وهي كلمة بتحمل كل حمولة القرن العشرين عن الذكاء الاصطناعي."},{"i":"myth-m15","s":58,"h":"الأسطورة في الشعر الإنجليزي","t":"learn","x":"وده مثال حلو على إن الترجمة بتغير المعنى بشوية. وده بيوصلنا لهيرميس تاني: المترجم هو هيرميس. بياخد حكاية من لغة، ويديها للغة تانية، وبيفقد حاجة، وبيكسب حاجة. وليه آريس غايب؟ آريس موجود في الشعر الإنجليزي، بس غالبا كصورة، مش كشخصية: صورة الحرب، والدمار، والغضب. وهيفايستوس/فولكان موجود أكتر، لأنه بيشتغل: بيصنع، وبيبني، وبيرمم."},{"i":"myth-m15","s":59,"h":"الأسطورة في الشعر الإنجليزي","t":"learn","x":"والشعراء بيحبوا الصانع، لأنه شبيههم. الشاعر بيصنع حاجة من مادة خام، زي الحداد بالظبط."},{"i":"myth-m15","s":60,"h":"الأسطورة في الشعر الإنجليزي","t":"mc","x":"إيه الاسم اللي سمى بيه ميلتون هيفايستوس في الفردوس المفقود؟ ؟ باخوس / بلوتو / ساتورن / مولسيبر ( Mulciber ) . مولسيبر ( Mulciber )"},{"i":"myth-m15","s":61,"h":"الأسطورة في الشعر الإنجليزي","t":"tf","x":"ميلتون قدم حكاية سقوط هيفايستوس كأنها حقيقة. . غلط"},{"i":"myth-m15","s":63,"h":"إزاي تعرفهم في قصيدة","t":"learn","x":"كلمات آريس/مارس الأسماء: Ares, Mars, Mars Ultor ، Areopagus . الحرب: war, battle, strife, slaughter, blood, spear, helm, shield . الغضب: rage, wrath, fury, bellow, roar, mad . الحديد والنار: iron, bronze, fire, brand . الحيوانات: dog, vulture, boar . كلمات هيفايستوس/فولكان الأسماء: Hephaestus, Vulcan, Mulciber, Lemnos ."},{"i":"myth-m15","s":64,"h":"إزاي تعرفهم في قصيدة","t":"learn","x":"الصنعة: forge, anvil, hammer, bellows, craft, skill, art . النار: fire, flame, furnace, ember . الأشياء المصنوعة: shield, armour, net, chain, wheel, gold . العجز: lame, cripple, halt, fall . والفرق بينهم في سطر واحد آريس بيدمر بإيده. هيفايستوس بيصنع بإيده. الاتنين إيدين، والنتيجة عكس."},{"i":"myth-m15","s":66,"h":"سؤال مفتوح","t":"learn","x":"فيه سؤال في الفصل، ومش هجاوب عليه. اليونان كرهوا آريس، وحبوا هيفايستوس. بس الاتنين أولاد زيوس وهيرا، والاتنين آلهة أوليمبية معترف بها. السؤال: ليه المجتمع بيكره إله الحرب، وبيحترم إله الصنعة، مع إنه محتاج الاتنين؟ فيه قراءة بتقول: لأن الحرب بتوجع الناس، والصنعة بتديهم حاجات. اللي بيديك حاجة بيبقى محبوب، واللي بياخد منك بيبقى مكروه."},{"i":"myth-m15","s":67,"h":"سؤال مفتوح","t":"learn","x":"وفيه قراءة تانية بتقول: لأن الحرب في الميثولوجيا مش شغل الآلهة الكبار. الحرب شغل البشر، والآلهة بتتفرج. فلما إله يتخصص في حرب البشر، بيبقى أقل شأن. والاتنين بيقروا نفس النص. وهنشتغل على ده في الفصل ١٢٠، أركيتايب يونج، لأن آريس وهيفايستوس بقوا نماذج في اللاشعور الجمعي: المحارب والحرفي."},{"i":"myth-m15","s":69,"h":"أخطاء شائعة","t":"learn","x":"آريس إله الشر. لأ. هو إله الحرب، والحرب مش أخلاقية. الشر في الميثولوجيا مش وظيفة إله. آريس أقوى من أثينا. لأ. أثينا غلبته بالعقل، وديوميديس جرحه بمساعدتها. هيفايستوس ابن زيوس وهيرا. في نسخة هسيود، هو ابن هيرا لوحدها، من غير زيوس. هيفايستوس إله النار بس. لأ. هو إله الصنعة والحرف والآلات، والنار أداته. فولكان زي هيفايستوس بالظبط."},{"i":"myth-m15","s":70,"h":"أخطاء شائعة","t":"learn","x":"قريب، بس فولكان في الأصل إله نار مدمرة، وعبادته كانت لدفع الحرائق، ومعابده كانت بره المدينة."},{"i":"myth-m15","s":71,"h":"أخطاء شائعة","t":"tf","x":"آريس أقوى من أثينا في الإلياذة. . غلط"},{"i":"myth-m15","s":73,"h":"كلمات هتقع لك في الشعر","t":"learn","x":"strife — نزاع، خصام. slaughter — مذبحة. wrath — غضب شديد. to bellow — يزعق بصوت عالي. helm — خوذة. spear — رمح. to forge — يصنع بالحدادة، وبمعنى يزور كمان. forge (اسم) — ورشة حدادة. anvil — سندان. bellows — منفاخ. craft — صنعة، ومهارة، وخداع كمان. lame — أعرج. to hurl — يقذف بقوة. threshold — عتبة. net — شبكة. ember — جمرة."},{"i":"myth-m15","s":75,"h":"خريطة الفصول الجاية","t":"learn","x":"M 16: هاديس/بلوتو، إله العالم التاني. وهنرجع لقصة هيفايستوس والشبكة من زاوية تانية. M 18: ديونيسوس/باكوس، والإله اللي بيتولد مرتين. M 22: أبولو ودفني، وقصص التحول. M 28: فيليمون وباوسيس. M 31: فينوس وأدونيس، وفيه آريس كمان. M 51 و52: هرقل، وهنشوف فيه آريس في الخلفية. M 62: هيبوليتوس وفيدرا، وفيه أرتميس وأفروديت. M 110: شكسبير والأسطورة."},{"i":"myth-m15","s":76,"h":"خريطة الفصول الجاية","t":"learn","x":"M 111: ميلتون والتوفيق بين الكلاسيكي والمسيحي. وهنا هنقرا مولسيبر بالتفصيل."},{"i":"myth-m15","s":78,"h":"ملخص في عشر جمل","t":"learn","x":"آريس إله الحرب، وهيفايستوس إله الصنعة، والاتنين أولاد زيوس وهيرا في التقليد الأساسي. هوميروس بينادي آريس \"بلية البشر\"، وده مش لقب فخر. في الإلياذة ٥، أثينا لبست خوذة هاديس، وساعدت ديوميديس يجرح آريس في بطنه. آريس طلع لأوليمبوس، وزيوس قال له إنه أكتر الآلهة كراهية عنده."},{"i":"myth-m15","s":79,"h":"ملخص في عشر جمل","t":"learn","x":"هيفايستوس أعرج، وفي الإلياذة ١ بيحكي إن زيوس مسكه من رجله ورماه من عتبة السماء، ووقع في ليمنوس. هسيود بيقول إن هيرا خلفته لوحدها من غير زيوس، لأنها كانت غضبانة. ورشته فيها منافيخ، وعشرين حلة بعجلات دهب بتمشي لوحدها، وخدامات دهب فيهم عقل وصوت. صنع درع أخيل اللي عليه صورة العالم، وصنع الشبكة اللي مسك بيها أفروديت وآريس."},{"i":"myth-m15","s":80,"h":"ملخص في عشر جمل","t":"learn","x":"في روما، مارس بقى إله انتقام سياسي بمعبد مارس ألتر سنة ٢ قبل الميلاد، وفولكان إله نار مدمرة بعيد فولكاناليا في ٢٣ أغسطس. في الشعر الإنجليزي، ميلتون سمى هيفايستوس \"مولسيبر\" وحكى سقوطه، وبعدها صحح الأسطورة بجملة \" thus they relate, Erring \"."},{"i":"myth-m15","s":82,"h":"مهمتك قبل الفصل الجاي","t":"learn","x":"اقرا جملة ميلتون \" thus they relate, Erring \". مين اللي \"غلطان\" في رأيه؟ الوثنيين ولا الشياطين؟ اكتب جملة واحدة: إيه الفرق بين اللي بيدمر واللي بيصنع، من تجربتك؟ فكر في حاجة في بيتك مصنوعة بإيد حد، مش مشتراة. مين اللي صنعها؟ وليه الحاجة دي ليها قيمة مختلفة؟"},{"i":"myth-m15","s":84,"h":"خاتمة","t":"learn","x":"آريس وهيفايستوس هما وشين لعملة واحدة: إيد الإنسان. واحدة بتكسر، وواحدة بتبني. واليونان اختاروا يبجلوا اللي بيبني، ويخافوا من اللي بيكسر. والشعر الإنجليزي ورث الاختيار ده، وخلى هيفايستوس/فولكان إله بيشتغل في الخلفية، وبيفضل حاضر في كل قصيدة عن الصنعة والفن."},{"i":"myth-m15","s":85,"h":"خاتمة","t":"learn","x":"وفي الفصل الجاي، هننزل تحت الأرض: هاديس، أو بلوتو، إله العالم التاني، وإله الأموات اللي مش بيحب يذكر اسمه. سلام يا عمر، وأشوفك في الفصل السادساشر."},{"i":"myth-m15","s":87,"h":"تذكر واكتب","t":"recall","x":"مين أم هيفايستوس، وإيه الغريب في ميلاده؟ . هيرا، وخلفته لوحدها من غير زيوس لأنها كانت غضبانة إنه خلف أثينا وحده. والميلاد الغريب ده أصل حكايته كلها."},{"i":"myth-m15","s":88,"h":"تذكر واكتب","t":"recall","x":"مين اللي سمى هيفايستوس مولسيبر، وإيه الجملة اللي صحح بيها الأسطورة؟ . ميلتون، والجملة \" thus they relate , / Erring \"، ومعناها إن الوثنيين بيحكوا السقوط وهم غلطانين."},{"i":"myth-m15","s":89,"h":"تذكر واكتب","t":"write","x":"قارن في ٣-٤ جمل بين سقوط هيفايستوس عند هوميروس وسقوطه عند ميلتون في الفردوس المفقود. . عند هوميروس الإله بيقع يوم كامل من أوليمبوس على ليمنوس، والسقوط حكاية جسدية، والضحك بعدها بيرجع السلام بين الآلهة. ميلتون بياخد نفس التفصيل ويحوله لسقوط شيطان من السما، وبيختم ب \" thus they relate , / Erring \"، فالحكاية القديمة بقت خطأ محترما. يبدو أن ميلتون بيعمد الأسطورة بالطريقة اللي اتكلمنا عنها قبل كده، بس هنا الإدانة في آخر السطر، مش في أوله. والنتيجة إن الشاعرين بيعملوا نفس الحاجة تقريبا: بياخدوا من الأسطورة اللي تناسب لحظتهم، ويسيبوا الباقي."},{"i":"myth-m15","s":90,"h":"تذكر واكتب","t":"write","x":"قارن في ٣-٤ جمل بين حضور آريس وحضور هيفايستوس في الشعر الإنجليزي، وفسر الفرق. . آريس بيظهر غالبا كصورة، زي الحرب والدمار والغضب، ونادرا كشخصية ليها مشهد وحوار. هيفايستوس حاضر أكتر، لأن ميلتون مثلا بيديه أسطرا كاملة ويسميه مولسيبر ويحكي سقوطه، والفاجلز بيترجم أدواته الحية بجملة \" Intelligence fills their hearts \". يمكن القول إن الشعراء بيفضلوا الصانع على المدمر، لأن الصانع شبيههم: بيحول مادة خام لحاجة ليها شكل. والفرق ده في الحضور نفسه دليل على إن الاختيار جمالي، مش محايد."},{"i":"myth-m16","s":1,"h":"إحنا فين في الحكاية","t":"learn","x":"في الفصل ١٥ خدنا آريس وهيفايستوس: الحرب والصنعة. والنهارده هنقابل الإله اللي بيقعد في نص العالم، تحت الأرض: هاديس، أو بلوتو عند الرومان. وهو مختلف عن كل الآلهة اللي خدناها، لسبب واحد بسيط: هو الإله الوحيد اللي مجاله هو الحاجة اللي محدش بيرجع منها. زيوس بيحكم السما. بوسيدون بيحكم البحر."},{"i":"myth-m16","s":2,"h":"إحنا فين في الحكاية","t":"learn","x":"هاديس بيحكم المكان اللي كل واحد فينا رايحه، ومحدش رجع منه يقول إيه اللي فيه. وعشان كده، اليونان عملوا معاه حاجة غريبة جدا: ما كانوش بيحبوا ينطقوا اسمه. اسمه هاديس، ومعناه على الأرجح \"اللي مش بيتشاف\". وسموه بلوتو، يعني \"الغني\"، لأن الدهب والفضة والمعادن كلها بتطلع من تحت الأرض، واللي تحت الأرض هو ملكه."},{"i":"myth-m16","s":3,"h":"إحنا فين في الحكاية","t":"learn","x":"يعني بدل ما يقولوا \"هاديس\"، كانوا يقولوا \"الغني\". وده أسلوب أدب مع القوة اللي بتخيف. زي ما بنقول عن حد خايفين منه \"الست الكبيرة\" بدل اسمه. وهو كمان شقيق زيوس وبوسيدون. تلاتة أخوات قسموا العالم بينهم، وهاديس خد النصيب اللي محدش عايزه. وهنشوف النص اللي بيقول ده بالنص."},{"i":"myth-m16","s":4,"h":"إحنا فين في الحكاية","t":"mc","x":"اسم هاديس معناه على الأرجح إيه؟ ؟ الغني / سيد الظلام / اللي مش بيتشاف / الحاكم الأعلى . اللي مش بيتشاف"},{"i":"myth-m16","s":5,"h":"إحنا فين في الحكاية","t":"tf","x":"بلوتو لقب معناه \"الغني\". . صح"},{"i":"myth-m16","s":7,"h":"البطاقة الأساسية","t":"learn","x":"الاسم هاديس باليوناني، وبلوتو ( Pluto ) باللاتيني. واسم هاديس في اليوناني Haidēs ، ومعناه على الأرجح \"اللي مش بيتشاف\"، من السابقة a- يعني \"بدون\"، ومن idein يعني \"يشوف\". قاموس أصل الكلمات بيقول ده بالنص، وبيضيف حاجة مهمة: أصل الاسم نفسه مش معروف، والتفسير ده احتمال مش يقين. وده فرق مهم في المنهج: لما المصدر يقول \"احتمال\"، إحنا ننقل \"احتمال\"، مش \"حقيقة\"."},{"i":"myth-m16","s":8,"h":"البطاقة الأساسية","t":"learn","x":"وبلوتو جاي من الكلمة اليونانية Ploutōn ، يعني \"إله الغنى\"، من ploutos يعني \"غنى وثروة\". وقاموس أصل الكلمات بيقول إن الاسم كان اسم بديل أو لقب لهاديس في وظيفته كإله للثروة، لأن المعادن النفيسة والجواهر بتطلع من تحت الأرض، واللي تحت الأرض ملكه. يعني اللقب مش عشوائي: هو وصف اقتصادي دقيق. اللي بيملك باطن الأرض، بيملك الثروة. العيلة أبوه كرونوس، وأمه ريا."},{"i":"myth-m16","s":9,"h":"البطاقة الأساسية","t":"learn","x":"وأخوته: زيوس، وبوسيدون، وهيرا، وديميتر، وهيستيا. ومراته: بيرسيفوني، بنت ديميتر، يعني بنت أخته. وعند اليونان ده مش مشكلة، لأن الآلهة مالهمش نظام قرابة زي البشر. وده اللي هيخلي العيلة كلها في مشكلة، لأن أم البنت مش موافقة. الأدوات خوذة الظلام. ودي أهم أداة عنده، وهي اللي بتخليه \"اللي مش بيتشاف\" بالمعنى الحرفي."},{"i":"myth-m16","s":10,"h":"البطاقة الأساسية","t":"learn","x":"والصورة في أبولودوروس، المكتبة ١.٢.١، بترجمة فريزر : \" And the Cyclopes then gave Zeus thunder and lightning and a thunderbolt, and on Pluto they bestowed a helmet and on Poseidon a trident .\" يعني: والسيكلوبس إدوا زيوس الرعد والبرق والصاعقة، وأدوا بلوتو خوذة، وبوسيدون رمح ثلاثي."},{"i":"myth-m16","s":11,"h":"البطاقة الأساسية","t":"learn","x":"وخد بالك من الحاجة الحلوة: نفس الخوذة دي هي اللي لبستها أثينا في الفصل اللي فات عشان تخبي نفسها عن آريس. يعني أداة هاديس بقت أداة أثينا. الأسطورة بتقترض من بعضها. والصورة التقليدية في الفن: راجل ناضج بلحية، ماسك عصاية أو مفتاح، وأحيانا واقف جنبه كلب الحراسة. وكلب الحراسة ده اسمه سيربيروس، وهو موجود في الفصل السادس مع جغرافيا العالم التاني."},{"i":"myth-m16","s":12,"h":"البطاقة الأساسية","t":"learn","x":"الشخصية هاديس مش شرير. ودي أهم نقطة في الفصل، وهنرجع لها في الآخر. هو إله صارم، ومحايد، وبيحكم قانون مش بيقبل استثناءات. ومابيخدعش، ومابيظلمش، ومابيرجعش في كلامه. والفرق بينه وبين الشيطان في الديانات التانية كبير: هاديس مش بيعاقب الناس. هو بس بيستقبلهم. العقاب في الميثولوجيا اليونانية بيحصل في مكان تاني جوه العالم التاني، ومش هو اللي بينفذه."},{"i":"myth-m16","s":13,"h":"البطاقة الأساسية","t":"tf","x":"هاديس إله شرير بيعاقب الناس. . غلط"},{"i":"myth-m16","s":15,"h":"القرعة: إزاي خد العالم التاني","t":"learn","x":"الحكاية دي في الإلياذة، الكتاب الخامس عشر، سطر ١٨٤ لحد ١٩٥، وهي بوسيدون بيتكلم. الخلفية الآلهة اتخانقوا، وبوسيدون زعلان من زيوس، وبيقول إنه مش أقل منه شأنا. وعشان يثبت كلامه، بيحكي حكاية القرعة. النص بترجمة موراي"},{"i":"myth-m16","s":16,"h":"القرعة: إزاي خد العالم التاني","t":"learn","x":"\" For three brethren are we, begotten of Cronos, and born of Rhea ,— Zeus, and myself, and the third is Hades, that is lord of the dead below. And in three-fold wise are all things divided, and unto each hath been apportioned his own domain. I verily, when the lots were shaken, won for my portion the grey sea to be my habitation for ever, and Hades"},{"i":"myth-m16","s":17,"h":"القرعة: إزاي خد العالم التاني","t":"learn","x":"won the murky darkness, while Zeus won the broad heaven amid the air and the clouds; but the earth and high Olympus remain yet common to us all .\""},{"i":"myth-m16","s":18,"h":"القرعة: إزاي خد العالم التاني","t":"learn","x":"والترجمة: إحنا تلات إخوة، من كرونوس، ومن ريا: زيوس، وأنا، والتالت هاديس، اللي هو سيد الموتى تحت. والأشياء اتقسمت تلات أقسام، ولكل واحد اتخصص مجاله. أنا، لما القرعة اتزغرطت، كسبت نصيبي: البحر الرمادي مسكن ليا للأبد. وهاديس كسب الظلام الدامس. وزيوس كسب السما الواسعة بين الهوا والسحاب. لكن الأرض وأوليمبوس العالي فضلوا مشتركين بيننا كلنا. الشرح"},{"i":"myth-m16","s":19,"h":"القرعة: إزاي خد العالم التاني","t":"learn","x":"خد بالك من تلات حاجات. أولا: هاديس ماختارش. هو خد اللي طلع في القرعة. ودي فكرة مهمة جدا: في الميثولوجيا اليونانية، حتى الآلهة بيخضعوا للقدر. زيوس نفسه بيخاف من القدر. ثانيا: النصيب اللي خده هو \"الظلام الدامس\". مش قصر، ولا كنز، ولا جيش. ظلام."},{"i":"myth-m16","s":20,"h":"القرعة: إزاي خد العالم التاني","t":"learn","x":"ثالثا: الأرض وأوليمبوس مشتركين. يعني هاديس ليه حق في الأرض، وده اللي بيفسر ليه المعادن والكنوز بتطلع من تحت الأرض، وليه هو إله الثروة كمان. ملكه بيبدأ من تحت رجلينا. والدرس: التقسيم عادل، بس مش متساوي في القيمة. واحد خد السما، وواحد خد البحر، وواحد خد الظلام. والعدل مش معناه إن كل واحد ياخد حاجة حلوة. العدل معناه إن كل واحد ياخد نصيبه بالقانون."},{"i":"myth-m16","s":21,"h":"القرعة: إزاي خد العالم التاني","t":"mc","x":"إيه اللي طلع لهاديس في القرعة؟ ؟ السما / البحر / العالم التاني، الظلام الدامس / الأرض كلها . العالم التاني، الظلام الدامس"},{"i":"myth-m16","s":23,"h":"الحكاية الكبيرة: خطف بيرسيفوني","t":"learn","x":"الحكاية دي في الترنيمة الهوميرية التانية، المخصصة لديميتر، وهي من أحلى النصوص اليونانية كلها. وبنقراها هنا من ناحية هاديس، وفي الفصل ٢١ هنقراها من ناحية ديميتر. البداية الترنيمة بتبدأ بالجملة دي، بترجمة Evelyn-White"},{"i":"myth-m16","s":24,"h":"الحكاية الكبيرة: خطف بيرسيفوني","t":"learn","x":"\" I begin to sing of rich-haired Demeter, awful goddess — of her and her trim-ankled daughter whom Aidoneus rapt away, given to him by all-seeing Zeus the loud-thunderer .\" والترجمة: أبدأ أغني لديميتر ذات الشعر الغزير، الإلهة المهيبة، عنها وعن بنتها الجميلة الكواحل، اللي خطفها أيدونيوس، بعد ما إداها له زيوس اللي بيشوف كل حاجة، الراعد بصوته العالي."},{"i":"myth-m16","s":25,"h":"الحكاية الكبيرة: خطف بيرسيفوني","t":"learn","x":"الشرح، وفيه تلات تفاصيل مهمة أولا: الاسم اللي مستخدم هنا هو أيدونيوس ( Aidoneus )، وهو اسم تاني لهاديس. يعني النص نفسه بيتجنب الاسم المباشر من أول سطر. ثانيا: الجملة فيها حاجة صادمة: \"بعد ما إداها له زيوس\". يعني هاديس ماخطفش لوحده، ده أخد موافقة أبو البنت. والأب هو زيوس، لأنه أبو بيرسيفوني من ديميتر."},{"i":"myth-m16","s":26,"h":"الحكاية الكبيرة: خطف بيرسيفوني","t":"learn","x":"ثالثا: والبنت مش عارفة حاجة. الأم مش عارفة حاجة. يعني الحكاية كلها مبنية على صفقة بين رجلين، من غير رأي البنت ولا رأي أمها. وده اللي هيولع الدنيا. الخطف بيرسيفوني كانت بتلعب وتقطف ورد في سهل، والأرض اتفتحت، وهاديس طلع بعربيته، وخدها. وديميتر سمعت صوتها، ولفت الدنيا تدور عليها، ومحدش قال لها حاجة. ولا إله، ولا بشر، ولا طير."},{"i":"myth-m16","s":27,"h":"الحكاية الكبيرة: خطف بيرسيفوني","t":"mc","x":"حسب أول سطر في الترنيمة التانية، مين إدى بيرسيفوني لهاديس؟ ؟ زيوس / ديميتر / بوسيدون / هيرميس . زيوس"},{"i":"myth-m16","s":28,"h":"الحكاية الكبيرة: خطف بيرسيفوني","t":"learn","x":"وفي الآخر، هيليوس، الشمس، اللي بيشوف كل حاجة، قال لها الحقيقة: زيوس إداها لهاديس. الغضب ديميتر سابت أوليمبوس، ومشيت على الأرض في شكل ست عجوز، وقعدت عند بير في إليوسيس جنب بيت راجل اسمه كيليوس. وفي النص : \" In the guise of an old woman who has ceased from childbirth \", يعني في هيئة ست عجوز كبرت عن الولادة. ومنعت الزرع من إنه ينبت."},{"i":"myth-m16","s":29,"h":"الحكاية الكبيرة: خطف بيرسيفوني","t":"learn","x":"والنتيجة: مجاعة. البشر بيموتوا، والآلهة مش بتاخد قرابين، لأن مفيش حصاد. فزيوس اضطر يتصرف. والأرض مش بتنتج، والآلهة جعانة. التفاوض زيوس بعت هيرميس، وفي الترنيمة سطر ٣٣٥، النص بيقول إنه بعت \"لهاديس اللي ماسك العصاية الدهبية، قاتل أرغوس\" — يعني هيرميس بالظبط، اللي خدناه في الفصل ١٤."},{"i":"myth-m16","s":30,"h":"الحكاية الكبيرة: خطف بيرسيفوني","t":"learn","x":"والمهمة: يقنع هاديس بكلام لطيف إنه يسيب بيرسيفوني تطلع من عالم الظلام. خد بالك من الاختيار: زيوس بعت الرسول، مش بعت قوة. لأن الحرب مع هاديس مش ممكنة. اللي بيحكم الموتى مش بيتغلب، لأن كل اللي بيموت بيروح له. البذرة هاديس وافق. بس قبل ما تسيب، إداها حاجة: بذرة رمان."},{"i":"myth-m16","s":31,"h":"الحكاية الكبيرة: خطف بيرسيفوني","t":"learn","x":"والنص بيقول، في سطر ٣٧٠ لحد ٣٧٤: بيرسيفوني قامت فرحانة، وهاديس في السر إداها بذرة رمان تأكلها. والبذرة دي هي الفخ. لأن اللي بياكل في عالم الموتى، بيبقى مربوط بيه. وده تفصيل صغير، لكنه أهم تفصيل في الحكاية. هاديس ماخدش البنت بالقوة في الآخر، خلاها تاخد حاجة بإيديها. وده ذكاء قانوني، مش عنف. الرجوع"},{"i":"myth-m16","s":32,"h":"الحكاية الكبيرة: خطف بيرسيفوني","t":"learn","x":"بيرسيفوني طلعت لأمها. وديميتر سألتها: إنت أكلتي حاجة هناك؟ والبنت قالت الحقيقة. والنتيجة: اتفاق. هتقعد جزء من السنة مع جوزها في العالم التاني، وجزء مع أمها. وده تفسير الأسطورة للفصول: وقت اللي البنت تحت الأرض، الزرع بيموت. ووقت اللي هي فوق، الزرع بيرجع."},{"i":"myth-m16","s":33,"h":"الحكاية الكبيرة: خطف بيرسيفوني","t":"learn","x":"والاتفاق ده هو أصل فكرة \"الموت والبعث\" في الميثولوجيا، وهي فكرة هنشوفها في الفصل ١٨ مع ديونيسوس. هيكاتي وفيه إلهة تالتة في الحكاية: هيكاتي، إلهة الطرق المتقاطعة والسحر. وفي الترنيمة، سطر ٤٣٨ لحد ٤٤٠: هيكاتي جات، وحضنت بيرسيفوني، ومن الوقت ده بقت مرافقتها."},{"i":"myth-m16","s":34,"h":"الحكاية الكبيرة: خطف بيرسيفوني","t":"learn","x":"يعني الحكاية مالهاش نهاية سعيدة ولا حزينة. نهايتها اتفاق، وكل واحد فيه خد حاجة: الأم خدت بنتها جزء من السنة، والجوز خدها جزء، والبنت بقت ملكة عالم، وهيكاتي كسبت صاحبة."},{"i":"myth-m16","s":35,"h":"الحكاية الكبيرة: خطف بيرسيفوني","t":"mc","x":"إيه اللي أكلته بيرسيفوني في العالم التاني؟ ؟ بذرة رمان / تفاحة دهب / عنب / لوتس . بذرة رمان"},{"i":"myth-m16","s":36,"h":"الحكاية الكبيرة: خطف بيرسيفوني","t":"tf","x":"الاتفاق النهائي: جزء من السنة مع الأم وجزء مع جوزها. . صح"},{"i":"myth-m16","s":38,"h":"ميادينه","t":"learn","x":"الأول: الموت ده مجاله الأساسي، وأي كلام عن الموت في الشعر الإنجليزي بيرجع له. وهو مش بيعاقب. هو بيستقبل. والفرق ده مهم: في الميثولوجيا اليونانية، الموت مش عقوبة. الموت قانون. التاني: الثروة كل حاجة تحت الأرض: المعادن، والجواهر، والكنوز، وحتى بذور الزرع اللي بتتحط في الأرض عشان تنبت. وده اللي خلى اسمه التاني \"بلوتو\"، يعني الغني."},{"i":"myth-m16","s":39,"h":"ميادينه","t":"learn","x":"والفلوس كلمة ليها علاقة قديمة بالموت في لغات كتير: \"اللي تحت الأرض\" هو اللي بيملك القيمة. ومثال قريب: كلمة capital في اللاتيني جاية من caput ، يعني رأس، ومنها \"راس المال\". يعني الثروة دايما ليها صورة مادية، وحاجة مدفونة. التالت: الحدود اللي مش بتتعدى هاديس هو حاكم الحد اللي مفيش منه رجوع."},{"i":"myth-m16","s":40,"h":"ميادينه","t":"learn","x":"وفي الفصل السادس خدنا جغرافيا العالم التاني: النهر، والمركب، والبوابة، والكلب. وهنا نضيف المعنى: كل حد في العالم التاني ليه وظيفة، وهاديس هو اللي بيضمن إن الحد شغال. والاستثناءات قليلة جدا، وأشهرها أورفيوس، وهنشوفها في الفصل ٣٣. الرابع: القسم من ألقابه إنه \"زيوس العالم السفلي\"، يعني هو المرجع في القسم اللي بيتحلف بيه."},{"i":"myth-m16","s":41,"h":"ميادينه","t":"learn","x":"واللي بيقسم بيه وبيحن، بيدفع. وده مش تعبير مجازي في الميثولوجيا، ده قانون."},{"i":"myth-m16","s":43,"h":"الأوديسة ١١: العالم التاني من ناحية الزائر","t":"learn","x":"في الأوديسة، الكتاب الحداشر، أوديسيوس بينزل للعالم التاني وهو حي. وده مش مسموح، لكنه بيعمله. الطقس بيحفر حفرة، وبيصب فيها لبن وعسل وخمر ومية ودقيق، وبيقدم قرابين، وبيستدعي أرواح الموتى. والأرواح بتيجي. بس مش بتتكلم قبل ما تشرب دم. فبيقف بالسيف مصلت، وبيخلي الأرواح بعيدة عن الدم لحد ما يتكلم معاه اللي هو عايزه. النص"},{"i":"myth-m16","s":44,"h":"الأوديسة ١١: العالم التاني من ناحية الزائر","t":"learn","x":"وفي ترجمة بوتشر ولانج، تيريسياس بيقول له \" Go back from the trench, and hold off thy sharp sword, that I may drink the blood and tell thee sooth .\" يعني: ابعد عن الحفرة، وابعد سيفك الحاد، عشان أشرب الدم وأقول لك الحقيقة."},{"i":"myth-m16","s":45,"h":"الأوديسة ١١: العالم التاني من ناحية الزائر","t":"learn","x":"الشرح: في المشهد ده، الدم هو وسيلة الكلام. الأرواح بتحتاج حاجة من عالم الأحياء عشان تقدر تتكلم. يعني حتى الموتى محتاجين حاجة من الحياة. ودي صورة قوية جدا، والشعراء الإنجليز استخدموها كتير بعدين. وليه المشهد مهم للشعر؟ لأنه بيحول الموت من فكرة لمكان. والمكان بيبقى مشهد. والمشهد بيبقى قصيدة."},{"i":"myth-m16","s":46,"h":"الأوديسة ١١: العالم التاني من ناحية الزائر","t":"learn","x":"وأوديسيوس هنا مش بطل شجاع، هو راجل خايف واقف بسيفه في إيده، وبيحاول يسمع حاجة من اللي ماتوا. وده أقرب حاجة لشعور أي حد فقد حد."},{"i":"myth-m16","s":47,"h":"الأوديسة ١١: العالم التاني من ناحية الزائر","t":"mc","x":"في الأوديسة ١١، الأرواح محتاجة إيه عشان تتكلم؟ ؟ تشرب الدم / تاخد خمر وبس / تسمع غنا / تلمس الأرض . تشرب الدم"},{"i":"myth-m16","s":49,"h":"في روما: بلوتو","t":"learn","x":"الرومان سموه بلوتو ( Pluto )، وخدوا الاسم من اليوناني مباشرة، زي ما قاموس أصل الكلمات بيقول : \" Roman god of the underworld, from Latin Pluto, Pluton, from Greek Ploutōn \". وكان ليهم اسم تاني: ديس باتر ( Dis Pater )، ومعناه حرفيا \"الأب الغني\"، وكان في الأصل مرتبط بالأرض الزراعية والثروة المعدنية، وبعدها اتوحد مع بلوتو وأوركوس."},{"i":"myth-m16","s":50,"h":"في روما: بلوتو","t":"learn","x":"والرومان كان عندهم طقس اسمه \"ليكتيسترنيوم\" ( lectisternium )، وهو وليمة بتتقدم للآلهة، بمعنى إنهم بيفرشوا كنبة، ويحطوا عليها تمثال الإله، ويحطوا قدامها أكل، كأنهم بيعزموه على العشا. والفكرة دي عجيبة: بدل ما تقدم قرابين محروقة، بتقعد الإله على السفرة. وده بيوريك إن العلاقة مع الآلهة في روما كانت قانونية واجتماعية أكتر منها خوفا."},{"i":"myth-m16","s":51,"h":"في روما: بلوتو","t":"learn","x":"ومشان هاديس بالذات، الفكرة دي مهمة: لما تخاف من حاجة، بتعزمها. وده أسلوب بشري قديم جدا."},{"i":"myth-m16","s":52,"h":"في روما: بلوتو","t":"tf","x":"الرومان سموا هاديس بلوتو، وسموه كمان ديس باتر. . صح"},{"i":"myth-m16","s":54,"h":"الأسطورة في الشعر الإنجليزي","t":"learn","x":"هنا المفاجأة التانية في الكورس: هاديس شبه غايب عن الشعر الإنجليزي كشخصية. اللي حاضر هو بلوتو، وبرسيفوني، وديميتر. ليه؟ لأن هاديس مش بيعمل حاجة. هو بيستقبل. والشخصية اللي مابتعملش حاجة صعب تبقى بطل قصيدة. واللي بيعمل حاجة في الحكاية هي البنت، والأم، والجوز. والقصيدة بتختار اللي بيتحرك."},{"i":"myth-m16","s":55,"h":"الأسطورة في الشعر الإنجليزي","t":"learn","x":"وده تحليلي، مش حقيقة نصية، بس بيتفق مع اللي شفناه في الفصول اللي فاتت: الشعراء بيختاروا الشخصية اللي عندها صراع. الشاهد: سوينبرن، حديقة برسيربين القصيدة اسمها \" The Garden of Proserpine \"، ل الجيرنون تشارلز سوينبرن، شاعر إنجليزي من العصر الفيكتوري. وبتفتح بالسطر ده \" Here, where the world is quiet ;\" والترجمة: هنا، حيث العالم ساكت."},{"i":"myth-m16","s":56,"h":"الأسطورة في الشعر الإنجليزي","t":"learn","x":"الشرح: السطر ده لوحده بيقول كل حاجة. حديقة برسيربين مش مكان رعب، هي مكان سكون. مفيش صراخ، مفيش عذاب، مفيش نار. سكوت. وده فرق كبير بين صورة العالم التاني عند اليونان، وصورته في الشعر الفيكتوري. عند اليونان: ظلام وخفافيش ودم. عند سوينبرن: هدوء."},{"i":"myth-m16","s":57,"h":"الأسطورة في الشعر الإنجليزي","t":"learn","x":"وملحوظة أمانة: أنا راجعت السطر الأول من الصفحة واتأكدت منه، لكن ما قريتش القصيدة كلها سطر بسطر، فمش هأحللها كلها. اللي أقدر أقوله إن السطر الأول بيحط القصيدة في مقام الهدوء، مش في مقام العذاب. والنمط العام الشعر الإنجليزي بيدخل على هاديس من بابين: باب برسيربين (البنت اللي اتخطفت)، وباب بلوتو كصورة للثرية والعمق."},{"i":"myth-m16","s":58,"h":"الأسطورة في الشعر الإنجليزي","t":"learn","x":"وباب تالت: الموت كفكرة، من غير أسماء. ولما الشاعر بيقول \" death \" من غير اسم إله، هو برضه بيتكلم عن هاديس، بس بطريقة غير مباشرة. وده درس في التحليل: مش كل إشارة أسطورية بتبقى باسم. أحيانا الإشارة بتبقى في الوظيفة."},{"i":"myth-m16","s":59,"h":"الأسطورة في الشعر الإنجليزي","t":"tf","x":"في \"حديقة برسيربين\" لسوينبرن، العالم التاني مكان سكون مش مكان رعب. . صح"},{"i":"myth-m16","s":61,"h":"إزاي تعرفه في قصيدة","t":"learn","x":"خمس مجموعات كلمات 1. الأسماء: Hades, Pluto, Dis, Aidoneus, Proserpine, Persephone, Cerberus . 2. المكان: underworld, realm, gloom, dark, deep, below, kingdom, gate, shore, river . 3. الموت: death, dead, shade, ghost, grave, tomb, sleep, rest . 4. الثروة: wealth, gold, treasure, mine, rich, hidden ."},{"i":"myth-m16","s":62,"h":"إزاي تعرفه في قصيدة","t":"learn","x":"5. الحد: threshold, boundary, key, lock, return, back, once . ولو لقيت تلاتة من دول، احتمال كبير إنك قدام هاديس أو عالمه. والفرق عن الآلهة اللي فاتوا: كلمات زيوس فيها السلطة والصاعقة. كلمات بوسيدون فيها البحر. كلمات أثينا فيها الدرع والنول. كلمات هيرميس فيها الجناح والطريق. وكلمات هاديس فيها الظلام والمفتاح والغنى والحد."},{"i":"myth-m16","s":64,"h":"سؤال مفتوح","t":"learn","x":"فيه سؤال في الفصل، ومش هجاوب عليه. اليونان خافوا من هاديس لدرجة إنهم مابيحبوش ينطقوا اسمه، وسموه \"الغني\". وفي نفس الوقت، هو الإله الوحيد اللي مابيظلمش حد، ومابيكدبش، ومابيعاقبش. السؤال: ليه بنخاف من اللي مابيظلمش؟ فيه قراءة بتقول: لأن الخوف مش من الظلم، الخوف من النهاية. واللي بيمثل النهاية بيبقى مخيف، حتى لو كان عادل."},{"i":"myth-m16","s":65,"h":"سؤال مفتوح","t":"learn","x":"وفيه قراءة تانية بتقول: لأن اللي مابيرجعش في كلامه أخطر من اللي بيغير رأيه. مع اللي بيغير رأيه ممكن تتفاوض. مع القانون مفيش تفاوض. والاتنين بيقروا نفس النص. وهنشتغل على ده في الفصل ١٢٣، القراءة النفسية، والفصل ١٢٨، الجدل بين الميثوس واللوجوس."},{"i":"myth-m16","s":67,"h":"أخطاء شائعة","t":"learn","x":"1. هاديس = الشيطان. لأ. هاديس مش بيعاقب، ومش شرير. هو حاكم مكان، مش قاضي أخلاق. 2. هاديس خطف بيرسيفوني لوحده. لأ. الترنيمة بتقول إن زيوس إداها له، يعني فيه موافقة أب. 3. هاديس إله الموت. أدق: هو إله الموتى وملكهم، مش الموت نفسه كحدث. والفرق مهم في التحليل: لما الشاعر بيتكلم عن الموت كحدث، ده مش بالضرورة هاديس."},{"i":"myth-m16","s":68,"h":"أخطاء شائعة","t":"learn","x":"4. بلوتو اسم يوناني. لأ. بلوتو لقب يوناني ( Ploutōn ) اتحول لاسم لاتيني، والاسم اليوناني الأساسي هاديس. 5. العالم التاني = الجحيم. لأ. في الميثولوجيا اليونانية، العالم التاني فيه أماكن كتير، ومنها أماكن للعقاب، بس مش كلها عقاب. والفصل السادس فيه التفاصيل."},{"i":"myth-m16","s":69,"h":"أخطاء شائعة","t":"tf","x":"هاديس خطف بيرسيفوني لوحده من غير ما حد يوافق. . غلط"},{"i":"myth-m16","s":71,"h":"كلمات هتقع لك في الشعر","t":"learn","x":"1. underworld — العالم التاني. 2. realm — مملكة أو مجال. 3. gloom — ظلام وضيق نفس. 4. shade — ظل، وبمعنى روح الميت. 5. ghost — شبح. 6. grave — قبر. 7. tomb — ضريح. 8. threshold — عتبة. 9. to summon — يستدعي. 10. to conjure — يستحضر بالأسماء. 11. key — مفتاح. 12. to withhold — يمنع ويحجب. 13. lot — قرعة، ونصيب. 14. portion — نصيب."},{"i":"myth-m16","s":72,"h":"كلمات هتقع لك في الشعر","t":"learn","x":"15. to apportion — يوزع بالأنصبة. 16. wealth — ثروة."},{"i":"myth-m16","s":74,"h":"خريطة الفصول الجاية","t":"learn","x":"M 17: ديميتر، إلهة الزرع، وأم بيرسيفوني. M 18: ديونيسوس، الإله اللي بيتولد مرتين، وفيه فكرة الموت والبعث. M 21: بيرسيفوني وديميتر، الحكاية كاملة من ناحية الأم. M 33: أورفيوس ويوريديس، أشهر محاولة للرجوع من العالم التاني. M 45: كليتي وسالماسيس، وفيه تحولات. M 78: الإنيد، الكتاب السادس، وإينياس في العالم التاني."},{"i":"myth-m16","s":75,"h":"خريطة الفصول الجاية","t":"learn","x":"M 95: الجحيم في المسيحية، والفرق بينه وبين هاديس. M 111: ميلتون، والتوفيق بين الجحيم المسيحي والعالم الوثني."},{"i":"myth-m16","s":77,"h":"ملخص في عشر جمل","t":"learn","x":"1. هاديس ابن كرونوس وريا، وأخو زيوس وبوسيدون، ومراته بيرسيفوني. 2. اسمه معناه على الأرجح \"اللي مش بيتشاف\"، وأصل الاسم نفسه مش معروف. 3. لقبه بلوتو يعني \"الغني\"، لأن المعادن والكنوز بتطلع من تحت الأرض. 4. في الإلياذة ١٥، بوسيدون بيقول إن التلاتة قسموا العالم بالقرعة، وهاديس خد الظلام الدامس."},{"i":"myth-m16","s":78,"h":"ملخص في عشر جمل","t":"learn","x":"5. في الترنيمة التانية، زيوس إدى بيرسيفوني لهاديس من غير رأي البنت ولا أمها. 6. ديميتر منعت الزرع، فحصلت مجاعة، فزيوس بعت هيرميس يتفاوض. 7. هاديس وافق، بس إدى بيرسيفوني بذرة رمان، فبقت مربوطة بالعالم التاني. 8. النتيجة اتفاق: جزء من السنة مع الأم، وجزء مع الجوز، وده تفسير الأسطورة للفصول."},{"i":"myth-m16","s":79,"h":"ملخص في عشر جمل","t":"learn","x":"9. في الأوديسة ١١، أوديسيوس بيحفر حفرة وبيستدعي الأرواح بالسيف والدم. 10. في الشعر الإنجليزي، هاديس بيظهر من خلال برسيربين وبلوتو، وسوينبرن فتح حديقتها بكلمة واحدة: سكوت."},{"i":"myth-m16","s":81,"h":"مهمتك قبل الفصل الجاي","t":"learn","x":"1. اقرا سطر سوينبرن: \" Here, where the world is quiet \". ليه الهدوء أخطر من الصراخ في وصف الموت؟ 2. اكتب جملة واحدة: إيه الفرق بين إله بيعاقب وإله بيستقبل؟ 3. فكر في حاجة تحت الأرض في بيتك أو في بيت جدتك: قبو، أو خزان، أو حاجة مدفونة. ليه بنحط الحاجات الغالية تحت؟"},{"i":"myth-m16","s":83,"h":"خاتمة","t":"learn","x":"هاديس هو الإله اللي بنخاف نقول اسمه، مع إنه أعدل واحد فيهم. وهو الإله اللي خد النصيب اللي محدش عايزه، ومع ذلك شغله ماشي بنظام. والأسطورة بتقول لنا حاجة بسيطة: الموت مش استثناء في الحياة، هو جزء من تقسيمها. زي ما القرعة قسمت العالم تلات أقسام، الموت هو القسم اللي كلنا هناخده."},{"i":"myth-m16","s":84,"h":"خاتمة","t":"learn","x":"وفي الفصل الجاي، هنقابل أم بيرسيفوني: ديميتر، إلهة الزرع، واللي غضبها وقف العالم. سلام يا عمر، وأشوفك في الفصل السبعتاشر."},{"i":"myth-m16","s":86,"h":"تذكر واكتب","t":"recall","x":"إزاي اتقسمت الدنيا بين الأخوة التلاتة عند هوميروس؟ . بالقرعة: زيوس خد السما، وبوسيدون البحر، وهاديس خد الضلمة المرقطة، والأرض فضلت مشتركة."},{"i":"myth-m16","s":87,"h":"تذكر واكتب","t":"recall","x":"إيه معنى اسم هاديس حسب قاموس أصل الكلمات؟ . يمكن حرفيا \"غير المرئي\"، بس الجذر نفسه مش معروف. فالاسم بيوصف الغياب، مش المكان."},{"i":"myth-m16","s":88,"h":"تذكر واكتب","t":"write","x":"قارن في ٣-٤ جمل بين صورة الموتى في الأوديسة الكتاب 11 وصورتهم في قصيدة سوينبرن عن العالم التاني. . في الأوديسة الموتى بيفتقدوا الحياة بشكل جسدي: أخيل بيقول إنه يفضل يكون أجيرا على الأرض، وروح أخرى بتطلب \" hold off thy sharp sword, that I may drink the blood \". وعند سوينبرن العالم التاني ساكن وهادي: \" Here, where the world is quiet \"، والهدوء نفسه هو الموضوع، مش العطش للحياة. يبدو أن الاتنين بيستعملوا نفس المكان بمزاجين متضادين، والفرق في نبرة الشاعر، مش في الجغرافيا."},{"i":"myth-m16","s":89,"h":"تذكر واكتب","t":"write","x":"قارن في ٣-٤ جمل بين الاسم اليوناني هاديس والاسم الروماني ديس باتر من ناحية المعنى والوظيفة. . اسم هاديس بيوصف الغياب، لأنه يمكن معناه \"غير المرئي\"، واليونانيين كانوا بيخافوا ينطقوا اسمه، فده إله بيتعرف باللي مش باين فيه. وديس باتر معناه \"الأب الغني\"، وهو في الأصل مرتبط بالأرض الزراعية والثروة المعدنية، فالرومان شافوه من ناحية الكنز اللي تحت الأرض. يمكن القول إن الاسمين بيرووا نفس الإله من زاويتين: خوف من الغياب عند اليونانيين، وثقة في الثروة عند الرومان، والاتنين صحيحين في نفس الوقت."},{"i":"myth-m17","s":1,"h":"إحنا فين في الحكاية","t":"learn","x":"في الفصل اللي فات خدنا هاديس، الإله اللي بيستقبل الموتى، وشوفنا الحكاية من ناحيته هو: القرعة، والخوذة، وبذرة الرمان. والنهارده هنشوف نفس الحكاية من الناحية التانية خالص: من ناحية الأم."},{"i":"myth-m17","s":2,"h":"إحنا فين في الحكاية","t":"learn","x":"ديميتر، أو سيريس عند الرومان، هي إلهة الزرع. وفي الحكاية اللي خدناها، هي الطرف اللي اتظلم: بنتها اتاخدت من غير رأيها، والأب هو اللي وافق. فديميتر عملت حاجة محدش من الآلهة عملها قبله: وقفت الزرع. مش حرب، ولا سلاح، ولا صراخ. وقفت شغلها، والدنيا كلها جاعت. هاديس بياخد. زيوس بيوافق. ديميتر بتوقف الدنيا لحد ما ترجع بنتها."},{"i":"myth-m17","s":3,"h":"إحنا فين في الحكاية","t":"learn","x":"والبنت هي اللي بتدفع التمن في الآخر. ودي أهم فكرة في الفصل: في الحكاية دي، أقوى واحد مش اللي عنده الصاعقة، هو اللي عنده الحاجة اللي كل الناس محتاجاها."},{"i":"myth-m17","s":4,"h":"إحنا فين في الحكاية","t":"learn","x":"ومثال من حياتنا بيوضح الفكرة: في أي شركة، أقوى واحد مش دايما المدير. ساعات أقوى واحد هو اللي ماسك الحسابات، أو اللي بيفهم في الشبكة، أو السواق اللي كل حاجة بتقف من غيره. السلطة الظاهرة حاجة، والسلطة الفعلية حاجة تانية. والميثولوجيا اليونانية فهمت ده قبل الإدارة الحديثة بآلاف السنين، وحطته في صورة إلهة ست، مش في صورة ملك."},{"i":"myth-m17","s":5,"h":"إحنا فين في الحكاية","t":"mc","x":"إيه الفكرة الأساسية عن قوة ديميتر؟ ؟ أقوى واحد هو اللي عنده الحاجة اللي كل الناس محتاجاها / أقوى واحد هو اللي عنده الصاعقة / أقوى واحد هو اللي عنده الجيش / أقوى واحد هو اللي عنده البحر . أقوى واحد هو اللي عنده الحاجة اللي كل الناس محتاجاها"},{"i":"myth-m17","s":7,"h":"البطاقة الأساسية","t":"learn","x":"الاسم ديميتر باليوناني، وسيريس ( Ceres ) باللاتيني. وهي أخت زيوس وبوسيدون وهاديس وهيرا وهيستيا، بنت كرونوس وريا. وبنتها بيرسيفوني، من زيوس. والتوجيني بيقول في سطر ٩١٢ لحد ٩١٤ إن ديميتر اتجوزت زيوس وخلفت بيرسيفوني، وده اللي بيفسر ليه زيوس هو اللي إداها لهاديس من غير ما يسأل الأم. أدواتها"},{"i":"myth-m17","s":8,"h":"البطاقة الأساسية","t":"learn","x":"سنبلة قمح، ومشعل، وإكليل من سنابل. السنبلة هي الرمز الأساسي: مش سيف، ولا رمح، ولا صاعقة. والمشعل في إيدها بيرجع لحكاية البحث، وهنشوفها في روما بعد شوية. طبيعتها هي مش إلهة \"طيبة\" بالمعنى الساذج. هي إلهة قانون: الأرض بتدي لو اشتغلت، وبتقف لو اتظلمت. وفيها حاجة نادرة في الميثولوجيا: غضبها مش انتقام شخصي، غضبها إضراب."},{"i":"myth-m17","s":10,"h":"الاسم: ديميتر وسيريس","t":"learn","x":"قبل الحكاية، وقفة على الاسم، لأن الاسم هنا فيه درس منهجي مهم. قاموس أصل الكلمات بيقول إن الاسم جاي من اليوناني Dēmētēr ، والجزء التاني غالبا من māter يعني \"أم\". والجزء الأول ممكن يكون من da ، اللي هي الشكل الدوري لكلمة gē يعني \"الأرض\". يعني: \"الأم الأرض\"."},{"i":"myth-m17","s":11,"h":"الاسم: ديميتر وسيريس","t":"learn","x":"بس القاموس نفسه بيضيف حاجة مهمة جدا: قاموس ليدل وسكوت بيشوفوا التفسير ده \"غير محتمل\" ( improbable )، وبيكيز بيكتب إن \"مفيش دليل إن da معناها أرض\". يعني التفسير الجميل ده مش متأكد منه."},{"i":"myth-m17","s":12,"h":"الاسم: ديميتر وسيريس","t":"learn","x":"ودي نفس الحكاية اللي خدناها في الفصل اللي فات مع اسم هاديس: لما المصدر يقول \"احتمال\"، إحنا ننقل \"احتمال\". التفسير الشعبي بيقول \"ديميتر يعني الأم الأرض\"، والتفسير العلمي بيقول \"يمكن، بس فيه اعتراضات\". والاتنين لازم يبقوا في درسك."},{"i":"myth-m17","s":13,"h":"الاسم: ديميتر وسيريس","t":"learn","x":"وسيريس في اللاتيني جاية من Proto-Italic * kerēs ، ومن الجذر الهندوأوروبي * ḱerh₃- يعني \"يغذي\" أو \"غذاء\". يعني الاسم اللاتيني مالوش علاقة بالأرض، هو عن الغذاء نفسه. وده فرق حلو: اليوناني بيوصف المكان (الأرض)، واللاتيني بيوصف الوظيفة (الغذاء)."},{"i":"myth-m17","s":14,"h":"الاسم: ديميتر وسيريس","t":"tf","x":"التفسير \"ديميتر يعني الأرض الأم\" مؤكد من كل العلماء. . غلط"},{"i":"myth-m17","s":15,"h":"الاسم: ديميتر وسيريس","t":"mc","x":"اسم سيريس اللاتيني جاي من جذر معناه إيه؟ ؟ يحصد / يغذي / يموت / يدور . يغذي"},{"i":"myth-m17","s":17,"h":"الحكاية الكبيرة: الأم اللي وقفت الدنيا","t":"learn","x":"الحكاية موجودة في الترنيمة الهوميرية التانية، ودي أطول الترنيمات وأحلاها، وخدناها في الفصل اللي فات من ناحية هاديس. وهنا هنقراها من ناحية ديميتر. البداية بيرسيفوني كانت بتلعب وتقطف ورد، والأرض اتفتحت، وهاديس خدها. ديميتر سمعت صوت بنتها، ولفت الدنيا تدور عليها. ومحدش قال لها حاجة: لا الآلهة، ولا البشر، ولا الطير."},{"i":"myth-m17","s":18,"h":"الحكاية الكبيرة: الأم اللي وقفت الدنيا","t":"learn","x":"لحد ما هيليوس، الشمس، اللي بيشوف كل حاجة، قال لها الحقيقة: زيوس إداها لهاديس. الغضب ديميتر سابت أوليمبوس، ومشيت على الأرض، وقعدت عند بير في إليوسيس جنب بيت راجل اسمه كيليوس. وقررت حاجة واحدة: الأرض مش هتنتج. لا قمح، ولا شعير، ولا حاجة. والنتيجة: مجاعة. البشر بيموتوا، والآلهة مش بتاخد قرابين، لأن القرابين من الحصاد. التفاوض"},{"i":"myth-m17","s":19,"h":"الحكاية الكبيرة: الأم اللي وقفت الدنيا","t":"learn","x":"زيوس بعت هيرميس لهاديس، وفي الترنيمة سطر ٣٣٥ النص بيقول إنه بعت هيرميس، اللي وصفه إنه ماسك العصاية الدهبية وقاتل أرغوس. والمهمة: يقنع هاديس يسيب بيرسيفوني تطلع. وهاديس وافق، بس إداها بذرة رمان قبل ما تسيب. والنص في سطر ٣٧٠ لحد ٣٧٤ بيقول إنه إداها البذرة في السر. الاتفاق بيرسيفوني رجعت، وديميتر سألتها: إنت أكلتي حاجة هناك؟ والبنت قالت الحقيقة."},{"i":"myth-m17","s":20,"h":"الحكاية الكبيرة: الأم اللي وقفت الدنيا","t":"learn","x":"فالنتيجة: جزء من السنة مع الأم، وجزء مع الجوز. وده تفسير الأسطورة للفصول. والدرس الحكاية مالهاش منتصر. الأم خدت بنتها نص السنة، والجوز خدها النص التاني، والبنت دفعت التمن كله. وده اللي بيخلي الحكاية عايشة: مفيش فيها عدل كامل، فيها اتفاق. والاتفاق ده هو أصل فكرة الموت والبعث في الميثولوجيا."},{"i":"myth-m17","s":21,"h":"الحكاية الكبيرة: الأم اللي وقفت الدنيا","t":"learn","x":"وخد بالك من حاجة في التفاوض: ديميتر مطلبتش إن البنت ترجع خالص. هي قبلت بنص. وده مش ضعف، ده واقعية: اللي بيفاوض على حاجة مستحيلة بيخسر كل حاجة. اللي بيفاوض على حاجة ممكنة بيكسب نصها."},{"i":"myth-m17","s":22,"h":"الحكاية الكبيرة: الأم اللي وقفت الدنيا","t":"learn","x":"ومثال قريب: في أي خلاف عائلي على ميراث أو على حضانة، الحل اللي بيوقف الوجع مش الحل الكامل، هو الحل اللي كل طرف يقدر يعيش معاه. والحكاية بتقول نفس الحاجة، بس بمقياس آلهة."},{"i":"myth-m17","s":23,"h":"الحكاية الكبيرة: الأم اللي وقفت الدنيا","t":"learn","x":"والحاجة الأخيرة: الأسطورة بتحول الاتفاق ده لحاجة في الطبيعة. البنت في العالم التاني = الشتا. البنت فوق = الربيع. يعني الفصول نفسها بقت تذكير سنوي بالاتفاق. وده ذكاء أسطوري عالي: بدل ما تحكي حكاية وتخلص، خلوها تتكرر كل سنة قدام الناس."},{"i":"myth-m17","s":24,"h":"الحكاية الكبيرة: الأم اللي وقفت الدنيا","t":"mc","x":"إيه اللي ديميتر وافقت عليه في الاتفاق؟ ؟ البنت تقعد جزء من السنة معاها وجزء مع جوزها / البنت ترجع خالص / البنت تفضل في العالم التاني / البنت تقعد نص السنة مع جوزها بس . البنت تقعد جزء من السنة معاها وجزء مع جوزها"},{"i":"myth-m17","s":25,"h":"الحكاية الكبيرة: الأم اللي وقفت الدنيا","t":"tf","x":"الحكاية بتنتهي بانتصار كامل لديميتر. . غلط"},{"i":"myth-m17","s":27,"h":"ديموفون وإليوسيس: الأم اللي حاولت تعمل إله","t":"learn","x":"فيه حكاية جوه الحكاية، وهي أحلى جزء في الترنيمة، وأقل جزء بيتحكي. ديميتر، وهي في شكل ست عجوز، دخلت بيت كيليوس وميتانيرا في إليوسيس، وبقت داية لابنهم الصغير، ديموفون. والترجمة الإنجليزية (إيفلين-وايت) بتقول"},{"i":"myth-m17","s":28,"h":"ديموفون وإليوسيس: الأم اللي حاولت تعمل إله","t":"learn","x":"\" So the goddess nursed in the palace Demophoon, wise Celeus' goodly son whom well-girded Metaneira bare. And the child grew like some immortal being, not fed with food nor nourished at the breast: for by day rich-crowned Demeter would anoint him with ambrosia as if he were the offspring of a god and breathe sweetly upon him as she held him in her"},{"i":"myth-m17","s":29,"h":"ديموفون وإليوسيس: الأم اللي حاولت تعمل إله","t":"learn","x":"bosom. But at night she would hide him like a brand in the heart of the fire, unknown to his dear parents .\""},{"i":"myth-m17","s":30,"h":"ديموفون وإليوسيس: الأم اللي حاولت تعمل إله","t":"learn","x":"والترجمة: الإلهة ربت في القصر ديموفون، ابن كيليوس الحكيم، اللي ولدته ميتانيرا. والطفل كان بيكبر زي كائن خالد، مش بيتغذى بأكل ولا بلبن، لأن ديميتر كانت في النهار تدهنه بالأمبروسيا كأنه ابن إله، وتنفخ عليه وهي شايلاه في حضنها. وفي الليل كانت تخبيه زي جمرة في قلب النار، من غير علم أبويه."},{"i":"myth-m17","s":31,"h":"ديموفون وإليوسيس: الأم اللي حاولت تعمل إله","t":"learn","x":"وبعد كده النص بيقول: وكانت هتخليه خالد وما يكبرش، لولا إن ميتانيرا، في غفلتها، سهرت بالليل من أوضتها وشافت. فصرخت ولطمت على وركيها، لأنها خافت على ابنها، وقالت كلام مجنح: \"ديموفون يا ابني، الست الغريبة دي بتدفنك في النار، وبتعمل لي حزن ومرارة.\" والشرح ديميتر ما كانتش بتؤذي الطفل، كانت بتخليه خالد. النار في الميثولوجيا مش عقاب، النار تنقية."},{"i":"myth-m17","s":32,"h":"ديموفون وإليوسيس: الأم اللي حاولت تعمل إله","t":"learn","x":"والأم التانية، ميتانيرا، خافت. وخوفها طبيعي: أم بتشوف ابنها في النار. والنتيجة إن الطفل خسر الخلود، وديميتر قالت لها إنها جاهلة، وإن الخوف منع حاجة حلوة. وده أول تعليق في الحكاية على الأمومة: الأم بتحمي، وساعات حمايتها هي اللي بتمنع."},{"i":"myth-m17","s":33,"h":"ديموفون وإليوسيس: الأم اللي حاولت تعمل إله","t":"learn","x":"ودي حكاية صغيرة، بس فيها الفكرة الكبيرة: ديميتر عايزة تدي الخلود لحد، زي ما أخدت بنتها الموت. والحكاية بتقول إن الخلود مش بيتوهب لحد بسهولة، وإن الخوف البشري هو اللي بيوقف العملية. وخد بالك من التفصيل ده كويس"},{"i":"myth-m17","s":34,"h":"ديموفون وإليوسيس: الأم اللي حاولت تعمل إله","t":"learn","x":"ديميتر ما كانتش بتعذب الطفل، كانت بتعمل فيه نفس اللي بتعمله النار في الحديد: بتنقيه. وده مش تفسيري أنا، ده معنى الطقس في الميثولوجيا: النار بتفصل اللي بيفنى عن اللي بيفضل. والأمبروسيا هي أكل الآلهة، واللي بياكلها بيقرب من الخلود. فالصورة كاملة: أكل إلهي في النهار، ونار في الليل. الطفل بيتبني على مرحلتين."},{"i":"myth-m17","s":35,"h":"ديموفون وإليوسيس: الأم اللي حاولت تعمل إله","t":"learn","x":"وفشل العملية مش لأن ديميتر ضعيفة، لأن حد شاف. السر شرط النجاح، والكشف بيفسد العمل. ومثال من الحياة: في الطب، فيه علاجات محتاجة التزام هادي ومفيش حد يتدخل. لو حد قلقان دخل وفتح الباب في النص، العلاج بيبوظ. ميتانيرا فتحت الباب. والحكاية بتقول إن الخوف حب، بس الحب ده كلف الطفل الخلود."},{"i":"myth-m17","s":36,"h":"ديموفون وإليوسيس: الأم اللي حاولت تعمل إله","t":"mc","x":"ليه فشلت ديميتر في تخليد ديموفون؟ ؟ ميتانيرا شافتها وصرخت / زيوس منعها / الأمبروسيا خلصت / الطفل رفض . ميتانيرا شافتها وصرخت"},{"i":"myth-m17","s":38,"h":"الأسرار الإليوسينية","t":"learn","x":"بعد الحكاية، ديميتر عملت حاجة تانية: أسست طقس. وفي الترنيمة، سطر ٤٧٣ لحد ٤٨٢، النص بيقول إنها مشيت لملوك القانون، وورت تريبتوليموس وديوكليس وإيومولبوس وكيليوس الطقوس المقدسة، وعلمتهم الأسرار. والنص نفسه بيقول إن الأسرار دي مينفعش تتعدى ولا تتعلم ولا تتقال، لأن هيبة الآلهة بتمنع الصوت. وبعدها بيقول: طوبى لمن شاف الحاجات دي من البشر. والشرح"},{"i":"myth-m17","s":39,"h":"الأسرار الإليوسينية","t":"learn","x":"الأسرار دي هي أسرار إليوسيس، ودي أشهر طقس ديني في اليونان القديمة، واستمر أكتر من ألف سنة. وكونها \"أسرار\" مش تفصيلة صغيرة: ده معناه إن في حاجات في الدين اليوناني مكانتتقالش. والشاعر نفسه بيقول إنه مش هيتكلم. وده درس في القراءة: لما الشاعر يقول \"فيه حاجة مش هقولها\"، هو مش بيخبي، هو بيحترم حد. والاحترام ده جزء من النص."},{"i":"myth-m17","s":40,"h":"الأسرار الإليوسينية","t":"learn","x":"واللي كان بيدخل الأسرار مش الفلاسفة، الناس العاديين. لأن الحكاية كانت بتوعد بحاجة بسيطة: اللي يشوف الأسرار، له نصيب أحسن بعد الموت. وده أول مرة في الميثولوجيا اليونانية الفكرة دي تتقال بالوضوح ده. وليه الأسرار مهمة لدرسنا؟"},{"i":"myth-m17","s":41,"h":"الأسرار الإليوسينية","t":"learn","x":"لأنها بتوريك إن الدين اليوناني مش بس حكايات. فيه طقس، وفيه جماعة، وفيه سر. والحكايات اللي إحنا بنقراها كانت بتتقال في نص الطقس ده، مش في الفراغ. ولما شاعر إنجليزي بعد ألفين سنة يستعمل صورة \"السر\" أو \"الطقس\"، هو بيستعمل حاجة ليها أصل حقيقي، مش مجاز لفظي."},{"i":"myth-m17","s":42,"h":"الأسرار الإليوسينية","t":"learn","x":"وفيها كمان درس في الأدب: النص اللي بيقول \"مش هقول\" بيخلق في القارئ رغبة. وده أقدم مثال على اللي بنسميه اليوم \"التشويق\". والشاعر اليوناني عمله بالسكوت، مش بالكلام."},{"i":"myth-m17","s":43,"h":"الأسرار الإليوسينية","t":"tf","x":"النص بيقول إن الأسرار الإليوسينية مينفعش تتقال. . صح"},{"i":"myth-m17","s":45,"h":"في روما: سيريس","t":"learn","x":"الرومان خدوا ديميتر وسموها سيريس، وعملوا بها حاجة مختلفة: حولوها لموضوع دولة. المعبد في سنة ٤٩٣ قبل الميلاد، اتبنى معبد لسيريس وليبر وليبرا على تلة الأفنتين في روما، واتقدس على إيد القنصل سبوريوس كاسيوس. وده مش معبد عادي: المعبد ده بقى مركز الطبقة العامة في روما، لأن الكهنة كانوا من العامة، مش من الأرستقراطيين. المهرجان"},{"i":"myth-m17","s":46,"h":"في روما: سيريس","t":"learn","x":"المهرجان اسمه سيرياليا ( Cerealia )، وكان في نص شهر إبريل، واليوم الأساسي فيه ١٩ إبريل. وكان فيه ألعاب في السيرك الأكبر، وسباقات عربيات. وفي رواية عن الطقس: نساء لابسين أبيض وشايلين مشاعل مشتعلة بيجروا في الحلبة، والرمز إن سيريس بتدور على بنتها الضايعة. والكلمة"},{"i":"myth-m17","s":47,"h":"في روما: سيريس","t":"learn","x":"كلمة cereal في الإنجليزي جاية من سيريس. قاموس أصل الكلمات بيقول إن الكلمة دخلت من الفرنسي céréale ، ومن اللاتيني Cerealis يعني \"بتاع الحبوب\"، وأصلها \"بتاع سيريس\". وأول استعمال للكلمة بمعنى حبوب الإفطار كان في أمريكا سنة ١٨٩٩. والفرق عن اليونان في اليونان: أسرار، وصمت، وحكاية. في روما: معبد، ومهرجان، وألعاب، وكلمة دخلت اللغة."},{"i":"myth-m17","s":48,"h":"في روما: سيريس","t":"learn","x":"نفس الإلهة، وطريقتين مختلفتين في التعامل معاها."},{"i":"myth-m17","s":49,"h":"في روما: سيريس","t":"mc","x":"إيه اسم المهرجان الروماني لسيريس، وإمتى؟ ؟ الفولكاناليا في أغسطس / الليبراليا في ١٧ مارس / سيرياليا، حوالي ١٩ إبريل / الساتورناليا في ديسمبر . سيرياليا، حوالي ١٩ إبريل"},{"i":"myth-m17","s":50,"h":"في روما: سيريس","t":"tf","x":"كلمة cereal جاية من اسم سيريس. . صح"},{"i":"myth-m17","s":52,"h":"ميادينها","t":"learn","x":"الأول: الحبوب القمح والشعير، وكل حاجة بتتاكل. وده ميدانها الأساسي، ومش ميدان صغير: من غيره مفيش مدينة، ولا جيش، ولا شعر. والشعر الإنجليزي بيعرف ده كويس، وبيستعملها كصورة للخصب والخير. التاني: الفصول لأن بنتها في العالم التاني نص السنة، فالفصول بقت من اختصاصها بالتبعية. الشتا والربيع في الحكاية مش ظواهر طبيعية، دول نتيجة اتفاق عائلي."},{"i":"myth-m17","s":53,"h":"ميادينها","t":"learn","x":"التالت: الأرض نفسها كل حاجة بتطلع من الأرض بتمشي عليها: الزرع، والموت، والدفن. وده اللي بيربطها بهاديس في القصة، وهي مش ساكنة معاه، لكن ملكه وملكها متداخلين. الرابع: الأمومة والقانون هي الإلهة اللي بتدافع عن بنتها، وبتوقف العالم عشان حقها. وده ميدان أدبي أكتر منه ديني: صورة الأم اللي بتفاوض السلطة."},{"i":"myth-m17","s":54,"h":"ميادينها","t":"learn","x":"وفي الميدان ده، ديميتر مختلفة عن كل الآلهة اللي خدناها. زيوس بيحكم بالصاعقة، وأثينا بالعقل، وآريس بالسلاح. ديميتر بتتفاوض من موقع الضرورة: العالم محتاجها، فهي بتستخدم الاحتياج ده كورقة."},{"i":"myth-m17","s":55,"h":"ميادينها","t":"learn","x":"وده بيفسر ليه الشعراء الإنجليز رجعوا ليها في القرن التسعتاشر أكتر من أي عصر تاني: العصر الفيكتوري كان بيكتب عن الأم اللي بتفقد، وعن البيت اللي بيتفكك، وديميتر كانت الصورة الجاهزة."},{"i":"myth-m17","s":57,"h":"الأسطورة في الشعر الإنجليزي","t":"learn","x":"هنا المفاجأة: ديميتر حاضرة في الشعر الإنجليزي أكتر من هاديس، لكن حضورها مش بالاسم، حضورها بالوظيفة: الأم اللي بتدي، والأرض اللي بتخصب. الشاهد الأول: شكسبير، العاصفة، الفصل الرابع، المشهد الأول في مشهد الأقنعة ( masque ) اللي بيقدمه بروسبيرو، إيريس بتنادي سيريس، والكلام بيبدأ بالسطر ده \" Ceres, most bounteous lady, thy rich leas \""},{"i":"myth-m17","s":58,"h":"الأسطورة في الشعر الإنجليزي","t":"learn","x":"والترجمة: سيريس، يا السيدة الكريمة الكثيرة العطاء، حقولك الغنية. والشرح: شكسبير بيستدعيها هنا كإلهة الخصب، مش كأم حزينة. هي اللي بتضمن الجوازة تبقى خصبة، والزرع يطلع. وده استخدام عملي جدا للأسطورة: سيريس في المسرح الإليزابيثي بقت صورة للبركة، مش شخصية تراجيدية. الشاهد التاني: سوينبرن، حديقة برسيربين"},{"i":"myth-m17","s":59,"h":"الأسطورة في الشعر الإنجليزي","t":"learn","x":"القصيدة اللي خدناها في الفصل اللي فات، وبتفتح بالسطر \" Here, where the world is quiet ;\" والترجمة: هنا، حيث العالم ساكت. والشرح: سوينبرن بيوصف جنينة البنت، مش الأم. بس وجود الجنينة نفسها هو نتيجة الحكاية: البنت بقت ملكة مكان، والمكان بقى جنينة ساكتة. يعني الأم غايبة عن القصيدة، والحكاية موجودة. والنمط العام"},{"i":"myth-m17","s":60,"h":"الأسطورة في الشعر الإنجليزي","t":"learn","x":"الشعر الإنجليزي بيدخل على ديميتر من تلات أبواب: باب الخصب (شكسبير)، وباب الفصول، وباب الأم الحزينة اللي بيتحول في العصر الفيكتوري لصورة للفقد. والباب التالت هو الأهم للتحليل: لما شاعر بيكتب عن أم فقدت بنتها، هو بيكتب ديميتر حتى لو مش كاتب اسمها."},{"i":"myth-m17","s":61,"h":"الأسطورة في الشعر الإنجليزي","t":"learn","x":"وخد بالك من حاجة عملية للامتحان: لو السؤال بيسأل \"إزاي الأسطورة حاضرة في القصيدة؟\" والإجابة \"مفيش ذكر للأسطورة\" تبقى إجابة ناقصة. الأسطورة بتحضر بالوظيفة: أم بتدور، وأرض بتموت، وربيع بيرجع. وده اللي بنسميه \"الإشارة غير المباشرة\"."},{"i":"myth-m17","s":62,"h":"الأسطورة في الشعر الإنجليزي","t":"learn","x":"والفرق بين الفصل ده والفصل اللي فات: هاديس حضر بالاسم وبالصورة (الظلام والمفتاح)، وديميتر بتحضر بالفعل (الخصب والبحث). والحاجة دي هتتكرر مع ديونيسوس في الفصل الجاي، لأنه هيحضر بالطقس أكتر من الاسم. وملحوظة أمانة أنا تحققت من سطر شكسبير من نص مسرحية العاصفة، ومن سطر سوينبرن من صفحة القصيدة. ومش هأدي أبيات تانية من غير ما أتأكد منها."},{"i":"myth-m17","s":63,"h":"الأسطورة في الشعر الإنجليزي","t":"mc","x":"إزاي استدعى شكسبير سيريس في العاصفة؟ ؟ كأم حزينة / كإلهة حرب / كإلهة الخصب في مشهد الأقنعة / كإلهة بحر . كإلهة الخصب في مشهد الأقنعة"},{"i":"myth-m17","s":65,"h":"إزاي تعرفها في قصيدة","t":"learn","x":"خمس مجموعات كلمات 1. الأسماء: Demeter, Ceres, Persephone, Proserpine, Eleusis, Triptolemos, Celeus . 2. الزرع: corn, wheat, grain, harvest, field, ear, sheaf, reap, sow, seed . 3. الفصول: spring, summer, winter, season, bloom, wither, return . 4. الأمومة: mother, daughter, child, grief, search, torch, wandering ."},{"i":"myth-m17","s":66,"h":"إزاي تعرفها في قصيدة","t":"learn","x":"5. الطقس: rite, mystery, sacred, initiate, altar, temple, procession . ولو لقيت تلاتة من دول، احتمال كبير إنك قدام ديميتر أو عالمها. والفرق عن هاديس: كلمات هاديس فيها الظلام والمفتاح والقفل. كلمات ديميتر فيها السنبلة والمشعل والبحث. واحد بيملك الحد، والتانية بتدور على اللي عدى الحد."},{"i":"myth-m17","s":68,"h":"سؤال مفتوح","t":"learn","x":"فيه سؤال في الفصل، ومش هجاوب عليه. ديميتر أوقفت الزرع عشان بنتها. والنتيجة إن البشر ماتوا من الجوع، وكلهم مالهومش ذنب في اللي حصل. السؤال: هل ده عدل؟ فيه قراءة بتقول: لأ، ده ظلم. أم زعلانة خلت شعب كامل يموت."},{"i":"myth-m17","s":69,"h":"سؤال مفتوح","t":"learn","x":"وفيه قراءة تانية بتقول: أي إضراب بيتعب الناس اللي مالهمش ذنب، ومع كده الإضراب أحيانا هو الطريقة الوحيدة. العمال بيقفوا، والناس بتتعب، وبعدها بياخدوا حقهم. والقراءة التالتة، وهي الأقرب للنص: الحكاية مش بتقول إنها محقة، الحكاية بتقول إنها قادرة. والقدرة في إيد الأم هي اللي خلت زيوس يتفاوض، لأن مفيش حاجة تانية كانت هتخليه يتكلم."},{"i":"myth-m17","s":70,"h":"سؤال مفتوح","t":"learn","x":"والاتنين بيقروا نفس النص. وهنشتغل على ده في الفصل المية أربعة وعشرين، النقد النسوي للأسطورة، لأن ده بالظبط السؤال اللي بيبدأ منه."},{"i":"myth-m17","s":72,"h":"أخطاء شائعة","t":"learn","x":"1. ديميتر هي \"الطبيعة الأم\". تبسيط زيادة. هي إلهة الحبوب والزرع في نظام ديني محدد، مش رمز رومانسي للطبيعة. والفرق مش لفظي: الطبيعة الأم فكرة حديثة، وديميتر إلهة ليها معبد وكهنة وطقس وناس بتقدم لها قرابين."},{"i":"myth-m17","s":73,"h":"أخطاء شائعة","t":"learn","x":"2. سيريس مجرد اسم تاني لديميتر. قريب، بس مش دقيق. سيريس إلهة رومانية ليها معبدها ومهرجانها وكهنتها، والرومان ساووها بديميتر بعدين. وفي روما، سيريس بقت مرتبطة بالطبقة العامة وبالسياسة، وده مالوش علاقة بديميتر اليونانية."},{"i":"myth-m17","s":74,"h":"أخطاء شائعة","t":"learn","x":"3. ديميتر هي اللي إدت البنت لهاديس. لأ. زيوس هو اللي إداها، زي ما الترنيمة بتقول في أول سطر. وده الفرق اللي بيخلي الحكاية عن سلطة الأب، مش عن شر الإله. 4. الحكاية نهايتها حزينة. لأ، نهايتها اتفاق: نص السنة هنا ونص هناك. والحزن جزء منها، مش كلها."},{"i":"myth-m17","s":75,"h":"أخطاء شائعة","t":"learn","x":"5. كلمة cereal مالهاش علاقة بالأسطورة. لأ، الكلمة نفسها جاية من اسم الإلهة. وده مثال حلو على إن الميثولوجيا عايشة في اللغة اللي بنتكلمها كل يوم."},{"i":"myth-m17","s":76,"h":"أخطاء شائعة","t":"tf","x":"كلمة cereal مالهاش أي علاقة بالأسطورة. . غلط"},{"i":"myth-m17","s":78,"h":"كلمات هتقع لك في الشعر","t":"learn","x":"1. harvest — الحصاد. 2. grain — حبوب. 3. sheaf — حزمة قمح. 4. to reap — يحصد. 5. to sow — يزرع. 6. barren — أرض ما بتنتجش. 7. famine — مجاعة. 8. to wither — يذبل. 9. to bloom — يزهر. 10. torch — مشعل. 11. to wander — يهيم ويدور. 12. grief — حزن. 13. rite — طقس. 14. mystery (بمعنى أسرار دينية) — سر مقدس. 15. to initiate — يدخل حد في الطقس."},{"i":"myth-m17","s":79,"h":"كلمات هتقع لك في الشعر","t":"learn","x":"16. bounteous — كثير العطاء."},{"i":"myth-m17","s":81,"h":"خريطة الفصول الجاية","t":"learn","x":"M 18: ديونيسوس، الإله اللي بيتولد مرتين، وفيه فكرة الموت والبعث. M 19: بان والحوريات، والطبيعة اللي مش مروضة. M 20: تقليد الدعاء في الشعر الإنجليزي من هوميروس لميلتون. M 21: بيرسيفوني وديميتر، الحكاية كاملة من ناحية الأم. M 33: أورفيوس ويوريديس، أشهر محاولة للرجوع من العالم التاني. M 124: النقد النسوي للأسطورة، وفيه السؤال المفتوح بتاع الفصل ده."},{"i":"myth-m17","s":83,"h":"ملخص في عشر جمل","t":"learn","x":"1. ديميتر إلهة الزرع، وأخت زيوس، وأم بيرسيفوني. 2. اسمها على الأرجح \"الأم الأرض\"، بس التفسير ده عليه اعتراضات. 3. سيريس اسمها الروماني، وجاية من جذر معناه \"يغذي\". 4. زيوس إدى بيرسيفوني لهاديس من غير رأي الأم. 5. ديميتر منعت الزرع، فحصلت مجاعة، والآلهة جاعت. 6. زيوس بعت هيرميس يتفاوض، لأن الحرب مع هاديس مستحيلة."},{"i":"myth-m17","s":84,"h":"ملخص في عشر جمل","t":"learn","x":"7. الاتفاق خلى البنت نص السنة مع الأم ونص مع الجوز. 8. في إليوسيس، حاولت تخلي ديموفون خالد، وفشلت لأن أمه خافت. 9. أسست أسرار إليوسيس، والنص نفسه بيقول إنها مينفعش تتقال. 10. في الشعر الإنجليزي، شكسبير استعملها كصورة للخصب، وسوينبرن كتب جنينة بنتها."},{"i":"myth-m17","s":86,"h":"مهمتك قبل الفصل الجاي","t":"learn","x":"1. اقرا سطر شكسبير: \" Ceres, most bounteous lady, thy rich leas \". ليه شكسبير بيستدعيها في مشهد جواز؟ 2. اكتب جملة واحدة: إيه الفرق بين إلهة بتعاقب وإلهة بتوقف شغلها؟ 3. فكر في حاجة في بيتك بتقف لما حد يزعل: الأكل، أو الكهربا، أو الكلام. مين اللي بيمسك المفتاح؟"},{"i":"myth-m17","s":88,"h":"خاتمة","t":"learn","x":"ديميتر هي الإلهة اللي علمتنا حاجة مش موجودة في باقي الفصول: إن القوة مش دايما في الضرب. زيوس عنده الصاعقة، وبوسيدون عنده الرمح، وهاديس عنده الخوذة. ديميتر عندها سنبلة، ومشعل، وحاجة واحدة تانية: قدرتها إنها تقول \"لأ\"."},{"i":"myth-m17","s":89,"h":"خاتمة","t":"learn","x":"ولما قالت \"لأ\"، الدنيا وقفت. ومحدش قدر يعمل حاجة، لحد ما قعدوا على الطربيزة. وده اللي بيخلي الحكاية دي، وهي من تلات آلاف سنة، لسه بتتقرا. وفي الفصل الجاي، هنقابل الإله اللي بيموت ويرجع كل سنة: ديونيسوس. سلام يا عمر، وأشوفك في الفصل التمنتاشر."},{"i":"myth-m17","s":91,"h":"تذكر واكتب","t":"recall","x":"مين اللي إدى بيرسيفوني لهاديس حسب الترنيمة التانية؟ . زيوس، أبوها، ومن غير رأي الأم. وده اللي بيخلي الحكاية عن سلطة الأب، مش عن شر الإله."},{"i":"myth-m17","s":92,"h":"تذكر واكتب","t":"recall","x":"إيه اسم المهرجان الروماني لديميتر، وفي أنهي شهر؟ . سيرياليا، في نص إبريل، واليوم الأساسي فيه ١٩ إبريل."},{"i":"myth-m17","s":93,"h":"تذكر واكتب","t":"write","x":"قارن في ٣-٤ جمل بين سيريس في العاصفة لشكسبير وبيرسيفوني في قصيدة سوينبرن. . شكسبير بيستدعي سيريس في مشهد جواز، وبيوصفها بالعطاء: \" Ceres, most bounteous lady, thy rich leas \"، فالإلهة عنده أم للخصب والبركة. وسوينبرن بيقف عند بنتها في العالم التاني، والعالم عنده هادي وحزين، والجمال فيه بارد. يبدو أن الاتنين بياخدوا من نفس الحكاية نصا مختلفا: شكسبير بياخد الأم اللي بتدي، وسوينبرن بياخد البنت اللي اتاخدت، وده يوضح إن الحكاية فيها نبرتين، والاختيار بيقول حاجة عن الشاعر."},{"i":"myth-m17","s":94,"h":"تذكر واكتب","t":"write","x":"قارن في ٣-٤ جمل بين ديميتر اليونانية في الترنيمة التانية وسيريس الرومانية في مهرجان سيرياليا. . ديميتر في الترنيمة أم بتدور على بنتها، وغضبها إضراب عن العمل، وحكايتها شخصية وطقسية في نفس الوقت. وسيريس في روما بقت إلهة المدينة والطبقة العامة، وليها معبد على الأفنتين ومهرجان في إبريل، والاحتفال بيخص الحصاد والسياسة أكتر من الحزن. يمكن القول إن نفس الإلهة اتحركت من حكاية أم إلى مؤسسة، والفرق ده بيفسر ليه cereal كلمة لاتينية الأصل، مش يونانية."},{"i":"myth-m18","s":1,"h":"إحنا فين في الحكاية","t":"learn","x":"في الفصل اللي فات خدنا ديميتر، الإلهة اللي وقفت الزرع لحد ما ترجع بنتها. إلهة الحدود: الأرض اللي بتدي، والأرض اللي بتمنع. والنهارده هنقابل الإله اللي بيعمل العكس بالظبط: الإله اللي بيشيل الحدود."},{"i":"myth-m18","s":2,"h":"إحنا فين في الحكاية","t":"learn","x":"ديونيسوس، أو باخوس عند الرومان، هو إله الخمر والمسرح والجنون الطقسي. وكل حاجة فيه بتخص فكرة واحدة: إن الإنسان لما بيقف قدام حد، بيحتاج حاجة تكسره. الخمر بتكسر الحد بينه وبين نفسه. المسرح بيكسر الحد بينه وبين اللي على المسرح. والرقص والطبول بيكسروا الحد بينه وبين الجماعة. والجنون بيكسر الحد بينه وبين العقل. ديميتر = الحد اللي بيحمي (الأرض بتمنع)."},{"i":"myth-m18","s":3,"h":"إحنا فين في الحكاية","t":"learn","x":"ديونيسوس = الحد اللي بيتكسر (الإنسان بيسيب نفسه). وعشان كده، الفصل ده مش فصل عن \"إله الشرب\". ده فصل عن أخطر فكرة في الميثولوجيا: إن الحضارة نفسها بتحتاج لحظات بتخرج فيها عن نفسها، وإلا بتقف."},{"i":"myth-m18","s":4,"h":"إحنا فين في الحكاية","t":"learn","x":"ومثال من حياتنا: كلنا عندنا في السنة أيام بنكسر فيها الروتين بالكامل: فرح، أو ماتش كبير، أو ليلة عيد، أو حفلة تخرج. اليوم ده مش \"فوضى\"، هو وظيفة اجتماعية: الناس بتفضي اللي جواها، وبعدين ترجع تشتغل. اليونانيين عملوا للفكرة دي إله، وعملوا لها مهرجان رسمي في التقويم، بإذن الدولة."},{"i":"myth-m18","s":5,"h":"إحنا فين في الحكاية","t":"mc","x":"إزاي بيتوصف ديونيسوس في أول الفصل؟ ؟ الإله اللي بيشيل الحدود / الإله اللي بيحمي الحدود / الإله اللي بيحكم من فوق / الإله اللي بيحارب الوحوش . الإله اللي بيشيل الحدود"},{"i":"myth-m18","s":7,"h":"البطاقة الأساسية","t":"learn","x":"الاسم ديونيسوس ( Dionysus ) باليوناني، وباخوس ( Bacchus ) باللاتيني. وليه اسم تالت روماني: ليبر ( Liber ). وليه ألقاب كتير، وأشهرها بروميوس ( Bromios ) يعني \"العالي الصوت\" أو \"الهادر\"، من كلمة يونانية معناها الصوت العالي. الأب والأم أبوه زيوس، وأمه سيميله ( Semele )، بنت قدموس ملك طيبة. يعني هو الإله الوحيد من الآلهة الكبار اللي أمه بشرية."},{"i":"myth-m18","s":8,"h":"البطاقة الأساسية","t":"learn","x":"والتوجيني بيقولها في سطر واحد حلو جدا (٩٤٠–٩٤٢): \"وأمه سيميله، بنت قدموس، خلفت له ابنا مجيدا، ديونيسوس مانح الأفراح، بعد اتحاد في الحب، وهي فانية وهو خالد.\" أدواته الثيرسوس ( thyrsus ): عصاية طويلة في آخرها شكل مخروط صنوبر، وملفوفة باللبلاب والعنب. دي أشهر حاجة في إيده وفي إيد أتباعه. اللبلاب ( ivy ) والعنب، والكأس، والقناع ( mask )."},{"i":"myth-m18","s":9,"h":"البطاقة الأساسية","t":"learn","x":"وحيوانات معاه: الفهد، والنمر، والتيس، والأفعى. مش حيوانات عشوائية: دي حيوانات بتخرج الإنسان عن طوره. طبيعته هو مش إله \"مرح\" بالمعنى الساذج. هو إله بيفتح الباب، والباب لما يتفتح ممكن يدخل منه الضحك، وممكن يدخل منه الهلاك. وفي الفصل ده هتشوف الاتنين: القراصنة اللي اتحولوا لدلافين، وبنتيوس اللي اتقطع في الجبل."},{"i":"myth-m18","s":10,"h":"البطاقة الأساسية","t":"mc","x":"مين أم ديونيسوس؟ ؟ هيرا / سيميله، بنت قدموس / ديميتر / ليتو . سيميله، بنت قدموس"},{"i":"myth-m18","s":11,"h":"البطاقة الأساسية","t":"tf","x":"ديونيسوس هو الإله الكبير الوحيد اللي أمه بشرية. . صح"},{"i":"myth-m18","s":13,"h":"الاسم: ديونيسوس وباخوس","t":"learn","x":"قبل الحكاية، وقفة على الاسم، لأن الاسم هنا درس تاني في الأمانة العلمية. قاموس أصل الكلمات بيقول عن اسم Dionysus بالحرف: \"أصل اسمه غير معروف\" ( of unknown origin ). يعني العلماء لحد النهارده مش متأكدين من معنى الاسم."},{"i":"myth-m18","s":14,"h":"الاسم: ديونيسوس وباخوس","t":"learn","x":"لكن فيه تفسير مشهور جدا في الكتب الشعبية: إن الاسم معناه \"زيوس نيسا\"، أي زيوس بتاع المكان اللي اسمه نيسا، لأن الإله اتربى هناك. التفسير ده حلو، بس لازم تقدمه على إنه اقتراح، مش حقيقة. مفيش مصدر قاطع بيقوله."},{"i":"myth-m18","s":15,"h":"الاسم: ديونيسوس وباخوس","t":"learn","x":"وباخوس: قاموس أصل الكلمات بيقول إنها من اليوناني Bakkhos ، و\"يمكن\" ( perhaps ) تكون مرتبطة باللاتيني bacca يعني \"توتة\" أو \"ثمرة\"، أو تكون جاية من لغة آسيوية. وبيضيف حاجة مهمة: يمكن كان في الأصل إله خصب تراقي ( Thracian )."},{"i":"myth-m18","s":16,"h":"الاسم: ديونيسوس وباخوس","t":"learn","x":"يعني عندنا تلات احتمالات، ومفيش واحد منها مؤكد. ودي حاجة لازم تتعود عليها في الكورس ده: الاسم القديم مش دايما ليه معنى واضح، واللي بيقول لك \"معناه كذا وكذا\" بثقة كاملة غالبا بيجمل. كلمات جانبية تستاهل تعرفها"},{"i":"myth-m18","s":17,"h":"الاسم: ديونيسوس وباخوس","t":"learn","x":"maenad (ميناد): من اليوناني mainas ، ومعناها الحرفي \"امرأة مجنونة\"، من فعل معناه \"يثور\" أو \"يجن\". يعني الكلمة نفسها بتقول إن الجنون جزء من الطقس، مش عيب فيه. thyrsus : من اليوناني thyrsos يعني \"ساق نبات\"، وبيكيز بيقول إنها كلمة مستعارة من الأناضول، وأصلها مش معروف. Bromios : \"العالي الصوت\"، من كلمة معناها الضجيج."},{"i":"myth-m18","s":18,"h":"الاسم: ديونيسوس وباخوس","t":"tf","x":"أصل اسم Dionysus معروف ومؤكد. . غلط"},{"i":"myth-m18","s":19,"h":"الاسم: ديونيسوس وباخوس","t":"mc","x":"إزاي اتقدم تفسير \"زيوس نيسا\"؟ ؟ حقيقة مثبتة / نص من الإلياذة / اقتراح مش حقيقة / رواية ديونيسوس نفسه . اقتراح مش حقيقة"},{"i":"myth-m18","s":21,"h":"الحكاية الكبيرة: الميلاد مرتين","t":"learn","x":"الحكاية دي مش حكاية واحدة، دي حكايتين متركبتين: ميلاد من أم بشرية، وميلاد تاني من الأب. وعشان كده ديونيسوس بيتلقب \"اللي اتولد مرتين\". الجزء الأول: سيميله زيوس حب سيميله من غير علم هيرا، ووعدها إنه ينفذ لها أي طلب. هيرا خدعت سيميله (على شكل دايتها) وقالت لها: اطلبي منه إنه ييجي لك زي ما بييجي لهيرا."},{"i":"myth-m18","s":22,"h":"الحكاية الكبيرة: الميلاد مرتين","t":"learn","x":"زيوس ماقدرش يرفض، فجه لها بعربية فيها برق ورعد، وضرب الصاعقة. أبولودوروس (ترجمة فريزر) بيقول: \"وماتت سيميله من الرعب\" ( died of fright ). وفي ترجمات تانية لنفس النص بتلاقي \"اتحرقت\". الاتنين ترجمة لنفس الجملة اليونانية، والفرق في الترجمة مش في الحكاية. وده درس صغير: لما تقرا ترجمتين وتحس إنهم بيقولوا حاجة مختلفة، ارجع للأصل. الجزء التاني: الفخذ"},{"i":"myth-m18","s":23,"h":"الحكاية الكبيرة: الميلاد مرتين","t":"learn","x":"زيوس خد الطفل من النار، وده كان لسه في الشهر السادس، وخاطه في فخده. أبولودوروس بيقول بالحرف: \"زيوس، وهو بيخطف الطفل اللي في شهره السادس من النار، خاطه في فخذه هو\" ( sewed it into his own thigh ). ولما جاء وقت الولادة، فك الخيوط وولد ديونيسوس، وسلمه لهيرميس."},{"i":"myth-m18","s":24,"h":"الحكاية الكبيرة: الميلاد مرتين","t":"learn","x":"وهيرميس وداه لإينو وأثاماس (أخت سيميله وجوزها) يربوه، بس هيرا جنتهم، فزيوس حول ديونيسوس لتيس صغير، وهيرميس خده لحوريات نيسا في آسيا. والحوريات دول بقوا بعدين نجوم، اسمهم الهياديس. والحوريات نفسهم ليهم ترنيمة الترنيمة الهوميرية ٢٦ بتقول عنهم: \"الحوريات ذات الشعر الغزير استقبلوه في حضنهم من أبيه السيد، وربوه ونشأوه بعناية في وديان نيسا.\""},{"i":"myth-m18","s":25,"h":"الحكاية الكبيرة: الميلاد مرتين","t":"learn","x":"وهنا تيجي أجمل لفتة في الفصل في مسرحية الباكخاي ليوريبيديس، تيريسياس (الشيخ الأعمى) بيقول لبنتيوس إن حكاية الفخذ دي أصلا قصة اتغيرت كلمة فيها. زيوس، عشان يحمي الطفل من هيرا، سلمها \"رهينة\" ( hostage )، والكلمة اليونانية للرهينة هي homēros ، وقريبة في النطق من mēros يعني \"فخذ\". الناس سمعوا \"رهينة\" وفهموها \"فخذ\"، والحكاية اتولدت."},{"i":"myth-m18","s":26,"h":"الحكاية الكبيرة: الميلاد مرتين","t":"learn","x":"ودي حاجة مذهلة: شاعر من القرن الخامس قبل الميلاد بيقول لك إن الأسطورة نفسها ممكن تكون سوء فهم لكلمة. يعني فكرة \"الأساطير ليها نسخ، مش نص مقدس واحد\" مش فكرة حديثة، هي موجودة جوه النصوص نفسها."},{"i":"myth-m18","s":27,"h":"الحكاية الكبيرة: الميلاد مرتين","t":"mc","x":"ليه ديونيسوس بيتلقب \"اللي اتولد مرتين\"؟ ؟ اتولد مرتين من هيرا / اتولد من سيميله وبعد موتها اتخاط في فخد زيوس واتولد تاني / اتولد في اليونان ومصر / اتولد مرتين من زيوس وهيرا . اتولد من سيميله وبعد موتها اتخاط في فخد زيوس واتولد تاني"},{"i":"myth-m18","s":28,"h":"الحكاية الكبيرة: الميلاد مرتين","t":"tf","x":"يوريبيديس بيلمح إن حكاية الفخد ممكن تكون سوء فهم لكلمة \"رهينة\". . صح"},{"i":"myth-m18","s":30,"h":"القراصنة: أول معجزة","t":"learn","x":"أحلى حكاية عن ديونيسوس موجودة في الترنيمة الهوميرية السابعة، وهي قصيرة وكلها مشهد واحد. المشهد الأول: الشاب على الشط ديونيسوس واقف على راس جبل داخل البحر، شكله شاب في أول شبابه، وشعره غامق، ولبس عباية أرجوانية. قراصنة من Tyrrhenia (شعب بحري) شافوه، ونزلوا بسرعة، وخطفوه وحطوه على المركب، وفكروا إنه ابن ملك. المشهد التاني: الحبال اللي مش بتمسك"},{"i":"myth-m18","s":31,"h":"القراصنة: أول معجزة","t":"learn","x":"الترنيمة بتقول (ترجمة إيفلين-وايت): \"حاولوا يربطوه بحبال خشنة، بس الحبال مامسكتش، والأغصان وقعت بعيد عن إيديه ورجليه: وقعد يبتسم في عينيه الغامقتين.\" ودي صورة لازم تفتكرها: الإله مش بيتقيد. اللي بيقيده هو اللي بيتكسر. المشهد التالت: السفينة بتتحول أول حاجة: ريحة نبيت حلوة مالت في المركب كلها."},{"i":"myth-m18","s":32,"h":"القراصنة: أول معجزة","t":"learn","x":"تاني حاجة: كرمة طلعت على طول الشراع، وفيها عناقيد معلقة. تالت حاجة: لبلاب غامق لف نفسه حوالين الصاري، وفيه ورد وتوت. ورابع حاجة: المجاذيف كلها اتغطت بأكاليل."},{"i":"myth-m18","s":33,"h":"القراصنة: أول معجزة","t":"learn","x":"والنص بيقول بالحرف: \"وفي الحال انتشرت كرمة في الاتجاهين على طول أعلى الشراع وفيها عناقيد كتير معلقة منها، ولف لبلاب غامق نفسه حوالين الصاري، ومتفتح بالورد وعليه توت غزير؛ وكل المجاذيف اتغطت بأكاليل.\" المشهد الرابع: الوحوش الإله بقى أسد في مقدمة المركب، وزأر بصوت عالي. وفي النص بقى دب أشعث واقف بيهدد."},{"i":"myth-m18","s":34,"h":"القراصنة: أول معجزة","t":"learn","x":"القراصنة جروا على المؤخرة، والأسد نط على القبطان. المشهد الخامس: الدلافين البحارة نطوا في البحر كلهم، واتحولوا دلافين. لكن الربان (اللي كان بيفهم من الأول) رحمه الإله ومسكه وقال له: \"اتشجع... لقيت حظوة في قلبي. أنا ديونيسوس الهادر، اللي خلفته سيميله بنت قدموس من اتحاد مع زيوس.\""},{"i":"myth-m18","s":35,"h":"القراصنة: أول معجزة","t":"learn","x":"والترنيمة مابتقولش اسمه، هو معروف بصفته بس: الربان اللي فهم قبل الباقيين. وليه الحكاية دي مهمة؟ لأنها بتقول لك إيه اللي بيعمله الإله: مش بيقتل اللي أساء له، هو بيحوله. القرصان اللي عايز ياخد الناس ويبيعهم، بيتحول لكائن بحري بيعيش في جماعة وبيتحرك معاها. العقوبة نفسها شكل من أشكال الدرس."},{"i":"myth-m18","s":36,"h":"القراصنة: أول معجزة","t":"mc","x":"إيه اللي حصل للقراصنة في الترنيمة الهوميرية السابعة؟ ؟ غرقوا / اتسجنوا / اتحولوا لأشجار / اتحولوا دلافين . اتحولوا دلافين"},{"i":"myth-m18","s":37,"h":"القراصنة: أول معجزة","t":"tf","x":"ديونيسوس عاقب القراصنة بالصاعقة. . غلط"},{"i":"myth-m18","s":39,"h":"ليش هو إله مختلف: الحدود","t":"learn","x":"خلينا نوقف ونفهم ليه ديونيسوس مش زي باقي الآلهة. أولا: هو إله بيخص الإنسان نفسه، مش حاجة براه زيوس بيحكم، وأبولو بينور، وأرتميس بتحمي الغابة. كل دول إله ليه \"منطقة\" بره الإنسان. ديونيسوس منطقة: جوه الإنسان. الخمر مش حاجة في العالم، الخمر حالة في الجسم. ثانيا: هو الإله اللي بيقاوم"},{"i":"myth-m18","s":40,"h":"ليش هو إله مختلف: الحدود","t":"learn","x":"في الإلياذة، في أقدم إشارة ليه في الأدب اليوناني (الإلياذة ٦.١٣٠–١٤٠)، ديوميديس بيحكي حكاية ليكورجوس اللي طارد مربيات ديونيسوس المجنونات على جبل نيسا، فوقعوا العصي من إيديهم، فديونيسوس جري ورمى نفسه في البحر، وتيتيس استقبلته في حضنها. والآلهة بعد كده أعمت ليكورجوس. لاحظ: الإله هنا مش بيهاجم، هو بيهرب. ومع ذلك اللي طرده هو اللي اتعمى."},{"i":"myth-m18","s":41,"h":"ليش هو إله مختلف: الحدود","t":"learn","x":"ثالثا: هو الإله اللي بيعاقب بالجنون عقوبته مش صاعقة، عقوبته إنه يخليك تفقد نفسك. ودي عقوبة مناسبة لإله الحدود: اللي بيكسر حد، بيتكسر حده هو. رابعا: هو الإله اللي عنده مهرجانات كتير"},{"i":"myth-m18","s":42,"h":"ليش هو إله مختلف: الحدود","t":"learn","x":"الأنثستيريا ( Anthesteria ): تلات أيام في شهر أنثستيريون (فبراير–مارس)، أول يوم فتح البراميل، وتاني يوم مسابقة شرب، وتالت يوم للأموات. وكانوا بيقولوا إن أرواح الموتى بتطلع وتمشي في المدينة في الأيام دي. والمدينة نفسها كانت بتعمل في اليوم التاني طقس سري: امرأة كبيرة القضاة بتتجوز الإله رمزيا في معبده."},{"i":"myth-m18","s":43,"h":"ليش هو إله مختلف: الحدود","t":"learn","x":"وده مش هزار: المدينة بتعترف إن الإله ده جزء من نظامها، وإنها محتاجة يوم تخرج فيه عن نفسها."},{"i":"myth-m18","s":44,"h":"ليش هو إله مختلف: الحدود","t":"mc","x":"في الإلياذة، لما ليكورجوس طارد مربيات ديونيسوس، عمل الإله إيه؟ ؟ ضرب ليكورجوس بالصاعقة / سجنه في جبل / هرب ورمى نفسه في البحر / طلب من زيوس يعاقبه . هرب ورمى نفسه في البحر"},{"i":"myth-m18","s":45,"h":"ليش هو إله مختلف: الحدود","t":"tf","x":"الأنثستيريا فيها يوم للأموات. . صح"},{"i":"myth-m18","s":47,"h":"الباكخاي: لما المدينة تقاوم الإله","t":"learn","x":"مسرحية الباكخاي ليوريبيديس هي أهم نص عن ديونيسوس، وهي حكاية مقاومة مدينة لإله. البداية ديونيسوس رجع طيبة، مسقط رأس أمه، وطلع جنون في ستات المدينة، فطلعوا الجبل. بنتيوس، ملك طيبة الشاب، رفض الإله، وحبسه، وقرر يمنع الطقس. مين اللي وقف مع الإله؟ تيريسياس الشيخ الأعمى، وكادموس جد بنتيوس."},{"i":"myth-m18","s":48,"h":"الباكخاي: لما المدينة تقاوم الإله","t":"learn","x":"وكلام تيريسياس هو أحلى كلام في المسرحية، وهو بيربط الفصل ده بالفصل اللي فات. بيقول (ترجمة باكلي): \"فيه حاجتين، يا شاب، هما الأول عند الناس: الإلهة ديميتر — هي الأرض، سميها بالاسم اللي تحبه؛ هي بتغذي البشر بالطعام الجاف؛ والتاني اللي جه بعدها، ابن سيميله، اكتشف ما يعادله: الشراب السائل من العنب، وعرفه للبشر. بيفرج عن البشر التعساء من الحزن، لما"},{"i":"myth-m18","s":49,"h":"الباكخاي: لما المدينة تقاوم الإله","t":"learn","x":"يمتلوا من تيار الكرمة، وبيديهم نوم، وسيلة نسيان همومهم اليومية، ومفيش علاج تاني للمشاكل.\" وده ربط عبقري: ديميتر إدت الخبز، وديونيسوس إدى الخمر. الاتنين إدوا للإنسان حاجة بتخليه يستحمل. واحدة بالجوع، وواحدة بالنسيان. المعجزة الإله محبوس في السجن، وفجأة بيقول: \"اهز المكان، يا سيد روح الزلزال!\""},{"i":"myth-m18","s":50,"h":"الباكخاي: لما المدينة تقاوم الإله","t":"learn","x":"والكورس بيقول: \"شوفتوا القوايم الحجرية على العمد وهي بتقع؟\" والنار بتولع حوالين قبر سيميله، وبنتيوس بيفتكر إنه بيشوف سراب، وبعدها بيلاقي الإله واقف حر. النهاية: بنتيوس في الجبل الإله أقنع بنتيوس إنه يتنكر في هدوم ست، ويطلع الجبل يتفرج على الطقس. والستات شافوه، وطلعوه على شجرة."},{"i":"myth-m18","s":51,"h":"الباكخاي: لما المدينة تقاوم الإله","t":"learn","x":"وأمه أجافي هي اللي بدأت القتل، وهي اللي قطعت ابنها بيديها، لأن الإله خلاها تشوفه أسد. والنص بيقول: \"سحب إيده الشمال من الكوع وحط رجله في جنب الراجل المسكين، وقلع كتفه، مش بقوتها هي، الإله هو اللي سهل إيديها.\" وبعدين شالت راسه وحطتها على راس الثيرسوس، ومشيت بيه في وسط الجبل وهي فاكرة نفسها صيادة منتشرة. وآخر سطر في المشهد هو الدرس"},{"i":"myth-m18","s":52,"h":"الباكخاي: لما المدينة تقاوم الإله","t":"learn","x":"\"سلامة العقل وتوقير أمور الآلهة هو الأحسن؛ وأنا أظن إن دي أحكم حاجة عند البشر اللي بيتبعوها.\""},{"i":"myth-m18","s":53,"h":"الباكخاي: لما المدينة تقاوم الإله","t":"mc","x":"مين وقف مع ديونيسوس ضد بنتيوس في الباكخاي؟ ؟ أبولو وأرتميس / أجافي وكل الستات / هيرميس وأثينا / تيريسياس وكادموس . تيريسياس وكادموس"},{"i":"myth-m18","s":54,"h":"الباكخاي: لما المدينة تقاوم الإله","t":"tf","x":"تيريسياس ربط ديميتر بالخبز وديونيسوس بالشراب. . صح"},{"i":"myth-m18","s":56,"h":"المسرح: الإله اللي إدانا التراجيديا","t":"learn","x":"ديونيسوس مش إله الخمر بس، هو إله المسرح. والاتنين مش صدفة. إزاي المسرح ابتدا في أثينا، مهرجان المدينة الكبير ( City Dionysia ) كان لمصلحة ديونيسوس. بيسستراتوس نظم المهرجان في القرن السادس قبل الميلاد، وضاف مسابقة الأناشيد. وثيسپيس ( Thespis ) من إيكاريا كان أول واحد فصل نفسه من الكورس ولبس قناع وبقى \"ممثل\"، وبقى بيتكلم مع الكورس. ودي بداية الدراما."},{"i":"myth-m18","s":57,"h":"المسرح: الإله اللي إدانا التراجيديا","t":"learn","x":"والتاريخ التقليدي لأول مسابقة تراجيديا هو ٥٣٤ ق.م، بس فيه باحثين شايفين إن التاريخ الأصح ٥٠١ ق.م. فخد بالك: \"التاريخ التقليدي\" مش \"التاريخ المؤكد\". شكل المهرجان كان في شهر إلافيبوليون (مارس–أبريل)، حوالي يوم ١٠ ل ١٦. وفي القرن الخامس قبل الميلاد، كان فيه خمس أيام عروض، وتلاتة كتاب تراجيديا كل واحد بيقدم تلات مسرحيات + مسرحية ساتير."},{"i":"myth-m18","s":58,"h":"المسرح: الإله اللي إدانا التراجيديا","t":"learn","x":"وكل التراجيديات اليونانية اللي وصلت لنا (إسخيلوس، سوفوكليس، يوريبيديس) اتعرضت في مسرح ديونيسوس. وليه المسرح مرتبط بديونيسوس؟ القناع: الممثل بيغطي وشه، فبيبقى شخص تاني. وده نفس فكرة الإله: الحد بين الأنا وغير الأنا بيتشال. الكلمة نفسها: theatre جاية من اليوناني theatron ، من فعل معناه \"يشوف\" أو \"يتفرج\". يعني المسرح حرفيا \"مكان الرؤية\"."},{"i":"myth-m18","s":59,"h":"المسرح: الإله اللي إدانا التراجيديا","t":"learn","x":"والتراجيديا نفسها: الكلمة يونانية، وأصلها فيها كلام كتير بين الباحثين، فمش هنجزم بيه هنا."},{"i":"myth-m18","s":60,"h":"المسرح: الإله اللي إدانا التراجيديا","t":"mc","x":"كلمة theatre جاية من فعل معناه إيه؟ ؟ يغني / يتفرج / يشرب / يرقص . يتفرج"},{"i":"myth-m18","s":61,"h":"المسرح: الإله اللي إدانا التراجيديا","t":"tf","x":"التاريخ التقليدي لأول مسابقة تراجيديا هو التاريخ المؤكد. . غلط"},{"i":"myth-m18","s":63,"h":"في روما: باخوس وليبر","t":"learn","x":"الرومان خدوا الإله، وسموه باخوس، وسموه كمان ليبر ( Liber ) يعني \"الحر\". والاسم ده لوحده بيقول لك حاجة عن وظيفته. الليبراليا عيده في ١٧ مارس، والاسم Liberalia . أوفيد في ال Fasti بيقول (ترجمة فريزر): \"اليوم التالت بعد ال Ides هو احتفال شعبي جدا بباخوس.\""},{"i":"myth-m18","s":64,"h":"في روما: باخوس وليبر","t":"learn","x":"وكانوا بيقدموا له كيك من العسل ( liba )، والكيك ده هو أصل اسم العيد عند أوفيد، لأن الكيك بيتقدم على المذبح. وكانت ست كبيرة هي اللي بتقوم بالطقس، وأوفيد بيسأل ليه ست كبيرة، وبيجاوب: \"السن ده أكتر ميل للخمر.\""},{"i":"myth-m18","s":65,"h":"في روما: باخوس وليبر","t":"learn","x":"وفي نفس اليوم، الولد الروماني اللي بيكبر كان بيلبس التوجا الحرة ( toga libera ) لأول مرة، ويبقى راجل رسميا. يعني عيد الإله الحر هو يوم حرية الولد. الباخاناليا والمشكلة الباخاناليا كانت احتفالات ديونيسوس في روما، وفي سنة ١٨٦ ق.م مجلس الشيوخ منعها بمرسوم شديد."},{"i":"myth-m18","s":66,"h":"في روما: باخوس وليبر","t":"learn","x":"ليفي بيحكي الحكاية في الكتاب ٣٩، وبيوصف الطقس إنه بدأ قليل وبعدين بقى جماهيري، وبيحكي عن الليل والخمر والاختلاط، وإنهم كانوا بيعملوا جرائم تحت صوت الطبول. وسواء الكلام ده كله صح أو مبالغ فيه، الدرس واضح: لما الطقس الديني بيخرج من إشراف الدولة، الدولة بتخافه. وده مش عن دين، ده عن سلطة."},{"i":"myth-m18","s":67,"h":"في روما: باخوس وليبر","t":"tf","x":"الليبراليا كانت عيد باخوس في ١٧ مارس. . صح"},{"i":"myth-m18","s":68,"h":"في روما: باخوس وليبر","t":"mc","x":"إيه الدرس من منع الباخاناليا سنة ١٨٦ ق.م؟ ؟ الطقس كان بيشرب بس / الدولة كانت بتحب الطقس / الدولة كانت بتحميه من الأعداء / الدولة بتخاف من الطقس لما يخرج من إشرافها . الدولة بتخاف من الطقس لما يخرج من إشرافها"},{"i":"myth-m18","s":70,"h":"ميادينه","t":"learn","x":"لو شفت أي حاجة من دول في قصيدة، فكر في ديونيسوس على طول 1. الخمر : wine, vintage, grape, vine, cup, bowl, beaker, draught . 2. اللبلاب: ivy, thyrsus, wreath, garland . 3. الجبل: mountain, hill, Cithaeron, Nysa, wild, wood . 4. الرقص والطبول: dance, revel, rout, cymbal, drum, flute, pipe . 5. الجنون: mad, frenzy, ecstasy, possessed, raving ."},{"i":"myth-m18","s":71,"h":"ميادينه","t":"learn","x":"6. الحيوانات: leopard, lion, bear, goat, snake, dolphin . 7. المسرح: mask, stage, scene, actor, tragedy, chorus . 8. الأسماء: Bacchus, Dionysus, Iacchus, Bromios, Liber, Lyaeus ."},{"i":"myth-m18","s":73,"h":"الأسطورة في الشعر الإنجليزي","t":"learn","x":"هنا الجزء اللي الكورس كله عشانه: إزاي الشعراء الإنجليز استعملوا الإله ده. ١) شكسبير، أنطوني وكليوباترا، الفصل ٢ مشهد ٧ المشهد كله على مركب، وكلهم سكرانين، وبينوباربوس بيقود الرقص، والولد بيغني أغنية. والكلمات هي"},{"i":"myth-m18","s":74,"h":"الأسطورة في الشعر الإنجليزي","t":"learn","x":"\" Come, thou monarch of the vine , / Plumpy Bacchus with pink eyne ! / In thy vats our cares be drown'd , / With thy grapes our hairs be crown'd : / Cup us, till the world go round .\" باخوس هنا \"ملك الكرمة\"، وعينيه وردية من الخمر، وهمومهم بتغرق في براميله. والطلب الأخير \"اسقينا لحد ما الدنيا تلف\" هو الطلب الديونيسي الكامل: مش كاس، دوران."},{"i":"myth-m18","s":75,"h":"الأسطورة في الشعر الإنجليزي","t":"learn","x":"وقبلها أنطوني بيقول: \"تعالوا كلنا نمسك إيدين بعض، لحد ما الخمر الغالب يغرق إحساسنا في نسيان ناعم ولطيف.\" وكلمة Lethe هنا مش أي نسيان: هي نهر النسيان في العالم التاني، اللي خدناه في فصل هاديس. يعني شكسبير بيربط الخمر بالعالم التاني في سطر واحد. ٢) ميلتون، كوموس (١٦٣٤) ميلتون بيحكي أصل كوموس، الساحر الشرير، فيقول"},{"i":"myth-m18","s":76,"h":"الأسطورة في الشعر الإنجليزي","t":"learn","x":"\" Bacchus, that first from out the purple grape / Crushed the sweet poison of misused wine \" وبعدها بيسرد حكاية القراصنة بالحرف: \"بعد ما اتحول البحارة التوسكان، وهو بيمشي على شط Tyrrhene ، وقع على جزيرة Circe \" — وست Circe خلفت منه ابن، وهو كوموس."},{"i":"myth-m18","s":77,"h":"الأسطورة في الشعر الإنجليزي","t":"learn","x":"لاحظ إيه اللي عمله ميلتون: خد الترنيمة السابعة، وحولها لأصل عائلة شر. الإله اللي بيكسر الحدود بقى أب لساحر بيكسر شكل الإنسان. وميلتون بيوصف شراب كوموس إنه بيغير وش الشارب لوش وحش، ويسيبه ما يحسش بمسخه. ودي بالظبط فكرة الخمر عند ديونيسوس، بس من الناحية المرعبة. ٣) كيتس، \"قصيدة إلى عندليب\" (١٨١٩)، المقطع التاني"},{"i":"myth-m18","s":78,"h":"الأسطورة في الشعر الإنجليزي","t":"learn","x":"كيتس مش بيسمي باخوس، لكنه بيطلب نفس الطلب \" O, for a draught of vintage ! that hath been / Cool'd a long age in the deep-delved earth , / Tasting of Flora and the country green , / Dance, and Provencal song, and sunburnt mirth !\""},{"i":"myth-m18","s":79,"h":"الأسطورة في الشعر الإنجليزي","t":"learn","x":"\"آه، لكأس من نبيت قديم، مبرد زمان طويل في الأرض المحفورة، طعمه فلورا وخضرة الريف، ورقص، وأغنية بروفنسالية، وضحك شمسه لسعته.\" ودي أهم حاجة تتعلمها من المقطع ده: الخمر عند كيتس مش مشروب، الخمر تجربة كاملة فيها الأرض والريف والرقص والأغنية. وده تعريف ديونيسي مية في المية، من غير ما يتقال اسمه. ٤) ماثيو أرنولد، \"الشريب التائه\" (١٨٤٩)"},{"i":"myth-m18","s":80,"h":"الأسطورة في الشعر الإنجليزي","t":"learn","x":"القصيدة كلها مشهد عند سيرسي: شاب سكران من كاسها، وأولاده بيحكي، وسيرسي بتسأله، وأوليسيس بيطلع في الآخر. والشاب في الآخر بيقول \" The cup again ! / Faster, faster , / O Circe, Goddess .\" وفي وسط القصيدة، أوليسيس بيقول عن الشعراء حاجة تستاهل تتحفظ \" such a price / The Gods exact for song : / To become what we sing .\""},{"i":"myth-m18","s":81,"h":"الأسطورة في الشعر الإنجليزي","t":"learn","x":"\"ده هو التمن اللي الآلهة بتطلبه مقابل الأغنية: إنك تبقى اللي بتغنيه.\" وده أحلى تعليق على الفصل كله: الإله اللي بيكسر الحدود بيدخل في اللي بيحكيه. والشاعر اللي بيغني عن الجنون لازم يعرف الجنون شوية. ٥) ميلتون، الفردوس المفقود ٧.٥"},{"i":"myth-m18","s":82,"h":"الأسطورة في الشعر الإنجليزي","t":"learn","x":"وفي سطر واحد بس، ميلتون بيقول وهو بينادي: \"المعنى، مش الاسم، أنا بينادي.\" وده أنسب سطر لخاتمة قسم الأسماء: الإله ليه عشرين اسم، والمهم اللي هو بيعمله."},{"i":"myth-m18","s":83,"h":"الأسطورة في الشعر الإنجليزي","t":"mc","x":"إيه اللي عمله ميلتون بحكاية القراصنة في كوموس؟ ؟ ألغاها / خلاها كوميديا / خلى كوموس ابن باخوس وسيرسي / خلاها قصة حب . خلى كوموس ابن باخوس وسيرسي"},{"i":"myth-m18","s":84,"h":"الأسطورة في الشعر الإنجليزي","t":"mc","x":"إيه هو Lethe عند شكسبير؟ ؟ نهر النسيان في العالم التاني / اسم مركب / اسم كأس / اسم إله النوم . نهر النسيان في العالم التاني"},{"i":"myth-m18","s":86,"h":"إزاي تعرفها في قصيدة","t":"learn","x":"1. الأسماء: Bacchus ، Dionysus ، Iacchus ، Bromios ، Liber ، Lyaeus . 2. الشراب: wine ، vintage ، grape ، vine ، cup ، beaker ، bowl ، draught ، juice . 3. السكر: drunk ، revel ، rout ، wassail ، pledge ، carouse . 4. الطقس: thyrsus ، ivy ، wreath ، maenad ، Bacchante ، chorus ، cymbal . 5. الجنون: frenzy ، ecstasy ، possessed ، mad ، raving ، transport ."},{"i":"myth-m18","s":87,"h":"إزاي تعرفها في قصيدة","t":"learn","x":"6. المكان: Nysa, Cithaeron, Thebes, India . وهو غالبا بيظهر كفاتح للهند في الروايات المتأخرة. 7. المسرح: mask, scene, tragedy, stage . 8. الفكرة: النسيان، الحرية، الخروج عن النفس، اللي مش ممكن يتحمل."},{"i":"myth-m18","s":89,"h":"سؤال مفتوح","t":"learn","x":"السؤال ده من مستوى أعلى شوية، ومش مطلوب منك جواب نهائي، مطلوب منك تفكير. إزاي إله واحد بيبقى إله الخمر وإله التراجيديا في نفس الوقت؟ فيه تفسير مشهور: التراجيديا ابتدت من الطقوس اللي بتعيد تمثيل موت الإله وبعثه، فالفرح والحزن كانوا في نفس المشهد."},{"i":"myth-m18","s":90,"h":"سؤال مفتوح","t":"learn","x":"بس خد بالك: المدرسة اللي قالت الكلام ده (مدرسة كامبريدج للطقس) اتعرضت لنقد كبير، لأنها بتبسط كل حاجة لطقس واحد. فالتفسير ده احتمال قوي، مش حقيقة مسلمة. وهنشوفه بالتفصيل في M 119. وفيه سؤال تاني جوه السؤال: ليه الإنسان محتاج مهرجان يخرج فيه عن نفسه؟ وليه الحضارة اللي بتمنع ده بتبقى مهددة بالانفجار؟ لو عندك رأي، اكتبه في نص سطر."},{"i":"myth-m18","s":92,"h":"أخطاء شائعة","t":"learn","x":"1. ديونيسوس إله \"الشرب والحفلات\". تبسيط كبير. هو إله الخمر، بس الخمر عنده رمز لحاجة أكبر: الخروج عن النفس. وفي الباكخاي، نصه هو نص عن رفض الإله وعقابه، مش نص عن حفلة. 2. باخوس مجرد اسم تاني لديونيسوس. قريب، بس مش دقيق. باخوس وليبر أسماء رومانية، ولهم مهرجانهم وكهنتهم وسياساتهم (ومنع الباخاناليا سنة ١٨٦ ق.م)، وده مالوش علاقة بطيبة ولا بالباكخاي."},{"i":"myth-m18","s":93,"h":"أخطاء شائعة","t":"learn","x":"3. حكاية الفخذ حرفية عند كل المصادر. لأ. يوريبيديس نفسه، على لسان تيريسياس، بيقول إن الحكاية جاية من تبديل كلمة: رهينة ( homēros ) بدل فخذ ( mēros )."},{"i":"myth-m18","s":94,"h":"أخطاء شائعة","t":"learn","x":"4. زاجريوس هو نفس ديونيسوس في الميثولوجيا العادية. لأ. زاجريوس ابن زيوس وبيرسيفوني في روايات متأخرة، والحكاية بتاعة تقطيعه على إيد التيتاني هي رواية أورفية، وفيه باحثين (زي إدموندز) شايفين إن الصورة المترابطة اللي بنسميها \"أسطورة زاجريوس\" هي تركيب حديث من شذرات. فالروايه تتقال على إنها رواية، مش على إنها القصة."},{"i":"myth-m18","s":95,"h":"أخطاء شائعة","t":"learn","x":"5. المينادات مجرد ستات مجنونة. لأ. المينادات جماعة طقسية ليهم لبس وأدوات وأغاني، والجنون عندهم حالة مقصودة في إطار المهرجان. الفرق بين \"مجنون\" و\"في حالة طقس\" هو الفرق بين المرض والعبادة. 6. منع الباخاناليا كان عن الدين. لأ، كان عن السلطة. ليفي نفسه بيحكي إن التحقيق بدأ من خوف سياسي، والنتيجة كانت مرسوم على كل إيطاليا."},{"i":"myth-m18","s":96,"h":"أخطاء شائعة","t":"tf","x":"حكاية الفخد حرفية عند كل المصادر. . غلط"},{"i":"myth-m18","s":98,"h":"كلمات هتقع لك في الشعر","t":"learn","x":"1. vintage — نبيت قديم / محصول العنب. 2. vine — كرمة. 3. grape — عنب. 4. draught — جرعة / كأس. 5. beaker — كوب كبير. 6. revel — حفلة صاخبة. 7. rout — جماعة صاخبة متحركة. 8. frenzy — جنون مؤقت. 9. ecstasy — خروج عن الذات. 10. possessed — ملبوس / متحكم فيه. 11. ivy — لبلاب. 12. wreath — إكليل. 13. thyrsus — عصاية ديونيسوس."},{"i":"myth-m18","s":99,"h":"كلمات هتقع لك في الشعر","t":"learn","x":"14. maenad / Bacchante — ست من أتباع الإله. 15. chorus — الكورس في المسرح اليوناني. 16. mask — قناع. 17. carouse — يشرب ويعربد. 18. drown — يغرق (الهموم في الخمر)."},{"i":"myth-m18","s":101,"h":"خريطة الفصول الجاية","t":"learn","x":"M 19: بان والحوريات، والطبيعة اللي مش مروضة. M 20: تقليد الدعاء في الشعر الإنجليزي من هوميروس لميلتون. M 21: بيرسيفوني وديميتر، الحكاية كاملة من ناحية الأم. M 33: أورفيوس ويوريديس، وفيها الغناء اللي بيوقف العالم. M 110: شكسبير والأسطورة، وفيه كل استخداماته لباخوس. M 119: مدرسة كامبريدج للطقس، والسؤال المفتوح بتاع الفصل ده."},{"i":"myth-m18","s":103,"h":"ملخص في عشر جمل","t":"learn","x":"1. ديونيسوس إله الخمر والمسرح والجنون الطقسي، واسمه الروماني باخوس أو ليبر. 2. أبوه زيوس وأمه سيميله البشرية، والتوجيني بيقولها في سطر واحد: \"فانية وهي، خالد هو.\" 3. أصل اسمه غير معروف، وتفسير \"زيوس نيسا\" اقتراح مش حقيقة. 4. سيميله ماتت لما زيوس جه لها بصاعقته، والطفل اتحط في فخذ زيوس واتولد تاني."},{"i":"myth-m18","s":104,"h":"ملخص في عشر جمل","t":"learn","x":"5. يوريبيديس نفسه بيفسر حكاية الفخذ بتبديل كلمة: رهينة بدل فخذ. 6. الترنيمة السابعة بتحكي القراصنة: الحبال مامسكتش، والخمر مالت، والكرمة طلعت، والقراصنة بقوا دلافين. 7. الإلياذة فيها أقدم إشارة ليه: ليكورجوس طارد مربياته، والآلهة أعمت ليكورجوس. 8. الباكخاي بتحكي مقاومة بنتيوس، وانتهت بتقطيعه على إيد أمه وهي فاكرة نفسها صيادة."},{"i":"myth-m18","s":105,"h":"ملخص في عشر جمل","t":"learn","x":"9. تيريسياس بيربطه بديميتر: هي إدت الخبز، وهو إدى الخمر والنسيان. 10. المسرح اليوناني كله طلع من مهرجانه، وفي الشعر الإنجليزي شكسبير استعمله للفرح، وميلتون استعمله للخطر."},{"i":"myth-m18","s":107,"h":"مهمتك قبل الفصل الجاي","t":"learn","x":"1. اقرا أغنية شكسبير (\" Come, thou monarch of the vine \") بصوت عالي، ولاحظ إن كل سطر بيخلص بقافية. 2. اكتب في تلات سطور: شكسبير استعمل باخوس عشان إيه، وميلتون استعمله عشان إيه، وإيه الفرق بين الاستعمالين. 3. دور على كلمة Bacchus في أي قصيدة إنجليزية عندك، واكتب جنبها: هل الشاعر بيستعملها للفرح ولا للخطر ولا للاتنين؟"},{"i":"myth-m18","s":108,"h":"مهمتك قبل الفصل الجاي","t":"learn","x":"4. لو عندك وقت: اقرا مشهد القراصنة في الترنيمة السابعة كامل، وهو قصير، وعد المعجزات واحدة واحدة."},{"i":"myth-m18","s":110,"h":"خاتمة","t":"learn","x":"ديونيسوس هو الإله اللي علمنا إن الحضارة مش بس حدود، الحضارة كمان محتاجة لحظات بتكسر حدودها. زيوس بيحكم من فوق، وديميتر بتحمي الأرض، وديونيسوس بيشتغل في المكان اللي فيه الإنسان بيسيب نفسه: الكاس، والرقص، والمسرح، والقناع. ومن غير المكان ده، الإنسان بيمسك نفسه لدرجة إنه ينفجر."},{"i":"myth-m18","s":111,"h":"خاتمة","t":"learn","x":"والحكايات عنه كلها بنفس الشكل: اللي بيقاومه بيتكسر، واللي بيفهمه بيعدي. القراصنة اتحولوا دلافين، وليكورجوس اتعمى، وبنتيوس اتقطع، والربان اترحم عليه. وفي الفصل الجاي، هنقابل إله أهدى بكتير، وبريء أكتر، وبعيد عن المدن: بان، إله الغابة، والحوريات اللي بتعيش معاه. سلام يا عمر، وأشوفك في الفصل التسعتاشر."},{"i":"myth-m18","s":113,"h":"تذكر واكتب","t":"recall","x":"ليه ديونيسوس بيتلقب \"اللي اتولد مرتين\"؟ . لأنه اتولد من سيميله، وبعد ما ماتت اتحط في فخذ زيوس واتولد تاني منه."},{"i":"myth-m18","s":114,"h":"تذكر واكتب","t":"recall","x":"مين اللي اترحم عليه من القراصنة في الترنيمة السابعة، وليه؟ . الدريسون، لأنه كان بيفهم من الأول إنه إله، فالإله قال له إنه لاقى حظوة عنده."},{"i":"myth-m18","s":115,"h":"تذكر واكتب","t":"write","x":"قارن في ٣-٤ جمل بين استخدام شكسبير لباخوس في أنطوني وكليوباترا واستخدام ميلتون له في كوموس. . شكسبير بيخلي باخوس ملكا للكرمة: \" Come, thou monarch of the vine , / Plumpy Bacchus with pink eyne \"، والهموم بتغرق في البراميل، والدعوة إن الدنيا تلف. ميلتون بيسميه من بعيد ويوصف شرابه بالسم الحلو: \" Crushed the sweet poison of misused wine \"، ويخلي ابنه كوموس ساحرا بيغير شكل الشارب. يبدو أن شكسبير بيستعمل الإله للحظة جماعية مؤقتة، وميلتون بيستعمله لتحذير أخلاقي دائم، والاتنين متفقين على إن الخمر بتشيل حد الأنا."},{"i":"myth-m18","s":116,"h":"تذكر واكتب","t":"write","x":"قارن في ٣-٤ جمل بين طلب الخمر عند كيتس في قصيدة إلى عندليب وطلبه عند أرنولد في الشريب التائه. . كيتس بيطلب كأسا بتحمل تجربة كاملة: \" O, for a draught of vintage ! ... Tasting of Flora and the country green , / Dance, and Provencal song, and sunburnt mirth \"، فالخمر عنده أرض ورقص وأغنية. وأرنولد بيخلي الشاب يطلب المزيد من كأس سيرسي: \" The cup again ! / Faster, faster , / O Circe, Goddess \"، فالطلب عنده إدمان، مش صورة. يمكن القول إن الاتنين بيعبروا عن الرغبة نفسها، لكن واحد بيجملها والثاني بيبان فيها الخطر، وده اللي بيفرق بين الرومانتيكي المبكر والرومانتيكي المتشكك."},{"i":"myth-m19","s":1,"h":"إحنا فين في الحكاية","t":"learn","x":"في الفصل اللي فات خدنا ديونيسوس، الإله اللي بيكسر الحدود بين الإنسان ونفسه. والنهارده هنقابل إله مختلف خالص، ومش إله مدينة، ومش إله معبد كبير: بان، إله الجبل والغابة والقطيع. ديونيسوس بيشتغل جوه الإنسان: الخمر والجنون والمسرح. بان بيشتغل بره الإنسان: الجبل، والوحشة، والصوت اللي بيسمعه في الليل ومش عارف مصدره."},{"i":"myth-m19","s":2,"h":"إحنا فين في الحكاية","t":"learn","x":"والفرق ده هو أهم حاجة في الفصل: بان هو أول إله في الكورس ده مش عايز منك حاجة. زيوس عايز طاعة، وأثينا عايزة مدينة منظمة، وأبولو عايز معرفة، وديونيسوس عايزك تسيب نفسك. بان مابيعرضش عليك حاجة، ومابيطلبش منك حاجة. هو بس موجود في المكان، ولو دخلت مكانه بالغلط، هتخاف."},{"i":"myth-m19","s":3,"h":"إحنا فين في الحكاية","t":"tf","x":"الفصل بيقول إن بان إله مابيطلبش من الناس حاجة، عكس زيوس وأثينا. . صح"},{"i":"myth-m19","s":4,"h":"إحنا فين في الحكاية","t":"learn","x":"ومثال من حياتنا: لو مشيت لوحدك في طريق جبلي بعد المغرب، وسمعت صوت حركة في الشجر، جسمك بيتصرف قبل دماغك: قلبك بيزيد، وبتقف مكانك. الصوت ده يمكن يكون طير، يمكن يكون حد، ويمكن مفيش حاجة. الخوف نفسه هو اللي بيخليك تحس إن في حد هناك. اليونانيين حطوا للخوف ده إله، وسموه بان."},{"i":"myth-m19","s":6,"h":"البطاقة الأساسية","t":"learn","x":"الاسم بان ( Pan ) باليوناني، والاسم فضل زي ما هو في اللاتيني. والرومان قربوه من إلههم فاونوس ( Faunus )، إله الغابة والحقول والرعي، وأحيانا كمان من إينوس ( Inuus ) وسيلفانوس ( Silvanus )."},{"i":"myth-m19","s":7,"h":"البطاقة الأساسية","t":"learn","x":"بس ما ادوهوش اسم روماني جديد خاص بيه، زي ما زيوس بقى جوبيتر وأفروديت بقت فينوس. فضل بان. وفيرجيل في الإنيادة ذكر فاونوس وبان جنب بعض كأنهم اتنين، يعني التقريب ده عادة أدبية مش قاعدة ثابتة. ومن اسمه جت كلمة panic ، وهنشوفها تحت بالتفصيل. الشكل راجل من فوق، وتيس من تحت: رجلين وقرنين وشعر كثيف وذقن."},{"i":"myth-m19","s":8,"h":"البطاقة الأساسية","t":"mc","x":"مين أبو بان في الترنيمة الهوميرية ١٩؟ ؟ زيوس / أبولو / هيرميس / ديونيسوس . هيرميس"},{"i":"myth-m19","s":9,"h":"البطاقة الأساسية","t":"learn","x":"مش شكل جميل، وده مقصود. الترنيمة بتقول إن داياته خافت منه ورمته وجريت. ومعاه عصاية راعي، وناي من قصب ( syrinx )، وجلد وشق ( lynx ) على ضهره. العيلة أبوه هيرميس، وأمه بنت دريوپس ( Dryops )، حسب الترنيمة الهوميرية ١٩. وفيه نسخ تانية كتير، هنشوفها في القسم الجاي. المكان أركاديا ( Arcadia )، المنطقة الجبلية في وسط اليونان."},{"i":"myth-m19","s":10,"h":"البطاقة الأساسية","t":"learn","x":"والكهوف والمرتفعات، وأي مكان بعيد عن المدينة. طبيعته إله الرعاة والصيادين والقطيع. وإله الخوف المفاجئ، والوحشة، والصوت اللي ملوش مصدر. وإله الموسيقى كمان: الناي اللي بيصنعه من القصب."},{"i":"myth-m19","s":12,"h":"الاسم: بان والذعر","t":"learn","x":"قبل الحكاية، وقفة على كلمة إنجليزية بتستعملها كل يوم ومش عارف إنها إله. كلمة panic معاجم تأثيل الكلمات بتقول إن الكلمة دخلت الإنجليزي في أول القرن التمنتاشر كاسم، وقبلها كانت صفة من حوالي سنة ١٦٠٠. وجاية من الفرنسي panique ، ومن اليوناني panikon ، ومعناها الحرفي \"بتاع بان\". والأصل في اليوناني هو panikon deima ، يعني \"رعب بان\"."},{"i":"myth-m19","s":13,"h":"الاسم: بان والذعر","t":"tf","x":"كلمة panic جاية من اسم الإله بان. . صح"},{"i":"myth-m19","s":14,"h":"الاسم: بان والذعر","t":"learn","x":"والمعاجم نفسها بتشرح ليه: بان هو إله الغابات والحقول، وهو مصدر الأصوات الغامضة اللي بتسبب خوف جماعي من غير سبب واضح، في القطعان وفي الزحام وفي الأماكن الخالية. يعني لما تقول \"أنا اتخضيت\" بالإنجليزي، أنت حرفيا بتقول \"أنا اتمسكت برعب بان\". والكلمة عاشت ٢٥٠٠ سنة، وفضلت محتفظة باسم الإله اللي جوه منها. تفسير قديم للاسم"},{"i":"myth-m19","s":15,"h":"الاسم: بان والذعر","t":"learn","x":"أفلاطون في محاورة كراتيلوس بيقول إن بان هو \"ابن هيرميس المزدوج الطبيعة\" ( the double-natured son of Hermes )، لأنه نصه إنسان ونصه حيوان. وفي نفس المحاورة بيدي تفسيرا للاسم معناه \"كل\" ( pan يعني \"كل\" باليوناني)، وبيوصله بالكلام: الكلام كله، الحقيقي والكاذب."},{"i":"myth-m19","s":16,"h":"الاسم: بان والذعر","t":"tf","x":"تفسير أفلاطون لمعنى اسم بان حقيقة لغوية مؤكدة. . غلط"},{"i":"myth-m19","s":17,"h":"الاسم: بان والذعر","t":"learn","x":"وخد بالك: ده تفسير أفلاطون، مش حقيقة لغوية. وده مثال تاني على إن الفلاسفة القدام كانوا بيفسروا الأسماء على مزاجهم، والأمانة إنك تقول \"قال أفلاطون\"، مش \"معنى الاسم كذا\"."},{"i":"myth-m19","s":19,"h":"الحكاية: الترنيمة ١٩","t":"learn","x":"الترنيمة الهوميرية ١٩ قصيرة جدا، حوالي ٤٩ سطر، وهي أحلى وصف للإله ده في الأدب القديم. البداية الترنيمة بتفتح: \"أيتها الميوز، احكي لي عن بان، الابن العزيز لهيرميس، بأقدام التيس والقرنين، محب الضجيج المرح.\" يعني أول حاجة بتتقال عنه إنه بيحب الضجيج. مش الحكمة، ولا الحرب، ولا الحب: الصوت العالي. في الجبل"},{"i":"myth-m19","s":20,"h":"الحكاية: الترنيمة ١٩","t":"learn","x":"الترنيمة بتقول: \"في فجوات الغابة بيتجول مع حوريات راقصات بيطأوا على حرف جرف شاهق، بينادوا بان، إله الرعاة، طويل الشعر، أشعث.\" وليه أشعث؟ لأنه مش إله مدينة، مفيش حد بيمشطله شعره. ده إله بيبات في العراء. بالصبح وبالليل بالنهار بيجري على القمم، وبيصطاد الوحوش، وعينه حادة."},{"i":"myth-m19","s":21,"h":"الحكاية: الترنيمة ١٩","t":"learn","x":"وبالليل بيرجع من الصيد، وبينفخ في نايه، والترنيمة بتقول إن مفيش حد بيغلب لحنه، ولا حتى العصفورة اللي بتغني في الربيع. مع الحوريات وبيقول النص: \"في الساعة دي الحوريات ذات الصوت الصافي معاه، وبيتحركوا بأقدام خفيفة، بيغنوا عند عين مية غامقة، وإيكو بتعول حوالين قمة الجبل.\" ووصف الرقص ده مهم: الإله في النص، والحوريات حواليه، وإيكو بعيدة بتكرر الصوت."},{"i":"myth-m19","s":22,"h":"الحكاية: الترنيمة ١٩","t":"mc","x":"ليه الداية جريت وسابت الطفل؟ ؟ لأن شكله كان غريب، بأقدام تيس وقرنين / لأنه كان بيعيط كتير / لأن هيرا خافت منه / لأنه كان بيتكلم . لأن شكله كان غريب، بأقدام تيس وقرنين"},{"i":"myth-m19","s":23,"h":"الحكاية: الترنيمة ١٩","t":"learn","x":"ميلاده هيرميس كان بيرعى غنم عند راجل بشري، لأن حب بنت دريوپس اشتعل فيه. وخلفت له ابن \"من ساعته كان عجبا في الشكل، بأقدام تيس وقرنين، طفل صاخب ضاحك\". والداية شافته، خافت، وقامت جريت وسابته. وهيرميس شاله، ولفه في جلود أرنب جبلي دافية، وطلع به لأوليمبوس، وحطه جنب زيوس، وفرجه على الآلهة."},{"i":"myth-m19","s":24,"h":"الحكاية: الترنيمة ١٩","t":"learn","x":"وكل الآلهة فرحوا، وديونيسوس بالذات، \"وسموا الولد بان لأنه فرح قلوبهم كلها\". والجملة الأخيرة دي مهمة جدا"},{"i":"myth-m19","s":25,"h":"الحكاية: الترنيمة ١٩","t":"mc","x":"كام تفسير اتقال لاسم بان في الفصل؟ ؟ تفسير واحد مؤكد / تلات تفسيرات، ومفيش واحد منهم مؤكد / مفيش أي تفسير / عشرة تفسيرات كلها مؤكدة . تلات تفسيرات، ومفيش واحد منهم مؤكد"},{"i":"myth-m19","s":26,"h":"الحكاية: الترنيمة ١٩","t":"learn","x":"الترنيمة نفسها بتقول إن اسمه جاي من الفرح اللي عمله في قلوب الآلهة. يعني النص القديم بيدي تفسير للاسم، وأفلاطون بيدي تفسير تاني، وفيه تفسير تالت إن الاسم جاي من كلمة \"كل\". تلات تفسيرات، ومفيش واحد منهم مؤكد. وده درس الفصل: الأسطورة نفسها فيها أكتر من سبب للاسم."},{"i":"myth-m19","s":28,"h":"مين أمه؟ النسخ المختلفة","t":"learn","x":"هنا بقى تاخد نفس عميق، لأن الحكاية دي عندها نسخ أكتر من أي إله خدناها قبل كده. النسخة الأولى: هيرميس وبنت دريوپس. ودي نسخة الترنيمة ١٩، وهي أقدم نسخة كاملة. النسخة التانية: هيرميس وثيمبريس ( Thymbris )."},{"i":"myth-m19","s":29,"h":"مين أمه؟ النسخ المختلفة","t":"learn","x":"النسخة التالتة: هيرميس وبينيلوبي ( Penelope )، مرات أوديسيوس. ودي نسخة غريبة، لأنها بتخلي بان ابن مرات البطل، وفيه روايات بتقول إنها خلفته من هيرميس في صورة كبش. النسخة الرابعة: هيرميس لوحده، من غير أم، في محاورة كراتيلوس عند أفلاطون. وإيه اللي نتعلمه من ده؟ إن السؤال \"مين أم بان؟\" مش سؤال ليه جواب واحد، وده مش عيب في المصادر، ده طبيعة الميثولوجيا."},{"i":"myth-m19","s":30,"h":"مين أمه؟ النسخ المختلفة","t":"learn","x":"والأهم: لما شاعر إنجليزي يكتب عن بان، هو مش مضطر يختار نسخة، لأنه أصلا بيتعامل مع إله مالهوش سيرة رسمية موحدة."},{"i":"myth-m19","s":32,"h":"الحوريات: مين هما؟","t":"learn","x":"الفصل عنوانه \"بان والحوريات\"، فلازم نعرف مين الحوريات، لأنهم مش تفصيلة في الحكاية، هما نص الحكاية. الاسم nymph باليوناني معناها الأول \"عروسة\" أو \"زوجة شابة\"، وبعدين بقت \"شابة جميلة\"، وبعدين \"كائن نص إلهي في شكل بنت جميلة\". ومعاجم التأثيل بتقول إن أصل الكلمة مش متأكد، وفيه رأي إنها من لغة أقدم من اليونانية. الأنواع"},{"i":"myth-m19","s":33,"h":"الحوريات: مين هما؟","t":"mc","x":"إيه ال hamadryads ؟ ؟ حوريات البحر / حوريات الجبال / حوريات الأنهار / حوريات بتعيش جوه الشجرة وتموت لما الشجرة تموت . حوريات بتعيش جوه الشجرة وتموت لما الشجرة تموت"},{"i":"myth-m19","s":34,"h":"الحوريات: مين هما؟","t":"learn","x":"dryads : حوريات الشجر، والاسم من كلمة يونانية معناها \"بلوطة\". hamadryads : حوريات بتعيش جوه الشجرة نفسها، وتموت لما الشجرة تموت. naiads : حوريات المية والعيون والأنهار. nereids : حوريات البحر. oreads : حوريات الجبال. وليه دول مهمين في الشعر؟ لأنهم بيملوا المكان. الجبل عند بان مش خالي: فيه حوريات بيرقصوا، وإيكو بتعول، والناي بيغني."},{"i":"myth-m19","s":35,"h":"الحوريات: مين هما؟","t":"learn","x":"ولما شاعر إنجليزي يكتب عن الريف، هو غالبا بيستدعي الحوريات عشان يحول المكان من \"طبيعة\" إلى \"عالم فيه سكان\"."},{"i":"myth-m19","s":37,"h":"إيكو: الصوت اللي بيرد","t":"learn","x":"إيكو ( Echo ) بتظهر في الترنيمة ١٩ في سطر واحد، بس السطر ده مفتاح. النص بيقول إنها \"بتعول حوالين قمة الجبل\". وإيكو في الميثولوجيا هي الحورية اللي اتحولت لصوت بيرد، بعد حكاية مع هيرا، والحكاية الكاملة هتكون في فصل نرسيس وإيكو. وهنا وظيفتها بسيطة: هي الصوت اللي بيرد عليك في الجبل، واللي بيخليك تحس إن في حد معاك."},{"i":"myth-m19","s":38,"h":"إيكو: الصوت اللي بيرد","t":"learn","x":"ولاحظ الربط: إله الخوف، ومعه حورية الصوت اللي بيرد. الاتنين بيعملوا نفس الحاجة: بيخلوا المكان اللي فيه يبان مسكون."},{"i":"myth-m19","s":40,"h":"ليه بان مخيف؟","t":"learn","x":"هنا الجزء اللي بيفسر كل حاجة. أولا: هو إله نصه حيوان اللي نصه حيوان ونصه إنسان مش \"وحش\"، هو كائن على الحد. والحدود هي اللي بتخوف. وشكله نفسه كان صدمة لأمه ولدايته، فالخوف من شكله جزء من الحكاية من أول يوم. ثانيا: هو إله الصوت كل حاجة حواليه صوت: الناي، والصراخ، والضجيج، وإيكو."},{"i":"myth-m19","s":41,"h":"ليه بان مخيف؟","t":"learn","x":"والصوت أخطر من الشكل، لأنك بتشوف الشكل فتتصرف، لكن الصوت بيخليك تتخيل. ثالثا: هو إله الأماكن الخالية القطيع في الجبل، والراعي لوحده، والمسافر في طريق مقطوع. والخوف في المكان الخالي مضاعف، لأن مفيش حد يطمنك. رابعا: كلمة panic نفسها المعاجم بتقول إن الخوف اللي هو مصدره بيجي \"من غير سبب واضح\" ( groundless )، وده أهم وصف."},{"i":"myth-m19","s":42,"h":"ليه بان مخيف؟","t":"learn","x":"يعني الخوف مش من حاجة معينة، الخوف من إن في حاجة. والفرق بين الاتنين هو الفرق بين عقل بيحسب، وجسم بيترعب."},{"i":"myth-m19","s":44,"h":"بان والسياسة: هيرودوت","t":"learn","x":"فيه حكاية عند هيرودوت بتوضح إن بان كان إله حقيقي في حياة المدينة، مش إله أدبي. قبل معركة ماراثون، الأثينيين بعتوا عداء اسمه فيليپيديس لأسبرطة يطلب مساعدة. وفي طريقه، فوق جبل بارثينيوس عند تيجيا، قابله بان. وبان ناداه باسمه، وقال له: اسأل الأثينيين ليه مابيهتموش بيه، وهو صاحب نية حسنة لهم، وساعدهم كتير، وهيساعدهم في المستقبل."},{"i":"myth-m19","s":45,"h":"بان والسياسة: هيرودوت","t":"mc","x":"إيه اللي عمله الأثينيين لبان بعد حكاية فيليپيديس؟ ؟ عملوا له مكان مقدس تحت الأكروبوليس وقرابين وسباق مشاعل / بنوا له معبد في مصر / منعوا عبادته / حرقوا كهفه . عملوا له مكان مقدس تحت الأكروبوليس وقرابين وسباق مشاعل"},{"i":"myth-m19","s":46,"h":"بان والسياسة: هيرودوت","t":"learn","x":"والأثينيين صدقوا الكلام، ولما بقوا في حال كويس عملوا له مكان مقدس تحت الأكروبوليس، وبقوا يقدموا له قرابين كل سنة، وسباق مشاعل. وليه الحكاية دي مهمة؟ لأنها بتوضح إن الإله اللي جاي من الجبل دخل المدينة بالسياسة: الإله اللي كان بيخوف الرعاة بقى حليف في حرب."},{"i":"myth-m19","s":47,"h":"بان والسياسة: هيرودوت","t":"learn","x":"وكلمة \"صاحب نية حسنة\" هنا هي المفتاح: بان مش شرير، هو إله بيطلب اعتراف. زي أي قوة في الطبيعة: لو تجاهلتها، هتضربك، ولو عترفت بيها، هتساعدك."},{"i":"myth-m19","s":49,"h":"\"بان العظيم مات\"","t":"learn","x":"أشهر حكاية عن بان مش عن حياته، عن موته. بلوتارخ بيحكي، في رسالة عن انقطاع الوحي، حكاية سمعها من شيخ اسمه إبيثيرسيس. الحكاية: مركب كان مسافر لإيطاليا، ووقف عند جزيرة صغيرة اسمها باكسي. وفجأة سمعوا صوت بينادي باسم واحد من البحارة، اسمه ثاموس، وكان ملاح مصري. الصوت ناداه مرتين ومردش، وفي التالتة رد."},{"i":"myth-m19","s":50,"h":"\"بان العظيم مات\"","t":"learn","x":"والصوت قال له: لما توصل قدام بالوديس، أعلن إن \"بان العظيم مات\". ولما وصل، والهوا ساكن والبحر هادي، وقف على المؤخرة وقال الجملة. وبمجرد ما خلص، سمعوا عويل كبير، مش من واحد، من ناس كتير. والحكاية وصلت روما، والإمبراطور طيباريوس طلب ثاموس وسأله، وبقى مقتنع بالقصة لدرجة إنه عمل تحقيق. والعلماء اللي حواليه قالوا إن بان ده هو ابن هيرميس وبينيلوبي."},{"i":"myth-m19","s":51,"h":"\"بان العظيم مات\"","t":"mc","x":"مين اللي حكى حكاية \"بان العظيم مات\"؟ ؟ هوميروس / هيرودوت / بلوتارخ / أفلاطون . بلوتارخ"},{"i":"myth-m19","s":52,"h":"\"بان العظيم مات\"","t":"tf","x":"بلوتارخ نفسه قال إن موت بان معناه موت العالم الوثني. . غلط"},{"i":"myth-m19","s":53,"h":"\"بان العظيم مات\"","t":"learn","x":"وإيه معنى الحكاية دي؟ فيه قراءة مسيحية قديمة للحكاية: موت بان = موت العالم الوثني، وميلاد زمن جديد. بس خد بالك: دي قراءة، مش نص. بلوتارخ نفسه مابيقولش كده، هو بيحكي حكاية عن موت كائن نص إلهي. وفيه قراءات حديثة بتقول إن الحكاية عن انقطاع الوحي نفسه، مش عن موت إله."},{"i":"myth-m19","s":54,"h":"\"بان العظيم مات\"","t":"learn","x":"والقصة نفسها فيها تفاصيل غريبة: الصوت، والجزيرة، والملاح المصري. يعني هي حكاية شعبية قبل ما تكون عقيدة."},{"i":"myth-m19","s":56,"h":"أركاديا: البلد اللي مابقاش بلد","t":"learn","x":"أركاديا في اليونان كانت منطقة جبلية فقيرة، رعاة وغنم. ومع الوقت، بقت في الشعر مكان مثالي: طبيعة هادية، رعاة بيغنوا، حب بريء. وده انقلاب كامل: المكان الحقيقي كان خشن وفقير، والمكان الشعري بقى جنة. وبان هو سيد المكان ده في الحالتين: في الحقيقة إله بيخوف الرعاة، وفي الشعر إله بيعزف لهم."},{"i":"myth-m19","s":57,"h":"أركاديا: البلد اللي مابقاش بلد","t":"learn","x":"ودي حاجة تفتكرها في أي قصيدة رعوية إنجليزية: كلمة Arcadia أو صور الرعاة مش بريئة، هي بتستدعي إلها نصه وحش ونصه موسيقى."},{"i":"myth-m19","s":59,"h":"الأسطورة في الشعر الإنجليزي","t":"learn","x":"١) شيلي، \"نشيد بان\" شيلي بيخلي بان هو اللي بيغني، والقصيدة بتبدأ من الأماكن اللي جاي منها \" From the forests and highlands / We come, we come ; / From the river-girt islands , / Where loud waves are dumb / Listening to my sweet pipings .\" يعني: من الغابات والمرتفعات بنيجي، من الجزر اللي حوالينها النهر، حيث الأمواج العالية بتسكت وهي بتسمع نايي الحلو."},{"i":"myth-m19","s":60,"h":"الأسطورة في الشعر الإنجليزي","t":"mc","x":"إيه اللي عمله شيلي في \"نشيد بان\"؟ ؟ خلى بان هو اللي بيغني والطبيعة كلها بتسمع / وصف خوف الناس من بان / حكى موت بان / هاجم عبادته . خلى بان هو اللي بيغني والطبيعة كلها بتسمع"},{"i":"myth-m19","s":61,"h":"الأسطورة في الشعر الإنجليزي","t":"learn","x":"ولاحظ إيه اللي عمله شيلي: الأمواج نفسها بتسكت عشان تسمع. الطبيعة كلها بقت مستمعة، والإله هو اللي بيغني. وده عكس الخوف تماما: نفس الإله، بس من ناحية الفن. ٢) كيتس، \"إنديميون\"، الكتاب الأول في القصيدة، الرعاة بيغنوا ترنيمة لبان، وهي من أحلى وصف للإله في الشعر الإنجليزي"},{"i":"myth-m19","s":62,"h":"الأسطورة في الشعر الإنجليزي","t":"learn","x":"\" O THOU, whose mighty palace roof doth hang / From jagged trunks, and overshadoweth / Eternal whispers, glooms, the birth, life, death / Of unseen flowers in heavy peacefulness \" يعني: يا أنت، اللي سقف قصره العظيم معلق من جذوع خشنة، وبيظلل الهمسات الأبدية، والعتمة، وميلاد وحياة وموت زهور مش باينة، في سكون تقيل."},{"i":"myth-m19","s":63,"h":"الأسطورة في الشعر الإنجليزي","t":"mc","x":"كيتس في \"إنديميون\" وصف إيه؟ ؟ بيت الإله: الغابة نفسها كأنها قصره / شكل الإله / موت الإله / حروب الإله . بيت الإله: الغابة نفسها كأنها قصره"},{"i":"myth-m19","s":64,"h":"الأسطورة في الشعر الإنجليزي","t":"learn","x":"ولاحظ: كيتس مابيوصفش الإله، بيوصف بيته. والقصر هنا هو الغابة نفسها. وده أذكى وصف ممكن: بدل ما تقول \"الإله عايش في الغابة\"، تقول \"الغابة هي قصره\". ٣) إليزابيث باريت براوننج، \"بان الميت\" القصيدة دي مبنية على حكاية بلوتارخ، وبتكرر الجملة زي اللازمة \" Pan, Pan is dead .\""},{"i":"myth-m19","s":65,"h":"الأسطورة في الشعر الإنجليزي","t":"learn","x":"والقصيدة كلها سؤال: الآلهة راحت فين؟ والجواب عندها إن الجمال الحقيقي بقى في مكان تاني، وإن البشر لازم يرفعوا عينهم لفوق. وليه التلاتة دول مهمين مع بعض؟ شيلي بيستعمل بان عشان يقول إن الطبيعة بتسمع. كيتس بيستعمله عشان يقول إن الغابة قصر. وبراوننج بتستعمل موته عشان تقول إن عالم قديم خلص."},{"i":"myth-m19","s":66,"h":"الأسطورة في الشعر الإنجليزي","t":"learn","x":"تلات استعمالات لنفس الإله في تلاتين سنة تقريبا: فن، وطبيعة، وتاريخ."},{"i":"myth-m19","s":68,"h":"إزاي تعرفها في قصيدة","t":"learn","x":"1. الأسماء: Pan ، Arcadia ، Arcadian ، sylvan ، pastoral . 2. الشكل: goat-footed ، two-horned ، shaggy ، bearded ، cloven . 3. الأدوات: pipes ، reeds ، syrinx ، flute ، staff ، crook . 4. المكان: mountain ، glade ، thicket ، cave ، highland ، wilderness . 5. الأصحاب: nymphs ، dryads ، naiads ، oreads ، Echo . 6. الخوف: panic ، terror ، dread ، sudden fear ، haunted ."},{"i":"myth-m19","s":69,"h":"إزاي تعرفها في قصيدة","t":"learn","x":"7. الفكرة: الوحدة، الوحشة، الطبيعة اللي مش مهتمة بيك."},{"i":"myth-m19","s":71,"h":"سؤال مفتوح","t":"learn","x":"السؤال ده للتفكير، مش للإجابة النهائية. ليه الإله اللي بيخوف الناس هو نفسه الإله اللي بيعزف أحلى لحن؟ فيه قراءة بتقول إن الاتنين من نفس المصدر: المكان اللي مش مسيطر عليه. الصوت اللي مش عارف مصدره ممكن يخوفك، ونفس الصوت ممكن يبقى موسيقى، والفرق في اللي بيسمع."},{"i":"myth-m19","s":72,"h":"سؤال مفتوح","t":"learn","x":"وفيه قراءة تانية بتقول إن بان إله الحد: هو على حد الإنسان والحيوان، وحد المدينة والغابة، وحد الصوت والصمت. واللي على الحد بيبقى مخيف وجميل في نفس الوقت. والاتنين قراءات، مش حقائق. اختار واحدة، واكتب ليه."},{"i":"myth-m19","s":74,"h":"أخطاء شائعة","t":"learn","x":"1. بان هو الشيطان في التراث المسيحي. تبسيط. فيه تراث مسيحي ربط الآلهة الوثنية بالشياطين، لكن بان بالتحديد أخد قراءات مختلفة، وفيه قراءة خلت \"بان العظيم مات\" بشارة بميلاد المسيح. فالموضوع أعقد من معادلة واحدة. 2. بان إله \"الطبيعة\". قريب، بس مش دقيق. هو إله الرعاة والقطعان والجبال، ووظيفته في الحياة اليومية كانت عملية: يحمي الغنم، ويخوف اللي يغلط."},{"i":"myth-m19","s":75,"h":"أخطاء شائعة","t":"tf","x":"بان هو نفسه ساتير. . غلط"},{"i":"myth-m19","s":76,"h":"أخطاء شائعة","t":"learn","x":"3. كلمة panic من \"الخوف العام\". لأ، الكلمة من اسم الإله، ومعناها الحرفي \"بتاع بان\". 4. بان هو نفسه ساتير. لأ. الساتير كائنات في حاشية ديونيسوس، وبان إله لوحده، وشكله ثابت من أول يوم، وفيه فرق في الوظيفة والمكان. 5. حكاية موت بان من الكتاب المقدس. لأ، هي من بلوتارخ، وهو كاتب يوناني في القرن الأول الميلادي، والربط بالمسيحية جاء بعدين."},{"i":"myth-m19","s":77,"h":"أخطاء شائعة","t":"learn","x":"6. الحوريات مجرد بنات جميلة في الحكايات. لأ، الحوريات كائنات مرتبطة بمكان محدد، وبعضهم بيموت مع الشجرة بتاعته، وده معناه إن الطبيعة مش ديكور، هي كائنات ليها عمر."},{"i":"myth-m19","s":79,"h":"كلمات هتقع لك في الشعر","t":"learn","x":"1. pastoral — شعري رعوي، عن حياة الرعاة. 2. sylvan — بتاع الغابة. 3. glade — فجوة مفتوحة في الغابة. 4. thicket — شجر كثيف. 5. shaggy — أشعث، كثير الشعر. 6. cloven — مشقوق (زي حوافر التيس). 7. reed — قصب، ومنه الناي. 8. pipes — الناي. 9. nymph — حورية. 10. dryad — حورية شجر. 11. naiad — حورية مية. 12. oread — حورية جبل. 13. echo — صدى."},{"i":"myth-m19","s":80,"h":"كلمات هتقع لك في الشعر","t":"learn","x":"14. dread — رهبة وخوف. 15. haunted — مسكون، فيه حضور غريب. 16. wilderness — خلاء، أرض غير مسكونة."},{"i":"myth-m19","s":82,"h":"خريطة الفصول الجاية","t":"learn","x":"M 20: تقليد الدعاء في الشعر الإنجليزي من هوميروس لميلتون. M 21: بيرسيفوني وديميتر، الحكاية كاملة من ناحية الأم. M 23: بان وسيرينكس، والحورية اللي بقت ناي. M 25: نرسيس وإيكو، والحورية اللي بقت صوت. M 111: ميلتون والأسطورة، وفيه بان في قصيدة الميلاد."},{"i":"myth-m19","s":84,"h":"ملخص في عشر جمل","t":"learn","x":"1. بان إله الجبل والغابة والقطيع، وأبوه هيرميس وأمه بنت دريوپس في الترنيمة ١٩. 2. شكله نصه إنسان ونصه تيس، وداياته خافت منه وسابته. 3. هيرميس لفه في جلود أرنب وطلع به لأوليمبوس، والآلهة فرحوا بيه. 4. الترنيمة نفسها بتقول إن اسمه من الفرح اللي عمله، وأفلاطون بيدي تفسير تاني. 5. كلمة panic جاية من اسمه، ومعناها الحرفي \"رعب بان\"."},{"i":"myth-m19","s":85,"h":"ملخص في عشر جمل","t":"learn","x":"6. هو إله الصوت والوحشة والأماكن الخالية، وخوفه من غير سبب واضح. 7. الحوريات بيملوا مكانه: شجر، ومية، وجبال، وإيكو بتعول حواليه. 8. هيرودوت بيحكي إنه قابل فيليپيديس فوق تيجيا، والأثينيين عملوا له مكان مقدس تحت الأكروبوليس. 9. بلوتارخ بيحكي حكاية \"بان العظيم مات\" على مركب عند جزيرة باكسي."},{"i":"myth-m19","s":86,"h":"ملخص في عشر جمل","t":"learn","x":"10. في الشعر الإنجليزي: شيلي خلى الطبيعة تسمع نايه، وكيتس وصف الغابة كأنها قصره، وبراوننج كتبت موته."},{"i":"myth-m19","s":88,"h":"مهمتك قبل الفصل الجاي","t":"learn","x":"1. اقرا ترنيمة بان مرة واحدة بصوت عالي، وعد الصور اللي فيها. 2. اكتب في تلات جمل: بان بيخوف ليه؟ ولو شيلنا الخوف، إيه اللي يفضل منه؟ 3. دور على كلمة panic في أي نص إنجليزي عندك، ولاحظ إنها بتتقال من غير ما حد يفتكر الإله. 4. لو عندك وقت: قارن بين وصف بان في الترنيمة ووصفه عند كيتس، واكتب الفرق في سطر واحد."},{"i":"myth-m19","s":90,"h":"خاتمة","t":"learn","x":"بان هو الإله اللي علمنا حاجة صعبة: إن الطبيعة مش أم، ومش عدوة، هي مش مهتمة. زيوس بيحكم، وديميتر بتغذي، وديونيسوس بيكسر الحدود، وبان بيسيبك في الجبل لوحدك. ولو خفت، الخوف نفسه هو دليل إنك دخلت مكان مش بتاعك. وفكرة إن كلمة الخوف اليومية في الإنجليزي لسه شايلة اسم إله يوناني، هي أحلى دليل على إن الكورس ده مش عن الماضي: إحنا لسه بنتكلم بلغتهم."},{"i":"myth-m19","s":91,"h":"خاتمة","t":"learn","x":"وفي الفصل الجاي، هنشوف إزاي الشعراء الإنجليز بنوا تقليد الدعاء كله من هوميروس لميلتون، يعني إزاي الشاعر بيطلب المساعدة قبل ما يكتب. سلام يا عمر، وأشوفك في الفصل العشرين."},{"i":"myth-m2","s":0,"h":"","t":"learn","x":"📌 1) يعني إيه قصة خلق؟ كل حضارة قديمة عندها حكاية بتجاوب على أصعب سؤال: \"العالم ده جه منين؟\" مثال من حياتنا: زي ما تلاقي شقتك مكركبة قبل ما تنضفها — حاجات مرمية من غير ترتيب — وبعدين تبتدي ترتب كل حاجة في مكانها. الإغريق شافوا الكون كده بالظبط: كان \"كركبة\" الأول، وبعدين جه الترتيب."},{"i":"myth-m2","s":1,"h":"","t":"learn","x":"المهم للشعر: الشاعر لما يقول \" Chaos \" مش قصده \"زحمة\"، قصده الكلمة القديمة بالمعنى ده: اللاشكل اللي كان قبل كل شكل. 📌 2) Chaos : أول حاجة خالص Hesiod في Theogony (حوالي 700 ق.م) بيقول بالحرف: \" Verily at the first Chaos came to be, but next wide-bosomed Earth. .. and dim Tartarus. .. and Eros ( Love ), fairest among the deathless gods \" ( Theogony 116-120 )"},{"i":"myth-m2","s":2,"h":"","t":"mc","x":"كلمة Chaos في الشعر الإنجليزي القديم معناها الأصلي... ؟ زحمة وضوضاء / حرب / اللاشكل اللي كان قبل كل شكل / فوضى سياسية . اللاشكل اللي كان قبل كل شكل"},{"i":"myth-m2","s":3,"h":"","t":"learn","x":"الترتيب: Chaos الأول، بعده Gaia (الأرض)، بعده Tartarus (الهاوية تحت الأرض)، وبعده Eros (الحب). ليه الحب بدري؟ عشان من غير \"انجذاب\" مفيش حاجة هتتحد مع حاجة ولا حاجة هتتولد. فكرة عبقرية: الحب هو أول قوة خلق. Chaos مش إله بشكل، دي حالة: فجوة/فراغ لانهائي بلا ملامح. ومنها طلع Erebus (الظلام) و Night (الليل)، ومنهم Aether (النور) و Day (النهار)."},{"i":"myth-m2","s":4,"h":"","t":"mc","x":"الترتيب عند Hesiod في Theogony هو... ؟ Chaos ، Gaia ، Tartarus ، Eros / Gaia ، Chaos ، Eros ، Tartarus / Eros ، Chaos ، Gaia ، Tartarus / Chaos ، Eros ، Gaia ، Tartarus . Chaos ، Gaia ، Tartarus ، Eros"},{"i":"myth-m2","s":5,"h":"","t":"learn","x":"📌 3) Gaia و Uranus : أول جواز وأول مشكلة عائلية Gaia (الأرض) ولدت Uranus (السماء) من غير زوج، وبعدين اتجوزته. (في الأساطير ده عادي: الأولين كلهم عيلة واحدة.) ولادتهم:"},{"i":"myth-m2","s":6,"h":"","t":"learn","x":"١) ال Titans ال 12: ستة ولاد وست بنات. Hesiod عدهم بالاسم ( Theogony 133-138 ): Oceanus, Coeus, Crius, Hyperion, Iapetus, Theia, Rhea, Themis, Mnemosyne, Phoebe, Tethys ، وآخرهم Cronos \"أصغرهم وأخطرهم وكان بيكره أبوه\". ٢) ال Cyclopes : عمالقة بعين واحدة، صناع البرق. ٣) ال Hecatoncheires : وحوش بمية إيد."},{"i":"myth-m2","s":7,"h":"","t":"mc","x":"ال Cyclopes هم... ؟ وحوش بمية إيد / عمالقة بعين واحدة وصناع البرق / ست بنات / جبابرة بوجهين . عمالقة بعين واحدة وصناع البرق"},{"i":"myth-m2","s":8,"h":"","t":"learn","x":"Uranus خاف من ولاده وحبسهم جوه الأرض. Gaia اتوجعت وعملت منجل، وقالت لولادها: مين فيكم يعاقب أبوه؟ Cronos الوحيد اللي استجاب: قطع عضو أبوه بالمنجل. من الدم طلعت ال Furies ، ومن العضو اللي اترمى في البحر طلعت Aphrodite. 📌 4) Cronos ياكل ولاده"},{"i":"myth-m2","s":9,"h":"","t":"mc","x":"مين اللي استجاب لطلب Gaia وعاقب أبوه Uranus بالمنجل؟ ؟ Cronos / Zeus / Hades / Poseidon . Cronos"},{"i":"myth-m2","s":10,"h":"","t":"learn","x":"اتنبأ ل Cronos إن ابنه هيعمل فيه زي ما هو عمل في أبوه. فكان بيبلع كل مولود من مراته Rhea أول ما يتولد: Hestia و Demeter و Hera و Hades و Poseidon. مثال من حياتنا: زي ديكتاتور بيخلص من أي منافس محتمل قبل ما يكبر — بس هنا \"المنافسين\" ولاده هو. Rhea زهقت: خبت آخر مولود ( Zeus ) في جزيرة كريت وقدمت له حجر ملفوف في قماط، فبلعه Cronos من غير ما يبص."},{"i":"myth-m2","s":11,"h":"","t":"mc","x":"ليه كان Cronos بيبلع ولاده؟ ؟ كان جعان ومحتاج ياكل / كانت لعبة بين الآلهة / اتنبأ له إن ابنه هيقلعه من العرش / كان بيعاقبهم على عصيانهم . اتنبأ له إن ابنه هيقلعه من العرش"},{"i":"myth-m2","s":12,"h":"","t":"learn","x":"📌 5) ال Titanomachy : حرب الجيلين (عشر سنين) Zeus كبر ورجع، خلى أبوه يرجع إخواته، وأعلن الحرب على ال Titans. الحرب دي اسمها Titanomachy واستمرت عشر سنين ( Hesiod ). Zeus حرر ال Cyclopes من السجن، فشكروه بأجمل هدية في الأساطير: الصاعقة ( thunderbolt ). وحرر ال Hecatoncheires فرموا صخور بمية إيد."},{"i":"myth-m2","s":13,"h":"","t":"mc","x":"ال Titanomachy هي... ؟ حرب الجيلين بين Zeus وال Titans واستمرت عشر سنين / حرب طروادة بين اليونان والطرواديين / رحلة Odysseus للعودة لأيثاكا / حرب Zeus وأخوته ضد العمالقة . حرب الجيلين بين Zeus وال Titans واستمرت عشر سنين"},{"i":"myth-m2","s":14,"h":"","t":"learn","x":"النتيجة: ال Titans اتغلبوا واتحبسوا في Tartarus ، و Atlas (من طرف ال Titans ) اتعاقب بأنه يشيل السما على كتفه للأبد. وبكده اتأسس نظام الأوليمبيين: Zeus سيد السما، Poseidon البحر، Hades العالم السفلي. مثال من حياتنا: جيل بيقلب على جيل: الجد ( Uranus ) قلع عليه الأب ( Cronos )، والأب قلع عليه الابن ( Zeus )."},{"i":"myth-m2","s":15,"h":"","t":"mc","x":"إيه عقاب Atlas بعد الحرب؟ ؟ يتحبس في الجبل للأبد / يتحول لشجرة عالية / يغرق في بحر النسيان / يشيل السما على كتفه للأبد . يشيل السما على كتفه للأبد"},{"i":"myth-m2","s":16,"h":"","t":"learn","x":"القاعدة اللي هتشوفها في كل الأسطورة: اللي بياخد العرش بالقوة بيعيش خايف يتقلع بنفس الطريقة."},{"i":"myth-m2","s":17,"h":"","t":"learn","x":"📌 6) الأسطورة في الشعر الإنجليزي: أ) Ovid بترجمة Arthur Golding (1567) — الترجمة اللي شكسبير نفسه قراها، Metamorphoses الكتاب 1: \" Before the Sea and Lande were made, and Heaven that all doth hide, In all the worlde one onely face of nature did abide, Which Chaos hight, a huge rude heape. ..\""},{"i":"myth-m2","s":18,"h":"","t":"mc","x":"كمل الجملة اللي لسه شايفها: In all the _____ one onely face of nature did abide, ؟ shady / lazy / again / worlde . In all the worlde one onely face of nature did abide,"},{"i":"myth-m2","s":19,"h":"","t":"learn","x":"(\"قبل ما البحر والأرض يتخلقوا، كان في العالم كله شكل واحد للطبيعة، اسمه Chaos : كومة ضخمة خشنة...\") لما تلاقي \" chaos \" عند شكسبير (زي في Othello : \" perdition catch my soul / But I do love thee ! and when I love thee not, / Chaos is come again \") فهو بيستدعي الصورة دي: رجوع الكون لأصله المكركب = انهيار كل نظام."},{"i":"myth-m2","s":20,"h":"","t":"learn","x":"ب) ميلتون، Paradise Lost الكتاب 2: الشيطان بيعدي في رحلته من الجحيم على مملكة: \" eldest Night / And Chaos, ancestors of Nature, hold / Eternal Anarchy \" ( PL 2.894-896 ) ميلتون حول Chaos لمكان وملك: Chaos والليل \"أجداد الطبيعة\" حاكمين فوضى أبدية. الصورة الإغريقية بقت جزء من جغرافيا ملحمة مسيحية."},{"i":"myth-m2","s":21,"h":"","t":"learn","x":"ج) Keats ، بداية ملحمته \" Hyperion \" (1818-19) عن سقوط ال Titans : \" Deep in the shady sadness of a vale Far sunken from the healthy breath of morn, Far from the fiery noon, and eve's one star, Sat gray-hair'd Saturn, quiet as a stone \""},{"i":"myth-m2","s":22,"h":"","t":"mc","x":"في Hyperion ل Keats ، إيه الاسم الروماني ل Cronos ؟ ؟ Saturn / Mars / Jupiter / Neptune . Saturn"},{"i":"myth-m2","s":23,"h":"","t":"learn","x":"Saturn هو الاسم الروماني ل Cronos : الملك المخلوع قاعد في الوادي \"ساكن زي الحجر\". Keats خد حرب الجيلين وعملها تراجيديا عن الجيل القديم اللي لازم يروح عشان الجديد ييجي."},{"i":"myth-m2","s":24,"h":"","t":"learn","x":"📌 7) كلمات إنجليزي من درس النهارده: chaos / chaotic (مش \"زحمة\" — معناها الأصلي اللاشكل) • titan / titanic / titanium • Uranus (الكوكب) • Gaia (وكلمة geography و geology من نفس الجذر) • erotic من Eros. ✏️ كويز M2 (بعد ٣٠ دقيقة): ١) رتب دول حسب الظهور عند Hesiod : Eros, Chaos, Titans, Gaia. وليه ترتيبهم مهم؟"},{"i":"myth-m2","s":25,"h":"","t":"learn","x":"٢) احك قصة \"الحجر الملفوف\" وبين إيه القاعدة المتكررة في أجيال الحكم. ٣) إيه الفرق بين معنى \" chaos \" في الشارع ومعناها في الشعر؟ ادي مثال Othello. ٤) ليه Keats اختار Saturn مش Zeus بطل لملحمته؟ وإيه الفكرة اللي بيعبر عنها؟ ٥) ترجم واشرح سطرين Golding عن Chaos ، وقول ليه الترجمة دي بالذات مهمة لطالب أدب إنجليزي."},{"i":"myth-m2","s":27,"h":"تذكر واكتب","t":"recall","x":"رتب دول حسب ظهورهم عند هسيود: Chaos و Gaia و Eros و Titans . . Chaos الأول، وبعده Gaia و Eros ، والتيتانز بعدهم من اتحاد Gaia و Uranus . الترتيب مهم لأنه بيوضح إن العالم بدأ بفراغ، وبعدين اتشكل، وبعدين جاء الحكم."},{"i":"myth-m2","s":28,"h":"تذكر واكتب","t":"recall","x":"إيه الحيلة اللي عملتها ريا عشان تنقذ زيوس من كرونوس؟ . لفت حجر في قماش وسلمته لكرونوس بدل الطفل، فبلعه. وزيوس اتربى في الخفاء، ولما كبر رجع إخوته وخلصهم."},{"i":"myth-m2","s":29,"h":"تذكر واكتب","t":"write","x":"قارن في ٣-٤ جمل بين صورة الإله المخلوع عند Keats في Hyperion وصورة Chaos عند ميلتون في Paradise Lost 2.894-896. . في Hyperion بيقدم Keats الإله المخلوع بصورته الساكنة: \" Sat gray-hair'd Saturn, quiet as a stone \"، فالملك القديم بقى جزء من المنظر، مش فاعل فيه. أما ميلتون فيحول Chaos لمكان له حكام: \" eldest Night / And Chaos, ancestors of Nature, hold / Eternal Anarchy \" (٢.٨٩٤-٨٩٦). يبدو أن الاتنين بيستعملوا الجيل القديم عشان يتكلموا عن لحظة انتقال: عند Keats الانتقال حزن هادي، وعند ميلتون فوضى ليها نظام."},{"i":"myth-m2","s":30,"h":"تذكر واكتب","t":"write","x":"قارن في ٣-٤ جمل بين وصف Chaos في ترجمة Golding ل Ovid ووصفه عند ميلتون في الكتاب 2. . عند Golding ال Chaos كتلة بلا شكل: \" a huge rude heape \"، والوصف كوني وعام، ووظيفته إنه يقول للقارئ إيه اللي كان قبل الخلق. ميلتون بياخد نفس الكلمة ويعملها إقليم له حدود وحكام، ومحطة في رحلة الشيطان من الجحيم، فال Chaos بقى مكان على خريطة. يمكن القول إن الترجمة بتوصف أصل العالم، والملحمة بتوظف نفس الصورة في جغرافيا مسيحية. الفرق مش في الكلمة، الفرق في الشغل اللي بيتعمله بيها."},{"i":"myth-m20","s":1,"h":"إحنا فين في الحكاية","t":"learn","x":"في الفصل اللي فات قابلنا بان، الإله اللي مابيرد عليك ومابيسألش عنك. النهارده هنعمل العكس: هنقابل ربة بترد. دي الميوز ( Muse )، والشاعر بيناديها في أول القصيدة وبيقولها \"احكي أنت\". وده مش فصل عن حكاية واحدة. ده فصل عن عادة: أول سطر في أغلب الملاحم بيبقى طلب مساعدة. والعادة دي اسمها الاستدعاء ( invocation )."},{"i":"myth-m20","s":2,"h":"إحنا فين في الحكاية","t":"learn","x":"مثال من حياتنا: قبل ما حد يفتح مشروع كبير، بيقول \"بسم الله\". هو مش بيقول معلومة، هو بيعلن مين اللي بيتكل عليه. الاستدعاء في الشعر كده بالظبط."},{"i":"myth-m20","s":4,"h":"يعني إيه استدعاء؟","t":"learn","x":"التعريف البسيط الاستدعاء هو إن الشاعر في أول القصيدة يطلب من ربة أو قوة أعلى إنها تساعده يحكي. والكلمة بالإنجليزي invocation . فيه تلات حاجات نداء: \"غني يا ربة\" أو \"احكي لي\". موضوع: الشاعر بيقول هو عايز يحكي عن إيه. اعتراف: الشاعر بيقول ضمنيا إنه لوحده مش كفاية. مثال من الحياة"},{"i":"myth-m20","s":5,"h":"يعني إيه استدعاء؟","t":"learn","x":"طالب بيقف قدام لجنة المناقشة ويقول \"بعد إذن حضراتكم\". هو بيطلب إذن، وبيحدد هيتكلم في إيه، وبيعترف إن اللجنة أعلى منه."},{"i":"myth-m20","s":7,"h":"مين الميوز؟","t":"learn","x":"الأصل الميوز تسع ربات، بنات زيوس ومنيموسيني ( Mnemosyne )، ربة الذاكرة. ده اللي عرفناه من الفصل الأول. كلمة Muse جاية من اليوناني Mousa ، ومعناها كمان \"موسيقى وغنا\". وجذرها البعيد معناه \"يفكر\". مين بتعمل إيه"},{"i":"myth-m20","s":8,"h":"مين الميوز؟","t":"learn","x":"فيه قايمة تقليدية بتخصص كل واحدة في فن: كاليوبي ( Calliope ) للشعر الملحمي، وكليو ( Clio ) للتاريخ، وإيراتو ( Erato ) لشعر الحب، ويوتيربي ( Euterpe ) للموسيقى، وميلبومين ( Melpomene ) للمأساة، وبوليمنيا ( Polymnia ) للترانيم، وتيربسيكور ( Terpsichore ) للرقص، وتاليا ( Thalia ) للكوميديا، ويورانيا ( Urania ) للفلك."},{"i":"myth-m20","s":9,"h":"مين الميوز؟","t":"learn","x":"خد بالك: دي القايمة التقليدية. الشعراء القدام ما كانوش دايما بيحددوا ميوز بعينها، وده هيبان في الأمثلة تحت. ليه الذاكرة؟ أمهم ربة الذاكرة، وده منطقي: الشاعر القديم كان بيحفظ ويحكي بصوته. الذاكرة هي اللي بتخلي الحكاية تعيش."},{"i":"myth-m20","s":11,"h":"هوميروس: الاستدعاء الأصلي","t":"learn","x":"الإلياذة أول سطر في الإلياذة \" Sing, O goddess, the anger of Achilles son of Peleus, that brought countless ills upon the Achaeans .\" يعني: غني يا ربة غضب أخيل ابن بيليوس، اللي جاب على الأخيين مصايب لا تتعد. الأوديسة أول جملة في الأوديسة"},{"i":"myth-m20","s":12,"h":"هوميروس: الاستدعاء الأصلي","t":"mc","x":"في أول الإلياذة، الشاعر بيقول إيه للربة؟ ؟ عرفيني يا ربة بطل الأوديسة / غني يا ربة غضب أخيل / احكي لي عن الراجل الذكي / ياريت عندي ميوز من نار . غني يا ربة غضب أخيل"},{"i":"myth-m20","s":13,"h":"هوميروس: الاستدعاء الأصلي","t":"learn","x":"\" Tell me, O muse, of that ingenious hero who travelled far and wide after he had sacked the famous town of Troy .\" يعني: احكي لي يا ميوز عن البطل الذكي اللي سافر بعيد بعد ما خرب مدينة طروادة الشهيرة. وبعد شوية بيعيد الطلب بجملة : \" Tell me, too, about all these things, O daughter of Jove \". يعني: احكي لي كمان عن كل ده يا بنت جوف. ولاحظ إيه"},{"i":"myth-m20","s":14,"h":"هوميروس: الاستدعاء الأصلي","t":"learn","x":"الشاعر بيقول \"غني\" و\"احكي لي\". الأمر موجه للربة. هو مش هيحكي من دماغه، هو هيكون صوت. في الإلياذة الموضوع هو \"الغضب\". وفي الأوديسة الموضوع هو \"الراجل\". ده الفرق بين الحكايتين من أول سطر. ترجمة بتلر نثر، مش شعر. ففيه ترجمات تانية بتختلف في الكلمات، والمعنى واحد."},{"i":"myth-m20","s":16,"h":"هسيود: الميوز بتختار الشاعر","t":"learn","x":"الحكاية في الثيوجونيا ( Theogony )، هسيود بيقول إن الميوز علمته الغنا وهو بيرعى غنمه تحت جبل هيليكون ( Helicon ). اللي قالته الميوز بترجمة إيفلين وايت ( Evelyn-White ) \" Shepherds of the wilderness, wretched things of shame, mere bellies, we know how to speak many false things as though they were true; but we know, when we will, to utter true things .\""},{"i":"myth-m20","s":17,"h":"هسيود: الميوز بتختار الشاعر","t":"learn","x":"يعني: يا رعاة البرية، يا عار، يا بطون وبس: إحنا نعرف نقول أكاذيب كتير كأنها حقيقة، ونعرف لما نحب نقول الحقيقة. والهدية الميوز \" plucked and gave me a rod, a shoot of sturdy laurel \" يعني قطفوا له غصن لورد قوي وادوه له، و\" breathed into me a divine voice \" يعني نفخوا فيه صوت إلهي. ليه ده مهم؟"},{"i":"myth-m20","s":18,"h":"هسيود: الميوز بتختار الشاعر","t":"learn","x":"أول مرة الشاعر بيقول إيه سر سلطته: الميوز اختارته. هو مش شاعر لأنه تعلم، هو شاعر لأنه اتختار. والميوز بتعترف إنها ممكن تكذب. يعني الاستدعاء مش ضمان إن الكلام حقيقي. ده نقطة ممتازة للشاعر الأذكى بعدين. مثال: لو واحد قالك \"أنا موصي من الوزير\"، ده بيدي سلطة، بس ما بيثبتش إن الكلام صح."},{"i":"myth-m20","s":19,"h":"هسيود: الميوز بتختار الشاعر","t":"mc","x":"مين اللي حكى إن الميوز ادته غصن لورد وصوت إلهي؟ ؟ هسيود في الثيوجونيا / فيرجيل في الإنيادة / شكسبير في هنري الخامس / أوفيد في التحولات . هسيود في الثيوجونيا"},{"i":"myth-m20","s":20,"h":"هسيود: الميوز بتختار الشاعر","t":"tf","x":"عند هسيود، الشاعر شاعر لأنه اتختار من الميوز. . صح"},{"i":"myth-m20","s":22,"h":"فيرجيل: الاستدعاء بعد ما اتكتبت الحكاية الأولى","t":"learn","x":"الإنيادة \" I sing of arms and the man, he who, exiled by fate, first came from the coast of Troy to Italy \" يعني: أغني الحرب والراجل اللي نفاه القدر وجه من ساحل طروادة لإيطاليا. وبعد كام سطر بيطلب: \" Muse, tell me the cause \". يعني: يا ميوز احكي لي السبب. الفرق عن هوميروس"},{"i":"myth-m20","s":23,"h":"فيرجيل: الاستدعاء بعد ما اتكتبت الحكاية الأولى","t":"learn","x":"فيرجيل بيبدأ ب \"أنا بغني\" مش ب \"غني يا ربة\". هو بيحط نفسه قبل الميوز. وبعدين يطلب منها تحكي السبب. ممكن نقرأ ده إن الميوز عنده بتشرح اللي ورا الأحداث، مش بس بتحكيها. ليه ده مهم للشعر الإنجليزي؟ الشعراء الإنجليز بيتعلموا إن الاستدعاء قاعدة بتتوارث، وفيرجيل هو اللي حطها في شكلها اللاتيني اللي الإنجليز اتعلموه."},{"i":"myth-m20","s":24,"h":"فيرجيل: الاستدعاء بعد ما اتكتبت الحكاية الأولى","t":"tf","x":"فيرجيل بيبدأ الإنيادة ب \"غني يا ربة\" زي هوميروس بالظبط. . غلط"},{"i":"myth-m20","s":26,"h":"سبنسر: الشاعر بيغير سلاحه","t":"learn","x":"الفيري كوين ( The Faerie Queene )، الكتاب الأول، القصيدة الأولى أول سطر \" Lo I the man, whose Muse whilome did maske , / As time her taught in lowly Shepheards weeds , / Am now enforst a far unfitter taske , / For trumpets sterne to chaunge mine Oaten reeds , / And sing of Knights and Ladies gentle deeds ;\""},{"i":"myth-m20","s":27,"h":"سبنسر: الشاعر بيغير سلاحه","t":"learn","x":"بالعربي البسيط: أنا الراجل اللي ميوزه كانت زمان متخفية في لبس الرعاة. دلوقتي مضطر أعمل شغل أكبر من قدي: أبدل ناي الشعير ببوق الحرب، وأغني عن الفرسان والسيدات. الفكرة سبنسر بيقول: أنا بدأت شاعر رعاة (قصايد ريفية)، ودلوقتي ببدأ ملحمة."},{"i":"myth-m20","s":28,"h":"سبنسر: الشاعر بيغير سلاحه","t":"learn","x":"يعني الاستدعاء عنده بيقول لقرائه: أنا بتحرك لنوع أكبر، زي ما فيرجيل اتحرك. مثال: واحد بدأ بكتابة مقالات صغيرة، وبعدين بدأ يكتب كتاب كبير. وكلمة \" Oaten reeds \" ناي من القش، رمز للشعر الريفي. وده بيفكرنا ببان وناي القصب في الفصل اللي فات."},{"i":"myth-m20","s":30,"h":"شكسبير: الميوز اللي مش موجودة","t":"learn","x":"هنري الخامس، المقدمة ( Prologue ) أول سطر \" O for a Muse of fire, that would ascend / The brightest heaven of invention , / A kingdom for a stage, princes to act , / And monarchs to behold the swelling scene !\" يعني: ياريت عندي ميوز من نار، تطلع لأعلى سما الخيال، ومملكة تبقى مسرح، وأمراء يمثلوا، وملوك يتفرجوا على المشهد الكبير. اللي بيحصل هنا"},{"i":"myth-m20","s":31,"h":"شكسبير: الميوز اللي مش موجودة","t":"learn","x":"شكسبير بيقول \"ياريت\". يعني هو بيتمنى، مش بيطلب بثقة. والسبب إن المسرح صغير: الكلام بعده بيقول إن الممثلين \" flat unraised spirits \" وإن المسرح \" wooden O \". الميوز المطلوبة عشان الموضوع أكبر من المكان. وده تحويل ذكي: الاستدعاء بقى اعتراف بالنقص، ومعه دعوة للجمهور إنه يكمل بخياله."},{"i":"myth-m20","s":32,"h":"شكسبير: الميوز اللي مش موجودة","t":"mc","x":"شكسبير في مقدمة هنري الخامس بيطلب إيه؟ ؟ ميوز سماوية بجناحين / ميوز الفلك والنجوم / ميوز من نار / ميوز الأغاني الشعبية . ميوز من نار"},{"i":"myth-m20","s":34,"h":"ميلتون: الميوز اللي بقت روح","t":"learn","x":"ده أهم جزء في الفصل، فخد وقتك. الكتاب الأول، السطور ١-٦ (النص الأصلي بتهجئة طبعة ١٦٧٤ ) \" OF Mans First Disobedience, and the Fruit / Of that Forbidden Tree, whose mortal tast / Brought Death into the World, and all our woe , / With loss of Eden, till one greater Man / Restore us, and regain the blissful Seat , / Sing Heav'nly Muse \""},{"i":"myth-m20","s":35,"h":"ميلتون: الميوز اللي بقت روح","t":"learn","x":"يعني: عن أول عصيان للإنسان وثمرة الشجرة الممنوعة اللي طعمها القاتل جاب الموت للدنيا وكل أحزاننا، مع ضياع عدن، لحد ما راجل أعظم يرجعنا ونرجع المكان السعيد. غني يا ميوز سماوية. خد بالك من التفاصيل الجملة الأولى طويلة جدا، وفعلها (\" Sing \") ما بيجيش إلا في السطر السادس. ده أسلوب ميلتون: بيخليك تستنى."},{"i":"myth-m20","s":36,"h":"ميلتون: الميوز اللي بقت روح","t":"learn","x":"\" Heav'nly Muse \" يعني ميوز سماوية، مش ميوز جبل أوليمبوس. بعدها بيوضح مين هي بيقول إنها هي اللي ألهمت \" That Shepherd \" (الراعي، يعني موسى) على قمة جبل حوريب أو سيناء."},{"i":"myth-m20","s":37,"h":"ميلتون: الميوز اللي بقت روح","t":"learn","x":"وبعدين : \" And chiefly Thou, O Spirit, that dost prefer / Before all Temples th' upright heart and pure , / Instruct me \". يعني: وأنت يا روح، اللي بتفضل القلب المستقيم على كل المعابد، علميني. ناس كتير بتقرأ الميوز عنده على إنها الروح القدس أو قريبة منه، وده تفسير مش نص صريح. المهم إن الاستدعاء اليوناني اتحول لدعاء ديني. الهدف بتاعه (السطور ٢٤-٢٦)"},{"i":"myth-m20","s":38,"h":"ميلتون: الميوز اللي بقت روح","t":"learn","x":"\" That to the highth of this great Argument / I may assert Eternal Providence , / And justifie the wayes of God to men .\" يعني: عشان أوصل لعلو الموضوع العظيم ده، وأثبت العناية الإلهية الأبدية، وأبرر طرق الله للناس. ولاحظ كلمة \" justifie \": ميلتون بيقول إنه هيدافع عن الله قدام البشر. ده مشروع ضخم، وده سبب إنه محتاج ميوز أكبر من اللي عند هوميروس."},{"i":"myth-m20","s":39,"h":"ميلتون: الميوز اللي بقت روح","t":"learn","x":"وكمان ميلتون بيقول إنه بيتخطى اليونان بيقول إن غنوته \" adventrous Song \" بتطير \" no middle flight \" فوق \" Aonian Mount \" (جبل الميوز) وبتحاول \" Things unattempted yet in Prose or Rhime \". يعني: حاجات محدش جربها لسه لا في النثر ولا في الشعر."},{"i":"myth-m20","s":41,"h":"ميلتون تاني: يورانيا","t":"learn","x":"الكتاب السابع، السطور ١-٦ \" DEscend from Heav'n Urania, by that name / If rightly thou art call'd, whose Voice divine / Following, above th' Olympian Hill I soare , / Above the flight of Pegasean wing . / The meaning, not the Name I call: for thou / Nor of the Muses nine, nor on the top / Of old Olympus dwell'st \""},{"i":"myth-m20","s":42,"h":"ميلتون تاني: يورانيا","t":"learn","x":"يعني: انزلي من السما يا يورانيا، لو ده اسمك الصح. أنا ماشي ورا صوتك الإلهي فوق جبل أوليمبوس وفوق طيران الحصان المجنح. أنا بنادي المعنى مش الاسم، لأنك مش من التسع ميوز ولا ساكنة قمة أوليمبوس القديم. ليه ده مهم ميلتون بيستعمل اسم يوناني (يورانيا) وفي نفس الوقت بيقول \"أنا مش قصدي الاسم\". هو بيقول: الاسم قديم، لكن المعنى أعلى منه."},{"i":"myth-m20","s":43,"h":"ميلتون تاني: يورانيا","t":"tf","x":"ميلتون بيقول إن يورانيا واحدة من التسع ميوز. . غلط"},{"i":"myth-m20","s":44,"h":"ميلتون تاني: يورانيا","t":"learn","x":"وده مثال ممتاز على المزج بين التراث اليوناني والديني، وهو موضوع الفصل ١١١. والكلام عن حاله \" Standing on Earth, not rapt above the Pole , / More safe I Sing with mortal voice, unchang'd / To hoarce or mute, though fall'n on evil dayes , / On evil dayes though fall'n, and evil tongues ;\""},{"i":"myth-m20","s":45,"h":"ميلتون تاني: يورانيا","t":"learn","x":"يعني: واقف على الأرض مش مرفوع فوق القطب، وبغني بصوت بشري أأمن، من غير ما يتحول لبحة أو صمت، حتى لو وقعت في أيام شريرة وألسنة شريرة. (السطر ٢٣ في الكتاب السابع.) فكرة: الشاعر بيعترف إنه بقى أقرب للأرض، وإنه بيخاف يقع زي بيليروفون ( Bellerophon ) اللي وقع من الحصان المجنح. وده نفس الاستدعاء بنبرة تانية: قلق وتواضع."},{"i":"myth-m20","s":47,"h":"الرومانسيين: الشاعر بقى هو الآلة","t":"learn","x":"شيلي، \"قصيدة إلى ريح الغرب\"، المقطع الخامس \" Make me thy lyre, even as the forest is : / What if my leaves are falling like its own !\" يعني: خليني قيثارتك زي ما الغابة قيثارتك. إيه يعني لو ورقي بيقع زي ورقها. وبعدها : \" Be thou, Spirit fierce , / My spirit ! Be thou me, impetuous one !\" يعني: كوني أنت روحي، كوني أنا يا قوة اندفاع."},{"i":"myth-m20","s":48,"h":"الرومانسيين: الشاعر بقى هو الآلة","t":"learn","x":"الفرق عن الاستدعاء القديم عند هوميروس: \"غني أنت\". عند شيلي: \"خليني أنا الأداة، وغني من خلالي\". يعني الشاعر ما بقاش بينادي ربة من بره، بقى بيطلب إن قوة الطبيعة تعدي من جواه. مثال: بدل ما تدي الميكروفون لحد، انت اللي بتبقى الميكروفون. كيتس، \"سقوط هايبيريون\"، الكانتو الأول في الحلم، الشاعر بيسمع من شخصية بتكلمه الجملة دي"},{"i":"myth-m20","s":49,"h":"الرومانسيين: الشاعر بقى هو الآلة","t":"mc","x":"في \"قصيدة إلى ريح الغرب\"، شيلي بيطلب إيه؟ ؟ خليني قيثارتك / إن الريح تحمل أغنيته / إن الريح تبقى ميوزه / إن الريح تسكت . خليني قيثارتك"},{"i":"myth-m20","s":50,"h":"الرومانسيين: الشاعر بقى هو الآلة","t":"learn","x":"\" The poet and the dreamer are distinct , / Diverse, sheer opposite, antipodes . / The one pours out a balm upon the world , / The other vexes it .\" يعني: الشاعر والحالم مختلفين، متضادين تماما. واحد بيسكب بلسم على العالم، والتاني بيضايقه. وده سؤال جديد: مش مين بيلهمك، لكن إنت شاعر ولا حالم؟ الإلهام وحده مش كفاية."},{"i":"myth-m20","s":52,"h":"الأسطورة في الشعر الإنجليزي","t":"learn","x":"١) ميلتون، الفردوس المفقود، الكتاب الأول، ٦ و٢٤-٢٦ \" Sing Heav'nly Muse \" / \" That to the highth of this great Argument / I may assert Eternal Providence , / And justifie the wayes of God to men .\" الميوز عنده سماوية، والغرض لاهوتي. ٢) ميلتون، الفردوس المفقود، الكتاب السابع، ١ و٢٣"},{"i":"myth-m20","s":53,"h":"الأسطورة في الشعر الإنجليزي","t":"learn","x":"\" DEscend from Heav'n Urania \" / \" Standing on Earth, not rapt above the Pole \" الاسم يوناني والمعنى أعلى من الاسم. ٣) سبنسر، الفيري كوين، الكتاب الأول، الكانتو الأول، المقطع الأول \" Lo I the man, whose Muse whilome did maske \" الشاعر بيقدم نفسه وبيقول إنه بيغير النوع. ٤) شكسبير، هنري الخامس، المقدمة"},{"i":"myth-m20","s":54,"h":"الأسطورة في الشعر الإنجليزي","t":"learn","x":"\" O for a Muse of fire, that would ascend / The brightest heaven of invention \" الميوز مطلوبة بتمني. ٥) شيلي، قصيدة إلى ريح الغرب، المقطع الخامس \" Make me thy lyre, even as the forest is \" الشاعر آلة بدل ما يبقى منادي. الخلاصة بتاعت التطور هوميروس: غني يا ربة. فيرجيل: أنا بغني، وقولي السبب. ميلتون: الميوز بقت روح سماوية. شيلي: خليني آلة."},{"i":"myth-m20","s":55,"h":"الأسطورة في الشعر الإنجليزي","t":"learn","x":"وكل مرة، الشاعر بيختار مين اللي بيرد عليه، وده اختيار تراث."},{"i":"myth-m20","s":57,"h":"إزاي تعرفها في قصيدة","t":"learn","x":"أول سطور القصيدة: دور على أمر موجه لربة ( Sing, Tell, Muse, Goddess, Spirit ). دور على كلمة نداء مع O أو Lo . لو الاستدعاء موجود، اسأل: الشاعر بيطلب من مين؟ ليه؟ وبيعترف بإيه؟ لو الاستدعاء بيتمنى (\" O for \") يبقى الشاعر بيعترف بنقص. لو الاستدعاء بيطلب الشاعر نفسه يبقى الأداة، فده تقليد رومانسي."},{"i":"myth-m20","s":59,"h":"سؤال مفتوح","t":"learn","x":"ليه الشعراء بعد هوميروس ما بطلوش الاستدعاء حتى لما بطلوا يصدقوا في الميوز؟ فكر في الجواب: هل هو تقليد، أو اختيار انتماء، أو لعبة أدبية؟ مفيش جواب واحد متفق عليه، وده سؤال بتتحاسب عليه في الامتحان بحجتك."},{"i":"myth-m20","s":61,"h":"أخطاء شائعة","t":"learn","x":"مش كل ميوز اسمها ميوز: ميلتون بيستعمل \" Heav'nly Muse \" ويورانيا وبيقول إنها مش من التسع. الاستدعاء مش ضمان إن الكلام حقيقي: الميوز عند هسيود بتقول إنها ممكن تكذب. ترجمة بتلر نثر. ما تقولش إنها \"شعر هوميروس بالحرف\"."},{"i":"myth-m20","s":63,"h":"كلمات هتقع لك في الشعر","t":"learn","x":"invocation : استدعاء. Muse : ربة الإلهام، والكلمة بالحرف الصغير muse معناها كمان \"يتأمل\". epic : ملحمة. argument : موضوع القصيدة (عند ميلتون \" great Argument \"). inspire : يلهم، وأصله \"ينفخ\". Providence : العناية الإلهية. Heav'nly : سماوي. lyre : قيثارة. adventrous : مغامر (بتهجئة ميلتون)."},{"i":"myth-m20","s":65,"h":"خريطة الفصول الجاية","t":"learn","x":"الفصل ٢١: بيرسيفوني وديميتر، حكاية الأم والبنت. الفصل ٢٢: أبولو وداڤني. الفصل ٢٣: بان وسيرينكس، ناي القصب. من هنا بنقفل المستوى التاني وبنبدأ حكايات الحب والتحول."},{"i":"myth-m20","s":67,"h":"ملخص في عشر جمل","t":"learn","x":"١. الاستدعاء هو طلب الشاعر مساعدة ربة أو قوة في أول القصيدة. ٢. هوميروس بيقول لها \"غني\" و\"احكي لي\". ٣. هسيود بيقول إنها اختارته وادته غصن لورد وصوت إلهي. ٤. الميوز عنده بتعترف إنها ممكن تقول أكاذيب. ٥. فيرجيل بيبدأ ب \"أنا بغني\" وبعدين يطلب السبب. ٦. سبنسر بيعلن إنه بيغير من شعر الرعاة للملحمة. ٧. شكسبير بيتمنى ميوز من نار عشان المسرح صغير."},{"i":"myth-m20","s":68,"h":"ملخص في عشر جمل","t":"learn","x":"٨. ميلتون بيحول الميوز ل \" Heav'nly Muse \" وللروح. ٩. وفي الكتاب السابع بيناديها يورانيا وبيقول إنها مش من التسع. ١٠. شيلي بيعكس: الشاعر هو اللي يبقى القيثارة."},{"i":"myth-m20","s":70,"h":"مهمتك قبل الفصل الجاي","t":"learn","x":"اختار قصيدة طويلة في المنهج وشوف سطورها الأولى. اكتب: فيه استدعاء ولا لأ؟ لمين؟ وبصيغة إيه؟ اكتب في تلات جمل: لو الشاعر ما استدعاش، ليه؟"},{"i":"myth-m20","s":72,"h":"خاتمة","t":"learn","x":"الاستدعاء مش زخرفة. هو أول عقد بيمضيه الشاعر مع التراث: هو بيقول مين اللي بيتكل عليه، وبيقول هيحكي عن إيه، وبيعترف بحدوده. الميوز بتجاوب، وبان ماجاوبش. والشعراء الإنجليز اختاروا أي واحد من الاتنين يسمعوه. نكمل في الفصل الجاي."},{"i":"myth-m21","s":1,"h":"إحنا فين في الحكاية","t":"learn","x":"خلصنا المستوى التاني: الآلهة الكبار، وآخرهم بان، وبعده الاستدعاء. والنهارده بنبدأ المستوى التالت: الحكايات اللي فيها حب وفقد وتحول. وأول حكاية هي أشهر حكاية أم وبنتها في الأساطير: ديميتر وبنتها بيرسيفوني."},{"i":"myth-m21","s":2,"h":"إحنا فين في الحكاية","t":"learn","x":"ملحوظة: إنت شفت أجزاء من الحكاية دي في فصل هاديس وفصل ديميتر. النهارده بنرجع لها كحكاية كاملة، من أول المرج لحد الرجوع، وبعدين نشوف الشعراء الإنجليز عملوا بيها إيه. مثال من حياتنا: بنت بتخرج تلعب مع صحباتها في الجنينة وتختفي. الأم بتدور عليها في الشارع كله. نفس الإحساس ده هو قلب الحكاية."},{"i":"myth-m21","s":4,"h":"البطاقة الأساسية","t":"learn","x":"الأشخاص بيرسيفوني ( Persephone ): البنت. اسمها الروماني Proserpina (بروسيربينا). ديميتر ( Demeter ): أمها، ربة الحبوب والغلة. اسمها الروماني Ceres (سيريس). هاديس ( Hades ): عم البنت، وبيتسمى كمان Aidoneus ، وبيتحكم في العالم السفلي. الروماني بلوتو ( Pluto ) أو ديس ( Dis ). زيوس ( Zeus ): أبوها، وهو اللي وافق."},{"i":"myth-m21","s":5,"h":"البطاقة الأساسية","t":"learn","x":"هيكاتي ( Hecate ) وهيليوس ( Helios ): اللي سمعوا وشافوا. المصدر الأقدم الترنيمة الهوميرية لديميتر ( Homeric Hymn to Demeter ). وفيه نسخة رومانية مشهورة عند أوفيد، في الكتاب الخامس من المسخ ( Metamorphoses ). الفكرة الكبيرة"},{"i":"myth-m21","s":6,"h":"البطاقة الأساسية","t":"learn","x":"الحكاية بتفسر ليه فيه مواسم: شتا بتموت فيه الأرض، وربيع بترجع فيه. بس الأهم من التفسير هو الإحساس: أم فقدت بنتها، والدنيا كلها تعبت معاها."},{"i":"myth-m21","s":8,"h":"المرج والزهرة","t":"learn","x":"البداية في الترنيمة، بيرسيفوني كانت بتلعب بعيد عن أمها مع بنات أوقيانوس ( Oceanus )، وبتجمع زهور في مرج ناعم. وهنا الفخ الترنيمة بتقول إن فيه ورد وزعفران وبنفسج وسوسن وياقوتية ونرجس ( narcissus )، والنرجس ده \" Earth made to grow at the will of Zeus \", يعني الأرض طلعته بإرادة زيوس عشان يبقى \" a snare for the bloom-like girl \", يعني فخ للبنت اللي زي الزهرة."},{"i":"myth-m21","s":9,"h":"المرج والزهرة","t":"learn","x":"ولاحظ: الفخ مش بقوة. الفخ جمال. زهرة حلوة جدا لدرجة إن السما والأرض والبحر ضحكوا لها. اللحظة البنت مدت إيديها تاخد \" the lovely toy \", يعني اللعبة الحلوة، والأرض اتفتحت في سهل نيسا ( Nysa )، وهاديس طلع بخيوله الخالدة وخطفها. مثال من حياتنا زي ما تلاقي حاجة حلوة على الأرض في الشارع وتنزل تاخدها، وتلاقي نفسك اتسحبت لمكان مش بتاعك. الجمال هنا هو الطعم."},{"i":"myth-m21","s":10,"h":"المرج والزهرة","t":"mc","x":"بحسب الترنيمة، إيه اللي كان فخ لبيرسيفوني في المرج؟ ؟ أسد جريح / مراية سحرية / رمانة حمرا / زهرة النرجس . زهرة النرجس"},{"i":"myth-m21","s":12,"h":"الصرخة اللي ماحدش سمعها","t":"learn","x":"اللي حصل بعد الخطف هاديس شالها على عربيته الدهب وهي بتصرخ وتنادي أبوها زيوس. الترنيمة بتقول إن ماحدش سمع صوتها، لا من الآلهة ولا من البشر، ولا حتى شجر الزيتون. بس اتنين سمعوا: هيكاتي من كهفها، وهيليوس، إله الشمس. ليه هيليوس بالذات؟ لأن الشمس بتشوف كل حاجة فوق الأرض. وده هيبان بعدين لما ديميتر تسأله. وزيوس؟"},{"i":"myth-m21","s":13,"h":"الصرخة اللي ماحدش سمعها","t":"mc","x":"مين اللي سمع صرخة بيرسيفوني؟ ؟ زيوس وهيرا / ديميتر وأرتميس / هيكاتي وهيليوس / هيرميس وأبولو . هيكاتي وهيليوس"},{"i":"myth-m21","s":14,"h":"الصرخة اللي ماحدش سمعها","t":"learn","x":"الترنيمة بتقول إنه كان قاعد بعيد عن الآلهة في معبده، بياخد القرابين، وإنه \" bearing her away by leave of Zeus \", يعني هاديس خدها بإذن زيوس. يعني الأب وافق. وده سبب جزء كبير من غضب ديميتر بعدين."},{"i":"myth-m21","s":15,"h":"الصرخة اللي ماحدش سمعها","t":"tf","x":"الترنيمة بتقول إن هاديس خدها من غير علم زيوس. . غلط"},{"i":"myth-m21","s":17,"h":"الأم بتدور","t":"learn","x":"تسع أيام الترنيمة بتقول إن ديميتر لفت الأرض تسع أيام بمشاعل مولعة في إيديها، ومأكلتش ومشربتش ومادخلتش ميه. في اليوم العاشر، هيكاتي قابلتها وقالتها إنها سمعت الصوت بس ما شافتش مين. السؤال لهيليوس راحوا لهيليوس. هو قال لها الحقيقة: زيوس هو اللي أعطى البنت لهاديس، وهاديس عم البنت، وهاديس \" no unfitting husband \" يعني مش جوز مش مناسب."},{"i":"myth-m21","s":18,"h":"الأم بتدور","t":"mc","x":"كام يوم ديميتر لفت الأرض تدور على بنتها؟ ؟ تسع أيام / سبعة أيام / يوم واحد / أربعين يوم . تسع أيام"},{"i":"myth-m21","s":19,"h":"الأم بتدور","t":"learn","x":"ده كلام بيحاول يهدي، بس ديميتر ماتهدتش. التفاصيل بتاعة الحزن الترنيمة بتخليها تتنكر في شكل واحدة عجوزة، وتقعد جنب بير في إليوسيس ( Eleusis )، وتتشغل مربية لعيال الملك. ده معروف من الفصل اللي فات: ديميتر وديموفون وما حصل بعدين. مثال من حياتنا أم مابتأكلش ومابتنامش لحد ما تعرف مكان ابنها. الحزن هنا مش كلمة، هو فعل."},{"i":"myth-m21","s":21,"h":"الأرض بتجوع","t":"learn","x":"اللي حصل لما ديميتر فضلت زعلانة الترنيمة بتقول إنها خلت الأرض ماتطلعش حاجة: محاريث بتتجر على الفاضي، وشعير بيتزرع وما بيطلعش. وبتقول إنها كانت هتبيد البشر كلهم بالجوع، وتحرم الآلهة من القرابين، لولا إن زيوس لاحظ. ليه ده مهم؟ دي أول مرة الحكاية تقول إن غضب إلهة يوقف الدنيا. الحزن الشخصي بقى مشكلة كونية."},{"i":"myth-m21","s":22,"h":"الأرض بتجوع","t":"learn","x":"والآلهة محتاجة البشر عشان القرابين. يعني الكل مرتبط بالكل. اللي عمله زيوس بعت إيريس ( Iris ) تنادي ديميتر. والحل في الآخر كان: يرجعوا البنت."},{"i":"myth-m21","s":24,"h":"الرمانة","t":"learn","x":"اللحظة اللي بتحسم كل حاجة هيرميس نزل لهاديس بأمر زيوس عشان ياخد بيرسيفوني. هاديس وافق، بس الترنيمة بتقول إنه \" secretly gave her sweet pomegranate seed to eat \", يعني اداها حبة رمان حلوة تاكلها في السر. وليه؟ \" taking care for himself that she might not remain continually with grave, dark-robed Demeter \", يعني عشان ماتفضلش مع أمها طول الوقت."},{"i":"myth-m21","s":25,"h":"الرمانة","t":"learn","x":"ليه الأكل هو المهم؟ في الحكاية، اللي يدوق أكل العالم السفلي مابيرجعش كامل. وبيرسيفوني كلت. القاعدة اللي اتحطت"},{"i":"myth-m21","s":26,"h":"الرمانة","t":"learn","x":"ديميتر لما قابلت بنتها سألتها إذا كانت دقت أكل هناك، وقالت : \" if you have tasted food, you must go back again beneath the secret places of the earth, there to dwell a third part of the seasons every year \", يعني لو دقتي أكل لازم ترجعي تحت الأرض وتقعدي هناك تلت الفصول كل سنة. وفي الباقي، التلتين، تفضلي معايا ومع الآلهة."},{"i":"myth-m21","s":27,"h":"الرمانة","t":"mc","x":"بحسب الترنيمة، بيرسيفوني بتقعد تحت الأرض قد إيه من السنة؟ ؟ ربع السنة / تلت السنة / نص السنة / السنة كلها . تلت السنة"},{"i":"myth-m21","s":28,"h":"الرمانة","t":"learn","x":"وبعدين: لما الأرض تتفتح بالزهور، تطلعي من الظلام تاني. نسخة أوفيد أوفيد بيحكي إنها أكلت سبع حبات رمان، وإن واحد اسمه أسكالافوس ( Ascalaphus ) هو اللي شافها وقال. وهو اللي اتحول لبومة. وفي نسخته، زيوس قسم السنة \" in equal parts \", يعني نصين: ست شهور مع الأم، وست شهور مع الجوز. خد بالك: الترنيمة بتقول تلت، وأوفيد بيقول نص. دول نسختين مختلفين، مش غلطة."},{"i":"myth-m21","s":29,"h":"الرمانة","t":"tf","x":"الترنيمة وأوفيد متفقين على مدة الغياب. . غلط"},{"i":"myth-m21","s":31,"h":"إليوسيس: الحكاية بقت طقس","t":"learn","x":"آخر الحكاية لما بيرسيفوني رجعت، الأرض اتغطت بالزهور والورق. ديميتر علمت ملوك إليوسيس طقوسها، ومن ضمنهم تريبتوليموس ( Triptolemus ) وإيومولبوس ( Eumolpus ). الأسرار الترنيمة بتقول إنها \" mysteries which no one may in any way transgress or pry into or utter \", يعني أسرار ماحدش يخترقها أو يكشفها."},{"i":"myth-m21","s":32,"h":"إليوسيس: الحكاية بقت طقس","t":"learn","x":"وبعدين : \" Happy is he among men upon earth who has seen these mysteries \", يعني سعيد اللي شاف الأسرار دي، وبعد الموت اللي مش مبتدئ ماله نصيب زيه في الضلمة. ليه ده مهم؟ الحكاية مش بس قصة. دي أصل طقس ديني اسمه أسرار إليوسيس. وده بيفرق عن باقي أساطير المستوى ده. ماتقولش إحنا نعرف تفاصيل الطقس. الترنيمة نفسها بتقول إنه سر."},{"i":"myth-m21","s":33,"h":"إليوسيس: الحكاية بقت طقس","t":"tf","x":"الترنيمة بتشرح تفاصيل طقس إليوسيس بالكامل. . غلط"},{"i":"myth-m21","s":35,"h":"إزاي نفهم الحكاية؟","t":"learn","x":"قراءة المواسم أكتر قراءة معروفة: الحكاية بتفسر الشتا والربيع. الأرض بتحزن لما البنت تنزل، وبتفرح لما ترجع. بس خد بالك إنها قراءة، والنص مش بيقول ده صراحة. قراءة الأم والبنت قراءة تانية: الحكاية بتتكلم عن الفقد والبنت اللي بتكبر وتبعد عن أمها. ده مش في النص بالحرف، لكن ناس كتير بتقراه كده. قراءة الطقس"},{"i":"myth-m21","s":36,"h":"إزاي نفهم الحكاية؟","t":"learn","x":"والقراءة التالتة: الرجوع بيربط الحكاية بفكرة الحياة بعد الموت، وده اللي الترنيمة بتلمح له في آخرها. السؤال للطالب تختار أنهي قراءة؟ المهم إنك تدافع عن اختيارك بسطر من النص."},{"i":"myth-m21","s":38,"h":"الأسطورة في الشعر الإنجليزي","t":"learn","x":"١) ميلتون، الفردوس المفقود، الكتاب الرابع، السطور ٢٦٨-٢٧٢ ميلتون بيوصف جنة عدن، وبيقول إن حتى أجمل جنينة في الأساطير ماتقارنش بيها \" Not that faire field / Of Enna, where Proserpin gathering flours / Her self a fairer Floure by gloomie Dis / Was gatherd, which cost Ceres all that pain / To seek her through the world \""},{"i":"myth-m21","s":39,"h":"الأسطورة في الشعر الإنجليزي","t":"learn","x":"يعني: مش ده المرج في إنا ( Enna ) اللي بروسيربين كانت بتجمع فيه زهور وهي نفسها زهرة أجمل، واتجمعت بإيد ديس الكئيب، وده كلف سيريس كل التعب ده عشان تدور عليها في الدنيا."},{"i":"myth-m21","s":40,"h":"الأسطورة في الشعر الإنجليزي","t":"learn","x":"ولاحظ: ميلتون بيقول \" Her self a fairer Floure \". البنت هي نفسها زهرة، وده نفس الفخ اللي في الترنيمة: الجمال هو اللي بيتخطف. وبيتكلم عن أم بتدور عليها. بس السبب إنه بيحط الحكاية جنب عدن: حتى المرج الأسطوري أقل من الجنة. ٢) سوينبرن، \"حديقة بروسيربين\"، ١٨٦٦"},{"i":"myth-m21","s":41,"h":"الأسطورة في الشعر الإنجليزي","t":"mc","x":"ميلتون ذكر مرج إنا في الفردوس المفقود عشان... ؟ يقول إنه أجمل من عدن / يقول إن عدن أجمل منه / يشرح المواسم الأربعة / يمدح خصوبة صقلية . يقول إن عدن أجمل منه"},{"i":"myth-m21","s":42,"h":"الأسطورة في الشعر الإنجليزي","t":"learn","x":"القصيدة من ديوان Poems and Ballads ، والراوي فيها بيدخل عالم بروسيربين وهو تعبان من الحياة. من أشهر مقاطعها \" From too much love of living , / From hope and fear set free , / We thank with brief thanksgiving / Whatever gods may be / That no man lives for ever ;\""},{"i":"myth-m21","s":43,"h":"الأسطورة في الشعر الإنجليزي","t":"learn","x":"يعني: من فرط حب الحياة، ومن الأمل والخوف متحررين، بنشكر شكر قصير أي آلهة موجودة، إن مفيش إنسان بيعيش للأبد. وكمان فيها وصف لها هي \" Pale, beyond porch and portal , / Crowned with calm leaves, she stands / Who gathers all things mortal \" يعني: شاحبة، ورا الباب، متوجة بورق هادي، واقفة هي اللي بتجمع كل حاجة فانية."},{"i":"myth-m21","s":44,"h":"الأسطورة في الشعر الإنجليزي","t":"learn","x":"لاحظ التحول: عند هوميروس بيرسيفوني بنت بتصرخ. عند سوينبرن هي ملكة الموت الهادية. والتعب والنوم بقوا هما الراحة. الفرق بين الاتنين ميلتون: الأسطورة معيار جمال، المرج اللي بيتخطف منه. سوينبرن: الأسطورة ملاذ، الملكة اللي بتريح. نفس البنت، وكل شاعر بيشوفها من ناحية."},{"i":"myth-m21","s":45,"h":"الأسطورة في الشعر الإنجليزي","t":"mc","x":"الفرق بين بيرسيفوني عند هوميروس وعند سوينبرن هو... ؟ بنت بتصرخ مقابل ملكة موت هادية / نفس الصورة بالظبط عند الاتنين / هي هاديس نفسه / ملكة بتصرخ عند هوميروس وبنت هادية عند سوينبرن . بنت بتصرخ مقابل ملكة موت هادية"},{"i":"myth-m21","s":47,"h":"إزاي تعرفها في قصيدة","t":"learn","x":"لو شفت أسماء زي Proserpine و Ceres و Dis و Enna و Hades ، يبقى فيه إشارة للحكاية. لو شفت مرج وزهور وبنت بتتخطف، افتكر الترنيمة. لو شفت أم بتدور على حد، افتكر ديميتر. لو شفت رمان أو \" pomegranate \" في سياق موت أو رجوع، افتكر اللي أكلته بيرسيفوني. ولو شفت \" spring \" كرجوع بعد شتا، ممكن يبقى صدى للحكاية، بس لازم السياق يأكد."},{"i":"myth-m21","s":49,"h":"أخطاء شائعة","t":"learn","x":"مش كل نسخة فيها نفس مدة الغياب: الترنيمة تلت السنة، وأوفيد نص السنة. ماتقولش إن النص بيقول \"المواسم\" صراحة. ده تفسير. هاديس مش \"الشيطان\". هو إله الموتى وعم البنت، وأخوه زيوس هو اللي وافق. الاسم الروماني Proserpina مش اسم تاني لشخصية تانية. هي نفسها بيرسيفوني. ماتخلطش بين سوينبرن (ملكة الموت الهادية) وهوميروس (بنت بتصرخ)."},{"i":"myth-m21","s":50,"h":"أخطاء شائعة","t":"tf","x":"هاديس هو \"الشيطان\" في الحكاية. . غلط"},{"i":"myth-m21","s":52,"h":"كلمات هتقع لك في الشعر","t":"learn","x":"abduction : خطف. pomegranate : رمان. mysteries : الأسرار (طقوس إليوسيس). Proserpine : الشكل الإنجليزي لاسم بروسيربينا. Enna : اسم المرج اللي اتخطفت منه بروسيربين في قصيدة ميلتون. thanksgiving : شكر. mortal : فان. gather : يجمع، ويقصد بيها كمان \"يخطف\" عند ميلتون."},{"i":"myth-m21","s":54,"h":"خريطة الفصول الجاية","t":"learn","x":"الفصل ٢٢: أبولو وداڤني، الحب اللي بيجري. الفصل ٢٣: بان وسيرينكس، ناي القصب. الفصل ٢٤: هياكينثوس."},{"i":"myth-m21","s":56,"h":"ملخص في عشر جمل","t":"learn","x":"١. بيرسيفوني بنت ديميتر بتلعب في مرج وتجمع زهور. ٢. الزهرة النرجس هي الفخ. ٣. هاديس يطلع من الأرض ويخطفها بإذن زيوس. ٤. هيكاتي وهيليوس بس هما اللي سمعوا وشافوا. ٥. ديميتر بتدور تسع أيام بمشاعل. ٦. بتغضب وتخلي الأرض ماتطلعش، ويبقى فيه خطر مجاعة. ٧. زيوس بيبعت هيرميس يجيب البنت. ٨. هاديس بيديها رمان تاكله في السر. ٩. فبترجع لتحت جزء من السنة."},{"i":"myth-m21","s":57,"h":"ملخص في عشر جمل","t":"learn","x":"١٠. وبعدها ديميتر تعلم أسرار إليوسيس."},{"i":"myth-m21","s":59,"h":"مهمتك قبل الفصل الجاي","t":"learn","x":"اقرا السطور الخمسة لميلتون تاني. اكتب جملتين: ليه ميلتون استخدم حكاية بيرسيفوني في وصف جنة عدن؟ واكتب جملة عن الفرق بين بيرسيفوني عند هوميروس وعند سوينبرن."},{"i":"myth-m21","s":61,"h":"خاتمة","t":"learn","x":"الحكاية دي مش بس عن مواسم. هي عن جمال بيتخطف، وأم بتدور، وأكل صغير بيغير قدر كامل. الشعراء الإنجليز خدوها وقالوا بيها حاجات مختلفة: ميلتون قارن بيها الجنة، وسوينبرن خلاها ملكة الراحة. نكمل في الفصل الجاي مع حب بيجري ومش بيوصل."},{"i":"myth-m22","s":1,"h":"إحنا فين في الحكاية","t":"learn","x":"الفصل اللي فات كان عن بيرسيفوني: بنت اتخطفت وأم بتدور عليها. النهارده حكاية تانية في المستوى التالت: أبولو ( Apollo ) وداڤني ( Daphne ). هنا مفيش خطف تحت الأرض. فيه واحد بيجري ورا واحدة، وهي بتجري منه. مثال من حياتنا: واحد بيحب واحدة من طرف واحد، وهي مش عايزاه ومش عارفة تهرب. الحكاية دي من أشهر النماذج لحب بيجري ورا واحدة مش عايزاه."},{"i":"myth-m22","s":3,"h":"البطاقة الأساسية","t":"learn","x":"الأشخاص أبولو ( Apollo ): إله النور والقوس والعلاج والنبوءات. عند أوفيد بيتسمى كمان فيبوس ( Phoebus ). اسمه في روما هو نفسه Apollo . داڤني ( Daphne ): نيمفة، يعني بنت من بنات الطبيعة. أوفيد بيقول في ترجمة بروكس مور إنها بنت إله نهر. وفي ترجمة تانية اسمه بينيوس ( Peneus ). يعني الاسم بيظهر في ترجمة وبيتخفى في التانية."},{"i":"myth-m22","s":4,"h":"البطاقة الأساسية","t":"learn","x":"كيوبيد ( Cupid ): إله الحب اللي بيرمي السهام. اسمه اليوناني إيروس ( Eros ). ديانا ( Diana ): إلهة الصيد والعذرية. اسمها اليوناني أرتيميس ( Artemis ). داڤني بتحلم تبقى زيها. المصدر الأقدم اللي هنقتبس منه أوفيد ( Ovid )، المسخ ( Metamorphoses )، الكتاب الأول، من السطر ٤٥٢ لحد ٥٦٦. الفكرة الكبيرة"},{"i":"myth-m22","s":5,"h":"البطاقة الأساسية","t":"mc","x":"مين اللي بيحب ويجري ورا مين في الحكاية دي؟ ؟ أبولو بيجري ورا نرسيس / أبولو بيجري ورا داڤني / داڤني بتجري ورا أبولو / كيوبيد بيجري ورا ديانا . أبولو بيجري ورا داڤني"},{"i":"myth-m22","s":6,"h":"البطاقة الأساسية","t":"learn","x":"الحب هنا مش هدية. هو سهم. وفيه سهم بيعمل حب وسهم بيعمل نفور."},{"i":"myth-m22","s":8,"h":"أبولو بيتريق على كيوبيد","t":"learn","x":"اللي حصل أبولو كان لسه فرحان إنه قتل الثعبان الضخم بايثون ( Python ). شاف كيوبيد بيشد قوسه الصغير. قاله باستهزاء: \" What, wanton boy, are mighty arms to thee \", يعني: إيه يا ولد شقي، الأسلحة الكبيرة دي ليك إيه؟ وقاله كمان إن القوس للآلهة الكبار اللي بتقتل الوحوش، وإن كيوبيد يكتفي بنار شعلته. رد كيوبيد"},{"i":"myth-m22","s":9,"h":"أبولو بيتريق على كيوبيد","t":"learn","x":"كيوبيد قاله إن قوس أبولو يغلب العالم، بس \" with this small arrow I shall pierce thy vaunting breast \", يعني: بالسهم الصغير ده هخرم صدرك المتفاخر. مثال من حياتنا زي واحد بيقول لزميله الأصغر \"ده مش شغلك\" قدام الناس. والصغير مش بيرد بالكلام. بيستنى الفرصة."},{"i":"myth-m22","s":10,"h":"أبولو بيتريق على كيوبيد","t":"mc","x":"إيه رد كيوبيد على أبولو؟ ؟ تجاهله ومشي / قال إنه هيخرم صدره بسهم صغير / اعتذر ليه بأدب / حذره من الاقتراب . قال إنه هيخرم صدره بسهم صغير"},{"i":"myth-m22","s":12,"h":"السهمين","t":"learn","x":"اللي عمله كيوبيد طار على جبل بارناسوس ( Parnassus ) وطلع من جعبته سهمين. الأول دهب ولامع وحاد، وبيعمل حب. التاني رصاص وبايظ الرأس، وبيطرد الحب. مين خد إيه؟ بسهم الرصاص ضرب داڤني. وبسهم الدهب ضرب أبولو. النتيجة: واحد اتملى بالحب، وواحدة بتكره فكرة الحب نفسها. ليه ده مهم؟"},{"i":"myth-m22","s":13,"h":"السهمين","t":"mc","x":"سهم الدهب بيعمل إيه؟ ؟ بيعمل حب / بيطرد الحب / بيعمل كره / بيعالج الجروح . بيعمل حب"},{"i":"myth-m22","s":14,"h":"السهمين","t":"tf","x":"سهم الرصاص ضرب أبولو. . غلط"},{"i":"myth-m22","s":15,"h":"السهمين","t":"learn","x":"المشكلة مش إن واحد بيحب. المشكلة إن الاتنين مش على نفس الموجة بالقوة. وده سبب المأساة."},{"i":"myth-m22","s":17,"h":"داڤني والعذرية","t":"learn","x":"اللي بتحبه أوفيد بيقول إنها زي ديانا: بتحب الغابة والصيد، وربطت شعرها بشريط بسيط، ورفضت حب أي راجل. مع أبوها أبوها قالها إنه كان نفسه في جوز لها وحفيد. هي نزلت راسها خجلانة. وبعدين حضنته وقالت: \" My dearest father let me live a virgin always \", يعني: يا أبويا الحبيب، سيبني أعيش عذراء دايما. وقالت إن جوف ( Jove ) سمح بكده لديانا وقت ولادتها."},{"i":"myth-m22","s":18,"h":"داڤني والعذرية","t":"mc","x":"داڤني كانت عايزة تعيش زي مين؟ ؟ ديانا إلهة الصيد / كيوبيد / هيرا / أثينا . ديانا إلهة الصيد"},{"i":"myth-m22","s":19,"h":"داڤني والعذرية","t":"learn","x":"اللي حصل رغم كده أبوها وعدها، بس جمالها غلب. أبولو شافها واتولع. أوفيد بيشبه ده بقش الغيط اللي بيولع من شرارة صغيرة. مثال من حياتنا بنت بتقول \"لأ\" بوضوح، والأهل بيحترموا ده، لكن الواحد التاني مش بيسمع. في الحكاية، المشكلة في الاندفاع مش في رفضها. ده تفسير مني."},{"i":"myth-m22","s":21,"h":"المطاردة","t":"learn","x":"كلام أبولو وهو بيجري بينادي: \" O Nymph ! O Daphne ! I entreat thee stay \", يعني: يا نيمفة، يا داڤني، أرجوكي استني. وبيقول إنه مش عدوها، وإن الحمل بيجري من الديب، والحمامة من النسر. وهو الوحيد اللي بيجري ورا اللي بيحبها."},{"i":"myth-m22","s":22,"h":"المطاردة","t":"learn","x":"بيعرفها بنفسه: ابن جوف، وإن الماضي والحاضر والمستقبل بيتكشفوا بيه، وإنه اخترع الطب، \" there is no herb to medicate my wound \", يعني: مفيش عشبة تعالج جرحي. مفارقة جميلة إله العلاج مش عارف يعالج نفسه. وده أطرف جزء في الحكاية. تشبيه الكلب والأرنب أوفيد بيشبه أبولو بكلب سلوقي ماسك أرنب. الكلب شبه ماسكها والأرنب في آخر لحظة بتفلت."},{"i":"myth-m22","s":23,"h":"المطاردة","t":"mc","x":"إيه المفارقة في إن أبولو إله العلاج؟ ؟ عالج داڤني من الخوف / مش لاقي علاج لجرحه / رفض يعالج حد بعد كده / كان بيعالج الكل إلا نفسه بس بسهولة . مش لاقي علاج لجرحه"},{"i":"myth-m22","s":24,"h":"المطاردة","t":"learn","x":"وبيقول إن نفس أبولو وصل لشعرها: \" his warm breath mingled in her hair \". مثال من حياتنا واحد بيكلمك من وراك في الشارع وهو بيمشي وراك وبيقول \"أنا ماشي بالراحة\". كلامه ممكن يبقى لطيف، بس المطاردة نفسها هي الخوف."},{"i":"myth-m22","s":26,"h":"التحول","t":"learn","x":"الدعاء داڤني خلصت قوتها. بصت لمياه أبوها، وقالت: \" Help me my father, if thy flowing streams have virtue \", يعني: ساعدني يا أبويا لو لمياهك قدرة. وطلبت : \" Destroy the beauty that has injured me, or change the body that destroys my life \", يعني: دمر الجمال اللي أذاني، أو غير الجسم اللي بيدمر حياتي. اللي حصل"},{"i":"myth-m22","s":27,"h":"التحول","t":"learn","x":"قبل ما تخلص كلامها، جسمها تقل. قشرة رقيقة غطت صدرها، وشعرها بقى ورق، وإيديها بقت فروع، ورجليها بقت جذور. ووشها اختفى وسط الورق. ليه ده مش حل سعيد؟ هي نجت من أبولو، بس خسرت شكلها البشري وحريتها في الحركة. ده نموذج التحول في الأساطير: النجاة بتتحول لخسارة."},{"i":"myth-m22","s":28,"h":"التحول","t":"mc","x":"داڤني اتحولت لإيه عند أوفيد؟ ؟ نهر جاري / قصبة في المستنقع / شجرة غار / شجرة زيتون . شجرة غار"},{"i":"myth-m22","s":30,"h":"شجرة الغار","t":"learn","x":"كلام أبولو بعد التحول أبولو لسه بيحبها. حط إيده على الجذع وحس قلبها بيدق في القشرة. بوس الخشب، والخشب بيتراجع. قال : \" Although thou canst not be my bride, thou shalt be called my chosen tree \", يعني: مع إنك مش هتبقي عروستي، هتتسمي شجرتي المختارة. وبعدين: ورقك، يا غار، هيتوج جبيني وجعبتي وقيثارتي، والأبطال الرومان هيتتوجوا بيك. الوعد الأخير"},{"i":"myth-m22","s":31,"h":"شجرة الغار","t":"learn","x":"قال إن شعره عمره ما بيتقص، وكده الغار هيفضل أخضر على طول. وفي الآخر، الشجرة \" bent her boughs \", يعني حنت فروعها، وأبولو افتكر ده موافقة. ملحوظة قراءة أوفيد بيقول \" it seemed to him \", يعني \"بدا له\". يعني الموافقة في دماغ أبولو هو، مش في النص كحقيقة."},{"i":"myth-m22","s":32,"h":"شجرة الغار","t":"tf","x":"أوفيد بيقول \" it seemed to him \" يعني الموافقة في دماغ أبولو. . صح"},{"i":"myth-m22","s":34,"h":"إزاي نفهم الحكاية؟","t":"learn","x":"قراءة الأصل القراءة المباشرة: الحكاية بتشرح ليه الغار رمز لأبولو والنصر. ده بيقوله أوفيد صراحة في الكلام اللي على لسان أبولو. قراءة الاندفاع قراءة تانية: الحكاية عن حب مش متبادل، وعن واحد مش بيقبل الرفض. دي قراءة، مش جملة في النص. قراءة الشعر"},{"i":"myth-m22","s":35,"h":"إزاي نفهم الحكاية؟","t":"learn","x":"وقراءة تالتة: التحول لشجرة بيبقى صورة للحفظ والخلود، لأن الغار فاضل أخضر. وأبولو في الحكاية صاحب القيثارة، وبيقول إن الغار هيتلف حول قيثارته. وعند مارڤل \" bays \" واحد من التيجان اللي الناس بتتعب عشانها: \" the palm, the oak, or bays \". بس ده ربط قراءة، مش جملة في نص أوفيد. السؤال للطالب تشوف الحكاية قصة حب ولا قصة هروب؟ دافع بسطر من النص."},{"i":"myth-m22","s":36,"h":"إزاي نفهم الحكاية؟","t":"mc","x":"الغار بيرمز لإيه عند أبولو؟ ؟ التتويج والنصر / الحرب والدفاع / الحزن والفقد / الخصب والزراعة . التتويج والنصر"},{"i":"myth-m22","s":38,"h":"الأسطورة في الشعر الإنجليزي","t":"learn","x":"١) أندرو مارڤل، \"الحديقة\" ( The Garden )، السطور ٢٥-٣٢ مارڤل بيمدح الحديقة اللي فيها هدوء، وبيقول إن الآلهة اللي كانت بتجري ورا الجمال خلصت جري في الشجر"},{"i":"myth-m22","s":39,"h":"الأسطورة في الشعر الإنجليزي","t":"learn","x":"\" When we have run our passion's heat , / Love hither makes his best retreat . / The gods, that mortal beauty chase , / Still in a tree did end their race : / Apollo hunted Daphne so , / Only that she might laurel grow ; / And Pan did after Syrinx speed , / Not as a nymph, but for a reed .\""},{"i":"myth-m22","s":40,"h":"الأسطورة في الشعر الإنجليزي","t":"learn","x":"يعني: لما نخلص حرارة شهوتنا، الحب بييجي هنا يرتاح. الآلهة اللي بتجري ورا الجمال الفاني دايما خلصت جريها في شجرة. أبولو طارد داڤني كده بس عشان تبقى غار. وبان جري ورا سيرينكس مش كنيمفة، لكن كقصبة."},{"i":"myth-m22","s":41,"h":"الأسطورة في الشعر الإنجليزي","t":"learn","x":"ولاحظ: مارڤل بيقول إن المطاردة كانت \" only that she might laurel grow \"، يعني عشان الغار يطلع. ودي قراءة مني: كأن الشاعر شايف إن الحب خلص في هدوء الشجر، وبيفضل الحديقة على الزحمة. ٢) ألكسندر بوب، \"غابة وندسور\" ( Windsor-Forest )، السطور ١٨٠-١٨٧ و٢٠٠-٢٠١"},{"i":"myth-m22","s":42,"h":"الأسطورة في الشعر الإنجليزي","t":"learn","x":"بوب بيحكي قصة لودونا ( Lodona )، نيمفة بيقول إنها بنت نهر التيمز ( Thames ). محرر نص القصيدة في طبعة أكاديمية بيكتب إن بوب بيقلد أوفيد في الجري والتحول لنهر."},{"i":"myth-m22","s":43,"h":"الأسطورة في الشعر الإنجليزي","t":"mc","x":"عند بوب في \"غابة وندسور\" النيمفة اسمها إيه؟ ؟ لودونا / داڤني / أرتميس / سيرينكس . لودونا"},{"i":"myth-m22","s":44,"h":"الأسطورة في الشعر الإنجليزي","t":"tf","x":"الإله اللي بيجري ورا لودونا عند بوب هو أبولو. . غلط"},{"i":"myth-m22","s":45,"h":"الأسطورة في الشعر الإنجليزي","t":"learn","x":"\" Pan saw and lov'd, and furious with desire / Pursu'd her flight; her flight increas'd his fire . / Not half so swift the trembling doves can fly , / When the fierce eagle cleaves the liquid sky ; / Not half so swiftly the fierce eagle moves , / When through the clouds he drives the trembling doves ;\""},{"i":"myth-m22","s":46,"h":"الأسطورة في الشعر الإنجليزي","t":"learn","x":"\" As from the god with fearful speed she flew , / As did the god with equal speed pursue .\" يعني: بان شافها وحبها، وجري وراها بغضب. هروبها زود ناره. الحمام الخايف مش بيطير نص السرعة دي من النسر القاسي، ولا النسر بيتحرك نص السرعة دي وراه. هي هربت من الإله بسرعة خوف، وهو جري وراها بنفس السرعة. وبعدين الجزء بتاع التحول"},{"i":"myth-m22","s":47,"h":"الأسطورة في الشعر الإنجليزي","t":"learn","x":"\" She said, and melting as in tears she lay , / In a soft, silver stream dissolv'd away .\" يعني: قالت كده، وذابت وهي نايمة كأنها دموع، وانحلت لتيار فضي ناعم. الربط: مين الإله هنا؟ بان مش أبولو. وبوب غير النهاية: لودونا بقت نهر، مش شجرة. بس الصورة هي نفس صورة أوفيد: حمامة ونسر، ودعاء للأب، وتحول. الفرق بين الاتنين"},{"i":"myth-m22","s":48,"h":"الأسطورة في الشعر الإنجليزي","t":"learn","x":"مارڤل: الحكاية بتلمح لإن المطاردة خلصت في شجر، والشجر بقى مكان راحة (قراءة). بوب: الحكاية بقت خريطة، بيحكي بيها ليه فيه نهر بيحمل اسمها: لودون ( Loddon )، وبوب نفسه بيذكر ده في هامش. نفس النموذج، وكل شاعر بيستخدمه لهدف."},{"i":"myth-m22","s":50,"h":"إزاي تعرفها في قصيدة","t":"learn","x":"لو شفت أسماء زي Daphne و Apollo و Phoebus ، يبقى فيه إشارة مباشرة. لو شفت \" laurel \" أو \" bays \" كتاج، افتكر الحكاية. لو شفت نيمفة بتجري من إله وبتتحول لشجرة أو نهر، ده نفس النموذج. لو شفت إله بيجري \" not as a nymph, but for a reed \" زي مارڤل، يبقى كمان فيه حكاية بان وسيرينكس، وهي الفصل الجاي."},{"i":"myth-m22","s":52,"h":"أخطاء شائعة","t":"learn","x":"داڤني مش هي اللي اختارت تتحول لشجرة بإرادة حرة. هي دعت أبوها، والتحول جه كإجابة. أبولو مش شرير في كل النص. هو بيتوسل في الكلام، بس المطاردة هي المشكلة. لودونا عند بوب مش داڤني. هي شخصية جديدة، والإله بان مش أبولو. الغار مش مجرد زينة. هو علامة التتويج والنصر عند أبولو. ماتقولش إن مارڤل بيحكي القصة كاملة. هو بيلمح بأربع سطور."},{"i":"myth-m22","s":53,"h":"أخطاء شائعة","t":"tf","x":"داڤني اختارت تتحول لشجرة بإرادة حرة. . غلط"},{"i":"myth-m22","s":55,"h":"كلمات هتقع لك في الشعر","t":"learn","x":"laurel : غار. bays : غار، وبيتستخدم كتاج. nymph : نيمفة، بنت الطبيعة. chase : يطارد. pursue : يلاحق. retreat : ملاذ، مكان للراحة. dissolve : يذوب. bough : فرع شجرة."},{"i":"myth-m22","s":57,"h":"خريطة الفصول الجاية","t":"learn","x":"الفصل ٢٣: بان وسيرينكس، ناي القصب. الفصل ٢٤: هياكينثوس."},{"i":"myth-m22","s":59,"h":"ملخص في عشر جمل","t":"learn","x":"١. أبولو بيتريق على كيوبيد وقوسه الصغير. ٢. كيوبيد بيطلع سهمين: دهب بيعمل حب، ورصاص بيطرد الحب. ٣. سهم الدهب بيضرب أبولو، وسهم الرصاص بيضرب داڤني. ٤. داڤني عايزة تعيش عذراء زي ديانا. ٥. أبولو بيجري وراها وبيقول إنه مش عدوها. ٦. إله العلاج مش لاقي علاج لجرحه. ٧. داڤني بتدعي أبوها إله النهر. ٨. بتتحول لشجرة غار."},{"i":"myth-m22","s":60,"h":"ملخص في عشر جمل","t":"learn","x":"٩. أبولو بيعتبر الغار شجرته ويتوج بيه. ١٠. مارڤل وبوب أخدوا النموذج في شعرهم بشكلين مختلفين."},{"i":"myth-m22","s":62,"h":"مهمتك قبل الفصل الجاي","t":"learn","x":"اقرا سطور مارڤل التمانية تاني. اكتب جملتين: إزاي مارڤل استخدم الحكاية عشان يمدح هدوء الحديقة؟ واكتب جملة عن الفرق بين داڤني عند أوفيد ولودونا عند بوب."},{"i":"myth-m22","s":64,"h":"خاتمة","t":"learn","x":"الحكاية دي حب بيجري، وبنت بتهرب، وشجرة بتبقى تاج. مارڤل لمح بيها في أربع سطور، وبوب نقلها لنهر في بلده. نكمل في الفصل الجاي مع بان وسيرينكس: ناي القصب."},{"i":"myth-m23","s":1,"h":"إحنا فين في الحكاية","t":"learn","x":"الفصل اللي فات كان عن أبولو وداڤني: إله بيجري ورا نيمفة، وهي بتتحول لشجرة. النهارده الحكاية شبهها كتير، بس النهاية مختلفة: بان ( Pan ) وسيرينكس ( Syrinx ). نيمفة هربت من إله، وبقت قصب. ومن القصب ده طلع الناي. مثال من حياتنا: تخيل إنك بتحاول تمسك حاجة، وفي الآخر تلاقي في إيدك حاجة تانية خالص، بس منها طلع صوت حلو. دي الحكاية."},{"i":"myth-m23","s":3,"h":"البطاقة الأساسية","t":"learn","x":"الأشخاص بان ( Pan ): إله الرعاة والبرية. عند أوفيد راسه متلفوفة بأغصان صنوبر. وفي الفصل التاسع عشر شفنا إن اسمه الروماني فاونوس ( Faunus ). سيرينكس ( Syrinx ): نيمفة من نوع النايادس ( Naiad )، يعني نيمفة مية. أوفيد بيقول إنها عاشت في جبل نوناكريس ( Nonacris ) في أركاديا ( Arcadia ). ميركوري ( Mercury ): ده اسم هيرميس ( Hermes ) الروماني. هو اللي بيحكي الحكاية."},{"i":"myth-m23","s":4,"h":"البطاقة الأساسية","t":"learn","x":"أرجوس ( Argus ): الحارس اللي عنده عيون كتير، وهو اللي بيسمع الحكاية. ديانا ( Diana ): إلهة الصيد، واسمها اليوناني أرتيميس ( Artemis ). سيرينكس بتقلدها. لادون ( Ladon ): النهر اللي وقف قدامها. المصدر الأقدم اللي هنقتبس منه أوفيد ( Ovid )، المسخ ( Metamorphoses )، الكتاب الأول، السطور ٦٨٩-٧١١ تقريبا. ملحوظة مهمة"},{"i":"myth-m23","s":5,"h":"البطاقة الأساسية","t":"learn","x":"الحكاية عند أوفيد مش بتتحكي مباشرة. هي حكاية جوه حكاية: ميركوري بيحكيها لأرجوس وهو بيحاول ينيمه. وده هنشوفه."},{"i":"myth-m23","s":6,"h":"البطاقة الأساسية","t":"mc","x":"عند أوفيد، مين اللي بيحكي حكاية سيرينكس؟ ؟ بان نفسه / ميركوري / ديانا / أبولو . ميركوري"},{"i":"myth-m23","s":8,"h":"الحكاية جوه الحكاية","t":"learn","x":"الموقف ميركوري نزل من السما متنكر في شكل راعي. معاه عصاه، وبيغني على ناي من قصب. أرجوس عجبه الصوت، وقاله: اقعد جنبي في الضل. الهدف أوفيد بيقول إن ميركوري عزف على القصب المتجمع عشان يخلي العيون اللي دايما صاحية تنام. أرجوس حاول يقاوم النوم، وسأل: \" I pray thee tell what chance discovered these \", يعني: أرجوك قولي إزاي اتكشفت الآلات دي."},{"i":"myth-m23","s":9,"h":"الحكاية جوه الحكاية","t":"tf","x":"ميركوري جه لأرجوس متنكر في شكل راعي. . صح"},{"i":"myth-m23","s":10,"h":"الحكاية جوه الحكاية","t":"learn","x":"مثال من حياتنا زي واحد بيحكيلك حكاية طويلة عشان تنام، وانت لسه بتحاول تفضل صاحي. الحكاية هنا هي المخدر."},{"i":"myth-m23","s":12,"h":"سيرينكس والغابة","t":"learn","x":"الحكاية بتبدأ ميركوري بيقول إن سيرينكس نيمفة مشهورة وسط الهامادرياد ( Hamadryads )، وإنها كانت بتهرب من الآلهة، وبتهرب كمان من الساتير ( Satyrs ) اللي بيطاردوها. أسلوبها نذرت العذرية، وبتقلد ديانا. حتى لبسها شبه لبس ديانا. الفرق الوحيد اللي أوفيد بيذكره: قوس سيرينكس من قرن، وقوس ديانا من دهب. ليه ده مهم؟"},{"i":"myth-m23","s":13,"h":"سيرينكس والغابة","t":"mc","x":"إيه الفرق الوحيد اللي أوفيد بيذكره بين سيرينكس وديانا؟ ؟ لبسهم مختلف خالص / قوس سيرينكس من قرن وقوس ديانا من دهب / سيرينكس بتصطاد وديانا لأ / قوس ديانا من قرن وقوس سيرينكس من دهب . قوس سيرينكس من قرن وقوس ديانا من دهب"},{"i":"myth-m23","s":14,"h":"سيرينكس والغابة","t":"learn","x":"سيرينكس نسخة من داڤني: نيمفة بتحب الغابة وبترفض الحب. الأسطورة بتكرر النموذج ده. داڤني بقت شجرة، وسيرينكس بقت قصب."},{"i":"myth-m23","s":15,"h":"سيرينكس والغابة","t":"mc","x":"سيرينكس اتحولت لإيه؟ ؟ قصب / كلب / شجرة غار / نهر . قصب"},{"i":"myth-m23","s":16,"h":"سيرينكس والغابة","t":"tf","x":"سيرينكس نسخة من داڤني: نيمفة بتحب الغابة وبترفض الحب. . صح"},{"i":"myth-m23","s":18,"h":"الكلام اللي ماتحكاش","t":"learn","x":"اللحظة أوفيد بيقول إن بان شاف سيرينكس راجعة من تل ليكايوس ( Lycian )، وقال لها كلام. بس ميركوري سكت. الكلام ده \" remains untold \", يعني ماتحكاش. معناها إيه؟ أوفيد بيخلي ميركوري يقطع الحكاية قبل كلمات بان. فإحنا ماعندناش نص رجاء بان. ميركوري بيكمل بشكل ملخص: لو كان قال كل حاجة، الحكاية كانت هتمشي كده. مثال من حياتنا"},{"i":"myth-m23","s":19,"h":"الكلام اللي ماتحكاش","t":"tf","x":"كلام بان لسيرينكس موجود كامل عند أوفيد. . غلط"},{"i":"myth-m23","s":20,"h":"الكلام اللي ماتحكاش","t":"learn","x":"زي واحد بيحكي موقف وبيقول \"وبعدين قال لها كلمتين... بلاش أقولك\". السكوت ده بيخلي السامع يتخيل."},{"i":"myth-m23","s":22,"h":"الهروب والنهر","t":"learn","x":"اللي حصل سيرينكس رفضت رجاء بان، وهربت في براري مفيهاش طريق، لحد ما وصلت لنهر لادون الهادي. مياه النهر منعتها تكمل. اللي طلبته طلبت من أخواتها النيمفات إنهم يغيروا شكلها. وده تقريبا نفس طلب داڤني، بس هنا الطلب لأخواتها، مش لأبوها. اللي حصل لبان بان افتكر إنه مسكها. بس اللي كان ماسكه قصب مستنقعات."},{"i":"myth-m23","s":23,"h":"الهروب والنهر","t":"mc","x":"سيرينكس طلبت من مين يغيروا شكلها؟ ؟ أبوها النهر / ميركوري / أخواتها النيمفات / بان نفسه . أخواتها النيمفات"},{"i":"myth-m23","s":24,"h":"الهروب والنهر","t":"learn","x":"أوفيد بيقول: \" held instead some marsh reeds for the body of the Nymph \". ليه ده كوميدي وحزين في نفس الوقت؟ هو فاكر إنه ماسك حبيبة، وهو ماسك نبات. وده زي واحد جري ورا باص وماسك الهوا."},{"i":"myth-m23","s":25,"h":"الهروب والنهر","t":"mc","x":"بان لما افتكر إنه مسكها، كان ماسك: ؟ نيمفة / شجرة / قصب مستنقعات / غصن غار . قصب مستنقعات"},{"i":"myth-m23","s":27,"h":"الريح والقصب","t":"learn","x":"اللحظة اللي بتتحول فيها الحكاية وهو بيتنهد، الريح في القصب بدأت تعمل صوت حزين وحلو، \" plaintive music \". الصوت حلو وشبه صوت إنسان، لدرجة إن بان قال: \" Forever this discovery shall remain a sweet communion binding thee to me \", يعني: الاكتشاف ده هيفضل رابط حلو بيني وبينك للأبد. الناي"},{"i":"myth-m23","s":28,"h":"الريح والقصب","t":"mc","x":"الصوت اللي طلع من القصب لما الريح عدت كان: ؟ مرعب ومخيف / حزين وحلو ( plaintive ) / عالي ومزعج / فرايحي وراقص . حزين وحلو ( plaintive )"},{"i":"myth-m23","s":29,"h":"الريح والقصب","t":"learn","x":"أوفيد بيقول إن قصبات مختلفة الطول لما بتتوصل ببعض بالشمع، بتاخد اسم \"سيرينكس\" من اسم البنت. يعني الاسم جاي من اسم الحورية، بحسب أوفيد. مثال من حياتنا تشبيه مني: الناي ذكرى بتفضل من حاجة راحت، زي واحد بيحتفظ بحاجة صغيرة من حد بيحبه."},{"i":"myth-m23","s":31,"h":"وبعدين الحكاية بترجع لأرجوس","t":"learn","x":"اللي حصل ميركوري شاف عيون أرجوس تقلت. سكت، ولمس الجفون بعصاه. بعد كده ضربه بسيفه المقوس تحت الراس، ورمى راسه من فوق الصخرة. ليه ده مهم؟ في الحكاية دي ميركوري بيعزف على القصب عشان يحاول ينيم أرجوس، وبعد النوم بييجي القتل. وده مختلف عن الصورة الحلوة اللي هنشوفها عند الشعراء. بالمناسبة"},{"i":"myth-m23","s":32,"h":"وبعدين الحكاية بترجع لأرجوس","t":"tf","x":"أرجوس نام وميركوري قتله. . صح"},{"i":"myth-m23","s":33,"h":"وبعدين الحكاية بترجع لأرجوس","t":"learn","x":"أوفيد بيقول إن جونو ( Juno ) حطت لمعة عيون أرجوس على ريش طايرها. ده جزء من حكاية تانية: حكاية آيو ( Io )."},{"i":"myth-m23","s":35,"h":"إزاي نفهم الحكاية؟","t":"learn","x":"قراءة الأصل القراءة المباشرة: الحكاية بتشرح إزاي الآلة خدت اسم سيرينكس. قراءة الفقد والفن قراءة تانية: الحزن بيتحول لفن. بان خسر البنت وطلع له موسيقى. دي قراءة، مش جملة في أوفيد، بس شعراء كتير بيقروها كده. قراءة التكرار والقراءة التالتة: بعد داڤني وسيرينكس، الأسطورة بتبقى نمط: نيمفة بترفض، إله بيطارد، تحول. والتحول بيبقى مصير نباتي. السؤال للطالب"},{"i":"myth-m23","s":36,"h":"إزاي نفهم الحكاية؟","t":"learn","x":"تشوف إن الناي هدية ولا تعويض؟ دافع بسطر."},{"i":"myth-m23","s":38,"h":"الأسطورة في الشعر الإنجليزي","t":"learn","x":"١) أندرو مارڤل، \"الحديقة\" ( The Garden )، السطور ٣١-٣٢ في الفصل اللي فات شفنا مارڤل بيجمع داڤني وسيرينكس في ثمن سطور. السطرين الأخيرين دول عن بان: \" And Pan did after Syrinx speed , / Not as a nymph, but for a reed .\" يعني: وبان جري ورا سيرينكس، مش كنيمفة، لكن عشان قصبة."},{"i":"myth-m23","s":39,"h":"الأسطورة في الشعر الإنجليزي","t":"mc","x":"عند مارڤل، بان جري ورا سيرينكس: ؟ عشان يتجوزها / عشان يحميها من الخطر / مش كنيمفة لكن عشان قصبة / عشان انتقم من ديانا . مش كنيمفة لكن عشان قصبة"},{"i":"myth-m23","s":40,"h":"الأسطورة في الشعر الإنجليزي","t":"learn","x":"ولاحظ: هنا مارڤل بيقول إن الجري كان \"عشان القصبة\". ودي قراءة مني: إنه بيبعد الحكاية عن الحب البشري وبيقربها للطبيعة. المهم إن السطرين بيلخصوا الأسطورة كلها. ٢) إليزابيث باريت براوننج، \"آلة موسيقية\" ( A Musical Instrument )، المقاطع ١ و٢ و٥ و٧ براوننج بتحكي بان وهو بيصنع الناي من القصب، لكن من وجهة نظر النهر والقصب:"},{"i":"myth-m23","s":41,"h":"الأسطورة في الشعر الإنجليزي","t":"learn","x":"\" What was he doing, the great god Pan , / Down in the reeds by the river ? / Spreading ruin and scattering ban , / Splashing and paddling with hoofs of a goat , / And breaking the golden lilies afloat / With the dragon-fly on the river .\""},{"i":"myth-m23","s":42,"h":"الأسطورة في الشعر الإنجليزي","t":"learn","x":"يعني: كان بيعمل إيه الإله العظيم بان، تحت في القصب جنب النهر؟ بينشر الخراب ويبعثر اللعنة، وبيطرطش وبيخبط بحوافر ماعز، وبيكسر الزنابق الدهبية الطايفة مع اليعسوب على النهر. \" He tore out a reed, the great god Pan , / From the deep cool bed of the river \" يعني: خلع قصبة، الإله العظيم بان، من قاع النهر البارد العميق."},{"i":"myth-m23","s":43,"h":"الأسطورة في الشعر الإنجليزي","t":"learn","x":"\"' This is the way ,' laughed the great god Pan / ( Laughed while he sat by the river ), / ' The only way, since gods began / To make sweet music, they could succeed .'\" يعني: قال وهو بيضحك: ده الطريق، الطريق الوحيد اللي من أيام ما بدأت الآلهة تنجح بيه في الموسيقى الحلوة. وفي آخر مقطع:"},{"i":"myth-m23","s":44,"h":"الأسطورة في الشعر الإنجليزي","t":"learn","x":"\" Yet half a beast is the great god Pan , / To laugh as he sits by the river , / Making a poet out of a man : / The true gods sigh for the cost and pain ,— / For the reed which grows nevermore again / As a reed with the reeds in the river .\""},{"i":"myth-m23","s":45,"h":"الأسطورة في الشعر الإنجليزي","t":"mc","x":"عند براوننج، بان بيعمل إيه بالقصبة؟ ؟ بيبيعها في السوق / بيصنع منها ناي / بيرميها في النهر / بيحرقها . بيصنع منها ناي"},{"i":"myth-m23","s":46,"h":"الأسطورة في الشعر الإنجليزي","t":"learn","x":"يعني: لكن بان نص وحش، بيضحك وهو قاعد جنب النهر وبيعمل شاعر من إنسان. الآلهة الحقيقية بتتنهد على التمن والوجع، على القصبة اللي مش هتنبت تاني كقصبة وسط القصب في النهر. لاحظ: براوننج ماسمتش سيرينكس خالص، وبتحكي من ناحية القصب والنهر. وبتركز على التمن: الموسيقى بتتولد من حاجة اتقطعت. وفي المقطع الأخير الجملة المشهورة: \" making a poet out of a man \"."},{"i":"myth-m23","s":47,"h":"الأسطورة في الشعر الإنجليزي","t":"learn","x":"٣) بيرسي شيلي، \"ترنيمة بان\" ( Hymn of Pan )، السطور ٣٠-٣٦ شيلي بيخلي بان نفسه يتكلم، وفي الآخر بيقول:"},{"i":"myth-m23","s":48,"h":"الأسطورة في الشعر الإنجليزي","t":"learn","x":"\" Singing how down the vale of Maenalus / I pursu'd a maiden and clasp'd a reed . / Gods and men, we are all deluded thus ! / It breaks in our bosom and then we bleed : / All wept, as I think both ye now would , / If envy or age had not frozen your blood , / At the sorrow of my sweet pipings .\""},{"i":"myth-m23","s":49,"h":"الأسطورة في الشعر الإنجليزي","t":"mc","x":"في ترنيمة بان لشيلي، مين اللي بيتكلم؟ ؟ ميركوري / أرجوس / سيرينكس / بان نفسه . بان نفسه"},{"i":"myth-m23","s":50,"h":"الأسطورة في الشعر الإنجليزي","t":"learn","x":"يعني: وهو بيغني إزاي في وادي مينالوس ( Maenalus ) جريت ورا بنت ومسكت قصبة. يا آلهة ويا بشر، إحنا كلنا بنتخدع كده! بتنكسر جوه صدرنا وبعدين بننزف. كلهم بكوا، وأنا شايف إنكم انتو الاتنين هتبكوا دلوقتي، لو الحسد أو السن ماكانوش جمدوا دمكم، على حزن نايي الحلو."},{"i":"myth-m23","s":51,"h":"الأسطورة في الشعر الإنجليزي","t":"learn","x":"الربط: شيلي بيحكي من لسان بان نفسه، وبان بيقول إنه جري ورا بنت ومسك قصبة. وفي المقاطع اللي قبل كده بان بيخاطب أبولو. هنا هنكتفي بالسطور دي. الفرق بين التلاتة مارڤل: لمحة سريعة في سطرين. براوننج: الناي ثمنه غالي، والشاعر بيتولد من الوجع. شيلي: بان نفسه بيحكي، والحزن مشترك بين الآلهة والبشر."},{"i":"myth-m23","s":53,"h":"إزاي تعرفها في قصيدة","t":"learn","x":"لو شفت Syrinx أو \" reed \" أو \" pipe \" مع إله بيجري، افتكر الحكاية. لو شفت \" reeds \" و\" river \" مع بان، يبقى غالبا فيه صدى ليها. لو شفت \" Pan \" و\" pipings \"، يبقى الموسيقى جاية من نفس المكان. لو شفت \" a maiden \" و\" a reed \" في سطر واحد، ده تلخيص الحكاية."},{"i":"myth-m23","s":55,"h":"أخطاء شائعة","t":"learn","x":"سيرينكس مش اسم الناي بس. هي اسم الحورية، والناي خد اسمها عند أوفيد. الحكاية عند أوفيد اتحكت على لسان ميركوري، مش على لسان الراوي مباشرة. كلام بان لسيرينكس ماتحكاش عند أوفيد. سيرينكس ماتحولتش لشجرة زي داڤني. اتحولت لقصب."},{"i":"myth-m23","s":57,"h":"كلمات هتقع لك في الشعر","t":"learn","x":"reed : قصب. pipe : ناي، مزمار. pipings : عزف الناي. nymph : نيمفة. maiden : بنت عذراء. deluded : متخدع. plaintive : حزين وحلو. speed : يجري بسرعة."},{"i":"myth-m23","s":59,"h":"خريطة الفصول الجاية","t":"learn","x":"الفصل ٢٤: هياكينثوس. الفصل ٢٥: نرسيس وإيكو."},{"i":"myth-m23","s":61,"h":"ملخص في عشر جمل","t":"learn","x":"١. ميركوري بيحكي الحكاية لأرجوس وهو بيحاول ينيمه. ٢. سيرينكس نيمفة بتقلد ديانا وبتهرب من الآلهة والساتير. ٣. بان بيشوفها ويكلمها، بس كلامه ماتحكاش. ٤. سيرينكس بتهرب لحد نهر لادون. ٥. بتطلب من أخواتها يغيروا شكلها. ٦. بان يمسك قصب بدل البنت. ٧. الريح في القصب بتعمل صوت حزين وحلو. ٨. القصبات المختلفة الطول بتتوصل بالشمع."},{"i":"myth-m23","s":62,"h":"ملخص في عشر جمل","t":"learn","x":"٩. الآلة بتاخد اسم سيرينكس. ١٠. مارڤل وبراوننج وشيلي كل واحد اتكلم عن القصبة من زاوية."},{"i":"myth-m23","s":64,"h":"مهمتك قبل الفصل الجاي","t":"learn","x":"اقرا سطري مارڤل عن بان تاني. اكتب جملتين: إيه الفرق بين مصير سيرينكس ومصير داڤني؟ واكتب جملة عن معنى \" Making a poet out of a man \" عند براوننج."},{"i":"myth-m23","s":66,"h":"خاتمة","t":"learn","x":"الحكاية دي عن جري، وقصب، وصوت طلع من حاجة اتكسرت. براوننج قالت إن الموسيقى ليها تمن، وشيلي خلى بان نفسه يعترف إن الحزن مشترك. نكمل في الفصل الجاي مع هياكينثوس. 🎓"},{"i":"myth-m24","s":1,"h":"إحنا فين في الحكاية","t":"learn","x":"الفصل اللي فات كان بان وسيرينكس: بنت بتتحول لقصب ومنها ناي. النهارده حكاية تانية لأبولو، بس مختلفة. مش مطاردة. دي صداقة وحب وموت بالغلط. بطلها شاب جميل اسمه هياكينثوس ( Hyacinthus )، وزهرة اتولدت من دمه. مثال من حياتنا: واحد بيلعب كورة مع صاحبه، وحاجة غلط بتحصل في لحظة، والصاحب مايقدرش يعمل حاجة. الحكاية دي عن الذنب اللي مالوش علاج."},{"i":"myth-m24","s":3,"h":"البطاقة الأساسية","t":"learn","x":"الأشخاص أبولو ( Apollo ): إله النور والقيثارة والعلاج. أوفيد بيسميه كمان فيبوس ( Phoebus ). هياكينثوس ( Hyacinthus ): شاب من إسبرطة ( Sparta ). أبولو بيحبه أكتر من غيره. أورفيوس ( Orpheus ): هو اللي بيغني الحكاية عند أوفيد. مش أوفيد اللي بيحكي مباشرة. المصدر الأقدم اللي هنقتبس منه"},{"i":"myth-m24","s":4,"h":"البطاقة الأساسية","t":"learn","x":"أوفيد ( Ovid )، المسخ ( Metamorphoses )، الكتاب العاشر، السطور ١٦٢-٢١٩. الفكرة الكبيرة الزهرة هنا مش بس زينة. هي علامة حزن مكتوبة على ورقها."},{"i":"myth-m24","s":6,"h":"أورفيوس بيختار يغني عن الأولاد","t":"learn","x":"الموقف في الكتاب العاشر، أورفيوس قاعد وسط الحيوانات والطيور. جرب أوتار قيثارته، وبدأ يغني. قال إنه غنى كتير عن قوة جوف ( Jove )، يعني زيوس، لكن دلوقتي عايز غنا أرق: \" I would sing of boys, the favorites of Gods \", يعني: عايز أغني عن الأولاد اللي الآلهة بتحبهم. ليه ده مهم؟"},{"i":"myth-m24","s":7,"h":"أورفيوس بيختار يغني عن الأولاد","t":"mc","x":"عند أوفيد، مين اللي بيغني حكاية هياكينثوس؟ ؟ أبولو / أورفيوس / زيوس / ميركوري . أورفيوس"},{"i":"myth-m24","s":8,"h":"أورفيوس بيختار يغني عن الأولاد","t":"learn","x":"معنى كده إن حكاية هياكينثوس جاية في وسط سلسلة حكايات حب. ومعاها حكاية جانيميد ( Ganymede ) اللي زيوس خطفه. يعني هياكينثوس مش حكاية لوحدها. هي جزء من أغنية أورفيوس. مثال من حياتنا زي واحد في سهرة بيقول: \"هغني لكم حاجة أهدى النهارده\". وبعدين يبدأ يحكي."},{"i":"myth-m24","s":10,"h":"أبولو وهياكينثوس","t":"learn","x":"قبل الحادثة أوفيد بيقول إن حب أبولو لهياكينثوس كان أعمق من حبه لغيره. أبولو سايب دلفي ( Delphi ). وبقى بيروح نهر يوروتاس ( Eurotas ) وفي إسبرطة. سايب القيثارة والقوس، وبقى بيشيل الشباك ويمسك الكلاب، ويمشي مع هياكينثوس على الجبال الوعرة. معنى ده إله كبير نسي هيبته عشان يقضي وقت مع صاحبه. وده معنى الحب في الحكاية: التنازل عن المكانة. مثال من حياتنا"},{"i":"myth-m24","s":11,"h":"أبولو وهياكينثوس","t":"mc","x":"أبولو سايب إيه عشان يقضي وقت مع هياكينثوس؟ ؟ جواده / هدومه الملكية / القيثارة والقوس / مركبته الذهبية . القيثارة والقوس"},{"i":"myth-m24","s":12,"h":"أبولو وهياكينثوس","t":"learn","x":"زي مدير كبير بيسيب مكتبه ويروح يلعب مع صاحبه الصغير. الناس تستغرب، وهو مش فارق معاه."},{"i":"myth-m24","s":14,"h":"القرص","t":"learn","x":"اللعبة قرب منتصف اليوم، الاتنين خلعوا هدومهم ودهنوا جسمهم بزيت الزيتون، وبدأوا مسابقة بالقرص ( discus ). المصدر بيقول \" friendly contest \", يعني مسابقة ودية. أبولو رمى القرص أول. القرص لف في الهوا وشق السحاب، ووقع بعيد، وده دليل على قوته ومهارته. اللي حصل هياكينثوس جري عشان ياخد القرص، من حماسه للعبة. القرص ارتد من الأرض الصلبة وضربه في وشه. ملحوظة"},{"i":"myth-m24","s":15,"h":"القرص","t":"mc","x":"إيه اللي قتل هياكينثوس؟ ؟ سهم / ثعبان / قرص ارتد من الأرض / وقعة من حصان . قرص ارتد من الأرض"},{"i":"myth-m24","s":16,"h":"القرص","t":"learn","x":"في الترجمة دي القرص ارتد من الأرض، وبس. فيه روايات تانية بتذكر ريح الغرب ( Zephyrus ) غيرانة، بس ده مش في النص اللي بنقتبس منه، فهنسيبه."},{"i":"myth-m24","s":17,"h":"القرص","t":"tf","x":"النص اللي بنقتبس منه بيقول إن ريح الغرب ( Zephyrus ) هي اللي حرفت القرص. . غلط"},{"i":"myth-m24","s":19,"h":"أبولو العاجز","t":"learn","x":"رد فعله وش أبولو شحب زي وش الولد. شال الجسم المنهار. حاول يدفيه ويحاول يعالج الجرح بالأعشاب. لكن الجرح \" past all art of cure \", يعني أكبر من أي علاج. ليه ده مؤلم؟ أبولو إله العلاج. في فصل داڤني شفنا إنه مش لاقي عشبة لجرحه. هنا كمان مش قادر. تشبيه أوفيد"},{"i":"myth-m24","s":20,"h":"أبولو العاجز","t":"mc","x":"الجرح \" past all art of cure \" معناه: ؟ أكبر من أي علاج / جرح بسيط / جرح بيشفى بسرعة / بيتعالج بالأعشاب . أكبر من أي علاج"},{"i":"myth-m24","s":21,"h":"أبولو العاجز","t":"learn","x":"أوفيد بيشبه الولد بزهور بنفسج وخشخاش وزنبق في جنينة، بتدبل وراسها بتنزل على الأرض. وراس هياكينثوس نزلت على كتفه. كلام أبولو \" I can see in your sad wound my own guilt \", يعني: شايف في جرحك ذنبي أنا. وقال: \" And oh, that I might now give up my life for you !\", يعني: يا ريتني أدي حياتي بدالك."},{"i":"myth-m24","s":23,"h":"الزهرة","t":"learn","x":"الوعد أبولو قال: هتبقى دايما معايا، وهتعيش على شفايفي، وقيثارتي وأغاني هتحتفل بيك. وقال إن زهرة جديدة هتطلع، \" with markings on your petals \", يعني بعلامات على ورقها، تشبه أنينه. وقال إن بطل شجاع هيتربط بنفس الزهرة وبنفس العلامات. اللي حصل"},{"i":"myth-m24","s":24,"h":"الزهرة","t":"learn","x":"دم هياكينثوس اللي وقع على العشب اتحول لزهرة أجمل من الأرجوان الصوري ( Tyrian dye ). وأوفيد بيقول إنها تقريبا زي الزنبق، بس بنفسجية، والزنبق أبيض. الكتابة أبولو كتب حزنه على الورق. الحروف AI AI . وبعدين إسبرطة بتفتخر بيه كابن ليها، وبتحتفل كل سنة بعيده الحزين."},{"i":"myth-m24","s":25,"h":"الزهرة","t":"mc","x":"إيه اللي كتبه أبولو على ورق الزهرة؟ ؟ AI AI / اسمه هو / ولا حاجة / اسم هياكينثوس . AI AI"},{"i":"myth-m24","s":26,"h":"الزهرة","t":"mc","x":"إيه المدينة اللي بتحتفل بهياكينثوس كل سنة عند أوفيد؟ ؟ أثينا / طيبة / إسبرطة / كورنثوس . إسبرطة"},{"i":"myth-m24","s":28,"h":"ليه الحروف دي؟","t":"learn","x":"اللي النص بيقوله أوفيد بيقول: \" These letters AI, AI, are inscribed on them \". الحروف دي بتتقرا كأنها صرخة حزن: آي آي. اللي النص مابيقولوش النص ماشرحش الحروف أكتر من إنها كتابة حزن أبولو. ماتقولش أكتر من كده. النص ماقالش إن الزهرة دي هي الهياسنت اللي بنعرفها النهارده. هو بس بيقول إنها شبه الزنبق بس بنفسجية. مثال من حياتنا"},{"i":"myth-m24","s":29,"h":"ليه الحروف دي؟","t":"learn","x":"زي واحد بيكتب اسم حد حبه على شجرة. هنا أبولو كتب حزنه، ومش على شجرة، على الزهرة نفسها."},{"i":"myth-m24","s":31,"h":"إزاي نفهم الحكاية؟","t":"learn","x":"قراءة الأصل القراءة المباشرة: الحكاية بتشرح ليه الزهرة دي عليها علامة، وإن إسبرطة بتحتفل بيه كل سنة. قراءة الذنب قراءة تانية: الحكاية عن الذنب بدون قصد. أبولو مش شرير، لكن إيده هي اللي رمت القرص. وهو بيقول بنفسه \" my own guilt \". دي قراءة مني. قراءة الدورة"},{"i":"myth-m24","s":32,"h":"إزاي نفهم الحكاية؟","t":"learn","x":"والقراءة التالتة: أوفيد بيقول إن هياكينثوس بيرجع كل ربيع: \" Always when warm spring drives winter out ... you rise and blossom \". يعني الموت والرجوع مع الفصول. ودي في النص، بس معناها التفسيري قراءة. السؤال للطالب تشوف هياكينثوس ضحية ولا رمز للربيع؟ دافع بسطر."},{"i":"myth-m24","s":34,"h":"الأسطورة في الشعر الإنجليزي","t":"learn","x":"١) جون ميلتون، \"ليسيداس\" ( Lycidas )، السطور ١٠٣-١٠٦ ميلتون بيكتب مرثية لشاب مات. وفي القصيدة شخصية اسمها كاموس ( Camus ) بتدخل وهي حزينة: \" Next Camus, reverend sire, went footing slow , / His mantle hairy, and his bonnet sedge , / Inwrought with figures dim, and on the edge / Like to that sanguine flower inscrib'd with woe .\""},{"i":"myth-m24","s":35,"h":"الأسطورة في الشعر الإنجليزي","t":"tf","x":"في \"ليسيداس\"، عبارة \" sanguine flower inscrib'd with woe \" بتشير لزهرة هياكينثوس. . صح"},{"i":"myth-m24","s":36,"h":"الأسطورة في الشعر الإنجليزي","t":"learn","x":"يعني: بعده جه كاموس، الشيخ الموقر، ماشي ببطء، عباءته شعرها كتير وقبعته من نبات المستنقعات ( sedge )، مطرزة برسومات باهتة، وعلى الحافة زي الزهرة الدموية المكتوب عليها الحزن."},{"i":"myth-m24","s":37,"h":"الأسطورة في الشعر الإنجليزي","t":"learn","x":"الزهرة الدموية ( sanguine flower ) هنا هي زهرة هياكينثوس. ده مذكور في شروح القصيدة. ولاحظ إن ميلتون ماقالش اسم هياكينثوس، بس عبارة \" inscrib'd with woe \" كفاية عشان تفهم: الزهرة اللي عليها كتابة حزن، يعني AI AI . الفكرة: المرثية الراعوية بتحب الزهرة الحمرا أو البنفسجية اللي طلعت من دم إله بيموت. وميلتون استخدم الصورة دي في سطر واحد."},{"i":"myth-m24","s":38,"h":"الأسطورة في الشعر الإنجليزي","t":"learn","x":"٢) تي إس إليوت، \"الأرض الخراب\" ( The Waste Land )، السطور ٣٥-٤١ هنا مفيش اسم أبولو ولا هياكينثوس. فيه بس الزهرة:"},{"i":"myth-m24","s":39,"h":"الأسطورة في الشعر الإنجليزي","t":"tf","x":"إليوت في \"الأرض الخراب\" ذكر اسم هياكينثوس صراحة. . غلط"},{"i":"myth-m24","s":40,"h":"الأسطورة في الشعر الإنجليزي","t":"learn","x":"\"' You gave me hyacinths first a year ago ; / ' They called me the hyacinth girl .' / — Yet when we came back, late, from the Hyacinth garden , / Your arms full, and your hair wet, I could not / Speak, and my eyes failed, I was neither / Living nor dead, and I knew nothing , / Looking into the heart of light, the silence .\""},{"i":"myth-m24","s":41,"h":"الأسطورة في الشعر الإنجليزي","t":"learn","x":"يعني: إنت إديتني هياسنت أول مرة من سنة، وسموني بنت الهياسنت. بس لما رجعنا متأخر من جنينة الهياسنت، دراعك مليان وشعرك مبلول، ماقدرتش أتكلم وعيني خانتني، كنت لا حي ولا ميت وماكنتش أعرف حاجة، وأنا بتفرج على قلب النور، والصمت."},{"i":"myth-m24","s":42,"h":"الأسطورة في الشعر الإنجليزي","t":"learn","x":"ربط: الزهرة اللي في الأسطورة بتفكر بالحب والموت. إليوت بيستخدمها لحظة حب بتنتهي بصمت. ده ربط قراءة، لأن القصيدة نفسها ماقالتش \"هياكينثوس\". بس اللي بيعرف الأسطورة يسمع الصدى. الفرق بين الاتنين ميلتون: لمحة مباشرة، بتحط الزهرة في مرثية. إليوت: بيستخدم الزهرة كذكرى حب وصمت، من غير اسم. نفس الزهرة، وكل شاعر بياخد منها شعور مختلف."},{"i":"myth-m24","s":44,"h":"إزاي تعرفها في قصيدة","t":"learn","x":"لو شفت \" hyacinth \" في سياق حب أو موت أو ربيع، فكر في الحكاية. لو شفت زهرة \" inscribed \" أو \" written \", يعني مكتوب عليها، ده الحروف AI AI . لو شفت \" sanguine flower \", يعني زهرة دموية، فكر في دم هياكينثوس. لو شفت مرثية راعوية، دور على زهرة طالعة من دم حد."},{"i":"myth-m24","s":46,"h":"أخطاء شائعة","t":"learn","x":"هياكينثوس مات بالغلط، مش بقصد. أبولو مش قاتل متعمد. الحكاية عند أوفيد بيغنيها أورفيوس، مش بتتحكي مباشرة. ماتقولش إن الريح هي اللي حرفت القرص. ده مش في الترجمة اللي اعتمدنا عليها. إليوت ماقالش \"هياكينثوس\". الربط بالحكاية قراءة. ميلتون ماسماش الزهرة. هو سماها \" sanguine flower \"."},{"i":"myth-m24","s":47,"h":"أخطاء شائعة","t":"tf","x":"أبولو قتل هياكينثوس بقصد. . غلط"},{"i":"myth-m24","s":49,"h":"كلمات هتقع لك في الشعر","t":"learn","x":"hyacinth : هياسنت، نبات زهري. discus : قرص رياضي. sanguine : دموي، لونه لون الدم. inscribed : مكتوب عليه. woe : حزن. bloom : يزهر. elegy : مرثية. pastoral : راعوي، نسبة للرعاة والطبيعة."},{"i":"myth-m24","s":51,"h":"خريطة الفصول الجاية","t":"learn","x":"الفصل ٢٥: نرسيس وإيكو. الفصل ٢٦: بيراموس وثيسبي."},{"i":"myth-m24","s":53,"h":"ملخص في عشر جمل","t":"learn","x":"١. أورفيوس بيغني عن الأولاد اللي الآلهة بتحبهم. ٢. أبولو بيحب هياكينثوس أكتر من غيره. ٣. أبولو بيسيب دلفي وقيثارته عشان يقضي وقت معاه. ٤. الاتنين بيلعبوا بالقرص. ٥. أبولو يرمي القرص، وهياكينثوس يجري ياخده. ٦. القرص يرتد ويضربه. ٧. أبولو يحاول يعالجه ومايقدرش. ٨. دمه يتحول لزهرة بنفسجية. ٩. أبولو يكتب AI AI على ورقها."},{"i":"myth-m24","s":54,"h":"ملخص في عشر جمل","t":"learn","x":"١٠. ميلتون وإليوت استخدموا الزهرة في قصايدهم."},{"i":"myth-m24","s":56,"h":"مهمتك قبل الفصل الجاي","t":"learn","x":"اقرا سطور ميلتون الأربعة تاني. اكتب جملتين: ليه ميلتون استخدم زهرة هياكينثوس في مرثية؟ واكتب جملة عن الفرق بين استخدام ميلتون واستخدام إليوت للهياسنت."},{"i":"myth-m24","s":58,"h":"خاتمة","t":"learn","x":"الحكاية دي عن حب وذنب وزهرة. أبولو ماقدرش يرجع صاحبه، فكتب حزنه على الزهرة. ميلتون خدها في مرثية، وإليوت خدها في لحظة صمت. نكمل في الفصل الجاي مع نرسيس وإيكو. 🎓"},{"i":"myth-m25","s":1,"h":"إحنا فين في الحكاية","t":"learn","x":"الفصل اللي فات كان هياكينثوس: زهرة طلعت من دم شاب. النهارده حكاية فيها كمان زهرة في الآخر، بس الحكاية نفسها عن حاجتين: صوت بيرجع آخر الكلام، وصورة في مية. نرسيس ( Narcissus ) وإيكو ( Echo ). مثال من حياتنا: واحد بيتصور سيلفي ومش قادر يبطل يبص على نفسه في الشاشة. وواحدة بتحب حد ومش قادرة تقوله غير آخر كلمة قالها. دول الاتنين مع بعض."},{"i":"myth-m25","s":3,"h":"البطاقة الأساسية","t":"learn","x":"الأشخاص نرسيس ( Narcissus ): شاب جميل. أمه نيمفة اسمها ليريوبي ( Liriope )، وأبوه إله نهر اسمه كيفيسوس ( Cephissus )، بحسب أوفيد. إيكو ( Echo ): نيمفة كانت بتحب الكلام. تيريسياس ( Tiresias ): العراف الأعمى اللي قال النبوءة. جونو ( Juno ): ملكة الآلهة، اللي عاقبت إيكو. اسمها اليوناني هيرا ( Hera ). نيميسيس ( Nemesis ): اللي سمعت الدعوة وردت عليها."},{"i":"myth-m25","s":4,"h":"البطاقة الأساسية","t":"learn","x":"المصدر الأقدم اللي هنقتبس منه أوفيد ( Ovid )، المسخ ( Metamorphoses )، الكتاب التالت، السطور ٣٣٩-٥٠٨. الفكرة الكبيرة حكاية حب مش بيوصل. نرسيس بيحب صورة، وإيكو بتحب شخص مايسمعهاش."},{"i":"myth-m25","s":6,"h":"النبوءة","t":"learn","x":"اللي حصل ليريوبي راحت لتيريسياس بابنها، وسألته: هيعيش لحد ما يكبر؟ رد العراف: \" If he but fail to recognize himself, a long life he may have \", يعني: لو ماعرفش نفسه، ممكن يعيش عمر طويل. ازاي الناس فهموا الكلام؟ أوفيد بيقول إن كلام العراف بدا تافه في وقتها. بعدين طريقة موت نرسيس أكدته. نرسيس نفسه"},{"i":"myth-m25","s":7,"h":"النبوءة","t":"mc","x":"إيه اللي قاله تيريسياس عن نرسيس؟ ؟ هيعيش عمر طويل لو ماعرفش نفسه / هيموت صغير / هيبقى ملك / هيتجوز نيمفة . هيعيش عمر طويل لو ماعرفش نفسه"},{"i":"myth-m25","s":8,"h":"النبوءة","t":"learn","x":"شباب وبنات كتير حاولوا يكسبوا حبه. هو كان متكبر ومحدش عجبه. مثال من حياتنا زي واحد قالولك \"كل حاجة تمام لو ماشفتش نفسك في المراية\". الجملة غريبة، ومعناها بيبان بعدين."},{"i":"myth-m25","s":10,"h":"إيكو وعقاب جونو","t":"learn","x":"إيكو كانت إيه؟ أوفيد بيقول إن إيكو كانت نيمفة ليها جسم، مش بس صوت. وكانت ما بتسكتش، وما بتبدأش الكلام إلا بعد ما حد يتكلم. العقاب جونو عاقبتها لأنها كانت بتشغل الإلهة بحكايات طويلة، فنيمفات كتير هربوا من حضن جوف ( Jove ). الإلهة قالتها: \" your endless voice, much shorter than your tongue \", يعني: صوتك اللي ما بينتهيش هيبقى أقصر من لسانك."},{"i":"myth-m25","s":11,"h":"إيكو وعقاب جونو","t":"mc","x":"ليه جونو عاقبت إيكو؟ ؟ لأنها شغلتها بحكايات طويلة / لأنها سرقت حاجة منها / لأنها حبت نرسيس / لأنها فضحتها قدام الآلهة . لأنها شغلتها بحكايات طويلة"},{"i":"myth-m25","s":12,"h":"إيكو وعقاب جونو","t":"learn","x":"من ساعتها إيكو بتكرر آخر الكلام بس. ليه ده مهم؟ العقاب بيحول الكلام لحاجة ناقصة. إيكو عايزة تقول حاجة، ومش قادرة غير تكرر. مثال من حياتنا زي واحد في مكالمة ضعيفة، مابيسمعش غير آخر كلمتك."},{"i":"myth-m25","s":14,"h":"الحوار اللي مش حوار","t":"learn","x":"اللحظة إيكو شافت نرسيس بيصطاد غزلان في الغابة وحبته، وبدأت تمشي وراه بهدوء. هو اتفصل عن صحابه ونادى: \" Who is here ?\" وإيكو ردت: \" Here !\" نادى: \" Come here !\" وهي: \" Come here !\" قال: \" Avoid me not !\" وهي رددت. وبعدين: \" Oh let us come together !\" وإيكو قالت نفس الجملة، وجريت ناحيته عشان تحضنه. رد نرسيس"},{"i":"myth-m25","s":15,"h":"الحوار اللي مش حوار","t":"learn","x":"هرب منها وقال: \" Take off your hands !\" وقال إن الموت أحسن من إنها تلمسه. ردت إيكو: \" Caress me !\" اللي حصل لإيكو اتخبت في الغابة وفي الكهوف. حبها زاد مع الإهمال. جسمها نشف لحد ما ماضلش منها غير عضمها وصوتها. والعضم بقى حجر. وأوفيد بيقول: \"' tis but a voice, a voice that lives, that lives among the hills \". مثال من حياتنا"},{"i":"myth-m25","s":16,"h":"الحوار اللي مش حوار","t":"tf","x":"إيكو في الحكاية كانت نيمفة ليها جسم، مش صوت بس. . صح"},{"i":"myth-m25","s":17,"h":"الحوار اللي مش حوار","t":"learn","x":"زي واحد بتحبه وانتي عارفة إن كل ردودك مجرد صدى لكلامه. والصدى مابيقدرش يطلب حاجة."},{"i":"myth-m25","s":19,"h":"الدعوة والنبع","t":"learn","x":"الدعوة واحد من اللي نرسيس رفضهم رفع إيده للسما: \" If he should love deny him what he loves !\" يعني: لو بيحب، يتحرم من اللي بيحبه. نيميسيس سمعت ووافقت. النبع نبع صافي زي الفضة، ماحدش لمسه: لا رعاة ولا ماعز ولا طيور ولا فروع وقعت عليه. نرسيس تعب من الصيد والحر، ونام قدامه."},{"i":"myth-m25","s":20,"h":"الدعوة والنبع","t":"mc","x":"مين اللي سمع دعوة اللي نرسيس رفضه؟ ؟ نيميسيس / أثينا / جونو / تيريسياس . نيميسيس"},{"i":"myth-m25","s":21,"h":"الدعوة والنبع","t":"learn","x":"وهو بيشرب، شاف نفسه في المية وحبه. أوفيد بيقول إنه حب \" an imagined body which contains no substance \", يعني جسم متخيل مالوش مادة. الوصف أوفيد بيشبه نرسيس بتمثال من رخام باروس ( Parian marble )، وعيونه زي نجمتين. مثال من حياتنا زي واحد بيكلم صورة نفسه في الموبايل ومش مصدق إن الصورة مش حد تاني."},{"i":"myth-m25","s":23,"h":"لحظة الإدراك","t":"learn","x":"اللي نرسيس بيقوله بيقول للغابة: \" was ever man in love more fatally than I ?\" يعني: هل فيه حد حب بشكل أقتل من كده؟ وبيقول إن الحاجز بينه وبين حبيبه بس شوية مية: \" only a little water keeps us far asunder \". وبعدين بيفهم: \" No more my shade deceives me, I perceive ' Tis I in thee — I love myself \", يعني: ماعدش ظلي بيخدعني، فهمت إن ده أنا فيك، أنا بحب نفسي."},{"i":"myth-m25","s":24,"h":"لحظة الإدراك","t":"mc","x":"إيه اللي بيفصل نرسيس عن \"حبيبه\" في النبع؟ ؟ شوية مية / جدار / غابة / حجارة . شوية مية"},{"i":"myth-m25","s":25,"h":"لحظة الإدراك","t":"learn","x":"ويقول: \" abundance makes me poor \", يعني: الوفرة بتفقرني. الفهم مابيحلش بيفهم، بس مابيقدرش يبطل. الحل الوحيد إنه يقبل الموت: \" death is not my bane — it ends my woe \". مثال من حياتنا زي واحد عارف إن عادته غلط، وبرضه مش قادر يبطل. الفهم لوحده مابيكفيش."},{"i":"myth-m25","s":27,"h":"الموت والزهرة","t":"learn","x":"آخر مشهد نرسيس بيبكي، والدموع بتعمل موجات تمحي صورته. بيضرب صدره بإيده، وصدره الأبيض بيحمر زي التفاحة. بيدوب زي الشمع على النار، وبيضعف. إيكو بتشوفه وبتحزن، ولما بيقول \" Alas !\" بترد \" Alas !\". ولما قال \" Ah, youth beloved in vain !\" ردت المكان: \" In vain, in vain !\". ولما قال \" farewell !\" ردت: \" Farewell !\""},{"i":"myth-m25","s":28,"h":"الموت والزهرة","t":"learn","x":"عينه اتقفلت، وحتى في العالم السفلي بيحب يبص على صورته في مية ستيكس ( Styx ). الجنازة أخواته النيمفات قصوا شعرهم وحطوه على جسمه. الدريادات ( Dryads ) حزنوا، وإيكو كمان. بس لما بصوا مكانه، ماكانش فيه جسم. كان فيه زهرة دهبي وبيضا، البيضا حوالين الدهبي. ملحوظة أوفيد ماسماش الزهرة. وصفها بس."},{"i":"myth-m25","s":29,"h":"الموت والزهرة","t":"mc","x":"إيه اللي لقوه مكان جسم نرسيس؟ ؟ حجر / زهرة دهبي وبيضا / شجرة / ورقة بيضا . زهرة دهبي وبيضا"},{"i":"myth-m25","s":30,"h":"الموت والزهرة","t":"tf","x":"أوفيد سمى الزهرة \" narcissus \" بالاسم في النص. . غلط"},{"i":"myth-m25","s":32,"h":"إزاي نفهم الحكاية؟","t":"learn","x":"قراءة الأصل القراءة المباشرة: الحكاية بتشرح من فين جت الزهرة، وإزاي الصدى بقى صدى. قراءة الحب المنعكس قراءة تانية: نرسيس مش بيحب نفسه بس. هو بيحب صورة. وكلمة \" narcissism \" اللي بنستخدمها النهارده مأخوذة من اسمه. بس ده استخدام حديث، مش في أوفيد. قراءة العلاقات"},{"i":"myth-m25","s":33,"h":"إزاي نفهم الحكاية؟","t":"tf","x":"كلمة narcissism الحديثة موجودة في نص أوفيد. . غلط"},{"i":"myth-m25","s":34,"h":"إزاي نفهم الحكاية؟","t":"learn","x":"والقراءة التالتة: الاتنين، نرسيس وإيكو، مش بيتواصلوا. هو مابيسمعش، وهي مابتتكلمش. دي قراءة مني، بس النص فيه الحوار اللي بيوضحها. السؤال للطالب مين ضحية أكتر: نرسيس ولا إيكو؟ دافع بسطر من النص."},{"i":"myth-m25","s":36,"h":"الأسطورة في الشعر الإنجليزي","t":"learn","x":"١) جون ميلتون، \"الفردوس المفقود\" ( Paradise Lost )، الكتاب الرابع، السطور ٤٦٠-٤٦٩ حواء بتحكي أول يوم ليها، وإزاي صحيت ولقت بحيرة"},{"i":"myth-m25","s":37,"h":"الأسطورة في الشعر الإنجليزي","t":"mc","x":"في \"الفردوس المفقود\"، حواء بتتحذر من الصورة في البحيرة بواسطة: ؟ صوت / حيوان / شجرة / إيكو . صوت"},{"i":"myth-m25","s":38,"h":"الأسطورة في الشعر الإنجليزي","t":"learn","x":"\" As I bent down to look, just opposite , / A Shape within the watry gleam appeerd / Bending to look on me, I started back , / It started back, but pleas'd I soon returnd , / Pleas'd it returnd as soon with answering looks / Of sympathie and love; there I had fixt / Mine eyes till now, and pin'd with vain desire , / Had not a voice thus warnd me, What"},{"i":"myth-m25","s":39,"h":"الأسطورة في الشعر الإنجليزي","t":"learn","x":"thou seest , / What there thou seest fair Creature is thy self , / With thee it came and goes: but follow me ,\""},{"i":"myth-m25","s":40,"h":"الأسطورة في الشعر الإنجليزي","t":"learn","x":"يعني: وأنا بنحني أبص قصاد، ظهرت صورة في بريق المية، وهي كمان بتنحني تبص عليا. اتراجعت، فاتراجعت. وبعدين رجعت مبسوطة، فرجعت مبسوطة بنظرات رد فيها عاطفة وحب. كنت هفضل مثبتة عيني هناك لحد دلوقتي، وأذبل برغبة فاضية، لولا إن صوت حذرني: اللي بتشوفيه يا مخلوقة جميلة هو نفسك، بيجي ويروح معاكي، بس اتبعيني."},{"i":"myth-m25","s":41,"h":"الأسطورة في الشعر الإنجليزي","t":"learn","x":"ولاحظ الفرق: حواء عند ميلتون بتعمل زي نرسيس بالظبط، بس صوت بيحذرها وبيشدها بعيد. وده الفرق بين مصيرها ومصير نرسيس. دي قراءة مني، والقصيدة نفسها ماقالتش \"نرسيس\" هنا. ٢) جون كيتس، \"وقفت على أطراف صوابعي على تل صغير\" ( I stood tip-toe upon a little hill ) كيتس بيسأل إيه اللي ألهم شاعر قديم يغني عن نرسيس"},{"i":"myth-m25","s":42,"h":"الأسطورة في الشعر الإنجليزي","t":"learn","x":"\" What first inspired a bard of old to sing / Narcissus pining o'er the untainted spring ? / In some delicious ramble, he had found / A little space, with boughs all woven round ; / And in the midst of all, a clearer pool / Than e'er reflected in its pleasant cool , / The blue sky here, and there, serenely peeping / Through tendril wreaths"},{"i":"myth-m25","s":43,"h":"الأسطورة في الشعر الإنجليزي","t":"learn","x":"fantastically creeping .\" \" And on the bank a lonely flower he spied , / A meek and forlorn flower, with naught of pride , / Drooping its beauty o'er the watery clearness , / To woo its own sad image into nearness :\""},{"i":"myth-m25","s":44,"h":"الأسطورة في الشعر الإنجليزي","t":"learn","x":"يعني: إيه اللي ألهم شاعر قديم يغني عن نرسيس وهو بيذبل جنب النبع الصافي؟ في مشوار حلو لقى مكان صغير محاط بأغصان، ووسطه بركة أصفى من أي بركة، عكست السما الزرقا. وعلى الشط شاف زهرة وحيدة متواضعة وحزينة، بتميل جمالها فوق المية الصافية، عشان تقرب صورتها الحزينة منها."},{"i":"myth-m25","s":45,"h":"الأسطورة في الشعر الإنجليزي","t":"learn","x":"الفكرة: كيتس مابيحكيش الأسطورة. بيقول إن الشاعر القديم اتألهم من زهرة بتبص على صورتها. وده تخمين شعري من كيتس، مش حقيقة من أوفيد. الفرق بين الاتنين ميلتون: حواء بتشوف صورتها وبتتحذر. يعني الحكاية بتتحول لدرس. كيتس: الزهرة بتبص على صورتها. يعني الحكاية بتتحول لسبب إلهام شعري. نفس الصورة، بس كل شاعر بيرجع منها بحاجة."},{"i":"myth-m25","s":46,"h":"الأسطورة في الشعر الإنجليزي","t":"mc","x":"كيتس في \" I stood tip-toe \" بيشوف: ؟ نرسيس نفسه / إيكو / نهر / زهرة بتبص على صورتها . زهرة بتبص على صورتها"},{"i":"myth-m25","s":48,"h":"إزاي تعرفها في قصيدة","t":"learn","x":"لو شفت \" pool \" أو \" fountain \" أو \" spring \" وحد بيبص على صورته، افتكر نرسيس. لو شفت \" echo \" أو صوت بيرجع آخر الكلام، افتكر إيكو. لو شفت \" pining \" يعني بيدبل من الحب، ممكن يكون الصدى ده. لو شفت زهرة مايلة فوق مية، افتكر نهاية الحكاية."},{"i":"myth-m25","s":50,"h":"أخطاء شائعة","t":"learn","x":"نرسيس مش بس \"بيحب نفسه\". هو في الأول مش عارف إن الصورة هو. إيكو مش اسم صوت وبس. أوفيد بيقول إنها كانت نيمفة ليها جسم. أوفيد ماسماش الزهرة. وصفها بس: دهبي وأبيض. ماتخلطش \" narcissism \" الحديثة بالأسطورة. الكلمة حديثة. ميلتون ماقالش \"نرسيس\" في سطور حواء. الربط قراءة."},{"i":"myth-m25","s":52,"h":"كلمات هتقع لك في الشعر","t":"learn","x":"echo : صدى. reflection : انعكاس. pool : بركة. spring : نبع. pine : يذبل من الحب. shade : ظل، صورة. vain : عبث، فاضي. gleam : بريق."},{"i":"myth-m25","s":54,"h":"خريطة الفصول الجاية","t":"learn","x":"الفصل ٢٦: بيراموس وثيسبي. الفصل ٢٧: هيرو وليندر."},{"i":"myth-m25","s":56,"h":"ملخص في عشر جمل","t":"learn","x":"١. تيريسياس بيقول إن نرسيس هيعيش لو ماعرفش نفسه. ٢. جونو بتعاقب إيكو وبتخليها تكرر آخر الكلام بس. ٣. إيكو بتحب نرسيس وبتمشي وراه. ٤. نرسيس بيرفضها، وإيكو بتختفي ويفضل صوتها. ٥. حد من اللي رفضهم نرسيس بيدعي عليه. ٦. نيميسيس بتوافق. ٧. نرسيس يشوف صورته في نبع ويحبها. ٨. يفهم إنها هو، بس مابيقدرش يبطل. ٩. بيموت، وإيكو بتردد \" Farewell \"."},{"i":"myth-m25","s":57,"h":"ملخص في عشر جمل","t":"learn","x":"١٠. مكانه تطلع زهرة دهبي وبيضا."},{"i":"myth-m25","s":59,"h":"مهمتك قبل الفصل الجاي","t":"learn","x":"اقرا سطور ميلتون عن حواء تاني. اكتب جملتين: إيه الفرق بين حواء ونرسيس قدام البركة؟ واكتب جملة عن سبب ذكر كيتس للزهرة بدل الأسطورة كلها."},{"i":"myth-m25","s":61,"h":"خاتمة","t":"learn","x":"الحكاية دي عن حاجتين: صورة ماقدرش حد يمسكها، وصوت ماقدرش يقول غير آخر الكلام. ميلتون خلى حواء تقف قدام نفس المنظر وتتحذر، وكيتس شاف في الزهرة سبب ألهم الشعر. نكمل في الفصل الجاي مع بيراموس وثيسبي. 🎓"},{"i":"myth-m26","s":1,"h":"إحنا فين في الحكاية","t":"learn","x":"الفصل اللي فات كان نرسيس وإيكو: صورة وصدى. النهارده قصة حب من النوع اللي بيتعرف من أول سطر: حبيبين، أهلهم ضدهم، وحيطة بينهم. بيراموس ( Pyramus ) وثيسبي ( Thisbe ). ملحوظة: الحكاية دي مش بتنتهي بتحول شخص لحاجة، لكن بتحول لون فاكهة. وده سبب وجودها عند أوفيد."},{"i":"myth-m26","s":2,"h":"إحنا فين في الحكاية","t":"learn","x":"مثال من حياتنا: اتنين جيران بيحبوا بعض والأهل رافضين، وبيتكلموا من الشباك. الحكاية دي أصل الفكرة دي."},{"i":"myth-m26","s":4,"h":"البطاقة الأساسية","t":"learn","x":"الأشخاص بيراموس ( Pyramus ): أوسم شاب، بحسب أوفيد. ثيسبي ( Thisbe ): أجمل بنت في الشرق، بحسب أوفيد. الأسد ( lioness ): لبوة بتنزل تشرب من النبع. المكان بيوتهم جنب أسوار بنتها الملكة سميراميس ( Semiramis ) حوالين مدينتها المشهورة. مكان اللقاء: قبر نينوس ( Ninus )، تحت شجرة توت جنب نبع. المصدر الأقدم اللي هنقتبس منه"},{"i":"myth-m26","s":5,"h":"البطاقة الأساسية","t":"learn","x":"أوفيد ( Ovid )، المسخ ( Metamorphoses )، الكتاب الرابع، السطور ٥٥-١٦٦. الفكرة الكبيرة حب بيلاقي طريق وسط الممنوع. وبسبب سوء فهم، بيخلص بموت."},{"i":"myth-m26","s":7,"h":"الحيطة والشق","t":"learn","x":"الوضع البيتين متلاصقين، والأهل منعوا الجواز. بس العاطفة بتتحرك لوحدها. كانوا بيتكلموا بإشارات وإيماءات. وأوفيد بيشبه الحب بنار تحت الرماد: كل ما تخنقها، تسخن. الشق في الحيطة اللي بين البيتين فيه شق صغير من سنين، ماحدش لاحظه. بس \" what is hid from love ?\" يعني: إيه اللي ممكن يستخبى من الحب؟ العاشقين استخدموا الشق عشان يبعتوا همس لبعض. كلامهم للحيطة"},{"i":"myth-m26","s":8,"h":"الحيطة والشق","t":"mc","x":"إيه اللي كان بين بيتين العاشقين عند أوفيد؟ ؟ نهر / حيطة فيها شق / جبل / سور المدينة . حيطة فيها شق"},{"i":"myth-m26","s":9,"h":"الحيطة والشق","t":"learn","x":"\" Thou envious wall why art thou standing in the way of those who die for love ?\" يعني: يا حيطة حسودة، ليه واقفة قدام اللي بيموتوا من الحب؟ وشكروها: \" unto thee we own our debt \", يعني: ليكي علينا دين، لأنها خلت الكلام يعدي. مثال من حياتنا زي اتنين بيتكلموا من ورا باب، وكل واحد حاطط وشه جنب شق الباب."},{"i":"myth-m26","s":11,"h":"الخطة","t":"learn","x":"القرار تعبوا من الهمس. اتفقوا يهربوا بالليل ويخرجوا من المدينة. اختاروا مكان: قبر نينوس، تحت شجرة توت ثمرها أبيض ثلج، جنب نبع. ليه الاختيار ده؟ أوفيد بيقول إنهم خايفين يمشوا في الحقول من غير طريق، فاختاروا مكان واضح يتقابلوا فيه. اللحظة"},{"i":"myth-m26","s":12,"h":"الخطة","t":"mc","x":"اتفقوا يتقابلوا فين؟ ؟ في بيت ثيسبي / على شط البحر / عند معبد فينوس / عند قبر نينوس تحت شجرة توت . عند قبر نينوس تحت شجرة توت"},{"i":"myth-m26","s":13,"h":"الخطة","t":"learn","x":"بالليل ثيسبي خدعت أهلها وفتحت الباب. لبست طرحة على وشها، وراحت للقبر، وقعدت تحت الشجرة. \" love made her bold \", يعني الحب خلاها جريئة."},{"i":"myth-m26","s":15,"h":"اللبوة والطرحة","t":"learn","x":"اللي حصل لبوة جت تشرب من النبع. فكها كان مليان دم ثيران دبحتهم. ثيسبي شافتها في ضوء القمر وهربت، وجريت لكهف مظلم. في الجري وقعت منها طرحتها. اللي عملته اللبوة بعد ما شربت، لقيت الطرحة في طريقها، ومزقتها بفكها الدامي. ليه ده مهم؟ الحكاية كلها معتمدة على الطرحة. مش على نية. سوء الفهم بيجي من حاجة صغيرة. مثال من حياتنا"},{"i":"myth-m26","s":16,"h":"اللبوة والطرحة","t":"mc","x":"إيه اللي وقع من ثيسبي وهي بتهرب من اللبوة؟ ؟ طرحتها / خاتمها / سيفها / حذاءها . طرحتها"},{"i":"myth-m26","s":17,"h":"اللبوة والطرحة","t":"tf","x":"اللبوة قتلت ثيسبي. . غلط"},{"i":"myth-m26","s":18,"h":"اللبوة والطرحة","t":"learn","x":"زي رسالة اتبعتت ناقصة، والكل فهمها غلط. وبعدين الوقت فات."},{"i":"myth-m26","s":20,"h":"بيراموس يصل متأخر","t":"learn","x":"اللحظة بيراموس وصل بعدها. شاف آثار الأسد على التراب، ووشه شحب. ولما لقى الطرحة مليانة دم قال: \" Alas, one night has caused the ruin of two lovers !\" يعني: يا خسارة، ليلة واحدة دمرت عاشقين. اللوم حمل نفسه الذنب، وقال إن نفسه هي اللي تستاهل الموت. طلب من أي أسد يمزقه، ثم قال: \" it is a craven's part to wish for death !\" يعني: تمني الموت من الجبناء."},{"i":"myth-m26","s":21,"h":"بيراموس يصل متأخر","t":"learn","x":"الموت بوس الطرحة وقال: \" Kisses and tears are thine, receive my blood as well .\" يعني: القبلات والدموع ليكي، وخدي دمي كمان. غرز سيفه في جسمه، ودمه طلع زي ماية من ماسورة اتشققت. اللون دمه رش الشجرة، وثمر التوت الأبيض بقى غامق: \" dyed a purple tint \"."},{"i":"myth-m26","s":22,"h":"بيراموس يصل متأخر","t":"mc","x":"إيه اللي اتغير عند أوفيد بعد موت بيراموس؟ ؟ اسم المدينة / شكل النبع / اسم الشجرة / لون ثمر التوت . لون ثمر التوت"},{"i":"myth-m26","s":24,"h":"ثيسبي ترجع","t":"learn","x":"اللي حصل رجعت وهي لسه بترتعش، وفكرت إنه مستنيها. بس لقت الشجرة بلون تاني، وشكت إن ده المكان. شافت جسم مجروح على الأرض. عرفته، وضربت صدرها وفرمت شعرها. اللحظة المؤلمة نادت: \" Pyramus ! Pyramus ! awake ! awake ! It is thy dearest Thisbe calls thee !\" يعني: بيراموس، اصحى، ثيسبي حبيبتك بتنادي. هو رفع عينه عند اسمها، وبعدين الضلمة غطته. القرار"},{"i":"myth-m26","s":25,"h":"ثيسبي ترجع","t":"learn","x":"شافت طرحتها، وغمد سيفه فاضي. فهمت. وقالت إن إيدها هتبقى جريئة زيه. طلبت من أهلهم يدفنوهم في قبر واحد، وطلبت من الشجرة إن ثمرها يفضل غامق \" an emblem of our blood \", يعني رمز لدمنا. وقعت على السيف وهو لسه دافي من دمه. الاستجابة أوفيد بيقول إن الآلهة والأهل اتحركوا. الثمر الناضج اتغير للغامق، ورماد الاتنين اتحط في جرة واحدة."},{"i":"myth-m26","s":26,"h":"ثيسبي ترجع","t":"tf","x":"ثيسبي استخدمت سيف بيراموس. . صح"},{"i":"myth-m26","s":28,"h":"مين اتغير؟","t":"learn","x":"اللي النص بيقوله اللي اتغير هو لون ثمر التوت: من أبيض لغامق. مش الشخصين. ودي حاجة بتفرق الحكاية دي عن حكايات التحول التانية. اللي النص مابيقولوش النص مابيقولش إن ده سبب كل التوت الأسود في العالم. هو بس بيقول إن الثمر اتغير. مثال من حياتنا زي مكان بيفتكر حاجة حصلت فيه. الشجرة بقت نصب تذكاري حي."},{"i":"myth-m26","s":29,"h":"مين اتغير؟","t":"tf","x":"عند أوفيد، بيراموس وثيسبي اتحولوا لشجرتين. . غلط"},{"i":"myth-m26","s":31,"h":"إزاي نفهم الحكاية؟","t":"learn","x":"قراءة الأصل القراءة المباشرة: الحكاية بتشرح ليه التوت غامق. قراءة العاطفة والمنع قراءة تانية: الحكاية بتتكلم عن حب بيتخنق بالمنع، وبيلاقي طريق من شق. دي قراءة مني. قراءة سوء الفهم والقراءة التالتة: الحكاية عن إن حاجة صغيرة، طرحة، بتغير كل حاجة. والاتنين مش غلطانين. ده معنى الأسى في الحكاية. السؤال للطالب"},{"i":"myth-m26","s":32,"h":"إزاي نفهم الحكاية؟","t":"learn","x":"مين المسؤول عن الموت: الأهل، الأسد، ولا الصدفة؟ دافع بسطر."},{"i":"myth-m26","s":34,"h":"الأسطورة في الشعر الإنجليزي","t":"learn","x":"ويليام شكسبير، \"حلم ليلة منتصف الصيف\" ( A Midsummer Night's Dream )، الفصل الخامس، المشهد الأول شكسبير بيحول الحكاية لمسرحية هزلية، مثلها ناس عاديين قدام الدوق ثيسيوس ( Theseus ). والكوميديا هي إن المسرحية الحزينة بتتمثل بشكل مضحك. ١) سنوت بيمثل الحيطة"},{"i":"myth-m26","s":35,"h":"الأسطورة في الشعر الإنجليزي","t":"learn","x":"\" In this same interlude it doth befall / That I, one Snout by name, present a wall ; / And such a wall as I would have you think / That had in it a crannied hole or chink , / Through which the lovers, Pyramus and Thisbe , / Did whisper often, very secretly . / This loam, this roughcast, and this stone doth show / That I am that same wall. The truth is"},{"i":"myth-m26","s":36,"h":"الأسطورة في الشعر الإنجليزي","t":"mc","x":"في مسرحية شكسبير، سنوت بيمثل إيه؟ ؟ الحيطة / بيراموس / الأسد / ثيسيوس . الحيطة"},{"i":"myth-m26","s":37,"h":"الأسطورة في الشعر الإنجليزي","t":"learn","x":"so . / And this the cranny is, right and sinister , / Through which the fearful lovers are to whisper .\""},{"i":"myth-m26","s":38,"h":"الأسطورة في الشعر الإنجليزي","t":"learn","x":"يعني: في المسرحية الصغيرة دي، أنا واحد اسمه سنوت ( Snout ) بمثل حيطة. حيطة زي اللي تتخيلوها، فيها ثقب أو شق، كان العاشقين بيتهامسوا منه بالسر. الطين ده والجبس ده والحجر ده يوريكم إني أنا الحيطة، والحقيقة كده. وده الشق، يمين وشمال، اللي هيتهامس منه العاشقين الخايفين."},{"i":"myth-m26","s":39,"h":"الأسطورة في الشعر الإنجليزي","t":"learn","x":"لاحظ: الحيطة الأصلية عند أوفيد كانت بتتخاطب، وهنا الحيطة شخص بيتكلم عن نفسه. وده أصل الضحك. ٢) بوتوم ( Bottom ) في دور بيراموس بيكلم الحيطة"},{"i":"myth-m26","s":40,"h":"الأسطورة في الشعر الإنجليزي","t":"learn","x":"\" And thou, O wall, O sweet, O lovely wall , / That stand'st between her father's ground and mine , / Thou wall, O wall, O sweet and lovely wall , / Show me thy chink to blink through with mine eyne . / Thanks, courteous wall. Jove shield thee well for this . / But what see I ? No Thisbe do I see . / O wicked wall, through whom I see no bliss , / Cursed be"},{"i":"myth-m26","s":41,"h":"الأسطورة في الشعر الإنجليزي","t":"learn","x":"thy stones for thus deceiving me !\" يعني: وإنتي يا حيطة، يا حلوة يا جميلة، اللي واقفة بين أرض أبوها وأرضي، يا حيطة، أوريني شقك عشان أبص منه بعيني. شكرا يا حيطة المهذبة، جوف يحميكي على كده. بس إيه اللي بشوفه؟ مفيش ثيسبي. يا حيطة شريرة، ما شفتش منك سعادة، ملعونة حجارتك لأنك خدعتيني!"},{"i":"myth-m26","s":42,"h":"الأسطورة في الشعر الإنجليزي","t":"learn","x":"ولاحظ: شكسبير حافظ على فكرة \"الحيطة السعيدة والحيطة الشريرة\". بس بوتوم بيعمل ده بمبالغة بتضحك. ٣) موت بيراموس بشكل هزلي، وتعليق الجمهور \" Now am I dead , / Now am I fled ; / My soul is in the sky . / Tongue, lose thy light ! / Moon, take thy flight ! / Now die, die, die, die, die .\""},{"i":"myth-m26","s":43,"h":"الأسطورة في الشعر الإنجليزي","t":"learn","x":"يعني: دلوقتي مت، دلوقتي هربت، روحي في السما. يا لسان، ضيع نورك! يا قمر، اطير! دلوقتي مت، مت، مت، مت، مت. وبعدها المتفرجين على المسرحية بيعلقوا. ديميتريوس ( Demetrius ) بيقول \" No die, but an ace for him, for he is but one .\" يعني: مش \"مت\"، دي \"آص\" بس، لأنه واحد. وثيسيوس ( Theseus ) بيقول"},{"i":"myth-m26","s":44,"h":"الأسطورة في الشعر الإنجليزي","t":"mc","x":"الجمهور بيهزر على كلمة \" die \" لأنها بتتقرا كمان: ؟ سيف / قمر / ورقة لعب / زهر نرد . زهر نرد"},{"i":"myth-m26","s":45,"h":"الأسطورة في الشعر الإنجليزي","t":"learn","x":"\" With the help of a surgeon he might yet recover and yet prove an ass .\" يعني: لو جراح ساعده، ممكن يتعافى ويطلع حمار. الأول بيلعب بكلمة \" die \" اللي معناها \"يموت\" ومعناها \"زهر نرد\". والتاني مسخرة: بيقول إن الجراح ممكن يخليه يطلع حمار. ( Ass في الإنجليزي: حمار.) شكسبير بيحول أصل مأساوي لكوميديا. الفرق بين أوفيد وشكسبير أوفيد: الحيطة جامدة، والموت جدي."},{"i":"myth-m26","s":46,"h":"الأسطورة في الشعر الإنجليزي","t":"learn","x":"شكسبير: الحيطة ممثل، والموت مضحك. نفس الأسطورة، بس شكسبير بيسخر من طريقة تمثيلها."},{"i":"myth-m26","s":48,"h":"إزاي تعرفها في عمل أدبي","t":"learn","x":"لو شفت حيطة بين حبيبين وشق، افتكر الحكاية. لو شفت طرحة أو قطعة هدوم ملطخة بدم، وسوء فهم بيؤدي لموت، دي نفس الفكرة. لو شفت شجرة ثمرها اتغير لونه بسبب موت حبيبين، افتكر الحكاية. لو شفت مسرحية داخل مسرحية بتمثل حب ومأساة، افتكر شكسبير."},{"i":"myth-m26","s":50,"h":"أخطاء شائعة","t":"learn","x":"الأسد ماقتلش ثيسبي. هو بس مزق الطرحة. مفيش حد اتحول لحاجة. اللي اتغير لون التوت. المسرحية عند شكسبير هزلية، والأصل عند أوفيد مأساوي. عند أوفيد، البيوت جنب أسوار سميراميس. وعند شكسبير المسرحية بتتمثل قدام الدوق ثيسيوس في أثينا."},{"i":"myth-m26","s":51,"h":"أخطاء شائعة","t":"tf","x":"شكسبير قدم الحكاية بنفس الجدية بتاعة أوفيد. . غلط"},{"i":"myth-m26","s":53,"h":"كلمات هتقع لك في الشعر","t":"learn","x":"wall : حيطة. chink : شق. cranny : ثقب صغير. veil : طرحة. mulberry : توت. lioness : لبوة. interlude : مسرحية قصيرة. tragical : مأساوي."},{"i":"myth-m26","s":55,"h":"خريطة الفصول الجاية","t":"learn","x":"الفصل ٢٧: هيرو وليندر. الفصل ٢٨: فيليمون وباوكيس."},{"i":"myth-m26","s":57,"h":"ملخص في عشر جمل","t":"learn","x":"١. بيراموس وثيسبي جيران وبيحبوا بعض. ٢. الأهل مانعين الجواز. ٣. الحيطة بينها شق بيتهامسوا منه. ٤. بيقرروا يتقابلوا عند قبر نينوس. ٥. ثيسبي توصل أول وتشوف لبوة. ٦. تهرب وتسيب طرحتها. ٧. اللبوة تمزق الطرحة بفكها الدامي. ٨. بيراموس يظن إنها ماتت، ويقتل نفسه. ٩. ثيسبي تلاقيه وتقتل نفسها."},{"i":"myth-m26","s":58,"h":"ملخص في عشر جمل","t":"learn","x":"١٠. ثمر التوت يتغير للون الغامق، وشكسبير بيحول الحكاية لمسرحية هزلية."},{"i":"myth-m26","s":60,"h":"مهمتك قبل الفصل الجاي","t":"learn","x":"اقرا سطور الحيطة عند شكسبير تاني. اكتب جملتين: إزاي شكسبير حول الحيطة من حاجة جدية لحاجة مضحكة؟ واكتب جملة عن سبب موت بيراموس عند أوفيد."},{"i":"myth-m26","s":62,"h":"خاتمة","t":"learn","x":"الحكاية دي عن حب جه من شق، وسوء فهم من طرحة، وثمر اتغير لونه. شكسبير خدها وخلى ناس بسيطة تمثلها، وكانت أحسن كوميديا في المسرحية كلها. نكمل في الفصل الجاي مع هيرو وليندر. 🎓"},{"i":"myth-m27","s":1,"h":"إحنا فين في الحكاية","t":"learn","x":"الفصل اللي فات كان بيراموس وثيسبي: حيطة وشق وطرحة. النهارده قصة حب تانية بتعدي على ميه. ليندر ( Leander ) بيعوم كل ليلة عشان يشوف حبيبته هيرو ( Hero )، وهي بتشيل نور من البرج عشان يهتدي بيه. مثال من حياتنا: حد بيسيب نور الشباك مفتوح عشان حبيبه يعرف يوصل بالليل. هيرو وليندر هي أشهر نسخة من الفكرة دي."},{"i":"myth-m27","s":2,"h":"إحنا فين في الحكاية","t":"learn","x":"ملحوظة مهمة: القصة هنا بتجي من مصدرين. مارلو ( Marlowe ) كتب قصيدة طويلة عن بداية الحب. والنهاية الحزينة جاية من الشاعر موسايوس ( Musaeus )، اللي مارلو نفسه بيقول عليه \" whose tragedy divine Musaeus sung \". هنقرا النهاية من ترجمة إنجليزية قديمة لموسايوس."},{"i":"myth-m27","s":4,"h":"البطاقة الأساسية","t":"learn","x":"الأشخاص هيرو ( Hero ): بنت من مدينة سستوس ( Sestos ). كاهنة لفينوس ( Venus ) بحسب النصين اللي قريناهم. ليندر ( Leander ): شاب من مدينة أبيدوس ( Abydos ). المكان مدينتين على جنبين من الهيليسبونت ( Hellespont )، بينهم بحر. مارلو بيقول إن نبتون ( Neptune ) هو اللي فاصلهم. هيرو عايشة في برج جنب الميه. ده من ترجمة موسايوس. الفكرة الكبيرة"},{"i":"myth-m27","s":5,"h":"البطاقة الأساسية","t":"mc","x":"هيرو كانت عايشة في: ؟ كهف / سفينة / قصر / برج جنب الميه . برج جنب الميه"},{"i":"myth-m27","s":6,"h":"البطاقة الأساسية","t":"learn","x":"حب بيعدي على بحر، لكن البحر بياخد ليندر في ليلة عاصفة."},{"i":"myth-m27","s":8,"h":"هيرو في قصيدة مارلو","t":"learn","x":"المدينتين مارلو بيبدأ كده: \" On Hellespont, guilty of true-love's blood , / In view and opposite two cities stood , / Sea-borderers, disjoined by Neptune's might ; / The one Abydos, the other Sestos hight .\" يعني: على الهيليسبونت، المذنب في دم الحب الصادق، كانت مدينتين قدام بعض، على الحدود، وبينهم قوة نبتون. الأولى أبيدوس والتانية سستوس."},{"i":"myth-m27","s":9,"h":"هيرو في قصيدة مارلو","t":"learn","x":"لاحظ: مارلو بيقول من أول سطر إن البحر ده \"مذنب\". قراءة مني: القصيدة بتلمح للنهاية من الأول. لبسها مارلو بيوصف فستان هيرو بالتفصيل: بطانة حرير بنفسجي، وكم أخضر مطرز، وطرحة من ورد صناعي. ومرة بيسميها \" Venus' nun \" يعني راهبة فينوس. وده بيأكد إنها خادمة لفينوس. وبيقول إن جمالها خلى كيوبيد ( Cupid ) نفسه يتلخبط: افتكرها أمه. مثال من حياتنا"},{"i":"myth-m27","s":10,"h":"هيرو في قصيدة مارلو","t":"learn","x":"زي واحد بيوصف فستان العروسة بالساعة قبل ما يوصف العروسة نفسها. الوصف نفسه جزء من الحكاية."},{"i":"myth-m27","s":12,"h":"ليندر في قصيدة مارلو","t":"learn","x":"التقديم \" Amorous Leander, beautiful and young , / ( whose tragedy divine Musaeus sung ,) / Dwelt at Abydos; since him dwelt there none / For whom succeeding times make greater moan .\" يعني: ليندر العاشق، جميل وصغير، (اللي موسايوس الإلهي غنى مأساته)، عاش في أبيدوس. ومن وقتها ماحدش سكن هناك والأجيال اللي بعد كده بتحزن عليه أكتر منه. جماله"},{"i":"myth-m27","s":13,"h":"ليندر في قصيدة مارلو","t":"learn","x":"مارلو بيبالغ: يقول إن شعره لو اتنقل لكولخيس ( Colchos ) كان هيجذب شباب اليونان أكتر من الصوف الذهبي. وده أسلوب مارلو: بيحط أسماء أساطير كتير جوه الوصف عشان يبين جمال الشخص. ملحوظة مارلو بيذكر إن موسايوس غنى المأساة. يعني مارلو نفسه بيقول إنه مش أول واحد يحكيها."},{"i":"myth-m27","s":15,"h":"اللقاء في معبد فينوس","t":"learn","x":"المكان مارلو بيوصف معبد فينوس: حيطانه من حجر اليشب، وعليه كرمة من العقيق الأخضر. على الأرض نقوش لآلهة في مشاهد كتير، منها جوف ( Jove ) وجانيميد ( Ganymede )، وأوروبا ( Europa )، وفولكان ( Vulcan ) ومارس ( Mars ) والشبكة. اللحظة هيرو بتقدم قربان على المذبح. ولما بترفع عينيها، \" Thence flew Love's arrow with the golden head , / And thus Leander was enamoured .\""},{"i":"myth-m27","s":16,"h":"اللقاء في معبد فينوس","t":"mc","x":"فين ليندر وقع في حب هيرو عند مارلو؟ ؟ على الشط / في البحر / في معبد فينوس / في بيت أبوه . في معبد فينوس"},{"i":"myth-m27","s":17,"h":"اللقاء في معبد فينوس","t":"learn","x":"يعني: ومن هناك طار سهم الحب بالرأس الذهبي، وهكذا وقع ليندر في الحب. ليندر وقف ساكت وبص لها، ونظرته خلت قلبها تحن: \" Such force and virtue hath an amorous look .\" مثال من حياتنا زي اتنين بيتقابلوا في فرح، وبصة واحدة بتغير اليوم كله."},{"i":"myth-m27","s":19,"h":"الحب من أول نظرة","t":"learn","x":"الفكرة عند مارلو مارلو بيقول: \" It lies not in our power to love or hate , / For will in us is overruled by fate .\" يعني: مش بإيدينا إننا نحب أو نكره، لأن إرادتنا بتتغلب بالقدر. وبعدها: \" Where both deliberate, the love is slight : / Who ever loved, that loved not at first sight ?\""},{"i":"myth-m27","s":20,"h":"الحب من أول نظرة","t":"mc","x":"السطر \" Who ever loved, that loved not at first sight ?\" بيعبر عن: ؟ الخوف من البحر / الحب من أول نظرة / الحذر في الحب / الحب بعد الزواج . الحب من أول نظرة"},{"i":"myth-m27","s":21,"h":"الحب من أول نظرة","t":"learn","x":"يعني: لما الاتنين بيفكروا كتير، الحب بيبقى ضعيف. مين حب فعلا وما حبش من أول نظرة؟ ازاي نفهمها ده رأي الشاعر في القصيدة، مش حقيقة علمية. وده الجزء اللي هيرجع له شكسبير (هتشوفه في القسم ١٠). اللمسة بعد كده بيلمس إيدها وهي بترتعش: \" True love is mute, and oft amazed stands .\" يعني الحب الحقيقي ساكت وكتير بيقف مبهور."},{"i":"myth-m27","s":23,"h":"النور والسباحة","t":"learn","x":"الجزء ده من موسايوس المترجم ده بيكتب شعر إنجليزي قديم (قافية)، وبيوسع الأصل. يعني دي ترجمة حرة، مش كلمة بكلمة. الاتفاق ليندر بيقول لهيرو: \" Ah ! from thy turret let some friendly light / Chase the thick darkness, and direct my sight \". يعني: من برجك، خلي نور صديق يطرد الضلمة ويوجه نظري."},{"i":"myth-m27","s":24,"h":"النور والسباحة","t":"mc","x":"إيه اللي كان بيرشد ليندر وهو بيعوم؟ ؟ نجمة / نور هيرو من البرج / صوت الموج / فنار على الشاطئ . نور هيرو من البرج"},{"i":"myth-m27","s":25,"h":"النور والسباحة","t":"learn","x":"وبيحذرها: \" For when its flame expires, I breathe my last .\" يعني: لما نوره يطفي، أنا هاموت. السباحة هيرو بترفع الشعلة: \" But watchful Hero rais'd the torch on high , / The kind fore-runner of approaching joy :\" وليندر وهو بيعوم: \" Still as he swam, he kept the light in view , / And was himself the ship, and pilot too .\""},{"i":"myth-m27","s":26,"h":"النور والسباحة","t":"learn","x":"يعني: كل ما كان بيعوم كان شايف النور، وكان هو السفينة والقبطان. الحياة السرية \" And was by day a maid, by night a bride .\" يعني: بالنهار بنت، وبالليل عروسة. ومفيش فرح ولا موسيقى: \" Silence and darkness, kindred gods, were there \". مثال من حياتنا زي حد بيمشي كل ليلة مسافة طويلة عشان يشوف حبيبته، وبيبص على نور واحد في الضلمة عشان يكمل."},{"i":"myth-m27","s":28,"h":"العاصفة والنهاية","t":"learn","x":"الشتا في الشتا الرياح بتشتد، والبحارة بيفضلوا على الأرض. لكن ليندر مصمم يروح. المترجم بيقول: \" But heat of passion hurry'd both too far , / And stubborn Fate's decrees resistless are \". الموت ليندر بيحاول بين الموجات، ويطلب مساعدة نبتون والإلهة المولودة من البحر، لكن من غير فايدة. وبعدين: \" But drinks the briny waves, and sucks in death \"."},{"i":"myth-m27","s":29,"h":"العاصفة والنهاية","t":"learn","x":"والنور بيقع من الريح: \" At once the torch down by the winds was tost , / And with its flame, his life and love were lost .\" هيرو الصبح بتلاقيه ميت على الشط. بتشد شعرها، وبعدين: \" Then darting headlong with a furious leap , / From the high tow'r she plung'd into the deep .\""},{"i":"myth-m27","s":30,"h":"العاصفة والنهاية","t":"mc","x":"إيه اللي أنهى حياة ليندر؟ ؟ هيرو / الأسد / العاصفة ووقوع النور / السجن . العاصفة ووقوع النور"},{"i":"myth-m27","s":31,"h":"العاصفة والنهاية","t":"learn","x":"والخاتمة: \" Thus for Leander dy'd his fair belov'd , / And equal fates their equal passion prov'd .\" يعني: كده ماتت حبيبته علشان ليندر، ومصيرهم المتساوي أثبت حبهم المتساوي. ملحوظة القصة دي مش بتحول حد لشجرة أو نجمة. ده تحول مأساوي، مش تحول جسدي."},{"i":"myth-m27","s":33,"h":"إزاي نفهم الحكاية؟","t":"learn","x":"قراءة الحب القدري مارلو بيقول إن الحب بيجي بالقدر. وده بيخلي ليندر مش مسؤول. دي قراءة مني. قراءة الجرأة قراءة تانية: ليندر بيختار يروح في العاصفة. والمترجم بيقول إن \" heat of passion \" أخدهم بعيد. يعني الاتنين شاركوا. قراءة النور النور في الحكاية بيرمز للأمل. لما بيطفي، كل حاجة بتنتهي. وده تفسير بسيط مني، مش من النص. السؤال للطالب"},{"i":"myth-m27","s":34,"h":"إزاي نفهم الحكاية؟","t":"learn","x":"هل ليندر غلطان لأنه راح في العاصفة، ولا هيرو لأنها خلته يعتمد على نور؟ دافع بسطر."},{"i":"myth-m27","s":36,"h":"الأسطورة في الشعر الإنجليزي","t":"learn","x":"كريستوفر مارلو، \"هيرو وليندر\" ( Hero and Leander )، الجزء الأول ( First Sestiad ) القصيدة اللي قريناها في الأقسام ٣ ل ٦. وده سطر مهم فيها: \" Who ever loved, that loved not at first sight ?\" ويليام شكسبير، \" As You Like It \"، الفصل الثالث، المشهد الخامس فيبي ( Phoebe ) بتتكلم لوحدها بعد ما شافت شاب وحبته"},{"i":"myth-m27","s":37,"h":"الأسطورة في الشعر الإنجليزي","t":"learn","x":"\" Dead shepherd, now I find thy saw of might : / Who ever loved that loved not at first sight ?\" يعني: يا راعي ميت، دلوقتي لقيت قولك قوي: مين حب وما حبش من أول نظرة؟ لاحظ: السطر التاني نفس كلمات مارلو. ممكن نفسر \"الراعي الميت\" على إنه مارلو، لكن ده تفسير مش مكتوب في النص ومش متأكد منه هنا. ويليام شكسبير، \" As You Like It \"، الفصل الرابع، المشهد الأول"},{"i":"myth-m27","s":38,"h":"الأسطورة في الشعر الإنجليزي","t":"mc","x":"فيبي في As You Like It بتقتبس سطر من: ؟ Milton / Marlowe / Ovid / Spenser . Marlowe"},{"i":"myth-m27","s":39,"h":"الأسطورة في الشعر الإنجليزي","t":"learn","x":"روزاليند ( Rosalind ) بتسخر من قصص الحب العظيمة وهي متنكرة"},{"i":"myth-m27","s":40,"h":"الأسطورة في الشعر الإنجليزي","t":"learn","x":"\" Leander, he would have lived many a fair year though Hero had turned nun, if it had not been for a hot midsummer night, for, good youth, he went but forth to wash him in the Hellespont and, being taken with the cramp, was drowned; and the foolish chroniclers of that age found it was Hero of Sestos .\""},{"i":"myth-m27","s":41,"h":"الأسطورة في الشعر الإنجليزي","t":"learn","x":"يعني: ليندر كان هيعيش سنين حلوة حتى لو هيرو بقت راهبة، لولا ليلة صيف حارة، لأنه خرج يستحمى في الهيليسبونت، وجاله تشنج وغرق. والمؤرخين الحمقى في الزمن ده قالوا إن السبب هيرو من سستوس. وبعدها بشوية بتقول عن القصص دي: \" But these are all lies .\" يعني: دي كلها أكاذيب. الفرق: مارلو بيصدق الحب القدري، وروزاليند بتسخر منه. نفس الأسطورة، قراءتين مختلفتين."},{"i":"myth-m27","s":42,"h":"الأسطورة في الشعر الإنجليزي","t":"mc","x":"روزاليند عند شكسبير بتقول عن قصص الحب العظيمة: ؟ كلها أكاذيب / كلها حقيقية / هيرو كانت راهبة بس / كلها بتتحقق دايما . كلها أكاذيب"},{"i":"myth-m27","s":44,"h":"إزاي تعرفها في عمل أدبي","t":"learn","x":"لو شفت حد بيعوم أو بيعدي ميه عشان يوصل لحبيبه، افتكر ليندر. لو شفت نور في برج أو شباك بيرشد حد في الضلمة، افتكر هيرو. لو شفت أسماء سستوس وأبيدوس والهيليسبونت، دي الحكاية. لو شفت \"الحب من أول نظرة\" في سطر مارلو، افتكر السطر ده."},{"i":"myth-m27","s":46,"h":"أخطاء شائعة","t":"learn","x":"ليندر ما اتحولش لنجمة. هو غرق. هيرو ما قتلتش ليندر. النص بيقول إن العاصفة والنور اللي وقع. النهاية الحزينة مش في الجزء الأول من قصيدة مارلو اللي قريناه. هي من موسايوس. الترجمة اللي قريناها لموسايوس ترجمة حرة قديمة، مش حرفية. روزاليند عند شكسبير بتسخر من الحكاية، مش بتأكدها."},{"i":"myth-m27","s":47,"h":"أخطاء شائعة","t":"tf","x":"عند مارلو، ليندر وهيرو اتحولوا لنجمتين. . غلط"},{"i":"myth-m27","s":48,"h":"أخطاء شائعة","t":"tf","x":"هيرو قتلت ليندر. . غلط"},{"i":"myth-m27","s":49,"h":"أخطاء شائعة","t":"tf","x":"النهاية الحزينة موجودة في الجزء الأول من قصيدة مارلو. . غلط"},{"i":"myth-m27","s":51,"h":"كلمات هتقع لك في الشعر","t":"learn","x":"tower : برج. torch : شعلة. Hellespont : اسم المضيق اللي بين المدينتين في النصين. swam : عام. drowned : غرق. enamoured : وقع في الحب. hight : اسمه (قديمة). moan : نحيب."},{"i":"myth-m27","s":53,"h":"خريطة الفصول الجاية","t":"learn","x":"الفصل ٢٨: فيليمون وباوكيس. الفصل ٢٩: سيكس وألكيوني."},{"i":"myth-m27","s":55,"h":"ملخص في عشر جمل","t":"learn","x":"١. هيرو في سستوس وليندر في أبيدوس. ٢. بينهم الهيليسبونت. ٣. مارلو بيوصف هيرو وليندر بالتفصيل. ٤. بيتقابلوا في معبد فينوس. ٥. بيحبوا بعض من أول نظرة. ٦. هيرو بترفع شعلة في برج. ٧. ليندر بيعوم كل ليلة ناحية النور. ٨. في عاصفة، النور بيقع وليندر بيغرق. ٩. هيرو بتقفز من البرج. ١٠. شكسبير بيقتبس مارلو في موضع وبيسخر من الحكاية في موضع تاني."},{"i":"myth-m27","s":57,"h":"مهمتك قبل الفصل الجاي","t":"learn","x":"اقرا سطري مارلو عن الحب من أول نظرة تاني. اكتب جملتين: إيه الفرق بين فيبي وروزاليند في الاستخدام؟ واكتب جملة عن دور النور في الحكاية."},{"i":"myth-m27","s":59,"h":"خاتمة","t":"learn","x":"حكاية عن بحر ونور وليلة عاصفة. مارلو حكى بدايتها، وموسايوس حكى نهايتها، وشكسبير ضحك منها واقتبس منها. نكمل في الفصل الجاي مع فيليمون وباوكيس. 🎓"},{"i":"myth-m28","s":1,"h":"إحنا فين في الحكاية","t":"learn","x":"الفصل اللي فات كان هيرو وليندر: حب انتهى بغرق. النهارده قصة مختلفة: حب هادي بين زوجين عواجيز، وضيافة بسيطة، ونهاية حلوة. فيليمون ( Philemon ) وباوكيس ( Baucis ). مثال من حياتنا: جيران فقراء فتحوا بيتهم لضيف غريب ما حدش رضي يستقبله. والضيف طلع أكبر من اللي كانوا فاكرينه."},{"i":"myth-m28","s":2,"h":"إحنا فين في الحكاية","t":"learn","x":"ملحوظة: القصة موجودة عند أوفيد ( Ovid ) في الكتاب الثامن من المسخ. وسويفت ( Swift ) كتب نسخة إنجليزية ساخرة منها، وكتب في عنوانها إنها \" Imitated from the Eighth Book of Ovid \"."},{"i":"myth-m28","s":3,"h":"إحنا فين في الحكاية","t":"mc","x":"سويفت كتب في عنوان قصيدته إنها: ؟ Translated from Homer / Imitated from the Eighth Book of Ovid / Written for the Queen / Adapted from Virgil's Eclogues . Imitated from the Eighth Book of Ovid"},{"i":"myth-m28","s":5,"h":"البطاقة الأساسية","t":"learn","x":"الأشخاص فيليمون وباوكيس: زوجين عواجيز متجوزين من شبابهم في نفس الكوخ، بحسب أوفيد. جوبيتر ( Jupiter ) وميركوري ( Mercury ): الاتنين نزلوا الأرض كأنهم مسافرين تعبانين. أوفيد بيسمي ميركوري \"ابنه\" يعني ابن جوبيتر. ليليكس ( Lelex ): الراجل الحكيم اللي بيحكي الحكاية قدام الناس. المكان تلال فريجيا ( Phrygia ). والمكان اللي كان فيه الكوخ بقى مستنقعات."},{"i":"myth-m28","s":6,"h":"البطاقة الأساسية","t":"learn","x":"المصدر اللي هنقتبس منه أوفيد، المسخ، الكتاب الثامن، السطور ٦١١-٧٢٤. الفكرة الكبيرة الضيافة الطيبة بتتكافأ. والشر بيتعاقب."},{"i":"myth-m28","s":8,"h":"ليه الحكاية بتتحكي؟","t":"learn","x":"الشكاك أوفيد بيقول إن في ناس اتحولت أشكالهم. وواحد من الناس، \"ابن إكسيون المتكبر\" ( Ixion's haughty son )، ضحك وقال إن ده كلام فاضي. وقال إن مفيش إله بيقدر يغير الأشكال. الرد ليليكس رد: قدرة الآلهة ما بتتحدش. وقال إنه شاف بنفسه في تلال فريجيا شجرتين، شجرة زيزفون ( linden ) وشجرة بلوط، فروعهم متشابكة، وحواليهم سور حجر واطي."},{"i":"myth-m28","s":9,"h":"ليه الحكاية بتتحكي؟","t":"learn","x":"وقال: عشان ماتشكش، \" I saw the spot \" يعني شفت المكان بنفسي. مثال من حياتنا زي واحد بيقولك: أنا شفت ده بعيني. الحكاية بتتحكي كشهادة، مش كخيال."},{"i":"myth-m28","s":11,"h":"السفر والأبواب المقفولة","t":"learn","x":"الزوار جوبيتر وابنه بيتجولوا في الأرض كمسافرين تعبانين، وبيطلبوا أكل وسرير. من ألف بيت تقريبا، كل الأبواب كانت مقفولة. أوفيد بيقول: \" so wicked were the people of that land \" يعني: الناس هناك كانوا أشرار. الكوخ في الآخر وصلوا لبيت صغير سقفه من قش وبوص. وهناك استقبلهم زوجين عواجيز."},{"i":"myth-m28","s":12,"h":"السفر والأبواب المقفولة","t":"mc","x":"ليه الزوار راحوا لكوخ فيليمون وباوكيس؟ ؟ لأنه أكبر بيت في القرية / لأنهم يعرفوهم من قبل / لأنهم كانوا مدعوين / لأن كل الأبواب التانية اتقفلت قدامهم . لأن كل الأبواب التانية اتقفلت قدامهم"},{"i":"myth-m28","s":13,"h":"السفر والأبواب المقفولة","t":"learn","x":"أوفيد بيقول إنهم تجوزوا في شبابهم في نفس الكوخ، وعاشوا فيه ووصلوا لسن كبيرة. وكانوا راضيين بفقرهم، من غير خجل منه. ومفيش عندهم خدم. هما بيخدموا نفسهم. مثال من حياتنا زي بيت بسيط فيه زوجين كبار، بيتعاملوا مع الضيف كأنه من العيلة."},{"i":"myth-m28","s":15,"h":"العشا البسيط","t":"learn","x":"الاستقبال فيليمون قدم دكة قعدوا عليها، وباوكيس حطت عليها قماش. باوكيس نفخت في الجمر لحد ما اشتعل، وجابت حطب. وحطت قدر مش كبير. فيليمون جاب كرنب من الجنينة، ونزل قطعة لحم خنزير مملح ( bacon ) كانت متعلقة فوق. المائدة ترابيزة رجل منها قصيرة، فباوكيس حطت تحتها قطعة فخار تثبتها. وبعدين نضفتها بالنعناع."},{"i":"myth-m28","s":16,"h":"العشا البسيط","t":"learn","x":"قدموا ثمر مينرفا ذو اللونين (ودي طريقة الترجمة في الكلام عن الزيتون)، وفجل، ولبن رايب، وبيض في الجمر. وبعدين جوز وتين ورطب وتفاح وعسل. اللي بيخلي الأكل مميز أوفيد بيقول إن الفواكه اتقدمت مع \" willing service and congenial smiles \" يعني خدمة بإرادة وابتسامات ودودة. مثال من حياتنا زي واحد غلبان يطلع كل اللي عنده للضيف، ويحس إن ده أقل واجب."},{"i":"myth-m28","s":17,"h":"العشا البسيط","t":"mc","x":"إيه الزيتون في الحكاية بيتسمى؟ ؟ ثمر فينوس / ثمر جوبيتر / ثمر مينرفا ذو اللونين / ثمر ديانا . ثمر مينرفا ذو اللونين"},{"i":"myth-m28","s":19,"h":"المعجزة الأولى","t":"learn","x":"الإبريق كل ما كانوا يشربوا، كان الإبريق بيتملى لوحده. فيليمون وباوكيس اتخضوا ورفعوا إيديهم، وطلبوا السماح على البيت والأكل البسيط. الوزة فهموا إن الزوار آلهة. فحاولوا يمسكوا وزتهم الوحيدة اللي بتحرس البيت عشان يدبحوها لهم. الوزة جريت واحتمت بالآلهة. والآلهة منعتهم. الإنذار"},{"i":"myth-m28","s":20,"h":"المعجزة الأولى","t":"mc","x":"إيه المعجزة اللي كشفت إن الزوار آلهة؟ ؟ الإبريق بيتملى لوحده / الخبز اتحول دهب / الكوخ طار في السما / الباب اتفتح من نفسه . الإبريق بيتملى لوحده"},{"i":"myth-m28","s":21,"h":"المعجزة الأولى","t":"mc","x":"إيه اللي حصل للوزة؟ ؟ اتدبحت للضيوف / احتمت بالآلهة والآلهة منعتهم يدبحوها / اتحولت لشجرة / هربت للغابة . احتمت بالآلهة والآلهة منعتهم يدبحوها"},{"i":"myth-m28","s":22,"h":"المعجزة الأولى","t":"learn","x":"الآلهة قالت إن الجيران الأشرار هيتعاقبوا، وإن البيت البسيط ما يصيبهوش حاجة. وطلبوا من الزوجين يطلعوا معاهم الجبل."},{"i":"myth-m28","s":24,"h":"الطوفان والمعبد","t":"learn","x":"الطلوع الزوجين طلعوا متكيين على عصيانهم. وقفوا قبل القمة بمسافة سهم من قوس الصياد. لما بصوا وراهم، شافوا الأرض حوالين بيتهم غرقت في مستنقع. بيتهم بس فضل. التحول وهما بيبكوا على أصحابهم، شافوا بيتهم الصغير بيتحول لمعبد: أعمدة من رخام بدل الخشب، وسقف بلمعة الدهب، وأبواب منقوشة. السؤال"},{"i":"myth-m28","s":25,"h":"الطوفان والمعبد","t":"tf","x":"الأرض حوالين الكوخ غرقت في مستنقع، وبيتهم بس فضل. . صح"},{"i":"myth-m28","s":26,"h":"الطوفان والمعبد","t":"learn","x":"جوبيتر (اسمه في النص ابن ساترن Saturn ) قال لهم بصوت لطيف: إيه اللي تتمنوه؟ مثال من حياتنا زي حد بيسأل واحد غلبان: اطلب أي حاجة. والجواب بيكشف مين هو الشخص."},{"i":"myth-m28","s":28,"h":"الأمنية والتحول","t":"learn","x":"الأمنية فيليمون اتشاور مع باوكيس، وبعدين قال إنهم عايزين يكونوا حراس المعبد. وبما إنهم عاشوا سنين كتير في وئام، عايزين يموتوا في نفس الساعة: \" I would not see the tomb of my dear wife \". يعني: ما أحبش أشوف قبر مراتي. التنفيذ اتحققت أمنيتهم. فضلوا حراس المعبد لحد ما كبروا."},{"i":"myth-m28","s":29,"h":"الأمنية والتحول","t":"mc","x":"إيه الأمنية اللي طلبها فيليمون؟ ؟ حراسة المعبد وإنهم يموتوا مع بعض / فلوس كتير / شباب دايم / بيت أكبر . حراسة المعبد وإنهم يموتوا مع بعض"},{"i":"myth-m28","s":30,"h":"الأمنية والتحول","t":"tf","x":"عند أوفيد، فيليمون وباوكيس اتحولوا لحيوانات. . غلط"},{"i":"myth-m28","s":31,"h":"الأمنية والتحول","t":"learn","x":"وفي يوم، كانوا واقفين عند السلالم المقدسة وبيحكوا الحكاية. باوكيس شافت فيليمون وهو بيطلع ورق، وهو شافها كمان. ولما أعلى الشجر غطى وشوشهم، قالوا لبعض: \" Farewell, farewell, my own \". يعني: مع السلامة يا حبيبي. وبعدين أوراق وفروع غطتهم الاتنين مع بعض. الشاهد"},{"i":"myth-m28","s":32,"h":"الأمنية والتحول","t":"learn","x":"أوفيد بيقول إن في تيانا ( Tyana ) الناس بيشاوروا على شجرتين طالعين من جذع مزدوج. وليليكس بيقول إنه شاف أكاليل معلقة على الفروع. وقال: \" Those whom the Gods care for are Gods ! And those who worshiped are now worshiped here .\" يعني: اللي بتهتم بيهم الآلهة بقوا آلهة، واللي عبدوا بقوا هم نفسهم معبودين هنا."},{"i":"myth-m28","s":34,"h":"إزاي نفهم الحكاية؟","t":"learn","x":"قراءة الضيافة الحكاية بتقول إن الضيافة البسيطة قيمتها كبيرة، حتى لو الضيف مجهول. دي قراءة بسيطة. قراءة الحب الاتنين بيطلبوا ما يتفرقوش. دي قراءة تانية: الحكاية عن حب العمر، مش حب الشباب. قراءة العقاب الأشرار اتعاقبوا بالغرق، والطيبين اتكافأوا. بس النص ما بيقولش تفاصيل كتير عن عقاب الجيران، بيقول بس إنها \" wicked neighborhood \". السؤال للطالب"},{"i":"myth-m28","s":35,"h":"إزاي نفهم الحكاية؟","t":"learn","x":"لو كنت مكان فيليمون وباوكيس، كنت هتفتح الباب لو ما تعرفش مين الزوار؟ دافع بسطر."},{"i":"myth-m28","s":37,"h":"الأسطورة في الشعر الإنجليزي","t":"learn","x":"جوناثان سويفت، \" Baucis and Philemon \" سويفت كتب قصيدة بالإنجليزي ورجع الحكاية لإنجلترا: القديسين بدل الآلهة، وقرية في كنت ( Kent )، وكنيسة بدل معبد. وكتب في عنوانها: \" Imitated from the Eighth Book of Ovid \". ١) بداية الحكاية"},{"i":"myth-m28","s":38,"h":"الأسطورة في الشعر الإنجليزي","t":"learn","x":"\" In ancient times, as story tells , / The saints would often leave their cells , / And stroll about, but hide their quality , / To try good people's hospitality .\" يعني: في الزمن القديم، زي ما بتقول الحكاية، القديسين كانوا بيسيبوا صوامعهم ويتمشوا من غير ما يعرفوا مين هم، عشان يختبروا ضيافة الناس الطيبين."},{"i":"myth-m28","s":39,"h":"الأسطورة في الشعر الإنجليزي","t":"learn","x":"لاحظ: سويفت بيذكر \"الضيافة\" في الأربع أسطر الأولى. يعني نفس فكرة أوفيد. ٢) الراجل والكوخ \" Where dwelt a good honest old yeoman , / Called, in the neighbourhood, Philemon ,\" يعني: كان فيه فلاح عجوز طيب وأمين، الناس بتسميه فيليمون. ٣) الإبريق اللي بيتملى \"' Twas still replenished to the top , / As if they ne'er had touched a drop .\""},{"i":"myth-m28","s":40,"h":"الأسطورة في الشعر الإنجليزي","t":"mc","x":"إيه الفرق في أمنية فيليمون عند سويفت؟ ؟ يبقى قسيس ويعيش مرتاح / يحرس معبد ويموت مع مراته / يبقى غني / يتحول لشجرة . يبقى قسيس ويعيش مرتاح"},{"i":"myth-m28","s":41,"h":"الأسطورة في الشعر الإنجليزي","t":"tf","x":"عند سويفت الزوجين اتحولوا لأشجار طقسوس ( yews ). . صح"},{"i":"myth-m28","s":42,"h":"الأسطورة في الشعر الإنجليزي","t":"learn","x":"يعني: لقوه مليان لحد فوق، كأنهم ما شربوش ولا نقطة. نفس معجزة أوفيد. ٤) البيت يتحول لكنيسة (والكوميديا) \" The kettle to the top was hoist , / And there stood fastened to a joist ; / But with the upside down, to show / Its inclination for below .\""},{"i":"myth-m28","s":43,"h":"الأسطورة في الشعر الإنجليزي","t":"learn","x":"يعني: الغلاية اترفعت لفوق وثبتت في عارضة، بس بالمقلوب، عشان تبين إنها عايزة تنزل. الفكرة: سويفت بيعمل من التحول مشهد مضحك. ٥) أمنية فيليمون \" I'm old, and fain would live at ease , / Make me the Parson, if you please .\""},{"i":"myth-m28","s":44,"h":"الأسطورة في الشعر الإنجليزي","t":"learn","x":"يعني: أنا عجوز وعايز أعيش مرتاح، خليني القسيس لو سمحت. ده الفرق الكبير: أوفيد بيخلي فيليمون يطلب يحرس المعبد، وسويفت بيخليه يطلب يبقى قسيس ويسخر من القسيسين. ٦) التحول لأشجار \" Description would but tire my Muse ; / In short, they both were turned to Yews .\""},{"i":"myth-m28","s":45,"h":"الأسطورة في الشعر الإنجليزي","t":"learn","x":"يعني: الوصف هيتعب موهبتي، باختصار الاتنين اتحولوا لأشجار طقسوس ( yew ). قبلها بتقول باوكيس \" My dear, I see your forehead sprout !\" يعني: يا عزيزي، شايفة جبهتك بتطلع براعم. لاحظ: عند أوفيد الأشجار هي اللي بتشير ليها الناس، وعند سويفت الأشجار طقسوس في ساحة كنيسة. ٧) النهاية"},{"i":"myth-m28","s":46,"h":"الأسطورة في الشعر الإنجليزي","t":"learn","x":"\" Here Baucis, there Philemon grew , / Till once a parson of our town , / To mend his barn, cut Baucis down ;\" يعني: هنا نبتت باوكيس، وهناك فيليمون، لحد ما قسيس من بلدنا قطع باوكيس عشان يصلح حظيرته. وده بعد ساخر جديد، مش موجود في النسخة اللي قريناها عند أوفيد. الفرق بين أوفيد وسويفت"},{"i":"myth-m28","s":47,"h":"الأسطورة في الشعر الإنجليزي","t":"learn","x":"أوفيد: آلهة، معبد، حب عميق، وشجرتين طالعين من جذع واحد (ليليكس بيذكرهم زيزفون ( linden ) وبلوط). سويفت: قديسين، كنيسة، سخرية من القسيس، وشجرتين في ساحة الكنيسة. نفس الأسطورة، بس سويفت بيحولها لنكتة اجتماعية."},{"i":"myth-m28","s":49,"h":"إزاي تعرفها في عمل أدبي","t":"learn","x":"لو شفت زوجين عواجيز بيستقبلوا ضيف غريب وبيطلع أكبر من المتوقع، افتكر الحكاية. لو شفت بيت متواضع بيتحول لمعبد أو كنيسة، دي نفس الفكرة. لو شفت اتنين بيتحولوا لشجرتين جنب بعض، افتكر فيليمون وباوكيس. لو شفت إبريق بيتملى لوحده، ده تلميح للحكاية."},{"i":"myth-m28","s":51,"h":"أخطاء شائعة","t":"learn","x":"الزوار مش مجرد مسافرين. هم جوبيتر وميركوري عند أوفيد. مفيش حد اتحول لحيوان. الوزة بس نجت. عند أوفيد المكان فريجيا، وعند سويفت قرية في كنت. عند أوفيد الآلهة بتحول البيت لمعبد، وعند سويفت القديسين بيحولوه لكنيسة. الأشجار عند أوفيد هي اللي الناس بتشوفها بعد التحول. وعند سويفت الأشجار طقسوس."},{"i":"myth-m28","s":53,"h":"كلمات هتقع لك في الشعر","t":"learn","x":"hospitality : ضيافة. cottage : كوخ. yeoman : فلاح حر. sprout : يطلع براعم. yew : شجرة الطقسوس. parson : قسيس. temple : معبد. wicked : شرير."},{"i":"myth-m28","s":55,"h":"خريطة الفصول الجاية","t":"learn","x":"الفصل ٢٩: سيكس وألكيوني. الفصل ٣٠: كيوبيد وسايكي."},{"i":"myth-m28","s":57,"h":"ملخص في عشر جمل","t":"learn","x":"١. جوبيتر وميركوري بيزوروا الأرض كمسافرين. ٢. الأبواب كلها مقفولة. ٣. فيليمون وباوكيس يستقبلوهم في كوخ بسيط. ٤. بيقدموا كل اللي عندهم. ٥. الإبريق بيتملى لوحده. ٦. الآلهة بتكشف نفسها وبتنقذ الزوجين. ٧. الأرض حوالين البيت بتغرق. ٨. الكوخ بيتحول لمعبد. ٩. الزوجين يطلبوا يموتوا مع بعض، فيتحولوا لشجرتين. ١٠. سويفت يخلي الحكاية ساخرة في إنجلترا."},{"i":"myth-m28","s":59,"h":"مهمتك قبل الفصل الجاي","t":"learn","x":"اقرا أبيات سويفت عن التحول لكنيسة تاني. اكتب جملتين: إيه اللي ضحك سويفت في التحول؟ واكتب جملة عن سبب إن الزوجين طلبوا يموتوا مع بعض."},{"i":"myth-m28","s":61,"h":"خاتمة","t":"learn","x":"حكاية عن باب اتفتح، وإبريق اتملى، وشجرتين فضلوا جنب بعض. أوفيد حكاها بحب، وسويفت حكاها بسخرية. نكمل في الفصل الجاي مع سيكس وألكيوني. 🎓"},{"i":"myth-m3","s":0,"h":"","t":"learn","x":"📌 1) الفكرة في سطر: الإنسان بينزل مش بيطلع مثال من حياتنا: جدك بيقول \"زمان كان الناس أحن على بعض والعيشة أرخص والدنيا أمان\". كل جيل بيقول الكلام ده. الفكرة دي عمرها أكتر من 2700 سنة، وأول واحد كتبها شاعر إغريقي اسمه Hesiod : البشرية مش بتتقدم، البشرية بتنزل من عصر أحلى لعصر أسوأ."},{"i":"myth-m3","s":1,"h":"","t":"learn","x":"كل عصر اسمه معدن: ذهب ← فضة ← برونز ← (أبطال) ← حديد. لاحظ: المعدن بيرخص، يعني القيمة بتقل. 📌 2) العصر الذهبي ( The Golden Age ) Hesiod بيقول بالحرف ( Works and Days 109-120 ):"},{"i":"myth-m3","s":2,"h":"","t":"mc","x":"مين أول واحد كتب فكرة العصور (أعمار البشرية) المسماة بالمعادن؟ ؟ Ovid / Milton / Hesiod / Virgil . Hesiod"},{"i":"myth-m3","s":3,"h":"","t":"learn","x":"\" First of all the deathless gods who dwell on Olympus made a golden race of mortal men who lived in the time of Cronos when he was reigning in heaven. And they lived like gods without sorrow of heart, remote and free from toil and grief : miserable age rested not on them. ..\" زمان ما Cronos ( Saturn ) كان لسه الملك — افتكر الدرس اللي فات."},{"i":"myth-m3","s":4,"h":"","t":"mc","x":"في الفكرة دي، المعادن بترخص يعني... ؟ القيمة بتزيد: برونز، فضة، دهب / القيمة ثابتة في كل العصور / المعادن ملهاش علاقة بالقيمة / القيمة بتقل: ذهب، فضة، برونز، حديد . القيمة بتقل: ذهب، فضة، برونز، حديد"},{"i":"myth-m3","s":5,"h":"","t":"learn","x":"عاشوا زي الآلهة: لا شغل، لا شقى، لا شيخوخة. الأرض بتطلع أكل لوحدها. لما ماتوا، ماتوا \"كأنهم ناموا\"، وبقوا أرواح طيبة حارسة للبشر. ملحوظة مهمة للامتحان: لما تقرا \" golden age \" في أي نص إنجليزي، دي الإشارة الأصلية. 📌 3) العصر الفضي ( The Silver Age ) \"أقل نبلا بكتير\" حسب تعبير Hesiod. الطفل بيفضل طفل يلعب جنب أمه مية سنة، وبعدين يعيش شوية صغيرين في هم."},{"i":"myth-m3","s":6,"h":"","t":"mc","x":"إزاي كان عيش الناس في العصر الذهبي عند Hesiod ؟ ؟ في حروب دايمة / زي الآلهة من غير شقى وشيخوخة / تحت الأرض / على جبل واحد بس . زي الآلهة من غير شقى وشيخوخة"},{"i":"myth-m3","s":7,"h":"","t":"learn","x":"خطيتهم: ماعبدوش الآلهة ولا قدموا قربان، ف Zeus خباهم تحت الأرض. القاعدة: النزول مش بس في الجسم، النزول في الأخلاق. 📌 4) العصر البرونزي ( The Bronze Age ) اتخلقوا من أشجار الدردار ( ash trees )، وكل همهم الحرب والعنف. أكلوا بعض ودمروا بعض، فنزلوا العالم السفلي بلا اسم ولا ذكر. لاحظ التصعيد: الذهبيين بقوا حراس، الفضيين اتخبوا، البرونزيين راحوا بالكلية."},{"i":"myth-m3","s":8,"h":"","t":"learn","x":"📌 5) عصر الأبطال ( The Age of Heroes ) — الاستثناء الوحيد Hesiod بيكسر سلسلة المعادن هنا ويحط عصر \"أنبل وأعدل\" من اللي قبله: عصر أنصاف الآلهة. دول أبطال طروادة وحرب طيبة ( Oedipus وعيلته — هناخدهم في المستوى الرابع). ماتوا في الحروب، و Zeus نقلهم ل \"جزر المباركين\" ( Isles of the Blest ) على أطراف الأرض."},{"i":"myth-m3","s":9,"h":"","t":"mc","x":"أنهي عصر بيكسر سلسلة المعادن عند Hesiod ؟ ؟ عصر الأبطال / العصر الفضي / عصر الذهب / العصر الحديدي . عصر الأبطال"},{"i":"myth-m3","s":10,"h":"","t":"learn","x":"ليه الاستثناء ده مهم؟ لأنه بيثبت إن Hesiod بيشرح الملاحم اللي الناس بتحفظها (هوميروس)، مش بس بيبكي على الماضي. 📌 6) العصر الحديدي ( The Iron Age ) — عصرنا احنا Hesiod بيقول: يا ريتني مت قبله أو اتولدت بعده. شغل وهم نهار، وهلاك ليل. الأب هيخاصم ابنه، والضيف هيخون مضيفه، والقوة هتبقى هي العدل."},{"i":"myth-m3","s":11,"h":"","t":"learn","x":"آخر حاجة حزينة: في الآخر هتهاجر من الأرض آخر إلهين باقيين مع البشر: Aidos (الحياء) و Nemesis (الغضب العادل)، ويسيبوا البشر لوحدهم. الصورة دي — \"العدالة بتسيب الأرض\" — هي اللي هتكبر وتدخل الشعر الإنجليزي (شوف قسم الشعر تحت). 📌 7) نسخة Ovid (أوفيد) — مختلفة في نقطتين"},{"i":"myth-m3","s":12,"h":"","t":"mc","x":"في آخر العصر الحديدي، مين اللي بيسيب الأرض؟ ؟ Aidos (الحياء) و Nemesis (الغضب العادل) / Zeus و Hera / Apollo و Artemis / Athena و Hermes . Aidos (الحياء) و Nemesis (الغضب العادل)"},{"i":"myth-m3","s":13,"h":"","t":"learn","x":"Ovid في Metamorphoses الكتاب 1 عنده أربعة عصور بس: شال عصر الأبطال خالص (ذهبي، فضي، برونزي، حديدي). وفي نسخته التدهور سببه فساد البشر نفسهم، والتفاصيل ألطف وأشعر."},{"i":"myth-m3","s":14,"h":"","t":"mc","x":"عند Ovid ، كام عصر؟ ؟ أربعة / خمسة / تلاتة / ستة . أربعة"},{"i":"myth-m3","s":15,"h":"","t":"learn","x":"📌 8) الأسطورة في الشعر الإنجليزي: أ) ترجمة Golding ل Ovid (1567) — ترجمة شكسبير — وصف العصر الذهبي: \" Then sprang up first the golden age, which of itself maintained The truth and right of everything unforced and unconstrained. There was no fear of punishment, there was no threatening law. ..\""},{"i":"myth-m3","s":16,"h":"","t":"mc","x":"كمل الجملة اللي لسه شايفها: Then sprang up _____ the golden age, ؟ last / first / rested / magnus . Then sprang up first the golden age,"},{"i":"myth-m3","s":17,"h":"","t":"learn","x":"(العصر الذهبي قام الأول، بيحافظ على الحق والعدل من نفسه، من غير قانون ولا تهديد). الصورة: مجتمع مفيش محتاج قاضي أصلا. ب) السلسلة الرومانية: Virgil ، Eclogue الرابعة (حوالي 40 ق.م): نبوءة رجوع العصر الذهبي: \" iam redit et Virgo, redeunt Saturnia regna \""},{"i":"myth-m3","s":18,"h":"","t":"learn","x":"(\"العذراء رجعت بالفعل، وحكم زحل بيرجع\"). ال Virgo (العذراء) هنا هي Astraea ، آلهة العدل اللي سابت الأرض آخر العصر الحديدي. والسطر قبله \" magnus ab integro saeclorum nascitur ordo \" (نظام عظيم للعصور بيتولد من جديد) — منه اتاخد شعار الدولار الأمريكي novus ordo seclorum."},{"i":"myth-m3","s":19,"h":"","t":"mc","x":"مين ال Virgo (العذراء) في Eclogue 4 ل Virgil ؟ ؟ Athena / Aphrodite / Demeter / Astraea ، آلهة العدل . Astraea ، آلهة العدل"},{"i":"myth-m3","s":20,"h":"","t":"learn","x":"ج) Dryden ، قصيدة \" Astraea Redux \" (1660): بيحتفل برجوع الملك تشارلز التاني للعرش: \"العدالة رجعت\" = الملك رجع. العنوان نفسه allusion كامل: رجوع Astraea = رجوع العصر الذهبي. مثال نموذجي إزاي أسطورة بتتستخدم في السياسة. د) Milton ، \" On the Morning of Christ's Nativity \" (1629): ميلاد المسيح هيصلح العالم: \" Time will run back, and fetch the age of gold \""},{"i":"myth-m3","s":21,"h":"","t":"mc","x":"Dryden في Astraea Redux (1660) بيحتفل ب... ؟ نهاية حرب طروادة / ميلاد المسيح / رجوع الملك تشارلز التاني للعرش / ثورة صناعية . رجوع الملك تشارلز التاني للعرش"},{"i":"myth-m3","s":22,"h":"","t":"learn","x":"(الزمن هيرجع لورا ويجيب عصر الذهب). ميلتون بيستخدم أسطورة وثنية عشان يقول وعد مسيحي — نفس حركته مع ال \" Heav'nly Muse \" في M1. ه) Shelley ، الكورس الختامي لملحمة \" Hellas \" (1822): \" The world's great age begins anew, The golden years return \""},{"i":"myth-m3","s":23,"h":"","t":"learn","x":"(عصر العالم العظيم بيبدأ من جديد، سنين الذهب بترجع). Shelley الثوري بيحلم بعودة العصر الذهبي بثورة إنسانية مش بمعجزة."},{"i":"myth-m3","s":24,"h":"","t":"learn","x":"📌 9) كلمات وتعبيرات من درس النهارده: \" the golden age of. ..\" بقت تعبير إنجليزي عادي لحد النهارده: the golden age of television / of Hollywood — أي فترة القمة في أي حاجة. • Saturnia regna (حكم زحل) • Astraea (اسم بنات وكويكب ومجلات). ✏️ كويز M3 (بعد ٣٠ دقيقة):"},{"i":"myth-m3","s":25,"h":"","t":"mc","x":"كمل الجملة اللي لسه شايفها: the _____ age of. ؟ golden / boring / miserable / great . the golden age of."},{"i":"myth-m3","s":26,"h":"","t":"learn","x":"١) اكتب الأعمار الخمسة بالترتيب، وقول مين العصر اللي بيكسر السلسلة وليه. ٢) اشرح بالتفصيل حياة العصر الذهبي عند Hesiod ، وإيه مصير أهله بعد الموت. ٣) إيه الفرق بين نسخة Hesiod ونسخة Ovid (نقطتين)؟ ٤) وصل السلسلة: Astraea عند Hesiod ← Virgil ← Dryden. ليه عنوان \" Astraea Redux \" اختيار سياسي ذكي؟"},{"i":"myth-m3","s":27,"h":"","t":"learn","x":"٥) ترجم واشرح \" Time will run back, and fetch the age of gold \"، وقول إزاي ميلتون بيستخدم أسطورة وثنية في قصيدة مسيحية."},{"i":"myth-m3","s":29,"h":"تذكر واكتب","t":"recall","x":"اكتب الأعمار الخمسة بالترتيب عند هسيود. . الذهبي، والفضي، والبرونزي، وعصر الأبطال، والحديدي. والأخير هو اللي بنعيش فيه، وفيه العدالة سابت الأرض."},{"i":"myth-m3","s":30,"h":"تذكر واكتب","t":"recall","x":"مين Astraea ، وإيه اللي عملته آخر العصر الحديدي؟ . هي إلهة العدل. لما فسد الناس سابت الأرض وطلعت للسماء، فبقى غيابها علامة على إن العدالة مش بين الناس."},{"i":"myth-m3","s":31,"h":"تذكر واكتب","t":"write","x":"قارن في ٣-٤ جمل بين استعمال Dryden لأسطورة العصر الذهبي في Astraea Redux واستعمال ميلتون لها في قصيدة الميلاد. . Dryden بيستعمل رجوع العدالة كناية عن رجوع الملك تشارلز التاني، فالعصر الذهبي بقى برنامجا سياسيا، والقصيدة كلها مناسبة عامة بتخص البلد. ميلتون في قصيدة الميلاد بيقول \" Time will run back, and fetch the age of gold \"، لكن اللي بيرجع العصر عنده مش ملك، هو حدث ديني، والزمن نفسه هو اللي بيرجع لورا. الاتنين بيستعملوا نفس الأسطورة، والفرق في مين اللي بيعمل المعجزة، وفي حجم الأمل المعلق عليها."},{"i":"myth-m3","s":32,"h":"تذكر واكتب","t":"write","x":"قارن في ٣-٤ جمل بين نبوءة Virgil في الإك logue الرابعة وخاتمة Shelley في Hellas . . Virgil بيعلن \" iam redit et Virgo, redeunt Saturnia regna \" كنبوءة، واللي بيرجع العصر إرادة إلهية، والناس بتستقبل فقط. Shelley بيقول في خاتمة Hellas \" The world's great age begins anew , / The golden years return \"، لكن اللي بيرجعه عنده ثورة بشرية، والفاعل هو الإنسان. الصورة واحدة، والمحرك مختلف: نبوءة عند الرومان، وأمل سياسي عند الرومانتيكيين. وده يوضح إن الأسطورة بتفضل نفسها، وأهل كل عصر بيحطوا فيها اللي محتاجينه."},{"i":"myth-m4","s":0,"h":"","t":"learn","x":"📌 1) ليه الحكاية دي هتبقى مألوفة ليك؟ كل حضارة قديمة عندها قصة طوفان: عندنا قصة سيدنا نوح في القرآن والتوراة، والإغريق عندهم نسختهم. وهتلاقي نفس الهيكل: فساد البشر ← غضب إلهي ← طوفان ← ناجي صالح ← بشرية جديدة. مقارنة القصص دي مهارة امتحان بحد ذاتها. 📌 2) السبب: الملك Lycaon"},{"i":"myth-m4","s":1,"h":"","t":"mc","x":"إيه الهيكل المشترك لقصص الطوفان القديمة؟ ؟ حرب، سلام، زواج / فساد البشر، غضب إلهي، طوفان، ناجي صالح، بشرية جديدة / سفر، كنز، عودة / حب، فراق، لقاء . فساد البشر، غضب إلهي، طوفان، ناجي صالح، بشرية جديدة"},{"i":"myth-m4","s":2,"h":"","t":"learn","x":"Zeus نزل يتفقد البشر متنكرا، فاختبره ملك اسمه Lycaon : قدم له لحم إنسان في الأكل عشان يشوف هيعرف ولا لأ. Zeus غضب: حرق قصره وحول Lycaon نفسه لذئب. من الحكاية دي جت كلمة lycanthropy (التحول لذئب) — ومنها كل أفلام المستذئبين ( werewolf ) لحد النهارده. وقرر Zeus : البشرية الفاسدة دي لازم تتغسل. 📌 3) الطوفان"},{"i":"myth-m4","s":3,"h":"","t":"mc","x":"إيه اللي حصل ل Lycaon بعد ما قدم ل Zeus لحم إنسان؟ ؟ اتحول لطائر / اتحول لذئب / اتحول لحجر / اتحول لشجرة . اتحول لذئب"},{"i":"myth-m4","s":4,"h":"","t":"learn","x":"Zeus (ومعه Poseidon في نسخة Ovid ) فتح السما والبحر، فغرقت الأرض كلها: الجبال بقت جزر والأسماك بتعوم فوق الغيطان. مين الناجي الوحيد؟ Deucalion ابن Prometheus (اللي هناخده الدرس الجاي) ومراته Pyrrha بنت Epimetheus. زوجين صالحين، ركبوا مركب صغيرة وطافوا فوق المية، لحد ما وقفوا على قمة جبل Parnassus — افتكر الجبل ده من M1 : جبل ال Muses."},{"i":"myth-m4","s":5,"h":"","t":"mc","x":"مين الناجي الوحيد من الطوفان في أسطورة Deucalion ؟ ؟ Zeus و Hera / Cronos و Rhea / Deucalion ومراته Pyrrha / Prometheus و Pandora . Deucalion ومراته Pyrrha"},{"i":"myth-m4","s":6,"h":"","t":"learn","x":"📌 4) نبوءة Themis : أحلى لغز في الدرس لما المية نشفت وشافوا الأرض فاضية، وقفوا قدام معبد آلهة اسمها Themis (العدل/الناموس) وسألوها: إزاي نرجع البشر؟ (من نص Ovid بترجمة Brookes More ): \" Depart from me and veil your brows ; ungird your robes, and cast behind you as you go, the bones of your great mother. \""},{"i":"myth-m4","s":7,"h":"","t":"learn","x":"(\"ارحلوا عني وغطوا رؤوسكم، وحلوا أحزمتكم، وارموا ورا ظهوركم وانتوا ماشيين عظام أمكم الكبيرة.\") Pyrrha اتهلعت: أنبش قبور؟ أدنس عظام أمي؟ ورفضت. بس Deucalion فكر وفك اللغز: \" Our mother is the Earth, and I may judge the stones of earth are bones that we should cast behind us as we go. \" (\"أمنا هي الأرض، وعظامها هي حجارة الأرض — دي اللي نرميها.\")"},{"i":"myth-m4","s":8,"h":"","t":"mc","x":"إيه معنى نبوءة Themis (ارموا عظام أمكم الكبيرة ورا ظهوركم)؟ ؟ الأم هي الأرض، وعظامها هي الحجارة / اسحبوا قبر أمكم / اهربوا من الجزيرة / ادفنوها تحت شجرة . الأم هي الأرض، وعظامها هي الحجارة"},{"i":"myth-m4","s":9,"h":"","t":"learn","x":"درس امتحاني: النبوءات في الأسطورة دايما متلغزة، والبطل الذكي هو اللي بيفك الرمز مش اللي بياخد الكلام حرفيا. 📌 5) البشرية التانية من الحجر رميا الحجارة وراهم، والحجارة لانت وكبرت واتشكلت ناس — الأول \"زي تمثال رخام لسه بيتنحت\":"},{"i":"myth-m4","s":10,"h":"","t":"learn","x":"\" every stone Deucalion threw should take the form of man, and those by Pyrrha cast should woman's form assume : so are we hardy to endure and prove by toil and deeds from what we sprung. \" (حجارة Deucalion بقت رجالة وحجارة Pyrrha بقت ستات: \"وعشان كده احنا جيل صلب بيتحمل وبيثبت بالشغل والتعب أصلنا منين\".)"},{"i":"myth-m4","s":11,"h":"","t":"mc","x":"إيه اللي حصل لحجارة Deucalion وحجارة Pyrrha ؟ ؟ كلها بقت حيوانات / فضلت حجارة / بقت أشجار / حجارة Deucalion بقت رجالة وحجارة Pyrrha بقت ستات . حجارة Deucalion بقت رجالة وحجارة Pyrrha بقت ستات"},{"i":"myth-m4","s":12,"h":"","t":"mc","x":"كمل الجملة اللي لسه شايفها: _____ stone Deucalion threw should take the form of man, ؟ empty / should / every / stood . every stone Deucalion threw should take the form of man,"},{"i":"myth-m4","s":13,"h":"","t":"learn","x":"لاحظ الفكرة: الجيل الجديد \"جاي من حجر\" عشان كده قاسي وبيكدح — تفسير رمزي للشقاء الإنساني. ومن ولادهم جه Hellen ، ومنه اتسمى اليونانيون أنفسهم \" Hellenes \" وبلدهم Hellas — اسم اليونان الحقيقي لحد النهارده."},{"i":"myth-m4","s":14,"h":"","t":"mc","x":"اسم Hellenes اتاخد من... ؟ Zeus / Hellen ، ابن Deucalion / Pyrrha / Prometheus . Hellen ، ابن Deucalion"},{"i":"myth-m4","s":15,"h":"","t":"learn","x":"📌 6) الأسطورة في الشعر الإنجليزي: أ) Milton ، Paradise Lost الكتاب 11 (الأسطر 11-14): آدم واقف يصلي نادما بعد الخطيئة، فميلتون يشبهه: \"... with prayers / ... Deucalion and chaste Pyrrha, to restore / The race of mankind drowned, before the shrine / Of Themis stood devout. \""},{"i":"myth-m4","s":16,"h":"","t":"learn","x":"(زي Deucalion و Pyrrha العفيفة وقفوا متدينين قدام مذبح Themis عشان يرجعوا البشرية المغرقة.)"},{"i":"myth-m4","s":17,"h":"","t":"learn","x":"والعبقرية إن ميلتون قبلها بسطور كتب: \" Prevenient Grace descending had remov'd / The stonie from thir hearts, & amp ; made new flesh \" — النعمة النازلة شالت الحجر من قلوبهم وعملتهم لحم جديد. يعني عكس Ovid بالظبط: عند Ovid الحجر بقى بشر، عند ميلتون القلوب الحجرية هي اللي لانت. الأسطورة الوثنية اتعمدت تاني — نفس حركة M1 و M3."},{"i":"myth-m4","s":18,"h":"","t":"mc","x":"في Paradise Lost الكتاب 11، Milton بيشبه آدم النادم ب... ؟ Zeus وهو بيغضب / Deucalion و Pyrrha قدام مذبح Themis / Lycaon وهو بيهرب / Prometheus وهو بيتحمل . Deucalion و Pyrrha قدام مذبح Themis"},{"i":"myth-m4","s":19,"h":"","t":"learn","x":"ب) في Ovid نفسه (المصدر الأصلي): الخاتمة اللي فوق (\" so are we hardy to endure. ..\") بتيجي في الامتحان كتير لأنها ربط الأسطورة بشقاء البشر."},{"i":"myth-m4","s":20,"h":"","t":"learn","x":"📌 7) المقارنة مع قصة نوح (سؤال كلاسيكي): متشابه: غضب إلهي من الفساد ← طوفان ← ناجي صالح بأهله ← إعادة عمارة الأرض. مختلف: عندنا السفينة والحيوانات والوعد، وعندهم النبوءة المتلغزة والحجارة. عندهم البشر الجداد \"من حجر\"، وعندنا البشر من نسل نوح."},{"i":"myth-m4","s":21,"h":"","t":"mc","x":"إيه الاختلاف بين الطوفان الإغريقي وقصة نوح؟ ؟ مفيش أي اختلاف / عند الإغريق مفيش ناجي / عند الإغريق نبوءة متلغزة وحجارة، وعندنا السفينة والحيوانات والوعد / عند الإغريق ناجي واحد بس من غير مراته . عند الإغريق نبوءة متلغزة وحجارة، وعندنا السفينة والحيوانات والوعد"},{"i":"myth-m4","s":22,"h":"","t":"learn","x":"في الامتحان: اسم النوع ده \" flood myth \" وأسطورة Deucalion هي النسخة الإغريقية-الرومانية اللي الشعراء الإنجليز بيرجعولها."},{"i":"myth-m4","s":23,"h":"","t":"learn","x":"📌 8) كلمات من درس النهارده: lycanthropy / werewolf • diluvial/antediluvian (قبل الطوفان — بتتقال كناية عن حاجة قديمة أوي: \" antediluvian ideas \") • Parnassus • Themis (رمز العدالة بالميزان في المحاكم لحد النهارده). ✏️ كويز M4 (بعد ٣٠ دقيقة):"},{"i":"myth-m4","s":24,"h":"","t":"learn","x":"١) احك قصة Lycaon ، وقول إيه الكلمة الإنجليزية اللي طلعت منها واللي لسه بنستخدمها في أفلام الرعب. ٢) اكتب نص نبوءة Themis ، واشرح إزاي Deucalion فك اللغز، وليه ده \"درس في قراءة الرموز\". ٣) ترجم واشرح الجملة الختامية من Ovid (\" so are we hardy to endure. ..\") — إيه تفسير الأسطورة لشقاء البشر؟"},{"i":"myth-m4","s":25,"h":"","t":"mc","x":"كمل الجملة اللي لسه شايفها: so are we hardy to _____. ؟ endure / chaste / stone / forget . so are we hardy to endure."},{"i":"myth-m4","s":26,"h":"","t":"learn","x":"٤) إزاي ميلتون استخدم Deucalion و Pyrrha في Paradise Lost الكتاب 11؟ وإيه \"الانعكاس\" اللي عمله بالحجارة؟ ٥) قارن بين الطوفان الإغريقي وقصة سيدنا نوح في ٣ نقاط تشابه ونقطتين اختلاف."},{"i":"myth-m4","s":28,"h":"تذكر واكتب","t":"recall","x":"إيه اللي عمله Lycaon عشان يستحق العقوبة؟ . حاول يختبر زيوس وقدم له لحم إنسان، فزيوس حوله ذئبا. ومن الحكاية دي طلعت فكرة المستذئب."},{"i":"myth-m4","s":29,"h":"تذكر واكتب","t":"recall","x":"إزاي Deucalion و Pyrrha عرفوا يرجعوا البشر بعد الطوفان؟ . نبوءة Themis قالت لهم يرموا عظام أمهم ورا ضهرهم، ففهموا إن الأم هي الأرض، ورموا حجارة، فبقت الحجارة بشرا."},{"i":"myth-m4","s":30,"h":"تذكر واكتب","t":"write","x":"قارن في ٣-٤ جمل بين استخدام ميلتون ل Deucalion و Pyrrha في Paradise Lost 11 ونهاية القصة عند Ovid . . عند Ovid الحجر بيتحول لبشر، والختام بيقول إن البشر بقوا \" hardy to endure \"، أي قساة على التحمل، فالحكاية بتفسر قسوة الإنسان ومصدر شقاه. ميلتون بيعكس الصورة: قبل ما يذكر Deucalion و Pyrrha في الكتاب ١١، بيقول إن النعمة شالت \" the stonie \" من قلوب البشر وعملتها لحم جديد. يبدو أن ميلتون بيقصد إن التغيير الحقيقي جوه الإنسان مش في مادته، وده استخدام مسيحي لأسطورة وثنية: نفس الحجر، بس في اتجاه معاكس."},{"i":"myth-m4","s":31,"h":"تذكر واكتب","t":"write","x":"قارن في ٣-٤ جمل بين الطوفان الإغريقي وقصة نوح. . التشابه إن الطوفان عقوبة على فساد، والناجي راجل صالح بأهله، وبعدها بتبدأ حياة جديدة على أرض نضيفة. الاختلاف إن عندنا سفينة وحيوانات ووعد بأن الطوفان مش هيتكرر، وعند الإغريق نبوءة متلغزة وحجارة بتبني بشرا جداد. الفرق الأهم إن قصة نوح بتبدأ تاريخا جديدا، وأسطورة Deucalion بتفسر طبيعة الإنسان نفسه: البشر الجداد اتولدوا من حجر، فقسوتهم أصلها في مادتهم. ومع ذلك الاتنين بيتفقوا على إن الطوفان بيفصل بين زمنين، وإن اللي بعده مش زي اللي قبله."},{"i":"myth-m5","s":0,"h":"","t":"learn","x":"📌 1) التوصيل باللي فات افتكر من M4 : Deucalion ابن مين؟ ابن Prometheus. النهارده نعرف إيه اللي عمله الأب ده وخلى اسمه أشهر اسم في الميثولوجيا كلها. وافتكر من M2 : Prometheus و Epimetheus ولاد Iapetus (من ال Titans )."},{"i":"myth-m5","s":1,"h":"","t":"learn","x":"معنى الاسمين: Prometheus = \"اللي بيفكر قبل\" ( Forethought )، و Epimetheus = \"اللي بيفكر بعد\" ( Afterthought ). الاسمين توقعات شخصية مكتوبة من الميلاد. 📌 2) خدعة الأضحية (عند Mecone ) لما اتقسم قربان الثور بين الآلهة والبشر، Prometheus قسمه كومين: كوم لحم كويس متغطي بجلد قبيح، وكوم عظام متغطية بطبقة دهن شهية. وخلى Zeus يختار."},{"i":"myth-m5","s":2,"h":"","t":"mc","x":"اسم Prometheus معناه... ؟ اللي بيفكر بعد / النار / السارق / اللي بيفكر قبل ( Forethought ) . اللي بيفكر قبل ( Forethought )"},{"i":"myth-m5","s":3,"h":"","t":"learn","x":"Zeus اختار الدهن اللامع... فطلع عظام. ومن يومها الإغريق بيحرقوا العظام والدهن للآلهة ويأكلوا اللحم هما. مثال من حياتنا: زي اللي بيلف علبة فاضية بورق هدايا فخم. الدرس: شكل الكوم مش هو جواه. 📌 3) سرقة النار Zeus عاقب البشر بإنه خبى عنهم النار. بس Prometheus رجع سرقها لهم، بكلام Hesiod نفسه:"},{"i":"myth-m5","s":4,"h":"","t":"mc","x":"إزاي Prometheus خدع Zeus في الأضحية؟ ؟ قسم القربان كومين، وغطى العظام بالدهن اللامع / رفض يقدم قربان / سرق الثور / قدم قربان من ذهب . قسم القربان كومين، وغطى العظام بالدهن اللامع"},{"i":"myth-m5","s":5,"h":"","t":"learn","x":"\" but that the noble son of Iapetos stole again for men from Zeus the counsellor in a hollow fennel-stalk, so that Zeus who delights in thunder did not see it. \" (ابن Iapetos النبيل سرقها تاني للبشر... في ساق نبات شمر مجوفة، من غير ما Zeus يشوف.) النار هنا مش مجرد شوب: دي رمز الحضارة كلها — الطبخ والصناعة والعلم."},{"i":"myth-m5","s":6,"h":"","t":"mc","x":"سرق Prometheus النار في... ؟ كوب ذهب / كيس جلد / ساق نبات شمر مجوفة / صندوق خشب . ساق نبات شمر مجوفة"},{"i":"myth-m5","s":7,"h":"","t":"learn","x":"ورد Zeus ، بكلام Hesiod : \"هيديكوا مقابل النار شر يفرح قلوبكم وانتوا بتعانقوا دماركم بإيديكم\". 📌 4) خلق Pandora : أول ست Zeus أمر إنها تتصنع من طين ومية، وكل إله يديها \"هدية\": Hephaestus شكلها من الطين \"على شكل عذراء محتشمة\". Athena لبستها وعلمتها الغزل والنسيج. Aphrodite حطت على رأسها الجاذبية و\"الشوق القاسي والهموم اللي بتتعب الجسد\"."},{"i":"myth-m5","s":8,"h":"","t":"learn","x":"Hermes حط فيها \"عقل بلا خجل وطبيعة مخادعة\" وعلمها الكلام. والتسمية، بكلام Hesiod بالحرف ( Works and Days 80-82 ): \" And he called this woman Pandora ( All-Gifts ), because all they who dwelt on Olympos gave each a gift, a plague to men who eat bread. \" (وسمى الست دي Pandora يعني \"كل الهدايا\"، لأن كل سكان أوليمبوس أدوها كل واحد هدية... بلاء على البشر.)"},{"i":"myth-m5","s":9,"h":"","t":"mc","x":"اسم Pandora معناه... ؟ كل النار / الجرة / كل الهدايا ( All-Gifts ) / كل الأمراض . كل الهدايا ( All-Gifts )"},{"i":"myth-m5","s":10,"h":"","t":"mc","x":"كمل الجملة اللي لسه شايفها: And he _____ this woman Pandora ؟ dwelt / called / hated / wrongs . And he called this woman Pandora"},{"i":"myth-m5","s":11,"h":"","t":"learn","x":"ملحوظة للمستويات العليا (هترجع في المستوى 9): النص فيه نظرة سلبية للمرأة ك \"بلاء\" — النقد النسوي بيحلل ده. دلوقتي خزن الملاحظة بس. 📌 5) Epimetheus ياخد الهدية Prometheus كان محذر أخوه: \"ماتاخدش أي هدية من Zeus ، ابعتها راجع\". بس Epimetheus (اللي بيفكر بعد!) شاف الجمال ونسي التحذير. Hesiod بيقول ببرود: \"أخد الهدية، ولما الشر بقى بتاعه خلاص، فهم.\""},{"i":"myth-m5","s":12,"h":"","t":"learn","x":"مثال من حياتنا: صاحبك اللي بيفتكر نصيحتك بعد ما يقع في المشكلة بالظبط. 📌 6) الجرة — مش علبة! (أهم تصحيح لغوي في الكورس) في النص الأصلي الإغريقي، Pandora فتحت \" pithos \" — جرة تخزين كبيرة من الفخار، مش علبة."},{"i":"myth-m5","s":13,"h":"","t":"mc","x":"في النص الإغريقي الأصلي، Pandora فتحت... ؟ علبة صغيرة / صندوق خشب / جرة تخزين كبيرة ( pithos ) / كيس جلد . جرة تخزين كبيرة ( pithos )"},{"i":"myth-m5","s":14,"h":"","t":"learn","x":"\"العلبة\" جت من خطأ ترجمة: عالم النهضة Erasmus في القرن 16 ترجم الكلمة للاتيني بكلمة معناها علبة ( pyxis )، ومن يومها الإنجليزي ماشي ب \" Pandora's box \". . مينفعش تنسى ده في امتحان: الأصل jar ، والتقليد box. 📌 7) اللي طلع... واللي فضل جوه"},{"i":"myth-m5","s":15,"h":"","t":"mc","x":"مين سبب خطأ Pandora's box ؟ ؟ Hesiod / Homer / Erasmus في القرن 16، ترجم الكلمة بمعنى علبة ( pyxis ) / Ovid . Erasmus في القرن 16، ترجم الكلمة بمعنى علبة ( pyxis )"},{"i":"myth-m5","s":16,"h":"","t":"learn","x":"بكلام Hesiod ( Works and Days 90-105 ): \" But the woman took off the great lid of the jar with her hands and scattered all these and her thought caused sorrow and mischief to men. Only Hope remained there in an unbreakable home within under the rim of the great jar, and did not fly out at the door. .. But the rest, countless plagues, wander amongst men ; for earth is full of evils and the sea is full. Of themselves diseases come upon men continually by day and by night, bringing mischief to mortals silently ; for wise Zeus took away speech from them. \""},{"i":"myth-m5","s":17,"h":"","t":"learn","x":"طلعت: التعب الشاق، الأمراض، الهموم. وملحوظة عبقرية: Zeus شال من الأمراض الكلام، فبتيجي \"بصمت\" — مابتحذرش. فضلت جوه: Elpis (الأمل)، اتقفل عليها الغطا قبل ما تطير. سؤال النقاش المشهور (هتتسأل فيه): ليه الأمل فضل في الجرة؟ قراءتين: ١) الأمل هو العزاء الوحيد اللي اتساب للبشر. ٢) الأمل هو آخر الشرور، اتحبس عشان ميوصلش — لأن الأمل الكاذب بيطول المعاناة."},{"i":"myth-m5","s":18,"h":"","t":"mc","x":"إيه اللي فضل جوه الجرة؟ ؟ الأمراض / Elpis (الأمل) / النار / الخوف . Elpis (الأمل)"},{"i":"myth-m5","s":19,"h":"","t":"learn","x":"مفيش إجابة نهائية، والسؤال نفسه هو كنز الامتحان. 📌 8) عقاب Prometheus Zeus قيده بسلاسل على جبل في ال Caucasus ، وبعت نسر ياكل كبده كل يوم، والكبد يتجدد كل ليلة ( Hesiod, Theogony 521-525 ). المسرحية الكاملة عن العقاب ده: Aeschylus \" Prometheus Bound \". وأخيرا Hercules (هرقل، هنقابله بعدين في الكورس) قتل النسر وحرره ( Theogony 526-528 )."},{"i":"myth-m5","s":20,"h":"","t":"mc","x":"إيه عقاب Prometheus ؟ ؟ اتقيد على جبل في ال Caucasus ونسر ياكل كبده كل يوم / اتحبس في Tartarus بس / اتحول لحجر / اتغرق في البحر . اتقيد على جبل في ال Caucasus ونسر ياكل كبده كل يوم"},{"i":"myth-m5","s":21,"h":"","t":"learn","x":"أ) Byron ، قصيدة \" Prometheus \" (1816): \" Thy Godlike crime was to be kind, To render with thy precepts less The sum of human wretchedness, And strengthen Man with his own mind ;\" (\"جريمتك الإلهية إنك كنت كريما: إنك تقلل بمبادئك مجموع بؤس البشر، وتقوي الإنسان بعقله هو.\") Byron بيقرأ Prometheus رمز للعقل الإنساني المتمرد اللي بيتحمل."},{"i":"myth-m5","s":22,"h":"","t":"mc","x":"في قصيدة Prometheus ل Byron (1816)، Prometheus هو رمز ل... ؟ الخوف من المجهول / الفوضى / العقل الإنساني اللي بيقاوم الظلم / الشر المطلق . العقل الإنساني اللي بيقاوم الظلم"},{"i":"myth-m5","s":23,"h":"","t":"mc","x":"كمل الجملة اللي لسه شايفها: Thy Godlike _____ was to be kind, ؟ crime / delights / darker / fear . Thy Godlike crime was to be kind,"},{"i":"myth-m5","s":24,"h":"","t":"learn","x":"ب) Percy Shelley ، \" Prometheus Unbound \" (1820): ملحمة درامية بيكمل فيها الأسطورة من عند Aeschylus بس بنهاية ثورية: Prometheus بيتحرر بالتسامح مش بالانتقام، والطغيان بينهار. من ختام الفصل الرابع: \" To suffer woes which Hope thinks infinite ; To forgive wrongs darker than death or night ; To defy Power, which seems omnipotent ;"},{"i":"myth-m5","s":25,"h":"","t":"learn","x":"To love, and bear ; to hope till Hope creates From its own wreck the thing it contemplates ;\" (تتحمل آلام بتبان بلا نهاية، تسامح أخطاء أغمق من الموت والليل، تتحدى قوة بتبان مابتتقهرش، وتحب وتصبر...) دي واحدة من أشهر الخواتيم في الشعر الإنجليزي."},{"i":"myth-m5","s":26,"h":"","t":"learn","x":"ج) Mary Shelley ، رواية \" Frankenstein ; or, The Modern Prometheus \" (1818): العنوان الفرعي نفسه allusion : العالم اللي بيصنع حياة = Prometheus العصري، والعقاب وراه. وملحوظة تاريخية حلوة: صيف 1816 في جنيف هو نفسه اللي اتكتبت فيه قصيدة Byron اللي فوق وبدايات Frankenstein — أسطورة واحدة، تلات أعمال خالدة من نفس الموسم."},{"i":"myth-m5","s":27,"h":"","t":"mc","x":"العنوان الفرعي لرواية Frankenstein (1818) ل Mary Shelley هو... ؟ The Modern Pandora / The Modern Prometheus / The New Zeus / The Modern Daedalus . The Modern Prometheus"},{"i":"myth-m5","s":28,"h":"","t":"learn","x":"📌 10) كلمات من درس النهارده: Promethean (مجهود/شجاعة بروميثيوسية: \" Promethean effort \") • Pandora's box (بتتقال في الأخبار لحد النهارده: \"فتح علبة باندورا\") • pithos (الجرة الأصلية — كلمة الامتحان). ✏️ كويز M5 (بعد ٣٠ دقيقة): ١) احك خدعة الأضحية عند Mecone ، واشرح إيه اللي بتبرره في العادات الإغريقية."},{"i":"myth-m5","s":29,"h":"","t":"learn","x":"٢) بأي حاجة سرق Prometheus النار؟ واكتب السطر من Hesiod. ٣) اشرح معنى اسم Pandora من نص Hesiod ، وعدد هدايا تلات آلهة ليها. ٤) صحح: \" Pandora's box \" — إيه الأصل، ومين سبب الخطأ وإمتى؟ ٥) قارن بين قراءة Byron وقراءة Shelley ل Prometheus في فقرة قصيرة: مين شافه عقل صابر ومين شافه ثورة؟"},{"i":"myth-m5","s":31,"h":"تذكر واكتب","t":"recall","x":"بأي حاجة سرق بروميثيوس النار من الآلهة؟ . خباها في ساق نبات الشمر، فالنار انتقلت من غير ما تنطفي. والتفصيلة دي هي اللي خلت السرقة تنجح."},{"i":"myth-m5","s":32,"h":"تذكر واكتب","t":"recall","x":"إيه معنى اسم Pandora ، ومين اللي سماها كده؟ . معناه \"اللي معطية كل حاجة\"، لأن كل الآلهة أدوها هدية. وهيرميس سماها بالاسم ده بأمر من زيوس."},{"i":"myth-m5","s":33,"h":"تذكر واكتب","t":"write","x":"قارن في ٣-٤ جمل بين قراءة Byron وقراءة Shelley لشخصية بروميثيوس. . Byron في قصيدته بيقرأ بروميثيوس كعقل صابر: \" Thy Godlike crime was to be kind \"، فالجريمة عنده كرم، والعقاب بيدي الإنسان قوة على نفسه، مش بيسلمه. Shelley في Prometheus Unbound بيحوله لثورة كونية بتنتهي بتحرر الطاغية نفسه، وبيقول في الختام \" To suffer woes which Hope thinks infinite \". يبدو أن Byron بيقف عند لحظة التحمل، و Shelley بيكمل لحد لحظة التغيير، والاتنين بيقروا نفس الأسطورة بروح رومانتيكية، لكن واحدة أهدى وأقرب للتراجيديا."},{"i":"myth-m5","s":34,"h":"تذكر واكتب","t":"write","x":"قارن في ٣-٤ جمل بين استخدام Byron لبروميثيوس في قصيدته واستخدامه في العنوان الفرعي لرواية Frankenstein . . عند Byron الإله المتمرد رمز للكرامة، والشاعر بيخاطبه باحترام، والقصة كلها بتدور على الإنسان اللي بيدفع تمن معرفته. وفي عنوان الرواية الفرعي، \" The Modern Prometheus \"، بقى بروميثيوس صانعا للحياة، مش حاملا للنار، والعقاب عنده مش صخرة، هو مخلوق بيتحول لمسؤولية. يمكن القول إن نفس الاسم بيتحرك من السياسة للعلم في سنتين بس، واللي بيفضل ثابت هو السؤال: إيه تمن إنك تدي البشر حاجة من عند الآلهة؟"},{"i":"myth-m6","s":0,"h":"","t":"learn","x":"📌 1) Hades : الإله والمكان بنفس الاسم من درس Chaos : لما اتقسمت الدنيا، Hades أخد العالم السفلي. فكلمة \" Hades \" معناها الشخص والمكان معا. مثال من حياتنا: عشان تفهم الخريطة دي، تخيل معبر حدودي قديم: فيه نهر لازم تعديه، ومعدية عليها وكيل بيفتش، وكلب حراسة، وقضاة بيحكموا عليك، و3 وجهات نهائية. كل تفصيلة في الأسطورة ليها دور في \"الإجراءات\"."},{"i":"myth-m6","s":1,"h":"","t":"mc","x":"كلمة Hades معناها... ؟ الإله بس / النهر بس / الإله والمكان (العالم السفلي) بنفس الاسم / المكان بس . الإله والمكان (العالم السفلي) بنفس الاسم"},{"i":"myth-m6","s":2,"h":"","t":"learn","x":"📌 2) الأنهار الخمسة (احفظ اسم كل واحد ومعناه) Styx (ستيكس): نهر الكراهية. أهميته الكبرى: الآلهة نفسها بتحلف بيه، والقسم بيه مابيتكسرش. (في Theogony : Styx — بنت Oceanus من ال Titans — وقفت مع Zeus في حرب ال Titanomachy من درس Chaos ، فكافأها بشرف إن يكون اسمها قسم الآلهة. اللي يحنث من الآلهة بقسم Styx يقع غشي عليه سنة كاملة.) Acheron : نهر الحزن."},{"i":"myth-m6","s":3,"h":"","t":"mc","x":"الآلهة نفسها بتحلف بنهر... ؟ Acheron / Styx / Cocytus / Lethe . Styx"},{"i":"myth-m6","s":4,"h":"","t":"learn","x":"Cocytus : نهر العويل والندب. Phlegethon : نهر النار الملتهبة. Lethe : نهر النسيان. اللي يشرب منه بينسى حياته كلها. قاعدة الحفظ: ٤ أنهار عواطف (كره، حزن، عويل، نار) وواحد ذاكرة (نسيان). 📌 3) Charon والعملة Charon راجل عجوز قبيح، المعدي ( ferryman ): بينقل الأرواح بمركبه عبر النهر."},{"i":"myth-m6","s":5,"h":"","t":"mc","x":"نهر Lethe هو نهر... ؟ النار / النسيان / العويل / الحزن . النسيان"},{"i":"myth-m6","s":6,"h":"","t":"learn","x":"مش ببلاش: الأجرة obol (عملة فضية صغيرة). وعشان كده الإغريق كانوا بيحطوا عملة في بق الميت أو على عينه قبل الدفن — عادة جنائزية حقيقية موثقة أثريا، والأسطورة بتشرحها. اللي ميتدفنش؟ روحه تفضل تائهة على البر ماتعديش. (في Aeneid الكتاب 6، بحار اسمه Palinurus مات من غير دفن، ف Charon رفض يشيله، وقعد يستنى على البر.)"},{"i":"myth-m6","s":7,"h":"","t":"mc","x":"أجرة Charon كانت... ؟ obol (عملة فضية صغيرة) / ذهب كتير / خاتم / عبد . obol (عملة فضية صغيرة)"},{"i":"myth-m6","s":8,"h":"","t":"learn","x":"الفكرة العميقة: الدفن عند الإغريق مش رفاهية، دي تأشيرة عبور. ومنها دراما Antigone كلها بعدين. 📌 4) Cerberus : كلب البوابة كلب ب 3 رؤوس (وفي Hesiod : خمسين رأس!) وذيله ثعبان، واقف على مدخل Hades. وظيفته: يستقبل الداخلين بود... ويمزق اللي يحاول يخرج. البوابة سهلة دخول، مستحيلة خروج. هرقل هينزله في مهمته الأخيرة، وأورفيوس هينومه بالموسيقى."},{"i":"myth-m6","s":9,"h":"","t":"learn","x":"📌 5) القضاة التلاتة Minos و Rhadamanthys و Aeacus — تلات ملوك اتعرفوا بالعدل في حياتهم، فبقوا قضاة بعد الموت. Minos ده ملك كريت، صاحب قصة ال Minotaur اللي هتيجي بعدين — شوف كل حاجة بترتبط. 📌 6) الوجهات التلات (النهاية بتاعتك) Tartarus : الهاوية العميقة — سجن العقاب للأشرار الكبار (زي ال Titans من درس Chaos ، و Sisyphus و Tantalus درسين الجايين)."},{"i":"myth-m6","s":10,"h":"","t":"mc","x":"القضاة التلاتة في العالم السفلي هم... ؟ Zeus و Hera و Hades / Clotho و Lachesis و Atropos / Minos و Rhadamanthys و Aeacus / Apollo و Hermes و Persephone . Minos و Rhadamanthys و Aeacus"},{"i":"myth-m6","s":11,"h":"","t":"learn","x":"Asphodel Meadows (حقول الأصفودل): للناس العادية — لا عقاب ولا نعيم، أرواح رمادية بتعيش نسخة باهتة من الحياة. ودي أهم تفصيلة: عند الإغريق الأقدمين، مصير معظم الناس \"ظل باهت\" مش عذاب ولا جنة — ده اللي هيوجع Achilles في الاقتباس تحت. Elysium / Isles of the Blest : جنة الأبطال — نفس \"جزر المباركين\" اللي اتقالت قبل كده (عصر الأبطال). 📌 7) Lethe والنسيان"},{"i":"myth-m6","s":12,"h":"","t":"mc","x":"عند الإغريق الأقدمين، مصير معظم الناس العاديين كان... ؟ جنة / عذاب في Tartarus / إعادة ميلاد / ظل باهت في Asphodel Meadows . ظل باهت في Asphodel Meadows"},{"i":"myth-m6","s":13,"h":"","t":"learn","x":"شربة من Lethe = فورمات كامل للذاكرة. الفيلسوف Plato في آخر كتاب \"الجمهورية\" (أسطورة Er ) خلى الأرواح بتشرب من Lethe قبل ما ترجع تتولد من جديد — عشان كده مابتفتكرش حياتها القديمة. منها الكلمة الإنجليزية: lethargy/lethargic (الخمول والنسيان من نفس العيلة)."},{"i":"myth-m6","s":14,"h":"","t":"learn","x":"📌 8) الأسطورة في الشعر الإنجليزي: أ) Milton ، Paradise Lost الكتاب 2 (577-581): ميلتون وضع أنهار اليونان جوه الجحيم المسيحي، وسماهم واحد واحد: \" Abhorr è d Styx, the flood of deadly hate ; Sad Acheron of sorrow, black and deep ; Cocytus, named of lamentation loud Heard on the rueful stream ; fierce Phlegethon, Whose waves of torrent fire inflame with rage. \""},{"i":"myth-m6","s":15,"h":"","t":"mc","x":"كمل الجملة اللي لسه شايفها: the _____ of deadly hate ؟ flood / torrent / enter / drought . the flood of deadly hate"},{"i":"myth-m6","s":16,"h":"","t":"learn","x":"(ستيكس الملعونة نهر الكراهية القاتلة، أخيرون الحزين أسود عميق، كوسيتوس اللي اسمه من العويل، وفليجيثون الناري...) رابع استخدام نشوفه لميلتون بيعمد الكلاسيك (بعد M1 و M3 و M4 ). ب) Keats ، أول ستانزا من \" Ode to a Nightingale \" (1819): \" Or emptied some dull opiate to the drains One minute past, and Lethe-wards had sunk \""},{"i":"myth-m6","s":17,"h":"","t":"learn","x":"(\"كأني شربت مخدر ثقيل لآخر قطرة... وغرقت ناحية Lethe. \") كلمة واحدة \" Lethe-wards \" = جرعة نسيان كاملة. دي قوة ال allusion : اتجاه واحد بيلخص كل أسطورة النسيان. ج) Dante ، Inferno الكانتو 3 — الكتابة على بوابة الجحيم، بترجمة Cary الإنجليزية (1814): \" All hope abandon, ye who enter here. \""},{"i":"myth-m6","s":18,"h":"","t":"mc","x":"في Ode to a Nightingale ل Keats (1819)، كلمة Lethe-wards بتشير ل... ؟ الاتجاه ناحية النسيان / الاتجاه ناحية النار / الاتجاه ناحية المدينة / الاتجاه ناحية الأحلام . الاتجاه ناحية النسيان"},{"i":"myth-m6","s":19,"h":"","t":"learn","x":"(\"اخلعوا كل أمل يا داخلين.\") ومباشرة بعد البوابة، Charon نفسه بيظهر بمركبه — Dante بنى جحيمه على خريطة Virgil ( Aeneid 6 ) اللي مبنية على هوميروس. سلسلة واحدة. د) Homer ، Odyssey الكتاب 11 (ترجمة Murray ، 11.489-491): أوديسيوس نزل يكلم الأرواح، فقابل روح Achilles أعظم بطل، فقاله أوجع سطر في الأدب القديم:"},{"i":"myth-m6","s":20,"h":"","t":"learn","x":"\" I should choose, so I might live on earth, to serve as the hireling of another, of some portionless man whose livelihood was but small, rather than to be lord over all the dead that have perished. \""},{"i":"myth-m6","s":21,"h":"","t":"learn","x":"(\"أفضل أعيش على الأرض أجير عند راجل فقير مالوش شي، عن إني أكون ملك على كل الموتى.\") المجد البطولي كله ميستاهلش شمس الحياة. سطر بيقلب فكرة \"الموت المجيد\" اللي الإلياذة نفسها بناها — ولاحظ: ده موقفه في حقول الأصفودل الباهتة (نقطة 6)."},{"i":"myth-m6","s":22,"h":"","t":"mc","x":"في Odyssey الكتاب 11، Achilles بيقول إنه يفضل... ؟ يبقى أجير عند فقير على الأرض عن إنه ملك على الموتى / يفضل يبقى ملك على أنهار الموتى وبس / يفضل ملك على الموتى / يرجع لطروادة . يبقى أجير عند فقير على الأرض عن إنه ملك على الموتى"},{"i":"myth-m6","s":23,"h":"","t":"learn","x":"📌 9) كلمات من درس النهارده: Stygian (مظلم كالستيكس: \" Stygian darkness \") • Elysian (نعيمي: \" Elysian fields \") • lethargic • \" cross the Styx \" (يعني يموت — تعبير إنجليزي شائع) • Charon's obol."},{"i":"myth-m6","s":25,"h":"تذكر واكتب","t":"recall","x":"ليه الآلهة بتحلف بنهر ستيكس، وإيه عقاب اللي يحنث؟ . لأنها النهر اللي الآلهة بتحلف بيه، والحانث بيتسجى سنة بلا نفس، وبعدها بيتغرب عن مجلس الآلهة تسع سنين."},{"i":"myth-m6","s":26,"h":"تذكر واكتب","t":"recall","x":"إيه اللي قاله أخيل لأوديسيوس لما قابله في العالم التاني؟ . إنه يفضل يكون أجير عند راجل فقير على الأرض، عن إنه يبقى ملك على كل الموتى. وده بيقلب فكرة المجد البطولي."},{"i":"myth-m6","s":27,"h":"تذكر واكتب","t":"write","x":"قارن في ٣-٤ جمل بين طريقة ميلتون في استدعاء أنهار العالم السفلي وطريقة Keats في استدعاء النسيان. . ميلتون في الكتاب التاني بيعمل قائمة كاملة، ويسمي كل نهر ويديه صفة أخلاقية: \" Abhorr è d Styx, the flood of deadly hate \"، فالخريطة كلها بقت جوه الجحيم المسيحي. Keats بيعمل العكس: كلمة واحدة، \" Lethe-wards had sunk \"، وفيها الاتجاه والحالة مع بعض. يبدو أن ميلتون بيبني مكانا، و Keats بيوصف لحظة داخلية، والاتنين بيعتمدوا على معرفة القارئ بالأسطورة، بس واحد بيوسع والتاني بيضغط. والفرق بين التقنيتين بيبان في طول النفس: القائمة بتوقف القارئ عشان يشوف الخريطة، والكلمة الواحدة بتعدي بيه عشان يحس بالغرق."},{"i":"myth-m6","s":28,"h":"تذكر واكتب","t":"write","x":"قارن في ٣-٤ جمل بين بناء ميلتون لجحيمه من المادة الكلاسيكية وبناء Dante لجحيمه في الكانتو التالت. . Dante بيبدأ من بوابة مكتوب عليها \" All hope abandon, ye who enter here \"، فالجحيم عنده قانون وأخلاق، والزائر بيدخل بصفة رسمية. ميلتون بيبدأ من الأنهار والأسماء، فالجحيم عنده جغرافيا ومنظر، والزائر عنده رحلة طويلة. الاتنين واخدين الخريطة من نفس التقليد، لكن Dante بيحولها لعدالة، وميلتون بيحولها لملحمة. يمكن القول إن الوريث بيختار من التركة اللي تناسب مشروعه. ومع إن الاتنين بيستعملوا نفس الأسماء المستعارة، إلا إن الوظيفة مختلفة تماما، وده اللي بيمنعنا من إننا نقول إن التأثر مجرد تقليد."},{"i":"myth-m7","s":0,"h":"","t":"learn","x":"📌 1) مين Sisyphus ؟ ملك كورنث ( Corinth )، وابن Aeolus. ومن حفيده هتعرفه بعدين: Bellerophon فارس ال Pegasus. هوميروس بيقدمه في Iliad الكتاب 6 بلقب واحد: \" Sisyphus lived, who was the craftiest of all mankind \" (\"عاش سيزيف، أخبث وأمكر البشر كلهم.\") مش أقواهم ولا أشجعهم: أمكرهم. بطل الأسطورة دي عقله مش عضلاته."},{"i":"myth-m7","s":1,"h":"","t":"mc","x":"بتقول Homer في Iliad إن Sisyphus كان... ؟ أقوى البشر / أشجع البشر / أحكم البشر / أخبث وأمكر البشر . أخبث وأمكر البشر"},{"i":"myth-m7","s":2,"h":"","t":"learn","x":"📌 2) جرايمه (حسب الروايات اللاحقة — Apollodorus وغيره) ملحوظة أمانة علمية: هوميروس نفسه ماقالش ليه اتعاقب؛ الحكايات التالية من مصادر أحدث، والنسخ بتختلف. ودي عادة كويسة تتعودها: الأسطورة ليها نسخ مش نص واحد مقدس."},{"i":"myth-m7","s":3,"h":"","t":"learn","x":"١) فضح سر Zeus : Zeus خطف بنت إله النهر Asopus (اسمها Aegina )، ف Sisyphus قال لأبوها مكانها مقابل إنه يعمل عين مية لمدينته. باع سر إله بمية. ٢) قيد الموت نفسه: لما جه Thanatos (الموت) ياخده، Sisyphus خدعه وكبله بالسلاسل. النتيجة؟ محدش في الدنيا بقى بيموت! لحد ما Ares (إله الحرب — اللي زهق من حرب بلا موتى) فك الموت من السلاسل."},{"i":"myth-m7","s":4,"h":"","t":"mc","x":"إيه الخطأ الأول ل Sisyphus في الرواية دي؟ ؟ سرق النار / قتل Zeus / فضح سر Zeus لإله النهر Asopus مقابل عين مية / خدع Hades . فضح سر Zeus لإله النهر Asopus مقابل عين مية"},{"i":"myth-m7","s":5,"h":"","t":"learn","x":"٣) خدعة الجنازة: أوصى مراته ماتعملوش مراسم الدفن. لما نزل Hades ، اشتكى: \"مراتي مادفنتنيش، سيبوني أطلع أوبخها وأرجع\". وطلع... وعاش لحد الشيخوخة وماردش. لحد ما اتسحب بالعافية في الآخر. لاحظ الخيط المشترك: كل جريمة فيهم تحدي لنظام الكون نفسه — سر الآلهة، قانون الموت، إجراءات الدفن (افتكر العالم السفلي). الراجل كان بيختبر: هل القواعد دي فعلا مابتتكسرش؟"},{"i":"myth-m7","s":6,"h":"","t":"mc","x":"إزاي خدع Sisyphus الموت في الآخر؟ ؟ هرب للجبل / أوصى مراته ماتدفنوش وطلب يرجع يوبخها / قتل Hades / دفع رشوة ل Charon . أوصى مراته ماتدفنوش وطلب يرجع يوبخها"},{"i":"myth-m7","s":7,"h":"","t":"learn","x":"📌 3) العقوبة: الحجر Odysseus شافه في العالم السفلي (افتكر خريطة العالم السفلي). النص من Odyssey 11.593-600 بترجمة Murray :"},{"i":"myth-m7","s":8,"h":"","t":"learn","x":"\" Aye, and I saw Sisyphus in violent torment, seeking to raise a monstrous stone with both his hands. Verily he would brace himself with hands and feet, and thrust the stone toward the crest of a hill, but as often as he was about to heave it over the top, the weight would turn it back, and then down again to the plain would come rolling the ruthless stone. But he would strain again and thrust it back, and the sweat flowed down from his limbs, and dust rose up from his head. \""},{"i":"myth-m7","s":9,"h":"","t":"mc","x":"عقاب Sisyphus في العالم السفلي ( Odyssey 11)... ؟ يشرب من نهر ويفضل عطشان / يرفع حجر ضخم لقمة التل ويتدحرج تاني / يتحمل ولا ياكل / يلف على عجلة نار . يرفع حجر ضخم لقمة التل ويتدحرج تاني"},{"i":"myth-m7","s":10,"h":"","t":"mc","x":"كمل الجملة اللي لسه شايفها: and I saw Sisyphus in _____ torment, ؟ often / gentle / crest / violent . and I saw Sisyphus in violent torment,"},{"i":"myth-m7","s":11,"h":"","t":"learn","x":"(\"شفت سيزيف في عذاب شديد، بيحاول يرفع حجر ضخم بإيديه الاتنين. يتسند بإيديه ورجليه ويدفع الحجر ناحية قمة التل، بس كل ما يقرب يعدي القمة، الوزن يرجعه، والحجر القاسي يتدحرج للسهل تاني. وهو يشد نفسه ويدفعه من جديد، والعرق بينزل من أطرافه، والتراب طالع من راسه.\")"},{"i":"myth-m7","s":12,"h":"","t":"learn","x":"ركز في التفاصيل: \"كل ما يقرب يعدي القمة\" — العذاب مش في الشغل، العذاب في القرب من النهاية والرجوع للصفر. و\"لكنه يشد نفسه من جديد\" — هو مش مكسور، هو مداوم. النقطة دي هي اللي Camus هياخدها بعد 2800 سنة. 📌 4) المعنى الأول: العقوبة على مقدار الذنب"},{"i":"myth-m7","s":13,"h":"","t":"mc","x":"إيه الحكمة في عقاب Sisyphus ؟ ؟ اللي عاش بالمكر يقضي أبديته في شغل بلا معنى / اللي ساعد غيره يتكافأ / الحجر رمز للثروة / اللي أطاع الآلهة ينجو . اللي عاش بالمكر يقضي أبديته في شغل بلا معنى"},{"i":"myth-m7","s":14,"h":"","t":"learn","x":"في نظام Tartarus (من خريطة العالم السفلي)، كل عقوبة مصممة على صاحبها: اللي بيعيش بالمكر واللف والدوران... يقضي أبديته في لف ودوران ميفضيش. اللي بيكسر القواعد بذكاء، اتعاقب بعمل ميستاهلوش ذكي: شغل بلا معنى. 📌 5) المعنى التاني: Camus وسيزيف السعيد"},{"i":"myth-m7","s":15,"h":"","t":"learn","x":"الفيلسوف الجزائري-الفرنسي Albert Camus كتب مقال فلسفي مشهور اسمه \" The Myth of Sisyphus \" (1942، ترجمة إنجليزية ل Justin O'Brien ). فكرته: حياة الإنسان زي حجر سيزيف بالظبط — شغلنا وتعبنا اليومي بيتكرر، والكون مابيجاوبش على سؤال \"ليه\". ده اللي بيسميه \"العبث\" ( the Absurd )."},{"i":"myth-m7","s":16,"h":"","t":"learn","x":"بس الحل مش الاستسلام: لما سيزيف بينزل من الجبل ورا حجره، هو واعي تماما بمصيره، والوعي ده نفسه هو انتصاره. العقوبة بتتحول لملكيته هو. الجملة الختامية المشهورة في المقال: \" One must imagine Sisyphus happy. \" (\"لازم نتخيل سيزيف سعيد.\") ليه الكلام ده مهم ليك في الكورس؟ لأنه النموذج الكامل ل \"إعادة القراءة\": الأسطورة مش بتموت، كل عصر بيقرأها بسؤاله."},{"i":"myth-m7","s":17,"h":"","t":"mc","x":"إيه جملة Camus الختامية في The Myth of Sisyphus (1942)؟ ؟ One must imagine Sisyphus happy / One must pity Sisyphus / Sisyphus must escape / One must hate Sisyphus . One must imagine Sisyphus happy"},{"i":"myth-m7","s":18,"h":"","t":"learn","x":"هوميروس شاف عذاب ماكر، و Camus شاف بطل حر. ده تمهيد للمستوى 9 (النظريات)."},{"i":"myth-m7","s":19,"h":"","t":"learn","x":"📌 6) الأسطورة في الشعر الإنجليزي: كلمة \" Sisyphean \" بقت صفة إنجليزية عادية: \" a Sisyphean task \" = مهمة مستحيلة بتتكرر بلا نتيجة. هتلاقيها في المقالات والأخبار أكتر من القصائد، لكن وجودها نفسه إثبات إن الأسطورة عايشة في اللغة."},{"i":"myth-m7","s":20,"h":"","t":"mc","x":"كلمة Sisyphean معناها... ؟ مهمة سهلة / مهمة سريعة / مهمة مستحيلة بتتكرر بلا نتيجة / مهمة ممتعة . مهمة مستحيلة بتتكرر بلا نتيجة"},{"i":"myth-m7","s":21,"h":"","t":"learn","x":"وفي الشعر الحديث، سيزيف بيظهر كل ما شاعر يتكلم عن الشغل اليومي المتكرر بلا معنى — افتكر الاسم لما تقابل صورة \"الجهد اللي بيرجع لنقطة الصفر\" في أي نص."},{"i":"myth-m7","s":22,"h":"","t":"learn","x":"📌 7) كلمات من درس النهارده: Sisyphean • \" the Absurd \" (مصطلح Camus ) • crafty (من لقب هوميروس: craftiest )."},{"i":"myth-m7","s":24,"h":"تذكر واكتب","t":"recall","x":"إيه لقب سيزيف عند هوميروس، وليه اللقب ده مهم؟ . لقبه \"أمكر البشر\". والمهم إن نفس المكر هو اللي رفعه لعرش، وهو اللي نزله للعقاب."},{"i":"myth-m7","s":25,"h":"تذكر واكتب","t":"recall","x":"إيه فكرة \"العبث\" عند كامو في مقال سيزيف؟ . إن الإنسان بيدور على معنى والكون ما بيردش عليه، والفكرة مش دعوة لليأس، هي دعوة للعيش بوعي من غير وهم."},{"i":"myth-m7","s":26,"h":"تذكر واكتب","t":"write","x":"قارن في ٣-٤ جمل بين سيزيف عند هوميروس وسيزيف عند كامو. . هوميروس بيقدم العقوبة كمشهد: حجر بيتدحرج، وجهد بيرجع لنقطة الصفر، والقارئ بيحس بالوجع من الصورة نفسها. كامو بيقف عند اللحظة اللي هوميروس مابيقولهاش، لحظة النزول من الجبل، ويقول \" One must imagine Sisyphus happy \". يبدو أن الأسطورة نفسها اتغيرت وظيفتها: من تحذير من غضب الآلهة إلى صورة لوضع الإنسان الحديث، واللي فضل ثابت هو التكرار، مش المعنى. والسؤال اللي بيفضل مفتوح بعد القراءتين: هل الجملة الأخيرة عزاء حقيقي، ولا طريقة أذكى لتحمل حاجة مش بتتحمل؟"},{"i":"myth-m7","s":27,"h":"تذكر واكتب","t":"write","x":"قارن في ٣-٤ جمل بين نبرة وصف العقوبة في الأوديسة ونبرة كامو في مقال سيزيف. . في الأوديسة النبرة تقريرية وحزينة، والشاعر بيعدد التفاصيل عشان القارئ يشوف المشهد بعينه، والموقف موقف رعب. عند كامو النبرة تحليلية وواثقة، والنص بيحول الرعب لسؤال فلسفي عن قيمة العمل المتكرر. يمكن القول إن النبرة بتتغير لأن الجمهور اتغير: نص بيحكي لمستمع قديم عن عقاب، ومقال بيخاطب قارئ حديث عن حياته اليومية. وده مثال حلو على إن الأسطورة بتعيش في النبرة اللي بتتحكي بيها، مش في الحكاية بس."},{"i":"myth-m8","s":0,"h":"","t":"learn","x":"سلسلة \"الأساطير للشعر الإنجليزي\" | المستوى: 1 ( A1-A2 ) 🌱 ──────────────────── 🎣 أول حاجة: تخيل الإحساس ده إنك عطشان جدا وقاعد قدام تلاجة مفتوحة مليانة مية ساقعة، بس كل ما تمد إيدك على زجاجة، التلاجة تتباعد خطوة. وتفضل كده ساعة، وساعتين، مليون سنة. 😱 ده بالظبط عقاب طنطالوس، بطل النهارده الأول."},{"i":"myth-m8","s":1,"h":"","t":"learn","x":"وفي نفس المكان، في واحد مربوط في عجلة نار بتلف من غير ما تقف أبدا، وواحدة وستين أخت بيصبوا مية في برميل مخروم. أهلا بيك في أعمق حتة في العالم السفلي عند الإغريق: التارتاروس. 📍 إحنا فين في الحكاية؟ في الفصل السادس ( M6 ) خدنا جولة في جغرافيا العالم السفلي، وعرفنا إن التارتاروس هو أعمق نقطة فيه، مكان عقاب الكبار."},{"i":"myth-m8","s":2,"h":"","t":"learn","x":"في الفصل السابع ( M7 ) شفنا سيزيف بيطلع الحجر الجبل وينزل بيه، للأبد. النهارده هنقابل التلاتة التانيين من أشهر سكان التارتاروس: طنطالوس، إكسيون، وبنات داناوس. لفتة حلوة: الشاعر الروماني أوفيد جمعهم كلهم في مشهد واحد في الكتاب الرابع من \"التحولات\" ( Metamorphoses 4 )، كأنهم زنازين جنب بعض في نفس العنبر. ──────────────────── 🍇 أولا: طنطالوس ( Tantalus )"},{"i":"myth-m8","s":3,"h":"","t":"learn","x":"1 ️ ⃣ مين الراجل ده؟ ابن زيوس نفسه، ملك غني جدا في آسيا الصغرى (منطقة فريجيا وليديا، تركيا دلوقتي). أبو بيلوبس ونيوبي. خد بالك من اسم بيلوبس ده، هنرجعله تحت. حصل على شرف شبه مستحيل: كان ضيف ثابت على مائدة الآلهة في الأوليمبوس، بياكل ويشرب معاهم ويسمع كلامهم. 2 ️ ⃣ عمل إيه غلط؟ (تلات نسخ، وكلها أوحش من بعض)"},{"i":"myth-m8","s":4,"h":"","t":"mc","x":"Tantalus كان... ؟ ابن Zeus وضيف على مائدة الآلهة / ابن Hades / إله البحر / ابن Cronos . ابن Zeus وضيف على مائدة الآلهة"},{"i":"myth-m8","s":5,"h":"","t":"learn","x":"نسخة 1: فش أسرار الآلهة للبشر. اللي بيسمعه على المائدة بقى على كل لسان في السوق. (المصدر: أبولودوروس، Epitome 2.1 ) نسخة 2: سرق النكتار والأمبروزيا، يعني أكل وشرب الخلود بتاع الآلهة، ووزعه على أصحابه من البشر. (المصدر: بندار، الأوليمبية الأولى Olympian 1 )"},{"i":"myth-m8","s":6,"h":"","t":"learn","x":"نسخة 3، وهي الأشهر والأفظع: قرر يختبر الآلهة، هل هما فعلا عارفين كل حاجة؟ فعملهم عزومة وحط لهم في الأكل ابنه بيلوبس، مسلوق ومقطع. 😨 (المصدر: أبولودوروس، Epitome 2.3 ) الآلهة فهموا الخدعة فورا وماكلوش، ما عدا ديميتر، كانت شاغلها حزنها على بنتها المفقودة، فأكلت من كتف الولد من غير ما تنتبه."},{"i":"myth-m8","s":7,"h":"","t":"mc","x":"إيه أشهر نسخة عن جريمة Tantalus ؟ ؟ سرق النار / قدم ابنه Pelops للآلهة في الأكل ليختبرهم / هرب من Tartarus / قتل ضيف Zeus . قدم ابنه Pelops للآلهة في الأكل ليختبرهم"},{"i":"myth-m8","s":8,"h":"","t":"learn","x":"الآلهة رجعوا بيلوبس للحياة أحلى من الأول، وعوضوا الكتف المأكول بكتف من العاج. (المصدر: هيجينوس Fabulae 83 ، وأوفيد Metamorphoses 6 ) ⚠️ ملحوظة \"الأسطورة نسخ\": الشاعر بندار نفسه رفض قصة العشا دي تماما وقال إنها إشاعة اخترعها جيران حسودين، والغلط الحقيقي عنده هو سرقة النكتار. شفت؟ حتى القدماء كانوا بيتخانقوا على النسخ. 3 ️ ⃣ العقاب: الصورة الأيقونية 🖼️"},{"i":"myth-m8","s":9,"h":"","t":"learn","x":"هوميروس شافه في الأوديسية، الكتاب الحداشر، واقف في بحيرة والمية واصلة لذقنه: \" And I saw Tantalus in bitter torment, standing in a pool, and the water came nigh unto his chin. \" ( Odyssey 11.582-584 ، ترجمة Murray ) كل ما ينزل يشرب، المية تنشف وتسيب الطين الأسود. وفوق راسه شجر محمل بالتفاح والرمان والتين والزيتون، كل ما يمد إيده، الريح تطير الفروع للسحاب."},{"i":"myth-m8","s":10,"h":"","t":"mc","x":"كمل الجملة اللي لسه شايفها: And I saw Tantalus in _____ torment, ؟ pleasant / evermore / bitter / weren . And I saw Tantalus in bitter torment,"},{"i":"myth-m8","s":11,"h":"","t":"learn","x":"أبولودوروس بيزود كمان صخرة ضخمة معلقة فوق راسه ممكن تقع في أي لحظة. ( Epitome 2.1 ) 🔄 من الحياة: زي حد صايم قاعد يتفرج على إعلانات الأكل، أو زي واحد الموبايل بتاعه 1% والشاحن قدامه بس مش بيوصل. العذاب مش في الغياب، العذاب في القرب. 4 ️ ⃣ كلمة دخلت اللغة للأبد 🔤 من اسمه جت كلمة إنجليزية مهمة جدا: tantalize"},{"i":"myth-m8","s":12,"h":"","t":"mc","x":"عقاب Tantalus هو... ؟ يرفع حجر / يلف على عجلة / يتحمل سيف فوق راسه / يشوف الأكل والشرب من غير ما يوصلهم . يشوف الأكل والشرب من غير ما يوصلهم"},{"i":"myth-m8","s":13,"h":"","t":"learn","x":"معناها: تغري حد بحاجة هو نفسه فيها، وتقربها منه، وبعدين تبعدها عنه. تعذيب بالإغراء. الكلمة ظهرت في الإنجليزي في أواخر القرن الستاشر (حوالي 1590 s ). مثال: \" The smell of fresh bread tantalized the hungry crowd. \" ريحة العيش الطازة عذبت الناس الجيعانة. 5 ️ ⃣ الإرث المظلم 👨‍👦 افتكر اسم بيلوبس؟ ابن طنطالوس اللي اتسلخ واتسلق ورجع للحياة؟"},{"i":"myth-m8","s":14,"h":"","t":"mc","x":"كلمة tantalize أصلها من... ؟ Tantalus / Sisyphus / Ixion / Prometheus . Tantalus"},{"i":"myth-m8","s":15,"h":"","t":"learn","x":"من نسل بيلوبس هيجي أتريوس، ومنه أجاممنون ومينيلاوس، يعني بيت أتريوس كله، أشهر عيلة ملعونة في المسرح اليوناني. هنقابلهم في فصول لاحقة. الخيانة بدأت من الأكل، زي ما هتشوف. ──────────────────── 🔥 ثانيا: إكسيون ( Ixion ) 1 ️ ⃣ مين هو؟ ملك اللابيث، شعب في ثيساليا (شمال اليونان). متجوز ديا وأبو بيريثوس، اللي هيبقى صاحب ثيسيوس البطل بعدين."},{"i":"myth-m8","s":16,"h":"","t":"learn","x":"ملحوظة نسخ: هوميروس في الإلياذة (14.317-318) بيخلي زيوس يقول إن بيريثوس ابنه هو من مرات إكسيون. برضه، الأسطورة نسخ. 2 ️ ⃣ الذنب الأول: أول دم قريب في التاريخ 🩸 إكسيون وعد حماة، ديونيوس، بهدايا عرس غالية مقابل بنته ديا، وبعد الجواز مشى كلامه. لما الحما طالب بحقه، إكسيون عزمه على وليمة، وجهز له حفرة مليانة نار ووقعه فيها. (المصدر: ديودورس 4.69)"},{"i":"myth-m8","s":17,"h":"","t":"learn","x":"ليه دي جريمة مختلفة؟ لأن القتيل قريبه، حماة يعني عيلة. بندار بيقول إن إكسيون هو أول واحد في البشر يسفك دم قريب بالخديعة. ( Pythian 2 ) الجريمة كانت بشعة لدرجة إن محدش في البشر كله كان مستعد يطهره منها. 3 ️ ⃣ الغلطة الكبرى: كفران النعمة 🐍"},{"i":"myth-m8","s":18,"h":"","t":"learn","x":"هنا ييجي المشهد اللي يجنن: زيوس نفسه رحمه. طهره من الذنب، ورفعه لفوق، وعزمه على مائدته في الأوليمبوس. تخيل: قاتل قريبه قاعد ياكل مع الآلهة. رد الجميل؟ إكسيون شاف هيرا، مرات زيوس ومضيفته، وحاول يغازلها. زيوس عارف، فعمل اختبار: صنع سحابة على صورة هيرا بالظبط، اسمها نيفيلي ( Nephele ، يعني سحابة)، وحطها في طريقه. إكسيون وقع في الفخ وافتخر، واتفضح."},{"i":"myth-m8","s":19,"h":"","t":"learn","x":"(المصدر: أبولودوروس، Epitome 1.20 وبندار، Pythian 2 ) 🔄 من الحياة: زي واحد صاحبه سنده في أزمة، دخله بيته وقاله \"اعتبر البيت بيتك\"، وبعدين يلاقيه بيحاول ياخد مراته. الإغريق كانوا شايفين إن كفران النعمة، ingratitude ، من أقبح الذنوب على الإطلاق. 4 ️ ⃣ النتيجة الغريبة: أبو الكينتاورز 🐎 من السحابة نيفيلي جاء ابن وحش اسمه كينتاوروس."},{"i":"myth-m8","s":20,"h":"","t":"learn","x":"كينتاوروس اتجاوز مع خيول ماجنيسيا عند جبل بيليون، فطلعت سلالة الكينتاورز: المخلوقات نص إنسان نص حصان. (المصدر: بندار، Pythian 2 ) بندار وصفهم وصف عبقري: من ناحية الأم \"الجزء التحتاني\" حصان، ومن ناحية الأب \"الجزء الفوقاني\" إنسان. يعني كل كينتاور هتقابله في أي قصيدة إنجليزية، من كيرون معلم أخيل لحد نيسوس، اسأل عن جده: سحابة وغدار."},{"i":"myth-m8","s":21,"h":"","t":"learn","x":"5 ️ ⃣ العقاب: العجلة اللي مبتقفش 🎡🔥 زيوس أمر بربط إكسيون، إيديه ورجليه، على عجلة ليها جناحات ونار، بتلف في الظلام بلا توقف، للأبد. والعجلة مش ساكتة. بندار بيقول إن إكسيون بيصرخ من فوقها رسالة للبشر كلهم: \"رد الجميل لصاحبه!\""},{"i":"myth-m8","s":22,"h":"","t":"mc","x":"عقاب Ixion هو... ؟ حمل المية في برميل بلا قاع / شرب نهر ما بيخلصش / دحرجة حجر لقمة جبل / الربط على عجلة نار بتلف بلا توقف . الربط على عجلة نار بتلف بلا توقف"},{"i":"myth-m8","s":23,"h":"","t":"learn","x":"بالإنجليزي في ترجمة Sandys : \" Ixion, as he whirleth round and round on his winged wheel. .. teacheth the lesson that men should requite the benefactor with fresh tokens of warm gratitude. \" شفت العبقرية؟ العقاب نفسه بقى درس أخلاقي متنقل، إكسيون بقى منبه بشري ضد كفران النعمة. ──────────────────── 🏺 ثالثا: بنات داناوس ( The Danaids )"},{"i":"myth-m8","s":24,"h":"","t":"mc","x":"إيه الدرس اللي بتعلمه عجلة Ixion ؟ ؟ ارد الجميل لصاحب المعروف / اكسر القواعد لو عندك سلطة / اهرب من عقاب الآلهة / اطلب كل حاجة تحبها . ارد الجميل لصاحب المعروف"},{"i":"myth-m8","s":25,"h":"","t":"mc","x":"كمل الجملة اللي لسه شايفها: as he _____ round and round on his winged wheel. ؟ whirleth / brethren / sleeps / revenge . as he whirleth round and round on his winged wheel."},{"i":"myth-m8","s":26,"h":"","t":"learn","x":"1 ️ ⃣ الخلفية: عيلتين متخانقين 👨‍👩‍👧‍👦 أخوين توأم تقريبا في كل حاجة إلا الظروف: داناوس عنده 50 بنت، وأخوه أيجيبتوس عنده 50 ولد. أيجيبتوس عايز يجوز ولاده لبنات أخوه، وداناوس خايف منهم، فهرب ببناته الخمسين من مصر لمدينة أرجوس في اليونان. (بالمناسبة، الجد البعيد للعيلة هو بيلوس ملك مصر، عشان كده بيتقال عليهم كمان Belides )."},{"i":"myth-m8","s":27,"h":"","t":"learn","x":"ولاد أيجيبتوس الخمسين لحقوهم لحد أرجوس وطلبوا الجواز رسمي. داناوس وافق، ظاهريا. (المصدر: أبولودوروس، Library 2.1.5 ) 2 ️ ⃣ ليلة العرس الدموية 🔪 في ليلة الدخلة، داناوس وزع على كل بنت خنجر، وأمرهم: لما جوزك ينام، اقتليه. 49 بنت نفذوا الأمر. قتلوا أزواجهن وهم نايمين، ودفنوا الرؤوس في مستنقع ليرنا."},{"i":"myth-m8","s":28,"h":"","t":"learn","x":"بنت واحدة بس رفضت: هيبرمنيسترا ( Hypermnestra )، أكبرهم. جوزها لينكيوس احترمها ليلة الدخلة ومايمسهاش، فهي عفت عنه وساعدته يهرب. عقابها عند أبوها؟ حبسها. وبعدين لما هدى، سامحها وجوزها للينكيوس رسمي، وباقي البنات جوزهم للفائزين في سباق رياضي. (المصدر: أبولودوروس، Library 2.1.5 ) 3 ️ ⃣ العقاب: البرميل اللي ميتملاش 🏺"},{"i":"myth-m8","s":29,"h":"","t":"mc","x":"أي بنت من بنات Danaus رفضت قتل جوزها؟ ؟ Aegina / Pyrrha / Hypermnestra / Hypsipyle . Hypermnestra"},{"i":"myth-m8","s":30,"h":"","t":"learn","x":"في العالم السفلي، ال49 أخت محكوم عليهم بشغلانة بلا نهاية: يحملوا المية في أواني ومناخل مخرومة، ويصبوا في برميل بلا قاع، فالمية بتضيع قبل ما توصل، ويرجعوا من الأول. للأبد. أوفيد شافهم في المشهد الجماعي بتاع الكتاب الرابع من التحولات، جنب طنطالوس وسيزيف وإكسيون بالظبط. تفصيلة مهمة من أبولودوروس: أثينا وهيرميس طهروا البنات من دم الجريمة بأمر زيوس."},{"i":"myth-m8","s":31,"h":"","t":"mc","x":"إيه عقاب بنات Danaus في العالم السفلي؟ ؟ عجلة نار بتلف / حجر بيتدحرج / حمل المية في أواني مخرومة لبرميل بلا قاع / جوع وعطش مع أكل قدامهم . حمل المية في أواني مخرومة لبرميل بلا قاع"},{"i":"myth-m8","s":32,"h":"","t":"learn","x":"يعني الإغريق نفسهم كانوا محتارين في الحكم عليهم: نفذوا أمر الأب، بس قتلوا أزواجهم. الالتباس الأخلاقي ده هو اللي خلى القصة تعيش. 4 ️ ⃣ لفتة من أجمل اللفتات 🎵 في الكتاب العاشر من التحولات، لما أورفيوس نزل العالم السفلي يعزف ويغني عشان يرجع مراته، العذاب كله وقف لحظة: حجر سيزيف وقف، عجلة إكسيون وقفت، وبنات داناوس حطوا الجرار. ( Ovid, Metamorphoses 10 )"},{"i":"myth-m8","s":33,"h":"","t":"learn","x":"يعني الموسيقى قدرت تعمل اللي الأبدية ما عملتهوش. هنقابل أورفيوس في فصل لاحق."},{"i":"myth-m8","s":34,"h":"","t":"learn","x":"5 ️ ⃣ 🔄 من الحياة: شغل بلا نتيجة: زي واحد بيذاكر طول السنة من ملخص مسرب غلط، مجهود كله بيروح في الفاضي. أو زي محل بيصرف فلوس على الديكور كل يوم والزباين مابتدخلش. البرميل المخروم موجود في كل حتة. ──────────────────── 🧠 رابعا: ليه التلاتة في فصل واحد؟ الفكرة العبقرية بص على العقوبات التلاتة، هتلاقي قانون ذهبي: العقاب هو الذنب، بس مقلوب."},{"i":"myth-m8","s":35,"h":"","t":"learn","x":"طنطالوس خان مائدة الآلهة وفسد الأكل، فاتعاقب بإنه يشوف الأكل والشرب من غير ما يوصلهم. إكسيون خان ولي نعمته، فاتربط في عجلة بتنادي ليل نهار: \"رد الجميل لصاحبه\". الدانايدات حولوا ليلة بناء البيت لمجزرة، فاتحبسوا في شغل بيت مابيكتملش: ملء برميل مستحيل يتملى."},{"i":"myth-m8","s":36,"h":"","t":"learn","x":"الدرس الإغريقي: الذنوب اللي بتكسر القوانين المقدسة، الضيافة والقرابة والجواز، ذنوب لانهائية الطبيعة، فعقابها لانهائي. مش قسوة، رمزية. ──────────────────── 📜 الأسطورة في الشعر الإنجليزي 1 ️ ⃣ روبرت براوننج، قصيدة \" Ixion \" (1883، من مجموعة Jocoseria ):"},{"i":"myth-m8","s":37,"h":"","t":"learn","x":"قصيدة كاملة براوننج بيخلي فيها إكسيون يتكلم بنفسه من على العجلة، ويدافع عن نفسه وعن البشرية كلها قدام زيوس. الافتتاحية: \" High in the dome, suspended, of Hell, sad triumph, behold us ! Here the revenge of a God, there the amends of a Man. \" وفي السطور 27-30 براوننج بيجمع كل معاقبي الفصل ده واللي فاته في جملتين:"},{"i":"myth-m8","s":38,"h":"","t":"mc","x":"كمل الجملة اللي لسه شايفها: Here the _____ of a God, ؟ brethren / revenge / laughter / their . Here the revenge of a God,"},{"i":"myth-m8","s":39,"h":"","t":"learn","x":"\" Sisuphos, teaches thy stone — Tantalos, teaches thy thirst. .. Sisuphos scouts low fraud, and to Tantalos treason is folly. \" يعني: سيزيف حجره بيعلمه، وطنطالوس عطشه بيعلمه. العذاب نفسه مدرسة. 2 ️ ⃣ شكسبير، الملك لير (الفصل الرابع، المشهد السابع): لير لما بيفوق من جنونه ويشوف بنته كورديليا، بيقول: \" Thou art a soul in bliss, but I am bound"},{"i":"myth-m8","s":40,"h":"","t":"learn","x":"Upon a wheel of fire, that mine own tears Do scald like molten lead. \" (انتي روح في النعيم، بس أنا مربوط على عجلة نار، دموعي بتحرقني زي الرصاص المداب.) ⚠️ ملحوظة: شكسبير مش بيسمي إكسيون بالاسم، بس صورة \"الرجل المربوط على عجلة النار\" إشارة معروفة للأسطورة. دي allusion غير مباشرة، وده أول مثال ليك على الإشارة من غير تسمية."},{"i":"myth-m8","s":41,"h":"","t":"learn","x":"3 ️ ⃣ تشوسر، \"أسطورة هيبرمنيسترا\" (من كتاب The Legend of Good Women ، حوالي 1380 s ): تشوسر حكى قصة البنت الوحيدة اللي عفت عن جوزها. بيبدأ كده: \" In Grece whylom weren brethren two, Of whiche that oon was called Danao. ..\" (في اليونان زمان كان في أخوين...)"},{"i":"myth-m8","s":42,"h":"","t":"learn","x":"⚠️ ملحوظة مذهلة: تشوسر قلب الأدوار! عنده داناوس هو أبو الولاد ولينكيوس ابنه، وأيجيبتوس هو أبو هيبرمنيسترا، عكس أبولودوروس تماما. درس عملي: الشعراء بياخدوا النسخة اللي تخدم قصتهم. الأسطورة مش نص مقدس، الأسطورة مادة خام. 4 ️ ⃣ ترجمة جولدنج لأوفيد (1567)، الترجمة اللي شكسبير نفسه قراها: \" And Danaus daughters forbicause they did their cousins kill,"},{"i":"myth-m8","s":43,"h":"","t":"learn","x":"Drew water into running tubbes which evermore did spill. \" (وبنات داناوس، لأنهم قتلوا قرايبهم، بيحملوا المية في أواني بتسرب على طول.) 5 ️ ⃣ الأصل الكلاسيكي: هوميروس، الأوديسية 11.582-592، أول ظهور لطنطالوس في الأدب، أوديسيوس شافه بعينه في العالم السفلي (ترجمة Murray فوق في الفصل). ──────────────────── 🔤 كلمات إنجليزي من الفصل"},{"i":"myth-m8","s":44,"h":"","t":"learn","x":"tantalize : يغريك بحاجة ويحرمك منها (من طنطالوس نفسه). torment : عذاب. benefactor : صاحب المعروف، ولي النعمة. ingratitude : كفران النعمة. kindred blood : دم القرابة، دم العيلة. wheel of fire : عجلة النار. sieve : منخل، غربال. leaky jar : جرة مخرومة بتسرب. eternal punishment : عقاب أبدي. to purify : يطهر من الذنب. wedding night : ليلة الدخلة."},{"i":"myth-m8","s":45,"h":"","t":"learn","x":"to repay kindness with betrayal : يرد المعروف بالخيانة. ──────────────────── خوسيه دي ريبيرا، لوحة \"طنطالوس\" (حوالي 1632، متحف البرادو، مدريد): ابحث في كومنز عن \" Ribera Tantalus Prado \". خوسيه دي ريبيرا، لوحة \"إكسيون\" (حوالي 1632، البرادو): ابحث عن \" Ribera Ixion Prado \". جون ويليام ووترهاوس، لوحة \" The Dana ï des \" (1903): ابحث عن \" Waterhouse Danaides \"."},{"i":"myth-m8","s":46,"h":"","t":"mc","x":"كمل الجملة اللي لسه شايفها: to _____ kindness with betrayal ؟ tubbes / revenge / repay / ignore . to repay kindness with betrayal"},{"i":"myth-m8","s":47,"h":"","t":"learn","x":"أوغست رودان، تمثال \" Dana ï d \" (حوالي 1889): ابحث عن \" Rodin Danaid \". نقش لبرنار بيكار عن عقاب طنطالوس أو إكسيون (1731، من سلسلة Temple of the Muses ): ابحث عن \" Picart Tantalus engraving \". ──────────────────── بندار، الأوليمبية والبيثية، Pythian 2 (قصة إكسيون، ترجمة Sandys ):"},{"i":"myth-m8","s":49,"h":"تذكر واكتب","t":"recall","x":"إيه اللي عمله طنطالوس عشان يتعاقب بالعطش والجوع الأبدي؟ . قدم لحم ابنه للآلهة في وليمة عشان يختبر معرفتهم، فرفضوا الوليمة وعاقبوه."},{"i":"myth-m8","s":50,"h":"تذكر واكتب","t":"recall","x":"إيه الذنبين اللي ارتكبهم إكسيون حسب بندار؟ . إنه أول واحد سفك دم قريب بالغدر، وإنه بعد ما زيوس طهره وعزمه خان المعروف وحاول يغازل هيرا."},{"i":"myth-m8","s":51,"h":"تذكر واكتب","t":"write","x":"قارن في ٣-٤ جمل بين إشارة براوننج المباشرة لإكسيون وإشارة شكسبير غير المباشرة في الملك لير. . براوننج بيسمي إكسيون وبيخليه هو المتكلم: \" High in the dome, suspended, of Hell, sad triumph, behold us !\"، فالإشارة مباشرة والقصيدة كلها حجة يدافع بيها عن نفسه. شكسبير مابيسميش الاسم خالص، وبيسيب الصورة تتكلم: \" I am bound / Upon a wheel of fire \"، والقارئ هو اللي يكمل الأسطورة. يبدو أن الإشارة غير المباشرة أقوى في المسرح، لأنها بتخلي المشهد شخصيا، بينما الإشارة المباشرة بتخلي الأسطورة موضوعا للتفكير."},{"i":"myth-m8","s":52,"h":"تذكر واكتب","t":"write","x":"قارن في ٣-٤ جمل بين رواية تشوسر لحكاية بنات داناوس ورواية جولدنج لها في ترجمته لأوفيد. . تشوسر قلب الأدوار: عند داناوس أبو الولاد ولينكيوس ابنه، وأيجيبتوس أبو هيبرمنيسترا، عكس الترتيب المعروف في المصادر القديمة. وجولدنج بيفضل قريبا من أوفيد، وبيوصف العقوبة نفسها: \" Drew water into running tubbes which evermore did spill \". يمكن القول إن تشوسر بياخد النسخة اللي تخدم قصته عن المرأة الوفية، وجولدنج بينقل النص زي ما هو. والفرق ده نفسه دليل إن الأسطورة مادة خام، مش نصا مقدسا."},{"i":"myth-m9","s":0,"h":"","t":"learn","x":"🎣 أول حاجة: إيماءة واحدة تهز جبل تخيل راجل عنده سلطة لدرجة إنه ميحتاجش يتكلم كتير ولا يهدد. بس يومل براسه، إيماءة صغيرة كده، فيهز الجبل اللي عايشين عليه الآلهة كلها."},{"i":"myth-m9","s":1,"h":"","t":"learn","x":"مش خيال ده، ده مشهد حقيقي في الإلياذة. زيوس بيقول لتيتيس لما طلبت منه طلب: كلمتي مابترجعش، ولما أومأ براسي يبقى العهد اتختم. وبعدين يومل، ف\"الجبل الكبير أوليمبوس اهتز\". ( Iliad 1.528-530 ) النهارده هنعرف مين زيوس: إزاي نجا من بطن أبوه، إزاي كسب عرش السما، وليه الشعراء الإنجليز من 700 سنة لحد دلوقتي مابيعرفوش يكتبوا من غيره."},{"i":"myth-m9","s":2,"h":"","t":"learn","x":"👶 أولا: الطفل اللي هرب من بطن أبوه 1 ️ ⃣ البيت المرعب أبو زيوس هو كرونوس ( Cronus )، ملك التييتنز (العمالقة الأوائل). وكرونوس سمع نبوءة من أبوه أورانوس والأرض جايا: ابن من ولادك هيقلعك من العرش، زي ما انت قلعت أبوك. فكرونوس لقى حل بسيط ومرعب: كل ما مراته ريا ( Rhea ) تخلف، يبلع الطفل. بلع هيستيا، وديميتر، وهيرا، وهاديس، وبوسيدون. خمس أطفال في بطن أبوهم."},{"i":"myth-m9","s":3,"h":"","t":"learn","x":"المصدر: هسيود، الثيوجونيا 453 وما بعدها (ترجمة Evelyn-White ). 2 ️ ⃣ خطة الأم 🗿 لما حان ميلاد زيوس، أصغر الولاد، ريا استغاثت بأبويها: الأرض (جايا) والسما (أورانوس). الخطة: ريا تولد سرا في جزيرة كريت، والأرض تخبي الطفل في كهف في جبل إيجيون، وتديل كرونوس حجر ملفوف في قماط على إنه المولود."},{"i":"myth-m9","s":4,"h":"","t":"learn","x":"كرونوس بلع الحجر من غير ما يبص. \"التعيس! ماكانش عارف إن مكان الحجر اتساب ابنه، غير مغلوب ولا مضايق\". (الثيوجونيا 453-491) 🔄 من الحياة: زي واحد بيبدل موبايل صاحبه المكسر بقالب طوب ملفوف في الكرتونة. الخدعة نجحت لأن الطمع عمى كرونوس عن التفتيش. 3 ️ ⃣ الحجر اللي بقى أثر"},{"i":"myth-m9","s":5,"h":"","t":"mc","x":"إيه الخدعة اللي عملتها ريا عشان تنقذ زيوس؟ ؟ هربت بكل أولادها لكريت / ادت كرونوس حجر ملفوف في قماط على إنه المولود / قتلت كرونوس وهو نايم / خلت زيوس يتنكر في شكل بنت . ادت كرونوس حجر ملفوف في قماط على إنه المولود"},{"i":"myth-m9","s":6,"h":"","t":"learn","x":"لما زيوس كبر وغلب أبوه، كرونوس تقيأ اللي بلعه: أول حاجة طلعت الحجر (آخر حاجة اتبلعت)، وبعدين الأخوة الخمسة. زيوس ثبت الحجر ده في دلفي (بيثو)، تحت جبل بارناسوس، \"علامة وأعجوبة للبشر\". يعني حجر الخدعة بقى مزار. (الثيوجونيا 492-500) وأول شغلانة سياسية لزيوس: حرر عمومه المسجونين، السيكلوبس (عين واحدة) والهيكاتونخيريس (مية إيد)."},{"i":"myth-m9","s":7,"h":"","t":"learn","x":"ردوا له الجميل فورا: ادوله الرعد والصاعقة والبرق، اللي كانت الأرض مخبياهم. \"بيهم بيحكم البشر والآلهة\". (الثيوجونيا 501-506) ⚔️ ثانيا: حرب العشر سنين (التيتانوماخيا) 1 ️ ⃣ الجيشان من ناحية: التييتنز، الجيل القديم، على جبل أوثريس. ومن الناحية التانية: زيوس وإخواته، ولاد كرونوس، على جبل أوليمبوس."},{"i":"myth-m9","s":8,"h":"","t":"learn","x":"\"فضلوا يتحاربوا بعناد عشر سنين كاملة، والصراع الصعب مالوش نهاية\". (الثيوجونيا 617-638، نسخة هسيود) 2 ️ ⃣ ورقة النصر زيوس نزل العالم السفلي وحرر الهيكاتونخيريس: كائنات لكل واحد مية إيد وخمسين راس. عشان يتخيل الحجم: كل واحد فيهم بيرمي صخور بمية إيد في نفس اللحظة. دي كانت المدفعية الثقيلة بتاعة الجيش. (الثيوجونيا 617 وما بعدها) 3 ️ ⃣ النتيجة"},{"i":"myth-m9","s":9,"h":"","t":"learn","x":"التييتنز اتغلبوا واتحبسوا في التارتاروس، أعمق نقطة في الكون (العالم السفلي اللي اتكلمنا عنه قبل كده). ومن يومها، بدأ عصر الأوليمبيين، الجيل الجديد بقيادة زيوس. 🎲 ثالثا: القرعة الكونية بعد النصر، الأخوة التلاتة قسموا المملكة. بوسيدون نفسه بيحكي في الإلياذة، الكتاب 15:"},{"i":"myth-m9","s":10,"h":"","t":"mc","x":"فين اتحبس التييتنز بعد ما اتغلبوا؟ ؟ في التارتاروس، أعمق نقطة في الكون / على جبل أوليمبوس / في جزيرة كريت / في قاع البحر عند بوسيدون . في التارتاروس، أعمق نقطة في الكون"},{"i":"myth-m9","s":11,"h":"","t":"learn","x":"\"إحنا تلاتة إخوة، ولاد كرونوس وريا: زيوس وأنا، وتالتهم هاديس مولى الأموات. والكون كله اتقسم تلاتة، وكل واحد ليه نصيبه. أنا لما القرعة اتهزت كسبت البحر الرمادي مسكنا للأبد، وهاديس كسب الظلام الكئيب، وزيوس كسب السما الواسعة وسط الهواء والسحاب.\" ( Iliad 15.187-193 ، ترجمة Murray )"},{"i":"myth-m9","s":12,"h":"","t":"learn","x":"يعني: البحر لبوسيدون، العالم السفلي لهاديس، السما لزيوس. والأرض وأوليمبوس مشتركة بين الكل. ⚠️ ملحوظة \"الأسطورة نسخ\": الشاعر الإسكندراني كاليماخوس بعدها بقرون سخر من قصة القرعة: \"مين اللي يعمل قرعة على أوليمبوس والهاوية؟ زيوس بقى ملك بأفعال إيديه، مش بالحظ\". شفت؟ حتى فكرة القرعة نفسها ليها معارضين قدام. 👑 رابعا: أبو الآلهة والبشر 1 ️ ⃣ اللقب الرسمي"},{"i":"myth-m9","s":13,"h":"","t":"mc","x":"إزاي اتقسم الكون بين الإخوة التلاتة بحسب بوسيدون في الإلياذة؟ ؟ البحر لزيوس، السما لهاديس / البحر لبوسيدون، العالم السفلي لهاديس، السما لزيوس / السما لبوسيدون، البحر لهاديس / السما لهاديس، العالم السفلي لزيوس . البحر لبوسيدون، العالم السفلي لهاديس، السما لزيوس"},{"i":"myth-m9","s":14,"h":"","t":"learn","x":"في الثيوجونيا، هسيود بيسمي زيوس \"أبو الآلهة والبشر\". اللقب ده، father of gods and men ، هتلاقيه متكرر في كل قصيدة ملحمية يونانية، وبعدها في كل شعر إنجليزي كلاسيكي. 2 ️ ⃣ مشهد التيتيس والإيماءة 🤝 في أول الإلياذة، البحرية تيتيس (أم أخيل) بتطلع أوليمبوس ترجو زيوس ينتقم لابنها. شاعر إنجليزي وصف المشهد، ألكسندر بوب في ترجمته المشهورة للإلياذة (1715-1720):"},{"i":"myth-m9","s":15,"h":"","t":"mc","x":"كمل الجملة اللي لسه شايفها: _____ of gods and men ؟ sleepless / enemy / worlds / father . father of gods and men"},{"i":"myth-m9","s":16,"h":"","t":"learn","x":"\" Suppliant the goddess stood : one hand she placed Beneath his beard, and one his knees embraced. \" (واقفة كمتوسلة: إيد تحت دقنه، وإيد بتعانق ركبته. دي كانت وضعية التوسل الرسمية عند الإغريق.) زيوس وافق، وبعدين يقول الجملة اللي تلخص سلطته: كلمتي لما أومأ عليها براسي مابترجعش ولا بتتحنى. وبعدين:"},{"i":"myth-m9","s":17,"h":"","t":"learn","x":"\" As he spoke the son of Kronos bowed his dark brows, and the ambrosial locks swayed on his immortal head, till vast Olympus reeled. \" (ومل براسه، فتمايلت خصل شعره الخالدة، حتى أوليمبوس العظيم اهتز.) ( Iliad 1.528-530 ، ترجمة Butler ) الدرس: سلطة زيوس مش في الصاعقة، في الكلمة. إيماءة زيوس = عقد مقدس لا يفسخ. 3 ️ ⃣ الميزان الذهبي ⚖️"},{"i":"myth-m9","s":18,"h":"","t":"mc","x":"سلطة زيوس في مشهد تيتيس مبنية على إيه؟ ؟ الصاعقة بس / جيش كبير / هدية من هيرا / إيماءة وكلمة ما بترجعش . إيماءة وكلمة ما بترجعش"},{"i":"myth-m9","s":19,"h":"","t":"learn","x":"في الإلياذة الكتاب التامن، والمعركة والاقفة، زيوس بيطلع ميزان من دهب: \" Then verily the Father lifted on high his golden scales, and set therein two fates of grievous death, one for the horse-taming Trojans, and one for the brazen-coated Achaeans. .. and down sank the day of doom of the Achaeans. \""},{"i":"myth-m9","s":20,"h":"","t":"learn","x":"(الأب رفع ميزانه الذهبي، وحط فيه قدرين للموت: واحد للطرواديين وواحد للإغريق، فهبطت كفة الإغريق.) ( Iliad 8.69-77 ، ترجمة Murray ) الصورة دي، الميزان اللي فيه مصير الشعوب، هتفضل شغالة في الفن والشعر والزخرفة لحد النهارده. كل ما تشوف ميزان عدالة، افتكر إن الأصل الأدبي ليه هنا: ميزان المصير. 🎭 خامسا: زيوس عند التراجيديين، من القوة للحكمة"},{"i":"myth-m9","s":21,"h":"","t":"learn","x":"إسخيلوس، مؤسس المسرح التراجيدي، في مسرحية \"أجاممنون\" (458 قبل الميلاد)، بيخلي الكورس يغني أغنية غريبة ومؤثرة: \" Zeus, whoever he may be, if by this name it pleases him to be invoked, by this name I call to him. As I weigh all things in the balance, I have nothing to compare save Zeus. ..\""},{"i":"myth-m9","s":22,"h":"","t":"learn","x":"(زيوس، أيا كان مين هو، لو الاسم ده بيرضيه، بالاسم ده بنده عليه. مهما وزنت كل حاجة في الميزان، مفيش حاجة تتقارن بيه إلا زيوس.) ( Agamemnon 160-166 ، ترجمة Smyth ) وبعدين تجي الجملة الأشهر في المسرحية كلها: زيوس \"وضع قانون ثابت إن الحكمة تجي بالألم\"، wisdom comes by suffering ، باليوناني pathei mathos."},{"i":"myth-m9","s":23,"h":"","t":"mc","x":"كمل الجملة اللي لسه شايفها: wisdom _____ by suffering ؟ comes / slaves / balance / forgets . wisdom comes by suffering"},{"i":"myth-m9","s":24,"h":"","t":"learn","x":"لاحظ التطور: زيوس هنا مش راجل الصواعق بس، ده بقى رمز للنظام الأخلاقي للكون: اللي بيعلم البشر بالمعاناة. دي نقطة هتنفعك جدا لما تذاكر التراجيديا. 🏛️ سادسا: زيوس يتنقل لروما، ويدخل اللغة 1 ️ ⃣ Jupiter / Jove الرومان سموه جوبيتر ( Jupiter )، وفي الشعر الإنجليزي هتلاقيه غالبا باسم مختصر: Jove (جوف)."},{"i":"myth-m9","s":25,"h":"","t":"mc","x":"إيه معنى الفكرة اللي عند إسخيلوس: wisdom comes by suffering ؟ ؟ الحكمة بتيجي بالألم / الحكمة بتيجي بالقوة / الحكمة بتيجي بالفلوس / الحكمة بتيجي بالتقليد . الحكمة بتيجي بالألم"},{"i":"myth-m9","s":26,"h":"","t":"learn","x":"اسم زيوس واسم جوبيتر بيرجعوا الاتنين لجذر هندوأوروبي قديم جدا (* dyeu- ) معناه \"السما المضيئة / نور النهار\". يعني من الاسم نفسه، زيوس هو إله السما. 2 ️ ⃣ by Jove ! تعبير إنجليزي قديم للقسم: by Jove ! (أقسم بجوف!). وكان قسم حقيقي وبعدين بقى تعبير مهذب للدهشة."},{"i":"myth-m9","s":27,"h":"","t":"learn","x":"شكسبير نفسه استخدمه: في \" Love's Labour's Lost \" (5.2): \" By Jove, I always took three threes for nine. \" وفي \" Antony and Cleopatra \" (3.13): \" Favours, by Jove that thunders !\" 3 ️ ⃣ jovial = مرح كلمة jovial (بشوش، مرح، قلبه أبيض) جاية من Jove ! ليه؟ لأن المنجمين القدام كانوا معتقدين إن اللي اتولد تحت تأثير كوكب المشتري ( Jupiter ) بيبقى مزاجه مرح."},{"i":"myth-m9","s":28,"h":"","t":"learn","x":"الكلمة دخلت الإنجليزي في 1580 s بمعنى \"تحت تأثير كوكب المشتري\" وبعدين بقت \"مرح\". يعني لما تقول عن حد jovial ، انت حرفيا بتقول \"مزاجه زيوسي\". 📜 الأسطورة في الشعر الإنجليزي"},{"i":"myth-m9","s":29,"h":"","t":"mc","x":"كلمة jovial (مرح) جاية من إيه؟ ؟ من اسم شاعر / من كلمة فرنسية معناها جميل / من Jove ، لأن المنجمين ربطوها بكوكب المشتري / من كلمة لاتينية معناها ضحك . من Jove ، لأن المنجمين ربطوها بكوكب المشتري"},{"i":"myth-m9","s":30,"h":"","t":"learn","x":"1 ️ ⃣ ألكسندر بوب، ترجمة الإلياذة (1715-1720): مشهد تيتيس المتوسلة (فوق)، من أشهر ترجمات الإلياذة على الإطلاق، واللي خلت هوميروس \"يتكلم إنجليزي\" لجيل كامل. 2 ️ ⃣ شكسبير، الملك لير (الفصل التاني، المشهد الرابع): لير بيرفض يستدعي عقاب السما على بناته، فيقول: \" I do not bid the thunder-bearer shoot, Nor tell tales of thee to high-judging Jove. \""},{"i":"myth-m9","s":31,"h":"","t":"learn","x":"(مش هطلب من حامل الرعد يضرب، ولا هشكيكي لجوف القاضي العادل.) \" thunder-bearer \" = حامل الرعد = زيوس نفسه. لير بينادي زيوس رغم إن المسرحية في بريطانيا الأسطورية قبل المسيحية، ودي ملحوظة شكسبيرية ممتعة: زيوس هو \"الإله الافتراضي\" لأي مأساة كلاسيكية."},{"i":"myth-m9","s":32,"h":"","t":"learn","x":"3 ️ ⃣ جون كيتس، \" Hyperion \" (نشرت 1820): القصيدة عن سقوط التييتنز وصعود الأوليمبيين، يعني قصة فصلنا ده بالظبط. أوشيانوس، أحكم التييتنز، بيقول لإخواته المهزومين: \" We fall by course of Nature's law, not force Of thunder, or of Jove. \" (إحنا بنسقع بقانون الطبيعة، مش بقوة الرعد ولا جوف.)"},{"i":"myth-m9","s":33,"h":"","t":"mc","x":"كمل الجملة اللي لسه شايفها: We fall by _____ of Nature's law, ؟ thunder / chance / course / pleases . We fall by course of Nature's law,"},{"i":"myth-m9","s":34,"h":"","t":"learn","x":"العبقرية هنا: كيتس بيخلي حتى المهزومين يعترفوا إن زيوس مكسبش بالقوة، كسب لأن ده قانون التطور. الجيل الجديد بيجي، دايما."},{"i":"myth-m9","s":35,"h":"","t":"mc","x":"في Hyperion لكيتس، إيه سبب سقوط التييتنز؟ ؟ خيانة من جوبيتر / طوفان غطى الكون / ضعف أخلاقي داخلهم / قانون الطبيعة، مش بس قوة الرعد . قانون الطبيعة، مش بس قوة الرعد"},{"i":"myth-m9","s":36,"h":"","t":"learn","x":"4 ️ ⃣ برسي شيلي، \" Prometheus Unbound \" (1820): شيلي بيخلي جوبيتر هو الطاغية الشرير في المسرحية الشعرية، وبروميثيوس المقيد بيفتتح الكلام بمخاطبته ساخرا: \" Monarch of Gods and Daemons, and all Spirits But One, who throng those bright and rolling worlds Which Thou and I alone of living things Behold with sleepless eyes : regard this Earth"},{"i":"myth-m9","s":37,"h":"","t":"learn","x":"Made multitudinous with thy slaves. ..\" (يا ملك الآلهة والأرواح... بص على الأرض اللي مليتها عبيد ليك...) عند الرومانتيكيين، زيوس بقى رمز الاستبداد، وبروميثيوس رمز الحرية. فاكر قصة بروميثيوس؟ نفس السلسلة، وبايرون كمان كتب قصيدة \" Prometheus \" (1816) بنفس الروح."},{"i":"myth-m9","s":38,"h":"","t":"mc","x":"عند الرومانتيكيين زي شيلي، جوبيتر بقى رمز لإيه؟ ؟ الحب والرحمة / الاستبداد / المطر والخصب / الحكمة والعدل . الاستبداد"},{"i":"myth-m9","s":39,"h":"","t":"learn","x":"5 ️ ⃣ المرجع الكلاسيكي: هوميروس (الإيماءة، Iliad 1.528-530 ) وهسيود (الميلاد، Theogony 453-506 ) وإسخيلوس (أغنية أجاممنون)، كلهم فوق بترجمات إنجليزية موثقة. 👨‍👧‍👦 سابعا: لمحة عن عيلة زيوس (خريطة الدروس الجاية) مراته وأخته: هيرا، ملكة الآلهة. (هنقابل غيرتها المشهورة في فصول كتير.)"},{"i":"myth-m9","s":40,"h":"","t":"learn","x":"أولاده الآلهة: أثينا (طلعت من راسه كاملة بالسلاح بعد ما بلع أمها ميتيس)، أبولو وأرتميس التوأم، أريس، هيرميس، ديونيسوس، وبيرسيفوني. قصص حبه الشهيرة مع البشر والتحولات: إيو وأوروبا وليدا وجانيميد، وألكميني أم هرقل. خلي بالك: أغلب الدروس الجاية مبنية على زيوس. هو مش بس ملك، ده \"الشبكة\" اللي شابكة الأساطير كلها ببعض. 🧠 ثامنا: الفكرة العامة"},{"i":"myth-m9","s":41,"h":"","t":"learn","x":"عرش زيوس اتبنى على أربع مراحل، وكل مرحلة ليها درس: 1) الحيلة: الحجر بدل الطفل. البداية دايما ذكاء، مش قوة. 2) القوة: عشر سنين حرب ضد التييتنز. مفيش عرش ببلاش. 3) القسمة العادلة: القرعة بين الأخوة. الملك الحكيم بيوزع قبل ما يحكم. 4) الكلمة المقدسة: الإيماءة اللي مابترجعش. السلطة الأخيرة هي مصداقية الكلمة. 🔤 كلمات إنجليزي من الفصل thunderbolt : الصاعقة."},{"i":"myth-m9","s":42,"h":"","t":"learn","x":"thunder-bearer : حامل الرعد (لقب زيوس). suppliant : متوسل / طالب رحمة. to nod : يومئ براسه. fate : القدر / المصير. golden scales : الميزان الذهبي. to draw lots : يعمل قرعة. jovial : مرح، بشوش (من Jove ). by Jove !: أقسم بجوف! sovereignty : سيادة / ملك. Titan : تيتان، عملاق من الجيل القديم. oath : قسم / يمين."},{"i":"myth-m9","s":44,"h":"تذكر واكتب","t":"recall","x":"إزاي اتقسمت مملكة الكون بين الأخوة التلاتة؟ . زيوس خد السما، وبوسيدون خد البحر، وهاديس خد العالم السفلي. والأرض فضلت مشتركة بينهم."},{"i":"myth-m9","s":45,"h":"تذكر واكتب","t":"recall","x":"كلمة jovial جاية منين، وليه بقت بمعنى مرح؟ . من Jove ، اسم المشتري. المنجمين القدام افتكروا إن اللي بيتولد تحت كوكب المشتري مزاجه مرح، فالكلمة بقت تعني بشوش."},{"i":"myth-m9","s":46,"h":"تذكر واكتب","t":"write","x":"قارن في ٣-٤ جمل بين استدعاء زيوس عند شكسبير في الملك لير وبين ترجمة بوب لمشهد تيتيس المتوسلة في الإلياذة. . لير بيرفض إنه يستدعي العقاب السماوي، وبيقول \" I do not bid the thunder-bearer shoot , / Nor tell tales of thee to high-judging Jove \" (٢.٤)، فزيوس موجود في النص كاحتمال، مش كإله بيصلي له. أما عند بوب، زيوس هو الطرف اللي بيتكلم معاه، والمشهد كله دعاء وتوسل، لأن الترجمة بتحافظ على دين النص الأصلي. يبدو أن الفرق مصدره المسرح: شكسبير بيكتب لبريطانيا قبل المسيحية، فزيوس عنده اسم مجازي، وبوب بينقل عالما وثنيا كامل الإيمان."},{"i":"myth-m9","s":47,"h":"تذكر واكتب","t":"write","x":"قارن في ٣-٤ جمل بين تعبير by Jove في الإنجليزي الحديث وبين طريقة شكسبير في استخدام اسم جوف على المسرح. . تعبير by Jove كان قسم حقيقي، وبعدها بقى تعبير مهذب للدهشة، فالإله اتحول لكلمة بتتقال من غير ما حد يفكر في معناها. وعند شكسبير الاسم لسه بيثير سؤالا: لير بيرفض إنه يشكي بناته لجوف، كأنه بيخاف من عدالة أوسع من عدالته هو. يمكن القول إن الاسم عاش مرتين: مرة كإله بيسأل عنه الناس، ومرة كلمة بيسيبوها في الكلام من غير سؤال. والانتقال ده نفسه موضوع يستاهل التأمل."}]};